-- =============================================================================
-- 429 — LE CATALOGUE DES CONTRÔLES BLANCS : 4e
--
-- 225 sujets écrits d'avance et relus : pour chaque fiche, un sujet
-- Facile, un Moyen, un Difficile, chacun avec son barème sur 20 et son corrigé
-- type (`contenu.corrige`, jamais envoyé à l'élève avant sa copie). L'IA ne fait
-- plus que les corriger ; elle ne rédige que « Un autre sujet ».
--
-- ⚠️ FICHIER GÉNÉRÉ — ne pas éditer à la main. Source : contenu/controles/.
--    Regénérer : node node_modules/jiti/lib/jiti-cli.mjs scripts/controles-sql.ts --num 429 --niveau 4e
--
--   francais.c07                 54 sujets · 18 fiches
--   histoire-geo.c23             54 sujets · 18 fiches
--   latin.c27                     9 sujets · 3 fiches
--   maths.c29a                   27 sujets · 9 fiches
--   maths.c29b                   27 sujets · 9 fiches
--   maths.c30                    54 sujets · 18 fiches
--
-- L'identifiant d'un sujet est dérivé de (fiche, niveau) : rejouer la migration
-- met le sujet à jour au lieu de le dupliquer. Une fiche absente est sautée.
--
-- PRÉREQUIS : 360 puis 364. Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

INSERT INTO public.chapter_exercices
  (id, chapter_id, style, contenu, difficulte, origine, created_by)
SELECT
  md5('exercice-catalogue:' || v.chapter_id::text || ':' || v.difficulte::text)::uuid,
  v.chapter_id,
  v.style,
  v.contenu,
  v.difficulte,
  'catalogue',
  NULL
FROM (VALUES
  ('c7aa5303-cee8-5f65-982a-d7988ca78342'::uuid, 1, 'redaction', $exo${"titre":"Informer ou donner son avis ?","consigne":"Lis les deux textes (écrits pour l’exercice), puis réponds par des phrases complètes.","enonce":"> **Texte A.** Le collège Jean-Moulin ouvrira son nouveau gymnase lundi 6 octobre, à 8 h. Les élèves de 4e y auront cours d’EPS dès la première semaine.\n>\n> **Texte B.** Fermer la cantine le mercredi serait une erreur : on ne peut pas prétendre lutter contre les inégalités et priver des enfants du seul repas chaud de leur journée.\n\n1. Donne le genre journalistique probable de chaque texte (brève, article informatif, éditorial, reportage) et justifie-le.\n2. Le texte A répond à plusieurs des « cinq questions » d’un article informatif. Relève-en trois avec la réponse que le texte donne.\n3. Peut-on reprocher au texte B de donner son avis ? Explique en une phrase.","bareme":[{"critere":"Texte A identifié comme brève ou article informatif (il informe), texte B comme éditorial (il s’engage), avec une justification","points":8},{"critere":"Trois réponses aux cinq questions relevées dans le texte A (quoi, où, quand, qui)","points":7},{"critere":"Idée que donner un avis est légitime, mais qu’il faut le distinguer de l’information","points":5}],"dureeMin":7,"corrige":"1. **Texte A** : une **brève** (ou un court article informatif) : quelques lignes, des faits précis, aucun jugement. **Texte B** : un **éditorial** (texte d’opinion) : l’auteur s’engage (« serait une erreur », « on ne peut pas prétendre »), il argumente au lieu de rapporter.\n\n2. Exemples : **quoi** : l’ouverture du nouveau gymnase ; **quand** : lundi 6 octobre, à 8 h ; **où** : au collège Jean-Moulin ; **qui** : les élèves de 4e. (Le « pourquoi » n’est pas donné.)\n\n3. Non : donner un avis est **légitime** dans un éditorial, un genre fait pour cela. Ce qui n’est pas légitime, c’est de **confondre** un texte d’opinion avec une information : le lecteur doit savoir ce qu’il lit."}$exo$::jsonb),
  ('c7aa5303-cee8-5f65-982a-d7988ca78342'::uuid, 2, 'redaction', $exo${"titre":"Anatomie d’un article et vérification d’une photo","consigne":"Lis le document (écrit pour l’exercice), puis réponds en justifiant.","enonce":"> **Le collège se met au vert**\n>\n> **Depuis lundi, les élèves de 4e B trient leurs déchets à la cantine : une première dans la ville.** *(paragraphe en gras)*\n>\n> « Tout a commencé par une idée de la délégation des élèves », raconte Mme Rey, principale adjointe. Quatre bacs de couleur ont été installés…\n>\n> *Photo : élèves devant les bacs. Crédit : archives du collège, 2019.*\n\n1. Nomme chaque élément : le titre, le paragraphe en gras, la première phrase du corps du texte, la ligne sous la photo. Que dit le crédit photo sur cette image, et pourquoi est-ce un problème ?\n2. Un lecteur veut vérifier que l’information est fiable. Propose trois vérifications concrètes parmi : source, date, recoupement, auteur, image.\n3. Le titre est-il informatif ou incitatif ? Explique.","bareme":[{"critere":"Éléments correctement nommés : titre, chapô, attaque, légende ou crédit photo","points":6},{"critere":"Repérage du problème : photo d’archive de 2019 pour un événement récent, donc image ancienne remise en circulation","points":5},{"critere":"Trois vérifications concrètes et adaptées à cet article","points":6},{"critere":"Titre analysé avec une justification cohérente","points":3}],"dureeMin":10,"corrige":"1. **Titre** : « Le collège se met au vert » ; **chapô** : le paragraphe en gras qui résume l’essentiel ; **attaque** : la première phrase du corps du texte (« Tout a commencé… » ou la citation) ; la ligne sous la photo est la **légende** avec son **crédit photo**. Le crédit indique « archives du collège, 2019 » : l’image est **ancienne** et n’illustre pas l’événement de la semaine. Une image ancienne présentée comme récente change le sens de l’information.\n\n2. Exemples : la **date** (la photo date de 2019, l’article de cette année) ; la **source** (Mme Rey est nommée, on peut la contacter) ; le **recoupement** (un autre média ou le site du collège dit-il la même chose ?) ; l’**auteur** (l’article est-il signé ?) ; la recherche d’**image inversée** pour retrouver l’origine de la photo.\n\n3. Le titre est plutôt **incitatif** : il joue sur l’image (« se met au vert ») et ne donne ni le lieu ni le fait précis. Un titre informatif dirait : « Le collège Jean-Moulin instaure le tri des déchets à la cantine »."}$exo$::jsonb),
  ('c7aa5303-cee8-5f65-982a-d7988ca78342'::uuid, 3, 'redaction', $exo${"titre":"Infox, rumeur ou information ? Le message qui circule","consigne":"Lis le document (écrit pour l’exercice) et rédige tes réponses de façon argumentée.","enonce":"> **Message reçu dans un groupe de discussion**\n>\n> « URGENT ‼️ Tous les lycées de la ville fermés demain à cause d’une alerte !!! Ils ne veulent pas que ça se sache. Partage vite avant que ce soit supprimé !!! » *(sans auteur, sans source, avec une photo de foule sans légende)*\n\n1. Ce message est-il une rumeur ou une infox ? Justifie en distinguant les deux notions et en relevant deux indices.\n2. Explique pourquoi ce type de message circule vite. Appuie-toi sur le rôle de l’émotion et sur l’effet des algorithmes (bulle de filtres).\n3. Applique la méthode de vérification : donne quatre contrôles à faire, avec ce que tu attends de chacun.\n4. Un journaliste qui diffuserait un tel message sans vérification manquerait à quelle règle ? Rappelle aussi ce que la loi de 1881 protège et une de ses limites.","bareme":[{"critere":"Distinction rumeur (relayée de bonne foi) et infox (fabriquée pour tromper) et choix argumenté avec deux indices du texte","points":5},{"critere":"Explication de la circulation : émotion, urgence, bulle de filtres qui conforte ce que l’on croit","points":5},{"critere":"Quatre contrôles pertinents appliqués au message (source, date, recoupement, auteur, image)","points":6},{"critere":"Déontologie (vérifier, protéger ses sources) et loi de 1881 avec une limite (diffamation, injure, incitation à la haine)","points":4}],"dureeMin":15,"corrige":"1. Le message est **au minimum une rumeur**, et il a toutes les marques d’une **infox** si on le fabrique pour effrayer. Une **rumeur** est une information non vérifiée, relayée de bonne foi ; une **infox** est fabriquée pour tromper. Indices : **aucune source ni auteur**, ton alarmiste (« URGENT », points d’exclamation), phrase qui pousse à partager (« avant que ce soit supprimé »), photo sans légende ni date. Les deux réponses sont acceptées si elles sont justifiées.\n\n2. Une infox circule d’autant plus vite qu’elle **indigne ou effraie** : l’émotion est son carburant, pas la vraisemblance. L’urgence empêche de réfléchir. Les algorithmes des réseaux montrent surtout ce qui confirme ce qu’on pense déjà : la **bulle de filtres** rend le message plus visible pour ceux qui sont prêts à y croire.\n\n3. Exemples : **source** : d’où vient l’alerte ? aucune autorité citée ; **date** : depuis quand circule-t-elle ? **recoupement** : les rectorats, la mairie ou plusieurs médias indépendants confirment-ils ? **auteur** : qui a écrit ? **image** : recherche d’image inversée pour retrouver son origine.\n\n4. Il manquerait à la **déontologie** : vérifier ses informations (et protéger ses sources). La **loi de 1881** garantit la liberté de la presse ; ses limites sont la diffamation, l’injure et l’incitation à la haine."}$exo$::jsonb),
  ('e104a714-229a-5083-b718-e27552811460'::uuid, 1, 'redaction', $exo${"titre":"Information, publicité ou propagande ?","consigne":"Lis les trois textes (écrits pour l’exercice, pays imaginaire) et réponds par des phrases complètes.","enonce":"> **Texte 1.** « Le pain Doré : croustillant, moelleux, cuit chaque matin. Achetez-le dans nos boulangeries ! »\n>\n> **Texte 2.** « Le Grand Guide nous a sauvés de la misère. Ceux qui doutent de lui sont des traîtres. Une seule voix, un seul peuple ! »\n>\n> **Texte 3.** « Le conseil municipal a voté hier le budget de la piscine : 40 voix pour, 12 contre. Les opposants estiment le projet trop coûteux. »\n\n1. Associe chaque texte à un discours : information, publicité, propagande. Donne le but de chacun.\n2. Relève dans le texte 2 deux procédés de propagande et nomme-les.","bareme":[{"critere":"Les trois textes associés au bon discours","points":6},{"critere":"But de chaque discours correctement formulé (faire savoir, vendre, faire adhérer)","points":6},{"critere":"Deux procédés relevés dans le texte 2 et nommés (culte du chef, désignation d’un ennemi, répétition, slogan)","points":8}],"dureeMin":7,"corrige":"1. **Texte 1** : **publicité**, son but est de vendre un produit. **Texte 2** : **propagande**, son but est de faire adhérer à une idée politique et à un chef. **Texte 3** : **information**, son but est de faire savoir, avec du contradictoire (les pour et les contre).\n\n2. **Culte du chef** : le Grand Guide « nous a sauvés ». **Désignation d’un ennemi** : ceux qui doutent sont des « traîtres » (un « eux » opposé à un « nous »). On accepte aussi la **simplification** et la formule martelée « Une seule voix, un seul peuple ! » (slogan, répétition)."}$exo$::jsonb),
  ('e104a714-229a-5083-b718-e27552811460'::uuid, 2, 'redaction', $exo${"titre":"Analyser une affiche imaginaire","consigne":"Lis la description de l’affiche (écrite pour l’exercice, pays imaginaire de Valdrie) et réponds en justifiant.","enonce":"> **L’affiche.** Année 1937. Sur un fond rouge et noir, un homme en uniforme, le menton levé, occupe les deux tiers de l’image ; il est vu **d’en bas**. Derrière lui, une foule minuscule brandit des drapeaux. En haut, en grosses lettres : « **UN CHEF, UNE PATRIE** ». En bas, en petits caractères : « Parti national valdrien ». Au coin, une silhouette sombre, aux traits grossiers, tient un sac d’argent ; sous elle : « L’étranger vous vole. »\n\n1. Précise la nature de ce document, son commanditaire et son but.\n2. Nomme deux procédés visuels et explique l’effet de chacun.\n3. Quel est le message **explicite** ? Quel est le message **implicite** ?\n4. Que doit-on faire d’abord pour bien comprendre une affiche de ce genre ?","bareme":[{"critere":"Nature (affiche), commanditaire (parti) et but (faire adhérer) identifiés","points":4},{"critere":"Deux procédés visuels expliqués (contre-plongée, taille du chef, foule minuscule, couleurs)","points":6},{"critere":"Distinction du message explicite (slogan) et du message implicite (l’étranger est coupable, le chef est seul à pouvoir sauver)","points":6},{"critere":"Méthode : auteur, commanditaire, date et contexte avant tout","points":4}],"dureeMin":10,"corrige":"1. C’est une **affiche de propagande** (nature), commandée par le **parti national valdrien** (commanditaire) : elle cherche à faire adhérer au chef et à désigner un coupable, non à informer.\n\n2. **Contre-plongée** : le chef vu d’en bas paraît grand, puissant, admirable. **Taille relative** : il occupe les deux tiers de l’image, la foule est minuscule, ce qui l’écrase et fait du chef le seul personnage qui compte. On accepte aussi les couleurs (rouge et noir, tonalité violente) ou la silhouette caricaturale de l’ennemi.\n\n3. **Explicite** : « Un chef, une patrie » et « L’étranger vous vole ». **Implicite** : ce qu’elle fait croire sans le dire : que tous les malheurs viennent de l’étranger et que seul ce chef peut sauver le pays ; on ne doit pas penser autrement.\n\n4. Identifier l’**auteur et le commanditaire**, puis la **date et le contexte** : qui parle, pour le compte de qui, dans quelle situation ? La question à garder : qui a intérêt à ce que je le croie ?"}$exo$::jsonb),
  ('e104a714-229a-5083-b718-e27552811460'::uuid, 3, 'redaction', $exo${"titre":"Décrypter un tract et une image détournée","consigne":"Lis les deux documents (écrits pour l’exercice, pays imaginaire de Valdrie), puis réponds en argumentant.","enonce":"> **Document 1 : un tract (1936).** « Nos usines ferment, nos enfants ont faim, nos rues ne sont plus sûres : le coupable, c’est l’étranger. Tout le monde le sait. Des millions de Valdriens nous font déjà confiance. Nous seuls avons la solution. Rejoignez-nous ! »\n>\n> **Document 2 : une photographie.** Elle montre le chef sur un balcon, devant une immense foule enthousiaste. Légende du journal du parti : « Tout un peuple acclame son chef. » On apprend plus tard que la photo a été prise sur une place vidée de ses habitants habituels, la foule étant composée de fonctionnaires convoqués, et recadrée pour cacher les chaises vides.\n\n1. Relève dans le tract trois procédés de propagande et nomme-les. Explique celui qui vise l’émotion.\n2. Quels éléments du document 2 montrent qu’une image peut tromper sans être truquée de toutes pièces ? Distingue cadrage, légende et contexte.\n3. Rédige un paragraphe argumenté : pourquoi la propagande s’adresse-t-elle à l’émotion plutôt qu’au raisonnement ? Cite deux contre-pouvoirs qui permettent de lui résister.","bareme":[{"critere":"Trois procédés relevés et nommés dans le tract (simplification, désignation d’un ennemi, argument d’autorité, appel à la peur)","points":6},{"critere":"Explication de l’appel aux émotions (peur, colère) avec des exemples du texte","points":3},{"critere":"Rôle du cadrage, de la légende et du contexte dans la falsification de l’image","points":6},{"critere":"Paragraphe argumenté avec deux contre-pouvoirs (pluralité des médias, droit de réponse, vérification des faits, éducation aux médias)","points":5}],"dureeMin":16,"corrige":"1. **Simplification** : un seul coupable (« l’étranger ») pour des problèmes complexes ; **désignation d’un ennemi** : « nous » contre « l’étranger » ; **argument d’autorité** : « Tout le monde le sait », « Des millions… » ; **appel aux émotions** : la peur (« nos enfants ont faim », « nos rues ne sont plus sûres ») pousse à réagir sans réfléchir.\n\n2. La photo n’est pas un faux montage, mais elle trompe : le **cadrage** cache les chaises vides ; la **légende** affirme que « tout un peuple » acclame ; le **contexte** (foule convoquée, place vidée) révèle qu’il s’agit d’une mise en scène. Une image ne dit rien toute seule : c’est le cadrage, la légende et le contexte qui lui font dire ce qu’elle ne montre pas.\n\n3. Attendu : la propagande veut **faire adhérer**, pas informer. Le raisonnement suppose du temps, des faits vérifiables et des avis contraires, ce qui affaiblirait son message. La peur, la fierté ou la colère poussent à agir vite et à rejoindre le groupe. Contre-pouvoirs : la **pluralité des médias**, le **droit de réponse**, les journalistes de **vérification des faits**, l’**éducation aux médias**. Conclusion : se demander qui a intérêt à ce que je le croie."}$exo$::jsonb),
  ('b270ad70-ec61-5760-b00d-1f57aa02685f'::uuid, 1, 'redaction', $exo${"titre":"Œuvres et journalistes","consigne":"Réponds par des phrases complètes.","enonce":"Voici cinq repères : *Illusions perdues*, *Bel-Ami*, Albert Londres, *Les Hommes du président* (1976), *Spotlight* (2015).\n\n1. Associe chaque repère à l’une de ces descriptions : (a) un roman de Maupassant sur un journaliste sans talent qui gravit les échelons ; (b) un film sur des journalistes du *Washington Post* et le Watergate ; (c) un roman de Balzac où Lucien de Rubempré se perd dans la presse ; (d) un film sur une enquête de plusieurs mois avant publication ; (e) un journaliste qui a inventé le grand reportage.\n2. Complète la phrase d’Albert Londres : « Notre métier n’est pas de faire plaisir, non plus de faire du tort, il est de porter la plume… » Explique-la en une phrase.","bareme":[{"critere":"Cinq associations correctes","points":10},{"critere":"Fin de la citation (« dans la plaie »)","points":4},{"critere":"Explication : le journaliste doit montrer la réalité, même si elle dérange","points":6}],"dureeMin":7,"corrige":"1. *Illusions perdues* = (c) ; *Bel-Ami* = (a) ; Albert Londres = (e) ; *Les Hommes du président* = (b) ; *Spotlight* = (d).\n\n2. « …de porter la plume **dans la plaie**. » Le journaliste ne cherche ni à flatter ni à nuire : il doit **montrer ce qui va mal**, même si cela dérange, en s’appuyant sur ce qu’il a vu."}$exo$::jsonb),
  ('b270ad70-ec61-5760-b00d-1f57aa02685f'::uuid, 2, 'redaction', $exo${"titre":"Le journalisme au XIXe siècle : Balzac et Maupassant","consigne":"Lis le résumé (écrit pour l’exercice) puis réponds en justifiant.","enonce":"> **Résumé.** Dans *Illusions perdues* (Balzac), le jeune Lucien de Rubempré monte à Paris et devient journaliste. Il découvre qu’un article se vend : on démolit une pièce qu’on n’a pas vue si un rival paie pour cela. Dans *Bel-Ami* (Maupassant), Georges Duroy, sans grand talent d’écriture, gravit tous les échelons du journal grâce aux femmes et à l’intrigue ; son journal sert à spéculer sur la politique.\n\n1. Que dénoncent ces deux romans à propos de la presse ? Précise pourquoi ce n’est pas seulement le portrait d’un homme malhonnête.\n2. Compare les deux héros : ce qu’ils ont en commun et ce qui les distingue (talent, chute ou réussite).\n3. Quel est l’intérêt d’un roman pour comprendre ce système, par rapport à un article de presse ?","bareme":[{"critere":"Dénonciation d’un système qui produit le mensonge, au-delà des individus","points":6},{"critere":"Comparaison de Lucien (se perd) et de Duroy (réussit sans talent) avec une ressemblance","points":7},{"critere":"Apport du roman : il montre comment et par quels moyens on obtient et fabrique l’information","points":7}],"dureeMin":10,"corrige":"1. Les deux romans montrent une presse où l’**article se vend** et où le journal sert des intérêts (argent, politique). Le mensonge n’est pas le fait d’un seul homme : c’est le **système** qui le produit, et les journalistes en sont les rouages.\n\n2. Points communs : deux jeunes ambitieux qui arrivent à Paris et entrent dans la presse, et deux journaux soumis à l’argent et à l’intrigue. Différence : Lucien a du talent mais **s’y perd** ; Duroy n’en a guère et **réussit** par les femmes et l’intrigue, ce qui rend le système encore plus accablant.\n\n3. Un article expose un **fait** ; le roman montre **comment** le mensonge se fabrique, ce qu’il coûte, les pressions et les compromis. Il rend visibles les **conditions** du travail journalistique."}$exo$::jsonb),
  ('b270ad70-ec61-5760-b00d-1f57aa02685f'::uuid, 3, 'redaction', $exo${"titre":"Que nous apprend la fiction sur le journalisme ?","consigne":"Rédige les réponses de façon argumentée en t’appuyant sur des œuvres précises.","enonce":"> **Deux scènes imaginées pour l’exercice.**\n> **A.** Dans un roman du XIXe siècle, un jeune rédacteur écrit, contre paiement, une critique très dure d’une pièce qu’il n’a pas vue.\n> **B.** Dans un film récent, une équipe passe des mois à recouper des témoignages et des documents ; le rédacteur en chef retarde la publication tant que tout n’est pas vérifié.\n\n1. Quelle image du journalisme chaque scène donne-t-elle ? Relie-les à une œuvre du cours pour chacune.\n2. Albert Londres a défini le journalisme par la formule « porter la plume dans la plaie ». Laquelle des scènes s’en rapproche le plus ? Explique.\n3. Rédige un paragraphe : qu’apporte la fiction (roman, film) que ne donne pas un article de presse ? Donne deux exemples de ce qu’elle rend visible.","bareme":[{"critere":"Image du journalisme de chaque scène (système corrompu / contre-pouvoir rigoureux)","points":5},{"critere":"Œuvres justes : Illusions perdues (ou Bel-Ami), Spotlight (ou Les Hommes du président)","points":5},{"critere":"Choix argumenté de la scène B pour la formule de Londres","points":4},{"critere":"Paragraphe : la fiction montre comment le fait a été obtenu et ce qu’il a coûté, avec deux exemples (délais, pressions, doute)","points":6}],"dureeMin":15,"corrige":"1. **Scène A** : un journalisme **corrompu**, où l’article se vend ; c’est le monde d’*Illusions perdues* (Balzac), on accepte *Bel-Ami*. **Scène B** : un journalisme **contre-pouvoir**, fait de vérification et de patience ; c’est *Spotlight* (2015), on accepte *Les Hommes du président* (1976).\n\n2. La **scène B** : porter la plume dans la plaie, c’est montrer ce qui va mal, sans chercher à plaire ni à nuire, ce qui exige une enquête rigoureuse. Dans la scène A, le journaliste écrit ce qu’on lui paie, pas ce qu’il a constaté.\n\n3. Là où un article expose un **fait**, le roman ou le film montre **comment ce fait a été obtenu** et **ce qu’il a coûté**. Exemples : les délais et la hiérarchie de la rédaction ; les pressions économiques ou politiques ; le doute avant de publier ; les mois de recoupement dans *Spotlight*. La fiction rend ainsi visibles les conditions du travail journalistique."}$exo$::jsonb),
  ('b0642ad8-fd82-5098-a691-f2de6b6d856e'::uuid, 1, 'redaction', $exo${"titre":"Trois romanciers, trois villes","consigne":"Réponds par des phrases complètes.","enonce":"Balzac, Zola et Hugo ont chacun donné à la ville un rôle différent.\n\n1. Associe chaque romancier à sa vision de la ville : (a) un milieu qui détermine le destin, (b) un champ de bataille qui promet puis dévore, (c) un labyrinthe de ruelles, d’égouts et de barricades.\n2. Quel personnage de Balzac lance « À nous deux maintenant ! » ? À qui ou à quoi s’adresse-t-il ?\n3. Cite deux raisons qui expliquent que la ville devienne un sujet de roman au XIXe siècle.","bareme":[{"critere":"Trois associations correctes : Balzac (b), Zola (a), Hugo (c)","points":8},{"critere":"Rastignac et Paris (la ville)","points":5},{"critere":"Deux raisons (exode rural, industrialisation, travaux d’Haussmann)","points":7}],"dureeMin":6,"corrige":"1. **Balzac** = (b) champ de bataille ; **Zola** = (a) milieu qui détermine le destin ; **Hugo** = (c) labyrinthe.\n\n2. **Rastignac**, du haut du Père-Lachaise, s’adresse à **Paris**, qu’il défie de le laisser réussir.\n\n3. L’**exode rural**, la **révolution industrielle**, les **grands travaux d’Haussmann** : Paris change tant en trente ans qu’il devient méconnaissable, et le roman prend acte de cette transformation."}$exo$::jsonb),
  ('b0642ad8-fd82-5098-a691-f2de6b6d856e'::uuid, 2, 'redaction', $exo${"titre":"Arriver en ville : une description en focalisation interne","consigne":"Lis l’extrait (texte écrit pour l’exercice, pas d’un auteur célèbre) puis réponds en citant le texte.","enonce":"> Louise descendit du train à la tombée du jour. La gare rugissait ; la foule, une marée grise, la portait plus qu’elle ne marchait. Dehors, la ville l’avala d’un coup : des façades hautes qui se penchaient sur elle, des fiacres, des cris de marchands, une odeur de fumée et de boue. Elle serra sa valise contre elle. Là-haut, aux fenêtres éclairées, des gens dînaient sans savoir qu’elle existait.\n>\n> *(Texte écrit pour l’exercice.)*\n\n1. De quel point de vue la ville est-elle décrite ? Justifie par deux indices.\n2. Relève deux personnifications de la ville et explique l’impression qu’elles donnent.\n3. Cite trois éléments qui appartiennent aux champs lexicaux de la foule, du bruit, de la boue ou de la lumière.\n4. Que révèle cette description sur le sentiment de Louise ? Rapproche-la d’une des trois visions de la ville vues en cours.","bareme":[{"critere":"Focalisation interne (la ville vue par Louise) avec deux indices","points":5},{"critere":"Deux personnifications relevées (la gare rugissait, la ville l’avala, façades qui se penchaient) et leur effet (ville menaçante)","points":6},{"critere":"Trois éléments de champs lexicaux correctement classés","points":4},{"critere":"Sentiment de Louise (petitesse, solitude) et rapprochement justifié avec Balzac ou Hugo","points":5}],"dureeMin":11,"corrige":"1. C’est une **focalisation interne** : la ville est vue **par Louise**, à son arrivée. Indices : « la portait », « Elle serra sa valise », la fin qui dit ce qu’elle ressent sans le savoir des autres (« sans savoir qu’elle existait »).\n\n2. « La gare **rugissait** » ; « la ville l’**avala** d’un coup » ; « des façades hautes qui **se penchaient** sur elle ». Prêter à la ville des attributs de bête ou de géant la rend **menaçante**, dévorante.\n\n3. **Foule** : « une marée grise » ; **bruit** : « rugissait », « des cris de marchands » ; **boue** : « une odeur de fumée et de boue » ; **lumière** : « fenêtres éclairées ».\n\n4. Louise se sent **petite, seule, écrasée** face à une ville indifférente. On peut rapprocher la scène de **Balzac** (la ville qui dévore) ou de **Hugo** (le labyrinthe où l’on se perd). Décrire ainsi la ville, c’est porter un jugement sur elle."}$exo$::jsonb),
  ('b0642ad8-fd82-5098-a691-f2de6b6d856e'::uuid, 3, 'redaction', $exo${"titre":"Deux quartiers, une même ville : le contraste et le jugement","consigne":"Lis les deux courts textes (écrits pour l’exercice) et réponds en justifiant par des citations et des idées du cours.","enonce":"> **Texte A.** Rue de la Paix, les vitrines rutilaient comme des bijoux ; des dames en fourrure glissaient d’une boutique à l’autre, et les lampadaires diffusaient une lumière dorée sur les pavés lavés à grande eau.\n>\n> **Texte B.** À trois rues de là, dans l’impasse des Corbeaux, la boue collait aux semelles. Les murs suintaient. Une famille entière dormait dans une pièce sans fenêtre, et l’air épais avait le goût du charbon.\n>\n> *(Textes écrits pour l’exercice.)*\n\n1. Quel procédé organise l’ensemble des deux textes ? Relève trois oppositions précises.\n2. Relève dans chaque texte un procédé (personnification, comparaison, champ lexical) et son effet.\n3. Le narrateur porte-t-il un jugement sur la ville ? Explique en partant de ce qu’il choisit de montrer.\n4. Rédige un paragraphe : en quoi ces textes se rapprochent-ils de la vision de Zola (la ville comme milieu qui détermine) ? Que dirait Balzac ou Hugo à la place ?","bareme":[{"critere":"Contraste identifié et trois oppositions précises (lumière/boue, luxe/misère, vitrines/mur sans fenêtre)","points":5},{"critere":"Un procédé par texte relevé et son effet (comparaison « comme des bijoux », air « épais », murs qui suintent)","points":5},{"critere":"Jugement du narrateur : le choix de montrer vitrines et taudis dit une intention critique","points":5},{"critere":"Paragraphe sur Zola : le quartier explique le destin, avec comparaison à Balzac (champ de bataille) ou Hugo (labyrinthe)","points":5}],"dureeMin":16,"corrige":"1. Le **contraste** entre les deux quartiers, séparés de trois rues. Oppositions : lumière dorée / boue ; vitrines rutilantes / murs qui suintent ; dames en fourrure / famille dans une pièce sans fenêtre ; pavés lavés à grande eau / air au goût de charbon.\n\n2. Texte A : la **comparaison** « rutilaient comme des bijoux » dit la richesse. Texte B : le champ lexical de la saleté (boue, murs qui suintent, charbon) et l’air « épais » disent l’étouffement ; on accepte la personnification des murs qui « suintent ».\n\n3. Oui : décrire une ville, c’est toujours **porter un jugement** sur elle. En montrant côte à côte vitrines et taudis, le narrateur dénonce l’**inégalité** ; ce qu’il choisit de montrer révèle son intention.\n\n4. Pour **Zola**, le quartier **détermine le destin** : ceux qui naissent dans l’impasse des Corbeaux ont peu de chances d’en sortir, comme la Goutte-d’Or dans *L’Assommoir*. **Balzac** verrait dans cette ville un champ de bataille où l’on se bat pour passer d’un quartier à l’autre ; **Hugo** insisterait sur la ruelle, le lieu où l’on se cache ou se perd."}$exo$::jsonb),
  ('5b9ab20a-14af-58fa-a25c-bd2a53961130'::uuid, 1, 'redaction', $exo${"titre":"La ville en poésie : repères","consigne":"Réponds par des phrases complètes.","enonce":"1. Quel poète a écrit la section « Tableaux parisiens » et dans quel recueil ? Que signifie « flâneur » chez lui ?\n2. Associe : Verlaine, Apollinaire, Rimbaud à (a) *Alcools*, (b) les *Illuminations*, (c) « Il pleure dans mon cœur / Comme il pleut sur la ville ».\n3. Explique la phrase de Baudelaire : « Tu m’as donné ta boue et j’en ai fait de l’or. »","bareme":[{"critere":"Baudelaire, *Les Fleurs du mal*, et le flâneur qui marche et capte des instants","points":7},{"critere":"Trois associations : Verlaine (c), Apollinaire (a), Rimbaud (b)","points":6},{"critere":"Explication : le poète transfigure la laideur en beauté sans la cacher","points":7}],"dureeMin":6,"corrige":"1. **Baudelaire**, dans *Les Fleurs du mal* (1857). Le **flâneur** est un poète qui marche dans la ville, observe et capte des visages et des instants.\n\n2. **Verlaine** = (c), **Apollinaire** = (a), **Rimbaud** = (b).\n\n3. La ville donne au poète de la « boue » (du laid, du sale) ; il la **transfigure** en « or », en poésie. Il ne la cache pas : il en tire de la beauté."}$exo$::jsonb),
  ('5b9ab20a-14af-58fa-a25c-bd2a53961130'::uuid, 2, 'redaction', $exo${"titre":"Un marché en poème en prose","consigne":"Lis le texte (écrit pour l’exercice) et réponds en citant.","enonce":"> Le marché s’éveille : cris des marchands, sourire des cerises, odeur de poisson bleu comme un matin d’hiver. Foule, coudes, paniers, caddies, poussettes ; un accordéon grince, un chien aboie, une vieille dame sourit aux tomates. Tout est bruit et pourtant tout chante ; la rue est laide et resplendissante, sale et tendre.\n>\n> *(Poème en prose écrit pour l’exercice.)*\n\n1. Pourquoi peut-on parler de poème en prose ? Quel lien avec le désordre de la ville ?\n2. Relève une énumération et dis ce qu’elle imite.\n3. Relève une synesthésie et explique-la.\n4. Relève deux mots ou expressions qui forment un oxymore ou une antithèse. Que montrent-ils de la ville ?\n5. Ce poème embellit-il la ville ou la transfigure-t-il ? Explique la différence.","bareme":[{"critere":"Poème en prose : pas de vers ni de rimes, rythme libre qui épouse le désordre","points":4},{"critere":"Énumération relevée et son effet (le défilé du regard, la foule)","points":4},{"critere":"Synesthésie relevée (« odeur de poisson bleu ») et expliquée","points":4},{"critere":"Oxymore ou antithèse (« laide et resplendissante », « sale et tendre ») et beauté du laid","points":4},{"critere":"Distinction : transfigurer sans cacher, embellir en cachant","points":4}],"dureeMin":11,"corrige":"1. C’est un **poème en prose** : pas de vers ni de rimes, mais des images et un rythme poétiques. Cette forme souple **épouse le désordre** de la ville.\n\n2. « Foule, coudes, paniers, caddies, poussettes » : l’**énumération** imite le **défilé du regard** et l’entassement du marché.\n\n3. « Une odeur de poisson **bleu** » mêle l’odorat et la vue : c’est une **synesthésie**, un mélange de sensations de natures différentes.\n\n4. « **Laide et resplendissante**, **sale et tendre** » : ces antithèses (oxymores) disent la **beauté du laid**, la ville qui est à la fois pesante et attachante.\n\n5. Le poème **transfigure** : il ne cache ni le bruit ni la saleté, il en fait de la beauté. **Embellir** reviendrait à masquer le laid ; c’est la distinction capitale de Baudelaire (la boue devient de l’or)."}$exo$::jsonb),
  ('5b9ab20a-14af-58fa-a25c-bd2a53961130'::uuid, 3, 'redaction', $exo${"titre":"Écrire la ville sans ponctuation","consigne":"Lis le poème (écrit pour l’exercice) et rédige tes réponses de façon argumentée.","enonce":"> Gare du Nord midi\n> les pigeons picorent des miettes de soleil\n> un néon s’allume dans la lumière\n> la ville respire elle tousse elle chante\n> une femme rit dans un bruit de ferraille\n> et le métro comme un dragon avale les visages\n> ô grande nuit en plein jour\n>\n> *(Poème écrit pour l’exercice.)*\n\n1. Quelle est la forme de ce poème ? Quels indices montrent qu’il rappelle « Zone » d’Apollinaire ? Que permet cette forme pour dire la ville ?\n2. Relève une personnification, une comparaison, un oxymore ou une antithèse, et une énumération. Explique l’effet de chacun.\n3. Rédige un paragraphe : comment ce poème fait-il de la ville un objet poétique sans cacher ce qu’elle a de laid ? Appuie-toi sur Baudelaire (« boue » et « or ») et sur le flâneur.","bareme":[{"critere":"Vers libre sans ponctuation, lien avec « Zone » (Paris moderne, sans ponctuation) et souplesse de la forme","points":5},{"critere":"Procédés relevés avec leur effet : personnification, comparaison, oxymore ou antithèse, énumération","points":6},{"critere":"Paragraphe : transfiguration de la boue en or, sans cacher le laid","points":5},{"critere":"Rôle du flâneur : regard qui capte des instants (femme, pigeons, métro)","points":4}],"dureeMin":17,"corrige":"1. Un poème en **vers libre**, **sans ponctuation** : comme « Zone » (1913) qui ouvre *Alcools* sur un Paris moderne. Cette forme souple suit le désordre et la vitesse de la ville.\n\n2. **Personnification** : « la ville respire elle tousse elle chante » (elle est vivante). **Comparaison** : « le métro comme un dragon avale les visages » (monstre qui dévore). **Antithèse ou oxymore** : « grande nuit en plein jour ». **Énumération** : « respire elle tousse elle chante ».\n\n3. Le poème garde le laid (ferraille, toux, dragon qui avale les visages) mais le **transfigure** : comme Baudelaire qui fait de la boue de l’or, il en tire de la poésie. Le **flâneur** est le poète qui marche et capte l’instant, le rire de la femme, les pigeons, la gare. La poésie de la ville n’embellit pas : elle regarde ce que personne ne regarde et le rend visible."}$exo$::jsonb),
  ('575652f4-6c8a-521c-942e-a10d9c4f3fb9'::uuid, 1, 'redaction', $exo${"titre":"Le roman policier : repères","consigne":"Réponds par des phrases complètes.","enonce":"1. Associe chaque héros ou œuvre à son auteur : (a) Arsène Lupin, (b) le commissaire Maigret, (c) *Le Mystère de la chambre jaune*, (d) Sherlock Holmes.\n   Auteurs : Simenon, Conan Doyle, Leroux, Leblanc.\n2. Quel récit de 1841 est considéré comme le premier récit d’énigme ? Qui l’a écrit ?\n3. Dans quelle ville Sherlock Holmes enquête-t-il ?","bareme":[{"critere":"Quatre associations exactes : (a) Leblanc, (b) Simenon, (c) Leroux, (d) Conan Doyle","points":10},{"critere":"« Double assassinat dans la rue Morgue » de Poe, avec le chevalier Dupin","points":6},{"critere":"Londres","points":4}],"dureeMin":6,"corrige":"1. (a) **Maurice Leblanc** ; (b) **Georges Simenon** ; (c) **Gaston Leroux** ; (d) **Conan Doyle**.\n\n2. « **Double assassinat dans la rue Morgue** » (1841), d’**Edgar Poe**, avec le chevalier Dupin qui résout par la déduction.\n\n3. **Londres**, ville de brouillard et de fiacres."}$exo$::jsonb),
  ('575652f4-6c8a-521c-942e-a10d9c4f3fb9'::uuid, 2, 'redaction', $exo${"titre":"Trois résumés, trois sous-genres","consigne":"Lis les trois résumés (écrits pour l’exercice) et réponds en justifiant.","enonce":"> **Roman 1.** Dans un manoir, un homme est retrouvé mort dans une pièce fermée de l’intérieur. Le détective réunit les invités et démontre, indice après indice, qui est le coupable.\n>\n> **Roman 2.** Dans un port sombre, un détective fatigué découvre que la police, les notables et les patrons du port sont tous corrompus.\n>\n> **Roman 3.** Une jeune femme est poursuivie dans la ville par un tueur ; à chaque chapitre, le danger se resserre.\n\n1. Nomme le sous-genre de chaque roman (roman à énigme, roman noir, thriller) et justifie.\n2. Cite un auteur ou une œuvre du cours pour l’un de ces sous-genres.\n3. Le roman 2 se passe dans un port : de quel apport de la grande ville au roman policier est-ce un exemple ? Cite deux autres choses que la ville fournit.","bareme":[{"critere":"Sous-genres exacts et justifiés : énigme, noir, thriller","points":9},{"critere":"Un auteur ou une œuvre du cours (Leroux, Christie, Chandler, Manchette)","points":3},{"critere":"Le port comme lieu typique (bar, port, gare, terrain vague)","points":3},{"critere":"Deux autres apports de la ville : anonymat, variété sociale, atmosphère","points":5}],"dureeMin":10,"corrige":"1. **Roman 1** : **roman à énigme** : un mystère, des indices, une solution logique. **Roman 2** : **roman noir** : société corrompue, détective désabusé. **Roman 3** : **thriller** : le suspense l’emporte sur l’énigme, on court après le criminel.\n\n2. Exemples : Leroux pour l’énigme (*Le Mystère de la chambre jaune*, crime en chambre close), Chandler ou Manchette pour le roman noir.\n\n3. Le port est un **lieu typique** de la ville (avec le bar, la gare, le terrain vague). La ville fournit aussi l’**anonymat** (on disparaît dans la foule), la **variété sociale** (le crime traverse les milieux) et une **atmosphère** propre au genre."}$exo$::jsonb),
  ('575652f4-6c8a-521c-942e-a10d9c4f3fb9'::uuid, 3, 'redaction', $exo${"titre":"Pourquoi le roman policier naît-il avec la grande ville ?","consigne":"Rédige tes réponses de façon argumentée en t’appuyant sur des dates, des œuvres et des personnages du cours.","enonce":"> **Document (écrit pour l’exercice).** « Une rue de Londres, un soir de brouillard : des passants pressés, des inconnus qui se croisent sans se voir. Dans une chambre, un homme est mort. Personne n’a vu le meurtrier entrer. Le détective, lui, saura lire dans la foule. »\n\n1. Relie ce document à trois dates du cours (1841, 1887, 1907) : que se passe-t-il à chacune ?\n2. Explique en un paragraphe ce que la grande ville apporte au roman policier : anonymat, variété sociale, lieux typiques, atmosphère.\n3. Compare Arsène Lupin et Maigret : de quel côté de la loi se place le héros, et sur quoi reposent les enquêtes ?\n4. Que veut dire la phrase du cours « Maigret n’existe pas hors de Paris » ? Donne ton avis.","bareme":[{"critere":"Trois dates exactes avec le fait associé (Poe, Conan Doyle, Leroux)","points":5},{"critere":"Paragraphe : anonymat, variété sociale, lieux, atmosphère avec exemples","points":6},{"critere":"Comparaison Lupin (voleur héros) et Maigret (atmosphère plus qu’indice)","points":5},{"critere":"Explication et avis justifié sur la phrase du cours","points":4}],"dureeMin":15,"corrige":"1. **1841** : Poe publie « Double assassinat dans la rue Morgue », premier récit d’énigme ; Paris se dote d’une police criminelle moderne. **1887** : Conan Doyle crée Sherlock Holmes dans Londres. **1907** : Gaston Leroux publie *Le Mystère de la chambre jaune*, modèle du crime en chambre close.\n\n2. La foule permet de **disparaître** (anonymat) ; la ville mêle les **milieux sociaux**, donc le crime les traverse ; elle offre des **lieux typiques** (bar, port, gare, terrain vague) et une **atmosphère** (brouillard, nuit). Sans grande ville, le crime n’aurait ni témoin manquant ni décor.\n\n3. **Arsène Lupin** (Leblanc) inverse les rôles : le héros est le **voleur**, gentleman-cambrioleur. **Maigret** (Simenon) est du côté de la police mais ses enquêtes tiennent moins à l’indice qu’à l’**atmosphère** d’un lieu.\n\n4. Chez les meilleurs auteurs, **changer la ville changerait le roman** : Maigret dépend des quartiers, des bistrots et des ambiances de Paris. Tout avis argumenté est accepté."}$exo$::jsonb),
  ('25408f17-a202-5e42-9aaa-740ad9343e15'::uuid, 1, 'redaction', $exo${"titre":"Photographie, cinéma, bande dessinée : les mots de l’image","consigne":"Réponds par des phrases complètes.","enonce":"1. Associe chaque artiste ou œuvre à ce qu’il montre de la ville : (a) Eugène Atget, (b) *Metropolis* (Fritz Lang, 1927), (c) *Les Cités obscures*, de Schuiten et Peeters.\n   Descriptions : 1. une ville verticale, ouvriers sous terre et maîtres au sommet ; 2. le vieux Paris avant sa disparition ; 3. des villes inventées, personnages à part entière.\n2. Définis en une phrase : le cadrage, la contre-plongée, le cartouche.\n3. Que dit le cours du célèbre baiser de l’Hôtel de Ville ? Quelle leçon en tirer ?","bareme":[{"critere":"Trois associations : (a)-2, (b)-1, (c)-3","points":6},{"critere":"Trois définitions justes (ce qu’on garde et exclut, vue d’en bas qui grandit, texte du narrateur)","points":8},{"critere":"Photo mise en scène et leçon : une image « spontanée » ne l’est pas toujours","points":6}],"dureeMin":7,"corrige":"1. (a) Atget = 2 ; (b) *Metropolis* = 1 ; (c) *Les Cités obscures* = 3.\n\n2. Le **cadrage** : le choix de ce que l’image garde et de ce qu’elle exclut. La **contre-plongée** : prise de vue d’en bas, qui grandit le sujet. Le **cartouche** : le texte du narrateur en bande dessinée.\n\n3. Le baiser de l’Hôtel de Ville est une photo **mise en scène**. Leçon : une image qui paraît spontanée ne l’est pas toujours, il faut se demander comment elle a été produite."}$exo$::jsonb),
  ('25408f17-a202-5e42-9aaa-740ad9343e15'::uuid, 2, 'redaction', $exo${"titre":"Lire une planche de bande dessinée","consigne":"Lis la description de la planche (écrite pour l’exercice) et réponds en justifiant.","enonce":"> **La planche.** *Case 1* (très grande, sur toute la largeur) : vue générale d’une ville de tours et de ponts, au petit matin. Cartouche : « Elle ne dormait jamais tout à fait. » *Case 2* (petite) : gros plan sur les yeux d’une jeune femme. *Case 3* (petite) : une porte se referme. *Case 4* (grande) : la même jeune femme, de dos, dans une rue déserte, le bruit d’un train au loin. Entre les cases 3 et 4, on ne voit pas comment elle est sortie de l’immeuble.\n\n1. Nomme l’unité de lecture, la composition d’ensemble, et le texte du narrateur.\n2. Que fait la grande case 1 par rapport aux petites ? Rapproche-la d’une échelle de plan au cinéma.\n3. Qu’est-ce que l’ellipse entre les cases 3 et 4 ? Qui « comble » ce qui manque ?\n4. La ville est-elle un simple décor dans cette planche ? Justifie avec deux éléments.","bareme":[{"critere":"Case, planche, cartouche correctement nommés","points":4},{"critere":"Grande case (situe la ville) et rapprochement avec le plan général","points":5},{"critere":"Ellipse définie et lecteur qui comble","points":5},{"critere":"Ville présente comme personnage : cartouche, ponts et tours, son du train","points":6}],"dureeMin":10,"corrige":"1. L’unité de lecture est la **case** ; la composition d’ensemble est la **planche** ; le texte du narrateur est le **cartouche**.\n\n2. La grande case 1 **situe** la ville et pose l’ambiance ; elle joue comme un **plan général** au cinéma. Les petites cases resserrent sur le détail (yeux, porte), comme des gros plans.\n\n3. L’**ellipse** est ce qu’on ne montre pas entre deux cases : ici la sortie de l’immeuble. C’est le **lecteur** qui comble ce qui manque.\n\n4. Non : la ville est presque un **personnage**. Le cartouche lui prête une vie (« elle ne dormait jamais tout à fait »), l’image de tours et de ponts occupe la plus grande case, et les sons hors champ (le train) la font exister. Ce qui est hors champ compte autant que ce qui est montré."}$exo$::jsonb),
  ('25408f17-a202-5e42-9aaa-740ad9343e15'::uuid, 3, 'redaction', $exo${"titre":"Une même ville en photo, en film et en BD","consigne":"Lis les trois descriptions (écrites pour l’exercice) et rédige tes réponses de façon argumentée.","enonce":"> **Photographie.** Une rue de faubourg au petit matin, vide, des volets clos, une charrette abandonnée. Aucun visage. Photo prise en 1905 et rangée dans un fonds d’archives.\n>\n> **Film.** Un plan-séquence suit un adolescent qui remonte une cité de haut en bas ; on n’entend que le bruit des portes et des pas, aucune musique.\n>\n> **Bande dessinée.** Sur une double page, les cases se resserrent peu à peu autour d’un passant qui se perd dans un dédale de ruelles ; un cartouche dit : « Ici, tout se ressemble. »\n\n1. Pour chacun des trois arts, nomme deux outils du cours qui construisent la vision de la ville (cadrage, angle, plan général, gros plan, travelling, bande-son, case, cartouche, ellipse…).\n2. Quel point commun ces trois documents partagent-ils ? Rappelle la leçon du cours sur le hors-champ.\n3. Rédige un paragraphe : pourquoi la photographie d’Atget est-elle à la fois un document et une œuvre ? Que dit le cours sur la photo « spontanée » ?\n4. Compare l’image de la ville dans le film (banlieue, cité) avec celle de *Metropolis* (ville verticale).","bareme":[{"critere":"Deux outils exacts pour chacun des trois arts","points":6},{"critere":"Point commun : l’absence, le hors-champ compte autant que le montré","points":4},{"critere":"Atget : archive devenue œuvre, avec la nuance sur la photo mise en scène","points":5},{"critere":"Comparaison de la banlieue (La Haine) et de la ville verticale de Metropolis","points":5}],"dureeMin":15,"corrige":"1. **Photo** : le cadrage (rue vide, sans visage) et l’angle de prise de vue. **Film** : le plan-séquence (ou travelling) et la bande-son (portes, pas). **BD** : la taille des cases, le cartouche, l’ellipse.\n\n2. Chacun **suggère** plus qu’il ne montre : une rue vide, un son sans image, des cases qui se resserrent. Ce qui est hors champ compte autant que ce qui est montré.\n\n3. Atget a photographié le vieux Paris **avant sa disparition** : c’est un **document** (une archive) et, par le choix du cadrage et des rues vides, une **œuvre**. Nuance : une photo qui paraît spontanée peut être mise en scène, comme le baiser de l’Hôtel de Ville.\n\n4. *Metropolis* (1927) montre une ville **verticale et divisée** : ouvriers sous terre, maîtres au sommet. *La Haine* (1995) filme la banlieue comme on filmait les quais et les faubourgs : une ville horizontale, périphérique. Les deux disent l’inégalité, l’un par l’espace vertical, l’autre par l’éloignement."}$exo$::jsonb),
  ('47687896-757b-5f82-9a14-52626788c308'::uuid, 1, 'redaction', $exo${"titre":"Zola et le naturalisme : repères","consigne":"Réponds par des phrases complètes.","enonce":"1. Qui a fondé le naturalisme ? Que veut-il appliquer au roman ?\n2. Comment s’appelle le cycle de romans dont fait partie *L’Assommoir* ? Combien de romans compte-t-il, et entre quelles dates ?\n3. Qui est l’héroïne de *L’Assommoir* ? Quel est son métier ?\n4. Que désigne le mot « assommoir » ?","bareme":[{"critere":"Zola et méthode scientifique (hérédité, milieu)","points":5},{"critere":"Les Rougon-Macquart, 20 romans, de 1871 à 1893","points":5},{"critere":"Gervaise Macquart, blanchisseuse","points":5},{"critere":"Un débit d’alcool populaire","points":5}],"dureeMin":6,"corrige":"1. **Émile Zola** ; il veut appliquer au roman la **méthode scientifique** : observer, se documenter, expérimenter, en étudiant l’**hérédité** et le **milieu**.\n\n2. *Les Rougon-Macquart*, **20 romans**, de **1871 à 1893** ; *L’Assommoir* (1877) en est le septième.\n\n3. **Gervaise Macquart**, **blanchisseuse** (et boiteuse).\n\n4. Un **débit d’alcool** populaire (le nom populaire d’un café-bistrot où l’on boit) ; le mot dit aussi ce qui « assomme »."}$exo$::jsonb),
  ('47687896-757b-5f82-9a14-52626788c308'::uuid, 2, 'redaction', $exo${"titre":"Un milieu qui défait une femme","consigne":"Lis le résumé (écrit pour l’exercice, il ne s’agit pas d’une citation de Zola) puis réponds en justifiant.","enonce":"> **Résumé.** Marthe, courageuse lingère, arrive dans un quartier populaire. Elle se marie, ouvre sa boutique et connaît quelques années de bonheur. Puis son mari se blesse en travaillant et cesse de travailler ; il se met à boire, elle s’endette. Peu à peu, la faim, la fatigue et l’alcool la défont. Le narrateur ne la juge jamais : il montre le quartier, les dettes, la boutique du marchand de vin.\n\n1. Ce résumé est-il celui d’un roman réaliste ou naturaliste ? Justifie avec deux éléments qui rappellent *L’Assommoir*.\n2. Le narrateur condamne-t-il Marthe ? Compare avec la position de Zola envers Gervaise.\n3. Pourquoi la langue populaire a-t-elle fait scandale dans *L’Assommoir* ? Où Zola l’a-t-il fait entrer ?\n4. Que veut dire « Histoire naturelle et sociale d’une famille sous le Second Empire » ?","bareme":[{"critere":"Naturalisme justifié : milieu, chute progressive, rôle du bistrot, absence de morale","points":6},{"critere":"Pas de condamnation : le milieu défait une femme courageuse","points":5},{"critere":"Langue populaire jusque dans la narration, pas seulement dans les dialogues","points":5},{"critere":"Sous-titre : hérédité et milieu appliqués à une famille sous le Second Empire","points":4}],"dureeMin":10,"corrige":"1. C’est un roman **naturaliste** : le romancier étudie l’effet du **milieu** (le quartier, la boutique du marchand de vin, la misère) sur une héroïne courageuse, en suivant sa **chute par étapes**, comme dans *L’Assommoir* (mari qui tombe d’un toit et boit, dettes, déchéance).\n\n2. Non : le narrateur **ne juge pas**. Zola ne condamne pas Gervaise, il montre comment le milieu défait une femme courageuse.\n\n3. Zola fait entrer dans le roman la **langue du peuple** (argot, familiarités, tournures orales), **y compris dans la narration**, et pas seulement dans les dialogues : c’est cette audace qui a choqué.\n\n4. Le sous-titre annonce une étude **scientifique** (« naturelle ») et **sociale** d’une même famille sur plusieurs générations : hérédité et milieu, sous le Second Empire."}$exo$::jsonb),
  ('47687896-757b-5f82-9a14-52626788c308'::uuid, 3, 'redaction', $exo${"titre":"Réalisme ou naturalisme ? Défendre une lecture","consigne":"Lis le texte (écrit pour l’exercice, il ne s’agit pas d’une citation de Zola) et rédige tes réponses de façon argumentée.","enonce":"> Cette année-là, dans la rue étroite, toutes les fenêtres s’ouvraient sur des cours où les enfants jouaient dans la boue. Les hommes rentraient à la nuit, et l’argent de la paie, on le retrouvait le samedi soir chez le marchand de vin, quatre sous par quatre sous. Chez les Bertin, on ne s’était pas mis à boire d’un coup : on s’était dit qu’on prendrait un verre en revenant de l’atelier, comme tout le monde.\n>\n> *(Texte écrit pour l’exercice, à la manière d’un roman naturaliste.)*\n\n1. Relève trois éléments qui montrent que le milieu détermine le destin des personnages.\n2. Distingue le réalisme (Balzac, Flaubert, Maupassant) et le naturalisme (Zola) : que veut faire le second de plus que le premier ?\n3. Le romancier naturaliste « observe et expérimente » : explique cette formule et cite le titre de l’essai de Zola qui la contient.\n4. Rédige un paragraphe : pourquoi *L’Assommoir* a-t-il fait scandale, et pourquoi n’est-ce pas un livre qui « condamne » ses personnages ?","bareme":[{"critere":"Trois éléments du milieu (rue, cours, paie chez le marchand de vin, habitude du verre)","points":5},{"critere":"Distinction réalisme (peindre tel qu’il est) et naturalisme (méthode scientifique, hérédité et milieu)","points":5},{"critere":"Formule « observateur et expérimentateur » et titre : Le Roman expérimental","points":4},{"critere":"Paragraphe sur le scandale (langue populaire dans la narration, complaisance dans la misère) et l’absence de condamnation","points":6}],"dureeMin":17,"corrige":"1. Le **milieu** : la rue étroite et les cours boueuses ; la paie qui va **chez le marchand de vin** ; la **habitude** du verre en sortant de l’atelier « comme tout le monde ». Le destin des Bertin n’est pas un choix isolé, il est produit par leur environnement.\n\n2. Le **réalisme** peint le réel tel qu’il est, sans idéaliser. Le **naturalisme** applique en plus au roman la **méthode scientifique** : le romancier observe, se documente, expérimente, et étudie l’effet de l’**hérédité** et du **milieu**.\n\n3. Dans *Le Roman expérimental*, Zola écrit que le romancier est « un observateur et un expérimentateur » : il observe la réalité, puis place ses personnages dans une situation pour voir comment le milieu agit sur eux.\n\n4. Le livre a fait scandale parce que Zola fait entrer la **langue du peuple**, argot compris, jusque dans la **narration**, et parce qu’on l’a accusé de complaisance dans la misère (il fut aussi son plus grand succès de librairie). Mais il ne condamne pas : il **montre** un mécanisme, comme un chercheur montre les conditions d’une expérience. Le narrateur ne juge pas Gervaise, il explique comment le milieu défait une femme courageuse."}$exo$::jsonb),
  ('5f0dd17a-731e-58c2-b628-990bc5b014c7'::uuid, 1, 'redaction', $exo${"titre":"La Parure : l’histoire et la chute","consigne":"Réponds par des phrases complètes.","enonce":"1. Quel bijou Mathilde emprunte-t-elle, et à qui ?\n2. Combien de temps le couple met-il à rembourser la parure de remplacement ?\n3. Quelle est la chute de la nouvelle ? Rappelle la phrase de Madame Forestier.\n4. Qui a réalisé l’adaptation de 2007 ? Dans quelle collection ?","bareme":[{"critere":"Une rivière de diamants, à Madame Forestier","points":5},{"critere":"Dix ans","points":4},{"critere":"Chute : la parure empruntée était fausse, la phrase « la mienne était fausse… cinq cents francs »","points":7},{"critere":"Claude Chabrol, collection Chez Maupassant","points":4}],"dureeMin":6,"corrige":"1. Une **rivière de diamants**, empruntée à son amie **Madame Forestier**.\n\n2. **Dix ans** de sacrifices.\n\n3. La chute : la parure empruntée était **fausse**. Madame Forestier dit : « Oh ! ma pauvre Mathilde ! Mais la mienne était fausse. Elle valait au plus cinq cents francs !… »\n\n4. **Claude Chabrol**, en 2007, pour la télévision, dans la collection *Chez Maupassant*."}$exo$::jsonb),
  ('5f0dd17a-731e-58c2-b628-990bc5b014c7'::uuid, 2, 'redaction', $exo${"titre":"Le récit et ses procédés","consigne":"Lis le résumé (écrit pour l’exercice) et réponds en justifiant.","enonce":"> **Résumé.** Mathilde Loisel, jolie femme d’un petit employé de ministère, souffre de sa condition modeste. Invitée à un bal, elle emprunte une rivière de diamants à son amie et triomphe. Au retour, la parure a disparu ; le couple achète une parure identique pour 36 000 francs. Il faut dix ans pour rembourser : Mathilde renvoie la bonne, lave, marchande, vieillit. Un jour, elle croise son amie et lui avoue tout. La révélation tombe : la parure était fausse.\n\n1. Quel type de narrateur Maupassant emploie-t-il et pourquoi rapporte-t-il « sans commenter » ?\n2. Que produit l’ellipse des dix années ? Que perdrait-on dans un roman ?\n3. En quoi la chute est-elle « préparée » ? Donne deux indices du cours.\n4. Que dénonce la nouvelle ? Est-ce la fatalité qui frappe Mathilde ?","bareme":[{"critere":"Narrateur externe, 3e personne, sans commenter","points":4},{"critere":"Ellipse : dix ans condensés en un paragraphe, accélération","points":5},{"critere":"Deux indices préparant la chute (boîte qui n’est pas d’origine, bijoutier qui ne reconnaît pas la parure)","points":5},{"critere":"Poids des apparences et hasard, non fatalité","points":6}],"dureeMin":10,"corrige":"1. Un **narrateur externe**, à la troisième personne. Il **rapporte sans commenter** : le lecteur juge lui-même, ce qui rend la chute plus cruelle.\n\n2. L’**ellipse** condense dix ans en un paragraphe : la nouvelle **accélère** là où un roman s’attarderait, et fait sentir la durée de la punition sans la détailler.\n\n3. La chute est **préparée** : la boîte de l’écrin n’est pas d’origine ; le bijoutier ne reconnaît pas la parure. À la relecture, les indices étaient là.\n\n4. La nouvelle dénonce le **poids des apparences** dans une société où le rang se joue au regard des autres, et la **disproportion** entre une faute minuscule et sa punition. Ce n’est pas la fatalité qui frappe : c’est le **hasard**, qui n’a pas de justice à rendre."}$exo$::jsonb),
  ('5f0dd17a-731e-58c2-b628-990bc5b014c7'::uuid, 3, 'redaction', $exo${"titre":"De la nouvelle au film : ce que gagne et perd l’adaptation","consigne":"Lis les deux passages (écrits pour l’exercice, ils imitent la nouvelle) et rédige tes réponses de façon argumentée.","enonce":"> **A. Dans la nouvelle (résumé).** « Pendant dix ans, le couple s’épuisa. Mathilde connut les gros travaux du ménage. » Un seul paragraphe, sans dialogue.\n>\n> **B. Dans le film (description).** Le film montre des scènes successives : Mathilde frotte le linge dans une eau glacée, les mains rougies ; elle négocie un loyer avec le propriétaire ; la lumière est grise, le logement étroit et sombre.\n\n1. Que montre l’écart entre A et B sur l’ellipse ? Quel effet obtient Maupassant, et quel effet le film ?\n2. Complète un tableau à deux colonnes : « ce que la caméra ajoute » (au moins deux éléments) et « ce qu’elle perd » (au moins deux éléments).\n3. Rédige un paragraphe : quelle lecture de Mathilde chacune des deux formes favorise-t-elle ? Appuie-toi sur le narrateur externe, sur la chute et sur le poids des apparences.","bareme":[{"critere":"Effet de l’ellipse dans la nouvelle (accélération, mise en valeur de la chute) et durée réelle du film","points":5},{"critere":"Ce que la caméra ajoute (décors, lumière, mesquinerie, corps, costume, durée réelle)","points":4},{"critere":"Ce qu’elle perd (le discours du narrateur, l’ellipse instantanée)","points":4},{"critere":"Paragraphe : narrateur silencieux et chute dans le texte ; corps et durée dans le film ; apparences","points":7}],"dureeMin":16,"corrige":"1. Dans la nouvelle, l’**ellipse** condense dix ans en un paragraphe : l’effet est celui d’une accélération, la chute n’en est que plus brutale. Le film, lui, doit **montrer** : il installe la **durée réelle** de la punition.\n\n2. **Ce que la caméra ajoute** : les décors, la lumière, la mesquinerie des logements, le corps et le costume de Mathilde, la durée réelle. **Ce qu’elle perd** : le discours du narrateur, l’ellipse instantanée (dix ans en une phrase).\n\n3. Dans la nouvelle, le **narrateur externe** rapporte sans commenter : le lecteur juge seul, et la **chute** (la parure était fausse) retourne le sens de tout ce qui précède. Le film fait éprouver le poids des dix ans par le corps, la lumière, les mains rougies : on ressent la peine plus qu’on ne la comprend. Dans les deux cas, on voit le **poids des apparences** : c’est pour paraître riche pendant une soirée que Mathilde paie pendant dix ans. Chaque forme éclaire un aspect : le texte l’ironie et la construction, le film la matérialité de la déchéance."}$exo$::jsonb),
  ('b02b1c1e-c59d-57e1-89d8-f06af97b87f2'::uuid, 1, 'redaction', $exo${"titre":"Le fantastique : distinguer trois genres","consigne":"Réponds par des phrases complètes.","enonce":"Voici trois courts récits (écrits pour l’exercice).\n\n> **Récit 1.** Une fée offre trois vœux à une jeune fille ; personne ne s’en étonne.\n> **Récit 2.** Dans une maison ordinaire, un homme entend chaque nuit un bruit de pas. Il se demande s’il est fou ou si la maison est hantée.\n> **Récit 3.** Un vaisseau spatial traverse une galaxie ; les phénomènes étranges sont expliqués par une théorie scientifique.\n\n1. Nomme le genre de chaque récit (fantastique, merveilleux, science-fiction) et justifie.\n2. Selon le cours, quelle est la « marque » du fantastique ?","bareme":[{"critere":"Trois genres correctement identifiés","points":9},{"critere":"Justification de chaque choix (va de soi / hésitation / expliqué par la science)","points":6},{"critere":"L’hésitation entre explication rationnelle et surnaturel","points":5}],"dureeMin":6,"corrige":"1. **Récit 1** : **merveilleux** : le surnaturel va de soi, comme dans un conte. **Récit 2** : **fantastique** : le surnaturel fait irruption dans un cadre réaliste et on hésite (folie ou hantise ?). **Récit 3** : **science-fiction** : l’étrange est expliqué par la science.\n\n2. La marque du fantastique est l’**hésitation** entre une explication rationnelle et le surnaturel. Un récit qui tranche cesse d’être fantastique."}$exo$::jsonb),
  ('b02b1c1e-c59d-57e1-89d8-f06af97b87f2'::uuid, 2, 'redaction', $exo${"titre":"La Chute de la maison Usher : les personnages et le cadre","consigne":"Lis le résumé (écrit pour l’exercice) et réponds en justifiant.","enonce":"> **Résumé.** Appelé au chevet de son ami d’enfance Roderick Usher, le narrateur découvre une maison lézardée au bord d’un étang noir. Roderick, hypersensible, est terrifié par les sons, les lumières et les odeurs ; sa sœur jumelle Madeline est mourante. Elle meurt, on l’enferme dans un caveau. Elle reparaît, enterrée vivante, et entraîne son frère dans la mort. La maison se fend et sombre dans l’étang.\n\n1. Présente les trois personnages : le narrateur, Roderick, Madeline.\n2. Relève trois éléments du cadre et dis leur effet sur le lecteur.\n3. Quel est le rôle du narrateur interne, témoin ? Pourquoi peut-on douter de lui ?\n4. Explique le double sens du titre (« chute de la maison »).","bareme":[{"critere":"Trois personnages présentés exactement (ami d’enfance anonyme, dernier héritier hypersensible, sœur jumelle)","points":5},{"critere":"Trois éléments du cadre (maison lézardée, étang noir, nuit, tempête) et effet","points":5},{"critere":"Rôle du narrateur interne et raison du doute","points":5},{"critere":"Double sens : le bâtiment et la lignée (house)","points":5}],"dureeMin":10,"corrige":"1. Le **narrateur** est un ami d’enfance dont on ne saura pas le nom ; **Roderick Usher** est le dernier héritier d’une famille éteinte, hypersensible ; **Madeline** est sa sœur **jumelle**.\n\n2. Une **maison lézardée**, un **étang noir**, la nuit et la tempête : un cadre isolé et décrépit qui installe l’angoisse.\n\n3. Le **narrateur interne** est un témoin qui raconte ce qu’il perçoit ; on peut **douter de lui**, car il ne voit qu’une partie des faits et peut être influencé par l’atmosphère : le doute reste ouvert.\n\n4. La « chute » de la maison Usher désigne autant le **bâtiment** qui s’effondre que la **lignée** qui s’éteint : la langue anglaise dit *house* pour les deux."}$exo$::jsonb),
  ('b02b1c1e-c59d-57e1-89d8-f06af97b87f2'::uuid, 3, 'redaction', $exo${"titre":"Un texte fantastique à analyser","consigne":"Lis l’extrait (écrit pour l’exercice, à la manière du fantastique) et rédige tes réponses de façon argumentée.","enonce":"> Je crus entendre, au-dessus de moi, comme un léger froissement d’étoffe. Peut-être n’était-ce que le vent qui courait dans les combles. La lampe, il me sembla, vacilla plus qu’il n’eût fallu. Au dehors, la tempête faisait craquer les vieux murs, et les fissures de la façade s’élargissaient à mesure que la nuit avançait. Mon hôte, blême, demeurait immobile, les yeux fixés sur la porte comme s’il attendait quelqu’un.\n>\n> *(Texte écrit pour l’exercice, il ne s’agit pas d’un passage de Poe.)*\n\n1. Relève trois modalisateurs. Que produisent-ils sur l’interprétation de la scène ?\n2. Relève deux éléments du cadre et le lexique de l’étrange ou de la peur. Comment progresse l’angoisse (gradation) ?\n3. Quelle correspondance le texte établit-il entre la maison et son habitant ? Retrouve-la dans la nouvelle de Poe.\n4. Rédige un paragraphe : pourquoi ce passage est-il fantastique et non merveilleux ni de science-fiction ?","bareme":[{"critere":"Trois modalisateurs (« Je crus », « comme », « Peut-être », « il me sembla », « comme si ») et doute maintenu","points":5},{"critere":"Cadre, lexique de l’étrange et gradation (froissement, vacillement, fissures, immobile)","points":5},{"critere":"Correspondance maison / habitant (fissures qui s’élargissent, hôte blême) rapprochée de Poe","points":4},{"critere":"Paragraphe : irruption dans un cadre réaliste, hésitation, absence d’explication scientifique","points":6}],"dureeMin":16,"corrige":"1. « Je **crus** entendre », « **comme** un léger froissement », « **Peut-être** n’était-ce que le vent », « il **me sembla** », « **comme si** il attendait » : les modalisateurs laissent le **doute ouvert** entre une explication naturelle (le vent) et une présence surnaturelle.\n\n2. Cadre : la tempête, les vieux murs, la façade fissurée, la nuit. Lexique de l’étrange : froissement, vacillement, blême, immobile. **Gradation** : on passe d’un léger bruit à la lampe qui vacille, puis aux fissures qui s’élargissent : l’angoisse monte progressivement.\n\n3. Les **fissures** de la maison s’élargissent tandis que son habitant est **blême et tendu** : la maison et l’hôte se défont ensemble. Chez Poe, la maison et Roderick se fissurent en même temps et s’effondrent au même instant.\n\n4. Le passage est **fantastique** : l’étrange fait **irruption dans un cadre réaliste** (une maison, une lampe, le vent) et on **hésite** (vent ou présence ?). Il n’est pas **merveilleux** (le surnaturel n’y va pas de soi) ni de **science-fiction** (aucune explication scientifique)."}$exo$::jsonb),
  ('a5ca98d8-8b8f-5cfa-b1e9-d855937fa78f'::uuid, 1, 'redaction', $exo${"titre":"La poésie lyrique : repères","consigne":"Réponds par des phrases complètes.","enonce":"1. D’où vient le mot « lyrique » ? Que signifie-t-il à l’origine ?\n2. Associe chaque poète à un poème ou à un vers du cours : Ronsard, Apollinaire, Éluard, Aragon.\n   Poèmes : « Liberté » ; « Le Pont Mirabeau » ; « Les Yeux d’Elsa » ; « Mignonne, allons voir si la rose… ».\n3. Combien de vers compte un sonnet ? Comment sont-ils répartis ?","bareme":[{"critere":"Lyre, poésie qui se chantait, exprimant les sentiments personnels","points":6},{"critere":"Quatre associations : Ronsard-Mignonne, Apollinaire-Le Pont Mirabeau, Éluard-Liberté, Aragon-Les Yeux d’Elsa","points":8},{"critere":"14 vers, deux quatrains et deux tercets","points":6}],"dureeMin":6,"corrige":"1. De la **lyre**, instrument des poètes grecs : la poésie lyrique se **chantait** et exprime les **sentiments personnels** du poète.\n\n2. Ronsard : « Mignonne, allons voir si la rose… » ; Apollinaire : « Le Pont Mirabeau » ; Éluard : « Liberté » ; Aragon : « Les Yeux d’Elsa ».\n\n3. **14 vers** : deux quatrains et deux tercets."}$exo$::jsonb),
  ('a5ca98d8-8b8f-5cfa-b1e9-d855937fa78f'::uuid, 2, 'redaction', $exo${"titre":"Reconnaître le lyrisme","consigne":"Lis le poème (écrit pour l’exercice) et réponds en justifiant.","enonce":"> Ô nuit, garde ma peine !\n> Je t’aime, et tu ne viens pas.\n> Le temps s’enfuit, l’heure est vaine\n> De courir loin de mes bras…\n> Reviens ! ta voix, ma lumière,\n> Ta main, mon ciel, mes hivers,\n> Je voudrais, comme la mer,\n> T’étreindre avant la poussière.\n>\n> *(Poème écrit pour l’exercice.)*\n\n1. Relève trois marques du lyrisme (première personne, apostrophe, ponctuation expressive, champ lexical du sentiment, images).\n2. Quel thème se mêle à celui de l’amour ? Par quels mots ?\n3. Ce poème est-il un sonnet ? Justifie. Quelle forme se rapproche d’un poème de plainte ?\n4. Quel poète de la Pléiade a écrit un vers célèbre sur le temps qui passe et l’amour ?","bareme":[{"critere":"Trois marques du lyrisme relevées et nommées","points":6},{"critere":"Thème du temps : « Le temps s’enfuit », « avant la poussière »","points":4},{"critere":"Pas un sonnet (8 vers) et élégie","points":5},{"critere":"Ronsard et « Mignonne, allons voir si la rose… »","points":5}],"dureeMin":10,"corrige":"1. **Première personne** (« je t’aime », « mes bras ») ; **apostrophe** (« Ô nuit », « Reviens ! ») ; **ponctuation expressive** (exclamations, points de suspension) ; comparaison (« comme la mer »).\n\n2. Le **temps** : « Le temps s’enfuit », « avant la poussière » : dire l’amour, c’est aussi dire le temps.\n\n3. Non : ce n’est pas un sonnet, qui compte **14 vers** (deux quatrains, deux tercets) ; ici il y en a **huit**. L’**élégie** est le poème de la plainte.\n\n4. **Ronsard**, avec « Mignonne, allons voir si la rose… »."}$exo$::jsonb),
  ('a5ca98d8-8b8f-5cfa-b1e9-d855937fa78f'::uuid, 3, 'redaction', $exo${"titre":"Du chant antique au vers libre : un parcours lyrique","consigne":"Lis le poème (écrit pour l’exercice) et rédige tes réponses de façon argumentée.","enonce":"> Sans ponctuation\n> tu passes\n> je ne sais plus si je t’appelle ou si je pleure\n> ô mon absente ô ma saison ô mon printemps refusé\n> l’heure sonne la rose se ferme\n> et je garde ton nom comme un feu sous la cendre\n>\n> *(Poème en vers libre écrit pour l’exercice.)*\n\n1. Repère quatre marques du lyrisme dans ce poème et nomme-les.\n2. En quoi la forme (vers libre, absence de ponctuation) rapproche-t-elle ce poème des poètes du XXe siècle (Apollinaire, Éluard, Aragon) ? Que devient l’ancien modèle du sonnet ?\n3. Rédige un paragraphe : comment ce poème lie-t-il l’amour et le temps ? Rapproche-le de Ronsard.\n4. Situe les grandes étapes du lyrisme : associe Sappho, les troubadours, la Pléiade, le romantisme et le XXe siècle à une innovation.","bareme":[{"critere":"Quatre marques : je, apostrophe, champ lexical, images, exclamations","points":5},{"critere":"Vers libre et absence de ponctuation comme renouvellement de la forme","points":4},{"critere":"Paragraphe sur l’amour et le temps avec rapprochement de Ronsard (rose, temps qui passe)","points":6},{"critere":"Repères historiques : cinq associations correctes","points":5}],"dureeMin":16,"corrige":"1. **Première personne** (« je t’appelle », « je garde ») ; **apostrophe** (« ô mon absente ô ma saison… ») ; **champ lexical du sentiment** (pleure, absente, nom) ; **images** (« comme un feu sous la cendre », métaphore de la saison, comparaison).\n\n2. Le **vers libre** et l’absence de ponctuation renouvellent la forme, comme chez Apollinaire, Éluard, Aragon au XXe siècle : la contrainte du sonnet (14 vers, rimes) est abandonnée au profit d’un rythme libre.\n\n3. « l’heure sonne la rose se ferme » dit la fuite du temps ; l’amour est celui d’une absente : le temps est le **compagnon obligé** du sentiment amoureux. Chez Ronsard (« Mignonne, allons voir si la rose… »), la rose qui se fane invite à aimer avant que la beauté passe.\n\n4. **Sappho** (VIe s. av. J.-C.) dit le trouble amoureux ; les **troubadours** inventent l’amour courtois ; la **Pléiade** (Ronsard, Louise Labé) adopte le sonnet de Pétrarque ; le **romantisme** (Lamartine, Hugo, Musset) ; le **XXe siècle** (Apollinaire, Éluard, Aragon) renouvelle la forme."}$exo$::jsonb),
  ('e44539ef-c1f1-509f-bb81-3f1246281327'::uuid, 1, 'redaction', $exo${"titre":"« Demain, dès l’aube… » : le contexte et la forme","consigne":"Réponds par des phrases complètes.","enonce":"1. Qui est Léopoldine ? Comment est-elle morte et en quelle année ?\n2. Dans quel recueil figure ce poème ? En quelle année ce recueil paraît-il ?\n3. Quelle est la forme du poème (nombre de strophes, de vers, type de rimes) ?\n4. Quel mot du dernier vers révèle le vrai sujet du poème ?","bareme":[{"critere":"Léopoldine, fille de Hugo, noyée à Villequier en septembre 1843","points":6},{"critere":"Les Contemplations, 1856","points":4},{"critere":"Trois quatrains d’alexandrins, rimes croisées ABAB","points":6},{"critere":"Le mot « tombe » (ou le bouquet sur la tombe)","points":4}],"dureeMin":6,"corrige":"1. **Léopoldine** est la fille de Victor Hugo ; elle se noie à 19 ans dans la Seine, à **Villequier**, en septembre **1843**.\n\n2. Dans **Les Contemplations**, publié en **1856**.\n\n3. **Trois quatrains** d’**alexandrins**, en **rimes croisées** (ABAB), une forme simple, presque nue.\n\n4. Le mot « **tombe** » (« je mettrai sur ta tombe… ») : il change le sens de tout le poème."}$exo$::jsonb),
  ('e44539ef-c1f1-509f-bb81-3f1246281327'::uuid, 2, 'redaction', $exo${"titre":"Un poème qui se relit","consigne":"Lis le poème (domaine public), puis réponds en citant.","enonce":"> Demain, dès l’aube, à l’heure où blanchit la campagne,\n> Je partirai. Vois-tu, je sais que tu m’attends.\n> J’irai par la forêt, j’irai par la montagne.\n> Je ne puis demeurer loin de toi plus longtemps.\n>\n> Je marcherai les yeux fixés sur mes pensées,\n> Sans rien voir au dehors, sans entendre aucun bruit,\n> Seul, inconnu, le dos courbé, les mains croisées,\n> Triste, et le jour pour moi sera comme la nuit.\n>\n> Je ne regarderai ni l’or du soir qui tombe,\n> Ni les voiles au loin descendant vers Harfleur,\n> Et quand j’arriverai, je mettrai sur ta tombe\n> Un bouquet de houx vert et de bruyère en fleur.\n>\n> — Victor Hugo, *Les Contemplations* (1856)\n\n1. À quel temps sont conjugués la plupart des verbes ? Quel effet produit-il ?\n2. Relève deux indices de la deuxième strophe qui annoncent la tristesse avant le dernier vers.\n3. Comment lit-on le poème avant et après le mot « tombe » ?\n4. Explique l’antithèse finale : « houx vert » et « bruyère en fleur ».","bareme":[{"critere":"Futur de la certitude, voyage inéluctable","points":4},{"critere":"Deux indices de la strophe 2 (yeux fixés, sans rien voir, dos courbé, « le jour comme la nuit ») cités","points":5},{"critere":"Lecture d’un poème d’amour puis d’un poème de deuil : relecture","points":6},{"critere":"Antithèse : houx persistant et piquant, bruyère fragile, fidélité et deuil","points":5}],"dureeMin":10,"corrige":"1. Le **futur** (« Je partirai », « Je marcherai ») : le **futur de la certitude** rend le voyage inéluctable, tourné vers un seul geste.\n\n2. « Les yeux fixés sur mes pensées », « Sans rien voir au dehors », « le dos courbé », « le jour pour moi sera comme la nuit » : l’homme est replié, fermé au monde, endeuillé (on accepte aussi « Triste »).\n\n3. Avant, on croit lire un **poème d’amour** (« je sais que tu m’attends ») ; le mot **« tombe »** renverse tout et on **relit** le poème comme un poème de **deuil**.\n\n4. Le **houx** est persistant et piquant, la **bruyère en fleur** est fragile : fidélité et souffrance d’un côté, fragilité de la vie de l’autre. **Fidélité et deuil dans un même bouquet.**"}$exo$::jsonb),
  ('e44539ef-c1f1-509f-bb81-3f1246281327'::uuid, 3, 'redaction', $exo${"titre":"Le non-dit d’un poème : commentaire","consigne":"Appuie-toi sur le texte du poème (domaine public) rappelé ci-dessous, puis rédige tes réponses de façon argumentée.","enonce":"> Je marcherai les yeux fixés sur mes pensées,\n> Sans rien voir au dehors, sans entendre aucun bruit,\n> Seul, inconnu, le dos courbé, les mains croisées,\n> Triste, et le jour pour moi sera comme la nuit.\n>\n> Je ne regarderai ni l’or du soir qui tombe,\n> Ni les voiles au loin descendant vers Harfleur,\n> Et quand j’arriverai, je mettrai sur ta tombe\n> Un bouquet de houx vert et de bruyère en fleur.\n>\n> — Victor Hugo, « Demain, dès l’aube… », *Les Contemplations* (strophes 2 et 3)\n\n1. Relève deux procédés de la strophe 2 (futur, anaphore, négations) et explique leur effet.\n2. Que révèle le poème sur la douleur du père ? Pourquoi le poème ne dit-il jamais les mots « fille » ni « mort » ?\n3. Rédige un paragraphe : comment Hugo construit-il un effet de chute ? Appuie-toi sur le mouvement des trois strophes (annonce, voyage, arrivée) et sur la retenue.\n4. Pourquoi peut-on dire que les indices étaient là dès la première lecture ?","bareme":[{"critere":"Deux procédés identifiés avec leur effet (futur de la certitude, anaphore du « je », négations « ni… ni »)","points":5},{"critere":"Retenue : la douleur dite sans les mots « fille » ni « mort »","points":4},{"critere":"Paragraphe : annonce du départ, voyage replié, arrivée et chute sur « tombe »","points":7},{"critere":"Indices présents dès la lecture : yeux baissés, refus de voir l’or du soir, dos tourné au monde","points":4}],"dureeMin":17,"corrige":"1. **Futur de la certitude** (« je marcherai », « je ne regarderai ») : le voyage est inéluctable. **Négations** (« sans rien voir… », « ni l’or du soir… ni les voiles… ») : elles disent le refus de regarder le monde, l’homme fermé sur sa douleur. **Anaphore** du « je » : le poème est tourné vers un seul geste.\n\n2. Le père est **replié** sur sa douleur (« seul, inconnu, le dos courbé ») ; le poème ne dit jamais « fille » ni « mort ». C’est cette **retenue** qui le rend bouleversant : le lecteur comprend seul.\n\n3. La **strophe 1** annonce le départ ; la **strophe 2** montre le voyage replié ; la **strophe 3** amène l’arrivée et la **chute** : « tombe ». Pendant onze vers, on croit lire un poème d’amour ; un seul mot renverse tout et on **relit** le poème autrement. La retenue accroît l’effet de surprise.\n\n4. Les indices étaient là : les **yeux baissés**, le refus de voir l’**or du soir**, le **dos tourné au monde**. On ne les comprend qu’à la **relecture**."}$exo$::jsonb),
  ('77d56b69-676a-5c71-93dc-e13260eee0ca'::uuid, 1, 'redaction', $exo${"titre":"La tragédie classique : les règles","consigne":"Réponds par des phrases complètes.","enonce":"1. Que sont les trois unités ? Énonce-les.\n2. Que veut dire « bienséance » ? Où se passent alors la violence et la mort ?\n3. Quelle forme de vers et quelle fin sont propres à la tragédie classique ?\n4. Selon Aristote, que produit la catharsis chez le spectateur ?","bareme":[{"critere":"Trois unités : action, lieu, jour","points":6},{"critere":"Bienséance : ni sang ni violence ni mort sur scène, on les raconte","points":5},{"critere":"Alexandrin en rimes plates et fin malheureuse","points":4},{"critere":"Catharsis : purger les passions par la terreur et la pitié","points":5}],"dureeMin":6,"corrige":"1. **Une seule action, en un seul lieu, en une seule journée.**\n\n2. La **bienséance** interdit de montrer sur scène le sang, la violence et la mort devant le public : on les **raconte**.\n\n3. L’**alexandrin** en **rimes plates** et une **fin malheureuse**.\n\n4. La **catharsis** purge les passions du spectateur par la **terreur** et la **pitié**."}$exo$::jsonb),
  ('77d56b69-676a-5c71-93dc-e13260eee0ca'::uuid, 2, 'redaction', $exo${"titre":"Bérénice : l’amour contre le devoir","consigne":"Lis le résumé (écrit pour l’exercice) et réponds en justifiant.","enonce":"> **Résumé.** À Rome, Titus, devenu empereur, aime Bérénice, reine de Palestine. Mais Rome interdit à son empereur d’épouser une reine étrangère. Titus renonce, Bérénice part. Antiochus, roi de Comagène et ami de Titus, qui aimait Bérénice en silence, reste seul. Personne ne meurt.\n\n1. Présente les trois personnages et dis ce qu’ils désirent.\n2. Quel est le conflit tragique ? Pourquoi peut-on parler d’« impasse » pour Titus ?\n3. « Personne ne meurt » : pourquoi cette pièce est-elle pourtant une tragédie ? Appuie-toi sur la préface de Racine (« il suffit que l’action en soit grande »).\n4. Quelle règle classique est respectée quand la mort n’est pas montrée ? Et quel est le dernier mot de la pièce ?","bareme":[{"critere":"Trois personnages présentés avec leur désir","points":5},{"critere":"Conflit amour contre devoir, et impasse : quel que soit son choix, il perd","points":5},{"critere":"Tragédie sans mort : triple renoncement, action grande (préface)","points":6},{"critere":"Bienséance / rang élevé, et le mot « Hélas ! »","points":4}],"dureeMin":10,"corrige":"1. **Titus** aime Bérénice mais doit obéir à Rome ; **Bérénice**, reine de Palestine, aime Titus ; **Antiochus**, roi de Comagène, aime Bérénice en silence et reste l’ami de Titus.\n\n2. Le conflit est **l’amour contre le devoir** : la passion personnelle contre la loi de Rome. Titus est dans une impasse : s’il épouse Bérénice il trahit Rome, s’il renonce il perd celle qu’il aime.\n\n3. La pièce s’achève sur un **triple renoncement** ; le malheur est complet sans mort, ce qui est tragique. Racine écrit que « ce n’est point une nécessité qu’il y ait du sang et des morts » ; il suffit que « l’action en soit grande ».\n\n4. La **bienséance** (pas de violence sur scène) ; on peut aussi citer le rang élevé des personnages. Le dernier mot est « **Hélas !** »."}$exo$::jsonb),
  ('77d56b69-676a-5c71-93dc-e13260eee0ca'::uuid, 3, 'redaction', $exo${"titre":"Tragique, dramatique : analyse d’un dilemme","consigne":"Lis le texte (écrit pour l’exercice, pas de Racine) et rédige tes réponses de façon argumentée.","enonce":"> **Scène imaginée pour l’exercice, à la manière d’une tragédie classique.** Le roi Alcée aime Iris, princesse d’un peuple ennemi. Ses conseillers exigent qu’il renonce à elle pour sauver la paix. Le roi dit à Iris : « Je vous perds, je m’en vais ; le royaume l’exige. » Iris répond : « Allez donc. » Puis le roi se retire ; la scène s’achève. On apprend seulement par un récit que la princesse a quitté la ville.\n\n1. Quelles règles de la tragédie classique reconnais-tu dans cette scène (rang des personnages, bienséance, récit, forme) ? Cite deux éléments.\n2. Rapproche cette situation de celle de *Bérénice* : mêmes ressorts, mêmes différences.\n3. Rédige un paragraphe : qu’est-ce qui fait qu’une situation est *tragique* (et non seulement *dramatique*) ? Définis chaque terme et illustre avec Bérénice.\n4. En quoi la simplicité de la langue de Racine convient-elle à cette situation ?","bareme":[{"critere":"Deux règles reconnues (rang élevé, bienséance et récit, vers noble)","points":5},{"critere":"Rapprochement avec Bérénice : amour contre devoir, renoncement, départ","points":5},{"critere":"Paragraphe : héros sans issue, quel que soit son choix il perd ; dramatique = grave mais avec issue","points":6},{"critere":"Langue simple, vocabulaire restreint, musicalité, retenue","points":4}],"dureeMin":15,"corrige":"1. **Rang élevé** : un roi, une princesse ; **bienséance** : le départ est raconté, rien n’est montré ; on accepte aussi le renoncement sans sang, la vraisemblance, et la fin malheureuse.\n\n2. Mêmes ressorts : un souverain amoureux d’une étrangère, la raison d’État qui exige le renoncement, un départ. Différence possible : ici la scène est brève et imaginaire, alors que *Bérénice* compte un troisième personnage (Antiochus) et une action portée par cinq actes.\n\n3. Un héros **tragique** n’a **aucune issue** : quel que soit son choix, il perd. Une situation **dramatique** est grave mais peut avoir une issue. Titus doit choisir entre l’amour et Rome : il perd dans les deux cas.\n\n4. Racine emploie une langue **simple**, un vocabulaire volontairement **restreint**, une musicalité fondée sur les sonorités : la simplicité laisse toute la place à la douleur, sans effet de cris ; c’est la **retenue** qui émeut (le dernier mot de la pièce est « Hélas ! »)."}$exo$::jsonb),
  ('35a5afc0-a4ac-5dd2-b136-d64c98aaaf75'::uuid, 1, 'redaction', $exo${"titre":"La comédie : les types de comique","consigne":"Réponds par des phrases complètes.","enonce":"Voici cinq extraits (écrits pour l’exercice). Nomme le type de comique dominant : mots, gestes, situation, caractère ou répétition.\n\n1. Un valet reçoit un coup de bâton et tombe dans un panier.\n2. Un père avare refuse de dépenser un sou, même pour sauver sa fille, et cela le rend ridicule.\n3. Deux personnages prennent l’un pour l’autre et se parlent sans se comprendre.\n4. Un personnage dit « fort bien, fort bien » à chaque réplique.\n5. Un valet fait un jeu de mots sur le nom de son maître.","bareme":[{"critere":"Cinq types de comique exacts (gestes, caractère, situation, répétition, mots)","points":15},{"critere":"Justification brève d’au moins un exemple","points":5}],"dureeMin":6,"corrige":"1. Comique de **gestes** (chute, coup de bâton).\n2. Comique de **caractère** (un défaut poussé à l’excès : l’avarice).\n3. Comique de **situation** (quiproquo, malentendu).\n4. Comique de **répétition** (une même réplique qui revient).\n5. Comique de **mots** (jeu de mots)."}$exo$::jsonb),
  ('35a5afc0-a4ac-5dd2-b136-d64c98aaaf75'::uuid, 2, 'redaction', $exo${"titre":"Ce qui change au XVIIIe siècle","consigne":"Lis le dialogue (écrit pour l’exercice) et réponds en justifiant.","enonce":"> **LE COMTE.** — Tu me réponds, valet ?\n> **FRONTIN.** — Monseigneur me fait l’honneur de m’interroger : je réponds. Mais je me demande qui, de nous deux, sait le mieux ce qu’il veut.\n> **LE COMTE.** — J’ai le droit de choisir la femme de mon fils.\n> **FRONTIN.** — Et lui, Monseigneur, qu’a-t-il le droit de choisir ? Ses gants ?\n>\n> *(Dialogue écrit pour l’exercice.)*\n\n1. Quelle évolution du valet ce dialogue illustre-t-il par rapport à la tradition de Molière ?\n2. Quelle critique sociale se lit dans la dernière réplique ? Nomme le thème (mariage arrangé, pouvoir des pères, inégalité).\n3. Rapproche cette scène de Beaumarchais : quelle célèbre réplique de Figaro reproche à son maître de « s’être donné la peine de naître » ?\n4. Cite deux « types » de la comédie que l’on retrouve ici.","bareme":[{"critere":"Valet égal intellectuel du maître, plus lucide","points":5},{"critere":"Critique du mariage arrangé et du pouvoir des pères, inégalité des conditions","points":5},{"critere":"Figaro et la peine de naître (Le Mariage de Figaro, 1784, critique des privilèges)","points":5},{"critere":"Deux types repérés (valet rusé, barbon)","points":5}],"dureeMin":10,"corrige":"1. Le valet devient l’**égal intellectuel de son maître**, et parfois plus **lucide** que lui : Frontin répond avec ironie.\n\n2. La critique porte sur le **pouvoir des pères** et le **mariage arrangé** : le fils n’a pas le droit de choisir sa femme. On peut aussi lire l’inégalité des conditions.\n\n3. Chez Beaumarchais, dans *Le Mariage de Figaro* (1784), Figaro reproche à son maître de « s’être donné la peine de naître » : il critique les privilèges de naissance. La pièce fut d’abord interdite par Louis XVI.\n\n4. Le **valet rusé** (Frontin) et le **barbon** (le comte qui commande)."}$exo$::jsonb),
  ('35a5afc0-a4ac-5dd2-b136-d64c98aaaf75'::uuid, 3, 'redaction', $exo${"titre":"Marivaux et Beaumarchais : deux comédies, deux voies","consigne":"Lis le dialogue (écrit pour l’exercice, il imite le marivaudage) et rédige tes réponses de façon argumentée.","enonce":"> **CLARICE.** — Je vous assure, Monsieur, que je ne pense rien de vous.\n> **DAMIS.** — Rien ? C’est beaucoup pour quelqu’un qui m’a regardé toute la soirée.\n> **CLARICE.** — Je regardais la pendule.\n> **DAMIS.** — Elle est de mon côté, en effet. Et que dit-elle ?\n> **CLARICE.** — Qu’il est tard, et que je m’en vais… si toutefois vous ne me retenez pas.\n>\n> *(Dialogue écrit pour l’exercice.)*\n\n1. Quel jeu de langage reconnais-tu ? Explique pourquoi chaque réplique « avance masquée ».\n2. Quel est l’obstacle qui empêche les deux personnages de s’avouer leur sentiment ? Distingue-le de l’obstacle chez Beaumarchais.\n3. Que comprend le spectateur avant les personnages ? Quelle règle du cours cela illustre-t-il ?\n4. Rédige un paragraphe : compare Marivaux (1688-1763) et Beaumarchais (Le Barbier de Séville, 1775 ; Le Mariage de Figaro, 1784) à partir de ce qu’ils critiquent et de ce qu’ils font rire.","bareme":[{"critere":"Marivaudage reconnu, réplique masquée, on parle pour ne pas s’avouer","points":5},{"critere":"Obstacle chez Marivaux : l’amour-propre ; chez Beaumarchais : la société, le pouvoir","points":5},{"critere":"Spectateur qui comprend avant eux : ironie dramatique / double registre","points":4},{"critere":"Paragraphe comparatif : jeu de langage et cœur ; critique sociale et valet","points":6}],"dureeMin":16,"corrige":"1. Le **marivaudage** : un dialogue léger et spirituel où chaque réplique avance **masquée** : Clarice dit qu’elle ne pense rien mais regardait Damis toute la soirée ; ils parlent **pour ne pas s’avouer** ce qu’ils ressentent.\n\n2. L’obstacle est l’**amour-propre** des personnages, qui refusent de reconnaître leur sentiment, et non ni le père ni la société. Chez Beaumarchais, l’obstacle est **social** : inégalité des conditions, pouvoir des maîtres.\n\n3. Le spectateur comprend avant les personnages qu’ils s’aiment : c’est l’**ironie dramatique** (le public en sait plus), qui produit le comique.\n\n4. **Marivaux** fait de l’amour un **jeu de langage** : le comique naît du mensonge à soi-même. **Beaumarchais** installe la **critique sociale** : le valet Figaro égale son maître ; la critique va si loin que Louis XVI interdit d’abord *Le Mariage de Figaro*. L’un explore le cœur, l’autre la société."}$exo$::jsonb),
  ('dcbb94fb-6cd1-5461-b9ca-a4fb206add7d'::uuid, 1, 'redaction', $exo${"titre":"Le Jeu de l’amour et du hasard : les déguisements","consigne":"Réponds par des phrases complètes.","enonce":"1. En quelle année la pièce est-elle créée ? Combien d’actes compte-t-elle ? En vers ou en prose ?\n2. Complète le tableau : Silvia se déguise en … ; Lisette en … ; Dorante en … ; Arlequin en …\n3. Qui sont Monsieur Orgon et Mario ? Que savent-ils ?\n4. Comment s’appelle l’effet comique produit par la confusion généralisée entre les personnages ?","bareme":[{"critere":"1730, trois actes, prose","points":5},{"critere":"Quatre déguisements exacts","points":8},{"critere":"Orgon père de Silvia, Mario son frère, dans la confidence","points":4},{"critere":"Quiproquo","points":3}],"dureeMin":6,"corrige":"1. **1730**, en **trois actes** et en **prose**.\n\n2. Silvia en **servante** ; Lisette en **maîtresse** ; Dorante en **valet** ; Arlequin en **maître**.\n\n3. **Monsieur Orgon** est le père de Silvia et **Mario** son frère ; ils sont **dans la confidence** et laissent faire.\n\n4. Le **quiproquo** (généralisé)."}$exo$::jsonb),
  ('dcbb94fb-6cd1-5461-b9ca-a4fb206add7d'::uuid, 2, 'redaction', $exo${"titre":"Le double registre et l’ironie dramatique","consigne":"Lis le dialogue (écrit pour l’exercice, il imite la pièce, ce n’est pas un extrait de Marivaux) et réponds en justifiant.","enonce":"> **SILVIA** *(à part).* — Ce valet a bien de la tenue… Que je suis sotte de le remarquer !\n> **DORANTE** *(à part).* — Cette servante a l’air d’une dame. Quel trouble !\n> **SILVIA.** — Vous êtes valet, dites-vous ?\n> **DORANTE.** — Oui, Mademoiselle, de mon maître. Et vous, de votre maîtresse ?\n>\n> *(Dialogue écrit pour l’exercice, sur le modèle de la pièce.)*\n\n1. Qu’est-ce qu’un aparté ? Relève-en deux dans ce dialogue.\n2. Que sait le spectateur que les personnages ignorent ? Comment s’appelle cet effet ?\n3. Pourquoi peut-on dire que le langage « trahit le rang malgré l’habit » ?\n4. Que veulent vérifier Silvia et Dorante en se déguisant, et que découvrent-ils ?","bareme":[{"critere":"Aparté défini (paroles dites au public) et deux relevés","points":5},{"critere":"Ironie dramatique : le spectateur sait qui est déguisé et pourquoi","points":5},{"critere":"Langage qui trahit le rang (tenue, air de dame malgré l’habit)","points":5},{"critere":"Chacun veut observer l’autre sans être jugé sur son rang, et découvre l’attirance","points":5}],"dureeMin":10,"corrige":"1. L’**aparté** est une réplique dite au public que les autres personnages n’entendent pas : « (à part) Ce valet a bien de la tenue… » et « (à part) Cette servante a l’air d’une dame. »\n\n2. Le spectateur sait que Silvia et Dorante sont **tous deux déguisés** et de rang élevé ; eux l’ignorent. C’est l’**ironie dramatique** (le public en sait plus), ressort du **double registre**.\n\n3. Le valet « a de la tenue » et la servante « a l’air d’une dame » : leur langage et leur allure **trahissent** leur vrai rang, malgré l’habit.\n\n4. Ils veulent observer l’autre sans être jugés sur leur rang. Chacun **tombe amoureux** d’un domestique supposé : il faut choisir entre son cœur et son rang."}$exo$::jsonb),
  ('dcbb94fb-6cd1-5461-b9ca-a4fb206add7d'::uuid, 3, 'redaction', $exo${"titre":"Sentiment et ordre social : le dénouement","consigne":"Lis le résumé du dénouement (écrit pour l’exercice) et rédige tes réponses de façon argumentée.","enonce":"> **Résumé.** Dorante, croyant aimer une servante, décide de l’épouser malgré son rang : il révèle son identité **par amour**. Silvia, elle, connaît déjà la vérité mais **prolonge l’épreuve** : elle veut être aimée pour elle-même. Quand tout est dévoilé, Silvia épouse Dorante, et la servante Lisette épouse Arlequin.\n\n1. Qui cède le premier ? Pourquoi Silvia prolonge-t-elle l’épreuve ?\n2. Quel est le vrai sujet de la pièce ? Formule-le avec les mots du cours.\n3. L’ordre social est-il renversé à la fin ? Justifie avec les mariages.\n4. Rédige un paragraphe : la pièce est-elle une critique sociale ou une comédie de sentiments ? Compare avec Beaumarchais.","bareme":[{"critere":"Dorante cède le premier ; Silvia veut être aimée pour elle-même","points":4},{"critere":"Vrai sujet : l’épreuve du sentiment face au préjugé social","points":4},{"critere":"Ordre social conservé : chacun se marie dans sa condition","points":5},{"critere":"Paragraphe nuancé, avec la comparaison à Beaumarchais (critique plus vive)","points":7}],"dureeMin":15,"corrige":"1. **Dorante** cède le premier et révèle son identité par amour. **Silvia** prolonge l’épreuve : elle veut être aimée **pour elle-même**.\n\n2. Le vrai sujet : **l’épreuve du sentiment face au préjugé social** ; chacun s’aime en croyant aimer un domestique et doit choisir entre son cœur et son rang.\n\n3. **Non** : la pièce s’achève sur la victoire du sentiment mais **l’ordre social n’est pas renversé** : maîtres et valets se marient chacun dans leur condition (Silvia avec Dorante, Lisette avec Arlequin).\n\n4. Réponse nuancée attendue : c’est d’abord une **comédie de sentiments** (le jeu de l’amour, le langage, l’amour-propre). La critique sociale est douce, puisque l’ordre est maintenu. Chez **Beaumarchais** (*Le Mariage de Figaro*, 1784), la critique est beaucoup plus vive : le valet reproche à son maître de « s’être donné la peine de naître », et la pièce fut d’abord interdite."}$exo$::jsonb),
  ('46988e38-b7a3-509b-a4b7-9df5e4264aa3'::uuid, 1, 'redaction', $exo${"titre":"Le drame romantique : repères","consigne":"Réponds par des phrases complètes.","enonce":"1. Quel auteur théorise le drame romantique, dans quel texte, en quelle année ?\n2. Cite deux règles classiques que le drame abolit ou transforme.\n3. Qui a écrit *Lorenzaccio*, à quel âge et en quelle année ?\n4. Où et quand se passe l’histoire ?","bareme":[{"critere":"Victor Hugo, Préface de Cromwell, 1827","points":5},{"critere":"Deux règles classiques abolies (trois unités, séparation des genres, unité de langue…)","points":5},{"critere":"Musset, 24 ans, 1834","points":5},{"critere":"Florence, 1537","points":5}],"dureeMin":6,"corrige":"1. **Victor Hugo**, dans la **Préface de Cromwell**, en **1827**.\n\n2. Il abolit les **trois unités** (l’action se déplace, s’étale sur des années) ; il **mêle** le sublime et le grotesque, le comique et le tragique ; il mêle aussi rois et gens du peuple, vers et prose.\n\n3. **Alfred de Musset**, à **24 ans**, en **1834**.\n\n4. À **Florence**, en **1537**."}$exo$::jsonb),
  ('46988e38-b7a3-509b-a4b7-9df5e4264aa3'::uuid, 2, 'redaction', $exo${"titre":"Lorenzo : un masque qui colle à la peau","consigne":"Lis le résumé (écrit pour l’exercice) puis réponds en citant le cours.","enonce":"> **Résumé.** À Florence, en 1537, le duc Alexandre de Médicis est un tyran. Lorenzo, son cousin, se fait son complice et son entremetteur. Ce n’est qu’un masque : il prépare son assassinat. Il le tue. Mais les Florentins, indifférents, laissent élire un autre Médicis, Côme, et Lorenzo est assassiné à son tour.\n\n1. Explique le surnom « Lorenzaccio ».\n2. Que veut dire la phrase de Lorenzo : « Le vice a été pour moi un vêtement ; maintenant il est collé à ma peau » ?\n3. Pourquoi tue-t-il, alors qu’il ne croit plus à l’utilité de son acte ?\n4. Quels thèmes la pièce interroge-t-elle ? Nomme le « mal du siècle ».","bareme":[{"critere":"Lorenzaccio : « le mauvais Lorenzo », surnom de mépris","points":4},{"critere":"Le masque devenu vrai : à force de jouer le débauché, il l’est devenu","points":6},{"critere":"Il tue pour rester fidèle à celui qu’il a été","points":5},{"critere":"Thèmes : engagement inutile, être et paraître, désenchantement","points":5}],"dureeMin":10,"corrige":"1. **Lorenzaccio** est un surnom de mépris : « le mauvais Lorenzo ».\n\n2. Il a joué le débauché pour approcher le tyran ; à force, il l’est **devenu** : le masque est devenu sa peau.\n\n3. Il agit sans plus croire à l’utilité de son acte : il tue **pour rester fidèle** à celui qu’il a été.\n\n4. La pièce interroge l’**engagement** et son inutilité, le rapport entre l’**être** et le **paraître**, et le désenchantement d’une génération née trop tard pour la Révolution : le « **mal du siècle** »."}$exo$::jsonb),
  ('46988e38-b7a3-509b-a4b7-9df5e4264aa3'::uuid, 3, 'redaction', $exo${"titre":"Pourquoi Lorenzaccio est-il un drame romantique ?","consigne":"Rédige tes réponses de façon argumentée en t’appuyant sur le cours.","enonce":"> **Scène imaginée pour l’exercice (elle imite un drame romantique).** Le décor change à chaque tableau : un palais, un marché, une taverne. Un duc parle en vers avec des courtisans, puis un mendiant lui répond en prose. Un même personnage est tour à tour généreux et cruel. Les costumes, les armes et les rues sont décrits avec une grande précision historique.\n\n1. Associe chaque élément de la scène à la règle classique qu’il transgresse ou à la revendication du drame (unités, séparation des genres, unité de langue, personnages complexes, couleur locale).\n2. Que signifie « couleur locale » ? Pourquoi Hugo la réclame-t-il ?\n3. Rédige un paragraphe : *Lorenzaccio* montre-t-il un héros ordinaire ? Analyse la double face de Lorenzo et l’échec de son acte.\n4. Pourquoi la pièce a-t-elle été jugée « injouable » pendant plus de soixante ans ? Quelle actrice l’a jouée en 1896 ?","bareme":[{"critere":"Quatre associations correctes (unités, mélange, langue, complexité, couleur locale)","points":6},{"critere":"Couleur locale définie (décors, costumes, détails historiques précis)","points":3},{"critere":"Paragraphe : Lorenzo double, masque et vice devenus réels, acte inutile, indifférence des Florentins","points":7},{"critere":"Injouable : ignore les contraintes de la scène ; Sarah Bernhardt en 1896","points":4}],"dureeMin":15,"corrige":"1. Décor qui change = abolition de l’**unité de lieu** (et de temps) ; vers et prose = **unité de langue** abolie ; duc et mendiant = mélange des rangs ; personnage généreux et cruel = personnages **complexes**, ni bons ni mauvais ; précision des costumes et des rues = **couleur locale**.\n\n2. La **couleur locale** est l’exigence de décors, de costumes et de détails historiques précis. Hugo la réclame pour ancrer le drame dans une époque réelle, à la différence du décor conventionnel classique.\n\n3. Lorenzo n’est pas un héros ordinaire : il joue le débauché pour approcher le tyran, mais **le vice est collé à sa peau**. Il tue Alexandre, mais **rien ne change** : les Florentins, indifférents, élisent Côme, et Lorenzo est assassiné à son tour. Son acte est inutile ; il l’accomplit pour rester fidèle à celui qu’il a été.\n\n4. Elle ignore les contraintes de la scène de son temps ; elle compte cinq actes, 39 scènes et une trentaine de personnages. Elle est créée en **1896** avec **Sarah Bernhardt** dans le rôle-titre."}$exo$::jsonb),
  ('92914028-1f3d-5b10-9383-a7c16ea1d813'::uuid, 1, 'redaction', $exo${"titre":"Le Cid : intrigue et personnages","consigne":"Réponds par des phrases complètes.","enonce":"1. En quelle année *Le Cid* est-il créé ? Quel nom Corneille lui donne-t-il d’abord, puis en 1648 ?\n2. Quels sont les liens entre Rodrigue, Chimène, Don Gomès, Don Diègue ?\n3. Que signifie le surnom « le Cid » ? Quel exploit le lui vaut ?\n4. Que signifie « dilemme cornélien » ?","bareme":[{"critere":"1637, tragi-comédie puis tragédie","points":5},{"critere":"Quatre liens exacts (amoureux, père de Chimène, père de Rodrigue)","points":6},{"critere":"Le seigneur, vainqueur des Maures","points":4},{"critere":"Choix entre deux valeurs également hautes sans pouvoir les concilier","points":5}],"dureeMin":6,"corrige":"1. **1637** ; d’abord une **tragi-comédie**, rebaptisée « tragédie » en **1648**.\n\n2. **Rodrigue** et **Chimène** s’aiment ; **Don Gomès** est le père de Chimène (il gifle Don Diègue) ; **Don Diègue** est le père de Rodrigue.\n\n3. « Le **seigneur** » ; Rodrigue vainc les **Maures**.\n\n4. Un **dilemme** : choisir entre deux valeurs également hautes sans pouvoir les concilier."}$exo$::jsonb),
  ('92914028-1f3d-5b10-9383-a7c16ea1d813'::uuid, 2, 'redaction', $exo${"titre":"Le dilemme de Rodrigue","consigne":"Lis le résumé (écrit pour l’exercice) puis réponds en justifiant.","enonce":"> **Résumé.** Don Gomès a giflé Don Diègue, trop vieux pour se venger. Rodrigue, fils de Don Diègue, doit défendre l’honneur de son père : mais l’offenseur est le père de Chimène, qu’il aime. Il tue Don Gomès en duel. Chimène doit réclamer sa mort au roi. Rodrigue vainc ensuite les Maures ; le roi accorde un délai d’un an.\n\n1. Explique le dilemme de Rodrigue avec le tableau : s’il venge son père, que perd-il ? S’il renonce, que perd-il ?\n2. Quel passage célèbre exprime ce déchirement ? Où se trouve-t-il ?\n3. Pourquoi *Le Cid* est-il une tragi-comédie et non une tragédie pure ?\n4. Que reproche l’Académie française à la pièce ?","bareme":[{"critere":"Dilemme : venger son père = perdre Chimène ; renoncer = perdre honneur et nom","points":6},{"critere":"Les stances de Rodrigue, acte I, scène 6 (« Percé jusques au fond du cœur… »)","points":4},{"critere":"Gravité de la tragédie mais fin heureuse, intrigue plus libre","points":5},{"critere":"Violation des unités et de la bienséance, Chimène épouserait le meurtrier","points":5}],"dureeMin":10,"corrige":"1. S’il **venge son père**, il perd **Chimène** ; s’il **renonce à l’honneur**, il perd sa **valeur** et son nom. Quel que soit son choix, il perd quelque chose d’essentiel.\n\n2. Les **stances** de Rodrigue (acte I, scène 6) : « Percé jusques au fond du cœur… ».\n\n3. La pièce a la **gravité** d’une tragédie mais une **fin heureuse** ; son intrigue est plus libre que les règles ne l’autorisent.\n\n4. L’Académie lui reproche de violer les **unités** et la **bienséance** (Chimène épouserait le meurtrier de son père)."}$exo$::jsonb),
  ('92914028-1f3d-5b10-9383-a7c16ea1d813'::uuid, 3, 'redaction', $exo${"titre":"Héros cornélien, héros racinien : comparer","consigne":"Rédige tes réponses de façon argumentée en t’appuyant sur le cours (Le Cid et Bérénice).","enonce":"> **Scène imaginée pour l’exercice.** Le chevalier Tancrède doit choisir entre sauver la ville en sacrifiant son frère, ou sauver son frère et livrer la ville. Après un long monologue, il choisit de sauver la ville. À l’acte suivant, il parle du poids de son choix mais ne le regrette pas : « Je l’ai voulu, je le tiens. » *(Texte écrit pour l’exercice.)*\n\n1. Cette scène est-elle un dilemme au sens du cours ? Justifie avec l’expression « quel que soit son choix ».\n2. Le héros de la scène est-il plutôt cornélien ou racinien ? Compare les deux avec au moins deux traits chacun.\n3. Rédige un paragraphe : pourquoi la querelle du Cid a-t-elle « fait une doctrine » ? Quelles règles ont été fixées ?\n4. Compare Rodrigue et Titus (*Bérénice*) : deux choix, deux issues.","bareme":[{"critere":"Dilemme reconnu : deux valeurs hautes, il perd quelque chose d’essentiel","points":4},{"critere":"Héros cornélien (volonté, choisit, grandit) et racinien (écrasé par une passion) comparés","points":6},{"critere":"Paragraphe sur la querelle : Académie, unités, bienséance, fixe les règles du théâtre classique","points":5},{"critere":"Comparaison Rodrigue (choisit et agit) et Titus (renonce, personne ne meurt)","points":5}],"dureeMin":16,"corrige":"1. Oui : c’est un **dilemme** : deux valeurs également hautes (la ville, le frère) qu’on ne peut concilier. **Quel que soit son choix**, le héros perd quelque chose d’essentiel.\n\n2. Il est **cornélien** : il se définit par sa **volonté**, il **choisit**, quoi qu’il en coûte, et il **grandit** par son choix (« Je l’ai voulu, je le tiens »). Le héros de **Racine** est au contraire **écrasé** par une passion qu’il subit.\n\n3. L’Académie française reproche au *Cid* de violer les **unités** et la **bienséance**. Cette querelle contribue à **fixer les règles** du théâtre classique : une polémique a fait une doctrine.\n\n4. **Rodrigue** choisit l’honneur, agit (duel, victoire) et le drame débouche sur une fin heureuse ; **Titus** renonce à Bérénice au nom du devoir, personne ne meurt et la pièce s’achève sur un triple renoncement. Le premier est un héros de la volonté, le second est écrasé par la loi de Rome."}$exo$::jsonb),
  ('a5c44eab-38c6-5217-9e7b-4a722e681f01'::uuid, 1, 'redaction', $exo${"titre":"La nouvelle : repères","consigne":"Réponds par des phrases complètes.","enonce":"1. Donne trois traits qui définissent une nouvelle par rapport à un roman.\n2. Qu’est-ce qu’une chute ? Cite deux façons dont elle peut agir.\n3. Associe : Maupassant, Mérimée, Poe, Tchekhov à (a) *La Vénus d’Ille*, (b) *La Parure*, (c) les États-Unis, (d) la Russie.","bareme":[{"critere":"Trois traits (intrigue resserrée, peu de personnages, cadre limité, rythme rapide, chute)","points":7},{"critere":"Chute : fin brève et frappante ; révèle, retourne la morale ou laisse en suspens","points":6},{"critere":"Quatre associations : Maupassant-b, Mérimée-a, Poe-c, Tchekhov-d","points":7}],"dureeMin":6,"corrige":"1. Intrigue **resserrée**, **peu de personnages**, cadre **limité** dans l’espace et le temps, rythme rapide avec des **ellipses**, et une **chute**.\n\n2. La **chute** est une fin brève et frappante qui souvent retourne le sens. Elle peut **révéler** une information cachée, **retourner** la morale attendue, ou **laisser en suspens**.\n\n3. Maupassant = (b) ; Mérimée = (a) ; Poe = (c) ; Tchekhov = (d)."}$exo$::jsonb),
  ('a5c44eab-38c6-5217-9e7b-4a722e681f01'::uuid, 2, 'redaction', $exo${"titre":"Lire une nouvelle : la chute et ses indices","consigne":"Lis la nouvelle (écrite pour l’exercice) et réponds en citant le texte.","enonce":"> **Le facteur.** Mme Auclair, vieille dame d’un village de montagne, ne recevait jamais de courrier. Par pitié, M. Pelletier, le facteur, glissait chaque matin dans son sac une enveloppe blanche vide, frappait, et la lui tendait. Elle la prenait sans un mot et la rangeait dans un tiroir déjà plein. Un soir de novembre, elle l’invita à prendre un café ; il vit le tiroir resté entrouvert et l’ouvrit, par curiosité. Les enveloppes, une par jour depuis des années, étaient toutes soigneusement gardées, et toutes vides. Dans la dernière, pourtant, elle avait glissé un mot de sa main : « Merci, monsieur Pelletier. »\n>\n> *(Nouvelle écrite pour l’exercice.)*\n\n1. Quel type de chute est-ce : révélation, retournement de la morale, ou suspens ? Justifie.\n2. Relève deux indices qui préparaient la chute.\n3. Quelles caractéristiques de la nouvelle ce texte respecte-t-il (personnages, cadre, rythme) ?\n4. Quel registre est employé : réaliste, fantastique ou merveilleux ?","bareme":[{"critere":"Chute-révélation : elle savait depuis le début que les enveloppes étaient vides et les gardait par gratitude","points":5},{"critere":"Deux indices (le courrier jamais reçu, l’enveloppe blanche, le tiroir plein, sans un mot)","points":5},{"critere":"Nouvelle : deux personnages, cadre limité, rythme rapide, ellipse","points":5},{"critere":"Registre réaliste et justification","points":5}],"dureeMin":10,"corrige":"1. C’est une **chute qui révèle** une information cachée : Mme Auclair **savait** depuis le début que les enveloppes étaient vides ; elle les a toutes gardées et remercie le facteur de sa gentillesse. (On accepte « retourne le sens » : la pitié du facteur est rendue par la dignité de la vieille dame.)\n\n2. La vieille dame **n’en recevait jamais** du courrier ; elle mettait l’enveloppe « **sans un mot** » dans un **tiroir déjà plein** ; l’enveloppe est **blanche**. À la relecture, les indices étaient là.\n\n3. **Peu de personnages** (deux), **cadre limité** (un village, un soir de novembre), **rythme rapide**, une intrigue **resserrée** et une chute finale.\n\n4. **Registre réaliste** : aucune irruption de l’inexplicable, tout est plausible."}$exo$::jsonb),
  ('a5c44eab-38c6-5217-9e7b-4a722e681f01'::uuid, 3, 'redaction', $exo${"titre":"Le genre de la nouvelle : analyser et comparer","consigne":"Rédige tes réponses de façon argumentée en t’appuyant sur le cours.","enonce":"> **Deux débuts de nouvelles (écrits pour l’exercice).**\n> **A.** « Le 3 mars, à 7 h 12, M. Vasseur ouvrit son courrier et y trouva sa propre lettre de licenciement, datée de la veille. »\n> **B.** « Dans la petite ville de Beauval, tout le monde savait que la maison du haut était hantée ; personne n’y était entré depuis des années, et c’était très bien ainsi. »\n\n1. Quelles caractéristiques de la nouvelle repère-t-on dans chaque début (précision, resserrement, cadre, personnages) ?\n2. Propose pour A une chute qui révèle une information cachée, et pour B une chute qui retourne la morale attendue. Justifie en une phrase chacune.\n3. Explique la phrase : « Une chute qui sort de nulle part n’est pas une chute, c’est une invraisemblance. » Cite un exemple du cours qui montre une chute bien préparée.\n4. Rédige un paragraphe : pourquoi la presse du XIXe siècle a-t-elle favorisé la nouvelle ? Cite deux auteurs et deux registres.","bareme":[{"critere":"Caractéristiques repérées dans A et B (précision temporelle, un personnage, cadre limité)","points":4},{"critere":"Deux chutes plausibles et justifiées (révélation ; retournement)","points":5},{"critere":"Chute préparée par des indices, exemple de La Parure (boîte, bijoutier)","points":5},{"critere":"Paragraphe : âge d’or, publications hebdomadaires, auteurs (Maupassant, Mérimée) et registres","points":6}],"dureeMin":16,"corrige":"1. **A** : précision (3 mars, 7 h 12), **un seul personnage**, **cadre limité**, action resserrée qui commence directement. **B** : un lieu limité (la ville, la maison), une situation posée en une phrase, le **rythme rapide**.\n\n2. Exemples : pour A, on découvre que M. Vasseur a lui-même écrit la lettre dans un moment d’égarement (**révèle** une information cachée). Pour B, on découvre que la « maison hantée » abritait un refuge d’enfants qu’on cachait (**retourne** la morale attendue). Toute chute plausible et justifiée est acceptée.\n\n3. Une bonne chute est **préparée** : à la relecture, les indices étaient là. Sans indices, elle est **invraisemblable**. Exemple : dans *La Parure*, la boîte qui n’est pas d’origine et le bijoutier qui ne reconnaît pas la parure préparent la révélation « la mienne était fausse ».\n\n4. Au **XIXe siècle**, c’est l’**âge d’or** du genre : la presse publie des nouvelles chaque semaine. Des auteurs comme **Maupassant** (*La Parure*, *Boule de Suif*, *Le Horla*) et **Mérimée** (*La Vénus d’Ille*) écrivent en registre **réaliste** ou **fantastique** ; le genre existe aussi en registre merveilleux, policier, de science-fiction ou d’absurde."}$exo$::jsonb),
  ('5322f300-a345-53c3-9f13-beb4155b92fb'::uuid, 1, 'redaction', $exo${"titre":"Les repères de la maritimisation","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Quelle part du commerce mondial de marchandises voyage par la mer ? Quel objet, inventé dans les années 1950, explique la chute du coût du transport ?\n2. Cite trois points de passage stratégiques.\n3. Qu'est-ce qu'une zone économique exclusive (ZEE) ? Quelle est sa taille et quel traité la crée ?","bareme":[{"critere":"Environ 80 % et le conteneur (boîte standardisée)","points":7},{"critere":"Trois points de passage stratégiques justes","points":6},{"critere":"ZEE définie, 200 milles, convention de Montego Bay (1982)","points":7}],"dureeMin":7,"corrige":"1. Environ **80 %** du commerce mondial de marchandises voyage par la mer. Le **conteneur**, boîte standardisée inventée dans les années **1950**, permet de charger et décharger sans manipuler la marchandise : le coût du transport s'effondre, et fabriquer en Asie pour vendre en Europe devient rentable.\n\n2. Trois au choix parmi : **Suez**, **Panama**, **Malacca**, **Ormuz**, Gibraltar, Bab el-Mandeb.\n\n3. Une **ZEE** est une zone maritime, jusqu'à **200 milles** des côtes, où un État a l'exclusivité de l'exploitation des ressources (pêche, énergie, minerais). Elle est créée en **1982** par la **convention de Montego Bay**."}$exo$::jsonb),
  ('5322f300-a345-53c3-9f13-beb4155b92fb'::uuid, 2, 'redaction', $exo${"titre":"Un porte-conteneurs bloqué","consigne":"Lis le document, puis réponds aux questions en t'appuyant sur le texte et sur ton cours.","enonce":"> **Document — Article de presse (texte écrit pour l'exercice).**\n> « Lundi matin, un porte-conteneurs géant s'est mis en travers du canal de Suez. Plus de deux cents navires attendent aux deux extrémités. Dans les usines d'Europe, on craint de manquer de pièces détachées venues d'Asie. Certains armateurs envisagent de contourner l'Afrique, ce qui ajoute plusieurs jours de mer. »\n\n1. Pourquoi le canal de Suez est-il qualifié de point de passage stratégique ?\n2. Explique pourquoi un incident dans ce canal touche des usines situées à des milliers de kilomètres.\n3. Cite deux autres passages stratégiques et un grand port asiatique.","bareme":[{"critere":"Suez : passage étroit par où transite une grande part du commerce entre Asie et Europe","points":5},{"critere":"Lien avec les usines : chaînes de production et flux de conteneurs mondialisés","points":7},{"critere":"Deux autres passages stratégiques justes","points":4},{"critere":"Un grand port asiatique juste (Shanghai, Singapour, Ningbo ou Shenzhen)","points":4}],"dureeMin":10,"corrige":"1. Le canal de **Suez** est un passage étroit, un **goulet** : une grande partie des marchandises entre l'**Asie** et l'**Europe** y transite. Le bloquer oblige à contourner l'Afrique.\n\n2. La mondialisation repose sur des **flux de marchandises par la mer**, surtout en **conteneurs**. Beaucoup d'usines européennes utilisent des pièces fabriquées en Asie : si les navires sont bloqués, la production s'arrête. Un incident sur un passage stratégique se répercute sur l'**économie mondiale en quelques jours**.\n\n3. Passages : **Panama**, **Malacca**, **Ormuz**, Gibraltar, Bab el-Mandeb (deux au choix). Grands ports asiatiques : **Shanghai**, **Singapour**, Ningbo, Shenzhen (un au choix)."}$exo$::jsonb),
  ('5322f300-a345-53c3-9f13-beb4155b92fb'::uuid, 3, 'redaction', $exo${"titre":"Océans : richesses, tensions et menaces","consigne":"Rédige un paragraphe argumenté d'une quinzaine de lignes, structuré, en t'appuyant sur des exemples précis.","enonce":"**Sujet.** Les océans sont à la fois une richesse, un espace de tensions et un milieu menacé.\n\n1. Présente deux ressources que fournissent les mers et les océans, avec un chiffre ou un fait précis.\n2. Explique pourquoi la France possède la deuxième ZEE du monde, et cite deux zones de conflits maritimes.\n3. Rédige un paragraphe : la mondialisation profite-t-elle aux océans ? Cite au moins deux menaces.","bareme":[{"critere":"Deux ressources précises (pêche et un tiers des stocks surexploité, énergie offshore, minerais)","points":5},{"critere":"France : territoires ultramarins, deuxième ZEE ; deux zones de conflits","points":5},{"critere":"Au moins deux menaces citées avec exemples","points":5},{"critere":"Paragraphe argumenté et structuré, avec conclusion","points":5}],"dureeMin":15,"corrige":"1. La **pêche** nourrit des centaines de millions de personnes mais **un tiers** des stocks est **surexploité**. L'**énergie** : pétrole et gaz offshore, éolien en mer. Les **minerais des grands fonds** sont encore peu exploités.\n\n2. La France a la **deuxième ZEE du monde** grâce à ses **territoires ultramarins** (Polynésie, Nouvelle-Calédonie, Antilles, océan Indien) : sa puissance maritime ne se lit pas sur la carte de l'Hexagone. Conflits : **mer de Chine méridionale**, **Arctique** (la fonte ouvre de nouvelles routes).\n\n3. Paragraphe attendu : la mondialisation dépend des océans (80 % du commerce, conteneur, grands ports) mais les fait payer cher : **pollutions**, **plastiques**, dégazages, **acidification**, **réchauffement**, **piraterie**, surpêche. Les océans absorbent une grande part du CO₂ et de la chaleur. Conclusion : un espace vital à protéger, dont l'exploitation suscite rivalités entre États."}$exo$::jsonb),
  ('7bed8703-f5f0-509a-b427-ced6a778ac29'::uuid, 1, 'redaction', $exo${"titre":"Une puissance mondiale","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Cite les quatre domaines dans lesquels les États-Unis sont une puissance.\n2. Qu'est-ce que le soft power ? Donne deux exemples américains.\n3. Associe chaque ville à sa fonction : New York, Washington, Los Angeles, Houston (finance, politique, cinéma, pétrole).","bareme":[{"critere":"Quatre domaines : économique, militaire, technologique, culturel","points":6},{"critere":"Soft power défini et deux exemples","points":7},{"critere":"Quatre villes associées correctement","points":7}],"dureeMin":7,"corrige":"1. **Économique** (première économie mondiale), **militaire** (bases sur tous les continents), **technologique** (Silicon Valley), **culturel** (soft power).\n\n2. Le **soft power** est la capacité d'influencer par la culture et les modes de vie, sans contrainte. Exemples : le **cinéma** (Hollywood), la **musique**, les **marques**, les modes de vie.\n\n3. **New York** : finance (Wall Street, ONU). **Washington** : le politique. **Los Angeles** : le cinéma (Hollywood). **Houston** : le pétrole (et le spatial)."}$exo$::jsonb),
  ('7bed8703-f5f0-509a-b427-ced6a778ac29'::uuid, 2, 'redaction', $exo${"titre":"Detroit et San José","consigne":"Lis le document, puis réponds aux questions.","enonce":"> **Document — Deux fiches de villes (texte écrit pour l'exercice).**\n> **Detroit (Michigan).** Ancienne capitale de l'automobile, la ville a perdu plus de la moitié de ses habitants depuis les années 1950. Des quartiers entiers sont abandonnés et la ville a connu la faillite.\n> **San José (Californie).** Au cœur de la Silicon Valley, la ville abrite les sièges de grandes entreprises du numérique. Les loyers y sont parmi les plus chers du pays.\n\n1. À quelle grande région appartient chaque ville ? Nomme-la.\n2. Explique la différence d'évolution entre les deux villes.\n3. Que montrent ces deux exemples sur les inégalités dans le territoire américain ?","bareme":[{"critere":"Detroit : Manufacturing Belt / Rust Belt ; San José : Silicon Valley (Sun Belt, Ouest)","points":5},{"critere":"Déclin industriel contre hautes technologies, avec au moins un facteur","points":7},{"critere":"Inégalités : région très riche et ville en faillite proches","points":4},{"critere":"Vocabulaire précis (Rust Belt, Sun Belt)","points":4}],"dureeMin":10,"corrige":"1. **Detroit** appartient à la **Manufacturing Belt** du Nord-Est, devenue la **Rust Belt** (ceinture de la rouille). **San José** est dans la **Silicon Valley**, en Californie, au cœur de la **Sun Belt**.\n\n2. Detroit décline depuis les années **1970** (déclin industriel, fermeture d'usines, population en baisse). La Sun Belt **attire** : climat, coûts plus bas, **hautes technologies**, aéronautique. Population et activités basculent du Nord-Est vers le Sud et l'Ouest.\n\n3. Une puissance mondiale peut abriter, à quelques milliers de kilomètres l'une de l'autre, **une région parmi les plus riches du monde et une ville en faillite**. L'accès aux soins et à l'éducation reste fortement lié au revenu : les inégalités sont fortes dans le territoire."}$exo$::jsonb),
  ('7bed8703-f5f0-509a-b427-ced6a778ac29'::uuid, 3, 'redaction', $exo${"titre":"Les États-Unis s'adaptent-ils à la mondialisation ?","consigne":"Rédige un paragraphe argumenté d'une quinzaine de lignes en t'appuyant sur des exemples précis.","enonce":"**Sujet.** Les États-Unis restent la première économie mondiale, mais leur territoire est profondément transformé par la mondialisation.\n\n1. Décris le basculement territorial entre le Nord-Est et le Sud-Ouest, avec au moins trois noms de lieux ou de régions.\n2. Explique le rôle des interfaces (façades maritimes, frontière mexicaine) et des maquiladoras.\n3. Rédige un paragraphe : la puissance américaine est-elle fragile ? Donne au moins deux fragilités.","bareme":[{"critere":"Basculement : Rust Belt / Manufacturing Belt vers Sun Belt, avec trois noms de lieux","points":6},{"critere":"Interfaces : trois façades, frontière mexicaine, maquiladoras expliquées","points":5},{"critere":"Au moins deux fragilités (endettement, ouragans, incendies, dépendance aux importations, Chine)","points":5},{"critere":"Paragraphe argumenté et structuré","points":4}],"dureeMin":15,"corrige":"1. Le **Nord-Est** (Manufacturing Belt, **Rust Belt**, **Detroit**) décline depuis les années 1970. Le **Sud et l'Ouest** (**Sun Belt**, Californie, **Silicon Valley**, **Houston**) attirent population et activités : climat, coûts plus bas, hautes technologies, aéronautique.\n\n2. Les **façades maritimes** (Atlantique, Pacifique, golfe du Mexique) et la **frontière mexicaine** concentrent les échanges. Les **maquiladoras** sont des usines d'assemblage du côté mexicain de la frontière : elles montrent l'intégration des deux économies.\n\n3. Paragraphe : les États-Unis sont une puissance complète (économique, militaire, technologique, culturelle avec le soft power) et s'adaptent en déplaçant leurs activités vers le Sud et l'Ouest. Mais ils sont **fragiles** : **dépendance aux importations**, **endettement**, vulnérabilité climatique (**ouragans**, incendies, sécheresses de l'Ouest), **inégalités**, **concurrence de la Chine**."}$exo$::jsonb),
  ('10fda032-3e4a-5bc1-a568-17428f3c8b29'::uuid, 1, 'redaction', $exo${"titre":"Les repères sur l'Afrique","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Combien d'États compte l'Afrique et combien d'habitants environ ?\n2. Donne deux chiffres qui caractérisent la démographie africaine.\n3. Pourquoi ne faut-il pas parler de « l'Afrique » comme d'un bloc ?","bareme":[{"critere":"54 États et environ 1,4 milliard d'habitants","points":6},{"critere":"Environ 40 % de moins de 15 ans ; population qui pourrait doubler d'ici 2050","points":7},{"critere":"Explication : pays très différents, exemples cités","points":7}],"dureeMin":6,"corrige":"1. L'Afrique compte **54 États** et environ **1,4 milliard** d'habitants.\n\n2. Environ **40 %** de la population a moins de 15 ans, et la population pourrait **doubler** d'ici **2050**.\n\n3. C'est un **continent, pas un pays** : le Maroc, le Nigeria, l'Éthiopie et l'Afrique du Sud n'ont ni la même économie, ni le même climat, ni la même histoire. Parler d'un bloc est un contresens."}$exo$::jsonb),
  ('10fda032-3e4a-5bc1-a568-17428f3c8b29'::uuid, 2, 'redaction', $exo${"titre":"Le cobalt de Kolwezi","consigne":"Lis le document, puis réponds aux questions.","enonce":"> **Document — Extrait d'un reportage (texte écrit pour l'exercice).**\n> « Dans le sud de la République démocratique du Congo, des camions chargés de minerai de cobalt roulent vers le port. Le minerai est exporté brut, puis transformé en Asie en composants pour batteries. Dans les villes minières, l'électricité est rare et beaucoup de familles vivent dans des quartiers précaires. »\n\n1. Quelles ressources du sous-sol africain le cours associe-t-il à la RDC ?\n2. Pourquoi l'exportation d'un minerai brut est-elle un problème pour le pays ?\n3. Cite deux difficultés que connaît l'Afrique, d'après le cours.","bareme":[{"critere":"Cobalt et cuivre pour la RDC","points":4},{"critere":"Valeur ajoutée captée ailleurs : transformation hors d'Afrique, vendre au prix de la matière et acheter au prix du travail","points":8},{"critere":"Deux difficultés citées (conflits, dette, dépendance aux cours, climat, pauvreté)","points":5},{"critere":"Réponses rédigées et précises","points":3}],"dureeMin":10,"corrige":"1. Le **cobalt** et le **cuivre** sont associés à la **RDC**.\n\n2. Le minerai est **exporté brut** : la **transformation**, donc l'**essentiel de la valeur**, se fait ailleurs (ici en Asie). Le pays vend au prix de la matière et achète l'objet fini au prix du travail : il n'a ni les emplois de la transformation ni les profits.\n\n3. Deux au choix : **conflits** et instabilité de certains États, **dépendance aux cours** des matières premières, **dette**, effets du **changement climatique** (Sahel, Corne de l'Afrique), **pauvreté massive** dans plusieurs régions."}$exo$::jsonb),
  ('10fda032-3e4a-5bc1-a568-17428f3c8b29'::uuid, 3, 'redaction', $exo${"titre":"Défi ou atout : la jeunesse africaine","consigne":"Rédige un paragraphe argumenté d'une quinzaine de lignes en t'appuyant sur des exemples.","enonce":"**Sujet.** L'Afrique est le continent le plus jeune du monde et l'un des plus dynamiques, mais elle reste confrontée à de grands défis.\n\n1. Explique pourquoi la jeunesse et l'urbanisation rapide sont à la fois un défi et un atout.\n2. Donne un exemple d'innovation qui montre le dynamisme du continent, et explique-le.\n3. Rédige un paragraphe : l'intégration régionale (Union africaine, ZLECAf) peut-elle aider l'Afrique à mieux profiter de la mondialisation ?","bareme":[{"critere":"Jeunesse et urbanisation : défi (écoles, emplois, logements, quartiers précaires) et atout (main-d'œuvre, marché)","points":6},{"critere":"Innovation : paiement mobile M-Pesa au Kenya, sauter l'étape du téléphone fixe et de la banque","points":4},{"critere":"ZLECAf en vigueur depuis 2021, commerce entre pays africains, limites","points":6},{"critere":"Paragraphe argumenté et nuancé","points":4}],"dureeMin":15,"corrige":"1. **Défi** : il faut des écoles, des emplois, des logements ; les villes (Lagos, Kinshasa, Nairobi) grandissent plus vite que leurs équipements, d'où l'extension des **quartiers précaires**. **Atout** : une **main-d'œuvre** et un **marché** immenses.\n\n2. Le **paiement mobile**, comme **M-Pesa** au Kenya : sans téléphone fixe, on est passé directement au mobile, et le paiement mobile touche des populations **sans compte bancaire**.\n\n3. Paragraphe : la **ZLECAf** (zone de libre-échange continentale), entrée en vigueur en **2021**, et l'**Union africaine** veulent développer le commerce **entre pays africains**, longtemps plus faible que le commerce avec l'extérieur. Cela peut aider à transformer les ressources sur place et à réduire la dépendance. Mais elle se heurte aux conflits, aux infrastructures insuffisantes et à la dépendance aux matières premières, et la croissance profite inégalement."}$exo$::jsonb),
  ('5a4d61d5-80eb-52e7-89a2-096322650cb1'::uuid, 1, 'redaction', $exo${"titre":"Les repères de l'industrialisation","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Dans quel pays et vers quelle date commence la révolution industrielle ? Quelle invention est au cœur de la première industrialisation ?\n2. Cite deux énergies de la seconde industrialisation.\n3. Qu'est-ce que l'exode rural ?","bareme":[{"critere":"Angleterre, vers 1780, machine à vapeur","points":7},{"critere":"Électricité et pétrole (à partir de 1870)","points":6},{"critere":"Exode rural défini","points":7}],"dureeMin":6,"corrige":"1. La révolution industrielle commence en **Angleterre** vers **1780**. La **machine à vapeur** de **James Watt**, alimentée au **charbon**, en est le moteur.\n\n2. La seconde industrialisation (à partir de **1870**) repose sur l'**électricité** et le **pétrole** (moteur à explosion).\n\n3. L'**exode rural** est le départ massif des habitants des campagnes vers les villes industrielles : les campagnes se vident et les villes explosent."}$exo$::jsonb),
  ('5a4d61d5-80eb-52e7-89a2-096322650cb1'::uuid, 2, 'redaction', $exo${"titre":"Lucie, ouvrière du textile","consigne":"Lis le document, puis réponds aux questions.","enonce":"> **Document — Témoignage d'une ouvrière (texte écrit pour l'exercice), ville textile du Nord, vers 1850.**\n> « Je suis entrée à la fabrique à dix ans, quand nous avons quitté la campagne. Nous commençons à cinq heures et demie et finissons à huit heures du soir. Mon petit frère de huit ans travaille aussi. Si je me blesse à la machine, personne ne me paiera. Le soir, nous rentrons dans une seule pièce sans eau courante. »\n\n1. Relève trois éléments qui décrivent le coût humain de l'industrialisation.\n2. Pourquoi la famille de Lucie a-t-elle quitté la campagne ? Nomme le phénomène.\n3. Quelles réactions le cours cite-t-il face à ces conditions ? Nommes-en deux.","bareme":[{"critere":"Trois éléments relevés (durée, travail des enfants, absence d'indemnisation, logement insalubre)","points":6},{"critere":"Exode rural, départ vers la ville pour trouver un emploi","points":5},{"critere":"Deux réactions : syndicalisme et grèves, socialisme, catholicisme social","points":6},{"critere":"Réponses rédigées","points":3}],"dureeMin":10,"corrige":"1. Journées très longues (de **5 h 30 à 20 h**, soit 14 heures et demie), **travail des enfants** (Lucie à dix ans, son frère à huit), **accidents sans indemnisation**, **logement insalubre** (une pièce sans eau courante).\n\n2. C'est l'**exode rural** : les campagnes se vident et les villes industrielles explosent, car les fabriques offrent du travail.\n\n3. Le **syndicalisme** et les **grèves** (organisation des ouvriers), le **socialisme** (Marx et Engels, lutte des classes), le **catholicisme social** (l'Église reconnaît la « question ouvrière »)."}$exo$::jsonb),
  ('5a4d61d5-80eb-52e7-89a2-096322650cb1'::uuid, 3, 'redaction', $exo${"titre":"Une révolution technique et sociale","consigne":"Rédige un paragraphe argumenté d'une quinzaine de lignes en t'appuyant sur des exemples précis.","enonce":"**Sujet.** La révolution industrielle n'est pas seulement une révolution technique : c'est une révolution de l'organisation du capital, du travail et du temps.\n\n1. Compare les deux âges de l'industrialisation (périodes, énergies, secteurs).\n2. Explique deux effets du chemin de fer, dont un sur l'heure.\n3. Rédige un paragraphe : qui profite de l'industrialisation et qui en supporte le coût ? Cite la classe dominante et une loi française.","bareme":[{"critere":"Comparaison des deux âges : charbon / vapeur / textile contre électricité / pétrole / chimie","points":6},{"critere":"Chemin de fer : distances, prix, heure unique par pays","points":4},{"critere":"Capitalisme : banques, sociétés par actions, bourgeoisie d'affaires ; loi de 1841 (enfants)","points":5},{"critere":"Paragraphe argumenté","points":5}],"dureeMin":15,"corrige":"1. **Première industrialisation** (fin XVIIIe - milieu XIXe) : **charbon**, **vapeur**, textile, sidérurgie, **chemin de fer**. **Seconde** (à partir de **1870**) : **électricité**, **pétrole**, moteur à explosion, chimie, acier.\n\n2. Le **chemin de fer** change les **distances** et les **prix**, et impose une **heure unique** par pays : avant lui, chaque ville vivait à son heure solaire.\n\n3. Paragraphe : des **banques** et des **sociétés par actions** réunissent les capitaux ; la **bourgeoisie d'affaires** (industriels, banquiers) devient la classe dominante devant l'aristocratie foncière. Le coût humain : journées de **12 à 15 heures**, **travail des enfants**, salaires bas, accidents sans indemnisation. La loi de **1841** limite le travail des enfants sans moyens de contrôle. Les ouvriers réagissent par les grèves, le syndicalisme et le socialisme."}$exo$::jsonb),
  ('27d22a9c-3d7e-5d27-a482-53ddcf2e1397'::uuid, 1, 'redaction', $exo${"titre":"Deux mondes dans la ville","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Que possède un ouvrier du XIXe siècle ? Que possède un bourgeois ?\n2. Pourquoi les patrons emploient-ils des femmes et des enfants ?\n3. Quelle maladie touche les quartiers ouvriers surpeuplés ? Pourquoi ?","bareme":[{"critere":"Ouvrier : seulement sa force de travail ; bourgeois : les entreprises","points":7},{"critere":"Ils coûtent moins cher (un calcul)","points":6},{"critere":"Choléra, surpeuplement, absence d'eau courante et d'égouts","points":7}],"dureeMin":6,"corrige":"1. L'ouvrier ne possède que sa **force de travail**, qu'il vend contre un **salaire**. Le bourgeois possède les **entreprises**.\n\n2. Femmes et enfants **coûtent moins cher** : c'est un calcul économique, non un effet secondaire.\n\n3. Le **choléra**. Les quartiers ouvriers sont **surpeuplés**, sans **eau courante** ni **égouts** : les épidémies s'y propagent."}$exo$::jsonb),
  ('27d22a9c-3d7e-5d27-a482-53ddcf2e1397'::uuid, 2, 'redaction', $exo${"titre":"Deux menus, deux mondes","consigne":"Lis le document, puis réponds aux questions.","enonce":"> **Document — Deux journées (texte écrit pour l'exercice), grande ville industrielle, vers 1880.**\n> **Chez les Delmas (industriels).** Domestique à demeure, appartement dans un quartier neuf, éducation soignée des enfants, vacances d'été au bord de la mer. Le père répète : « Le travail et l'épargne font la réussite. »\n> **Chez les Martin (ouvriers).** Le père travaille onze heures par jour à l'usine. La mère est blanchisseuse à domicile. Les enfants de douze ans travaillent aussi. En cas de maladie, la famille n'a aucune protection.\n\n1. À quels groupes sociaux appartiennent les deux familles ?\n2. Relève deux valeurs que défend la bourgeoisie.\n3. Quelles conquêtes sociales améliorent peu à peu la condition ouvrière ? Donne deux dates.","bareme":[{"critere":"Bourgeoisie et prolétariat identifiés","points":4},{"critere":"Deux valeurs : travail, épargne, mérite, respectabilité","points":5},{"critere":"Deux conquêtes datées : 1864 grève, 1884 liberté syndicale, 1906 repos hebdomadaire","points":7},{"critere":"Réponses rédigées","points":4}],"dureeMin":10,"corrige":"1. Les Delmas appartiennent à la **bourgeoisie** (industriels) ; les Martin au **prolétariat** ouvrier.\n\n2. **Travail**, **épargne** (aussi **mérite**, respectabilité).\n\n3. **1864** : droit de grève ; **1884** : liberté syndicale ; **1906** : repos hebdomadaire. Rien n'est donné : tout est arraché par la mobilisation."}$exo$::jsonb),
  ('27d22a9c-3d7e-5d27-a482-53ddcf2e1397'::uuid, 3, 'redaction', $exo${"titre":"À qui profite la richesse produite ?","consigne":"Rédige un paragraphe argumenté d'une quinzaine de lignes en t'appuyant sur le cours.","enonce":"**Sujet.** « La question qui traverse tout le siècle tient en une phrase : à qui profite la richesse produite ? »\n\n1. Présente les réponses de trois courants de pensée (libéralisme, socialisme, catholicisme social ou anarchisme).\n2. Explique qui compose les classes moyennes et où elles se situent.\n3. Rédige un paragraphe : les conquêtes sociales ont-elles été accordées ou arrachées ? Appuie-toi sur au moins deux dates.","bareme":[{"critere":"Trois courants exacts avec leur réponse","points":7},{"critere":"Classes moyennes : employés, instituteurs, petits commerçants, contremaîtres","points":3},{"critere":"Conquêtes arrachées : dates 1864, 1884, 1906 et lutte","points":6},{"critere":"Paragraphe argumenté","points":4}],"dureeMin":15,"corrige":"1. **Libéralisme** : l'État doit laisser faire le marché. **Socialisme** : partager les moyens de production, **Marx** annonce la lutte des classes. **Catholicisme social** : *Rerum novarum* (1891) reconnaît la question ouvrière. **Anarchisme** : supprimer l'État.\n\n2. Entre bourgeois et ouvriers : **employés**, **instituteurs**, **petits commerçants**, **contremaîtres**. Elles grandissent avec l'administration et le commerce.\n\n3. Paragraphe : les conquêtes sont **arrachées** par la mobilisation, non offertes spontanément par les patrons : **1864** droit de grève, **1884** liberté syndicale, **1906** repos hebdomadaire. Grèves et syndicats ont imposé ces avancées."}$exo$::jsonb),
  ('7396e312-7adb-55b8-bacf-e4d5660ee603'::uuid, 1, 'redaction', $exo${"titre":"Les repères de la colonisation","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Quelle part des terres émergées l'Europe contrôle-t-elle en 1914 ?\n2. Quels sont les trois grands motifs de la colonisation ?\n3. Que décide la conférence de Berlin (1884-1885) ?","bareme":[{"critere":"Environ 85 %","points":4},{"critere":"Motifs économique, politique, idéologique avec détail","points":9},{"critere":"Berlin : partage de l'Afrique, sans Africains","points":7}],"dureeMin":6,"corrige":"1. Environ **85 %**.\n\n2. **Économique** (matières premières, débouchés, placements), **politique** (prestige, rivalités, points d'appui militaires), **idéologique** (la prétendue « mission civilisatrice », adossée à des théories racistes).\n\n3. Les puissances européennes se **partagent l'Afrique**. **Aucun Africain** n'est présent et les frontières sont tracées à la règle."}$exo$::jsonb),
  ('7396e312-7adb-55b8-bacf-e4d5660ee603'::uuid, 2, 'redaction', $exo${"titre":"Un administrateur colonial","consigne":"Lis le document, puis réponds aux questions.","enonce":"> **Document — Lettre d'un administrateur (texte écrit pour l'exercice), colonie d'Afrique, vers 1900.**\n> « Ma mission est d'apporter la civilisation à ces populations. Chaque village doit fournir des travailleurs pour la construction du chemin de fer qui reliera les mines au port, ainsi qu'un impôt en argent. Les paysans ont dû planter du coton au lieu de leurs champs de mil. Ceux qui refusent sont punis. »\n\n1. Quel motif idéologique l'auteur invoque-t-il ? Que penser de cet argument ?\n2. Relève deux obligations imposées aux colonisés.\n3. Pourquoi le chemin de fer profite-t-il peu aux colonisés ? Quelle conséquence sur l'alimentation ?","bareme":[{"critere":"Mission civilisatrice et esprit critique (théories racistes, intérêts économiques)","points":5},{"critere":"Deux obligations : travail forcé, impôt, cultures imposées","points":5},{"critere":"Équipement conçu pour l'exportation, minorité servie","points":5},{"critere":"Cultures d'exportation contre vivrières : fragilité alimentaire","points":5}],"dureeMin":10,"corrige":"1. L'auteur invoque la « **mission civilisatrice** ». Cet argument masque les vrais motifs (matières premières, débouchés, rivalités) et repose sur des **théories racistes**.\n\n2. **Travail forcé** pour construire le chemin de fer, **impôt** en argent ; on peut ajouter les **cultures imposées**. Ceux qui refusent sont punis (code de l'indigénat).\n\n3. Le chemin de fer relie les **mines au port** : il est construit d'abord pour l'**exportation** et pour une **minorité**. Les cultures d'exportation (coton) remplacent les cultures **vivrières** (mil) : l'alimentation des colonisés est **fragilisée**."}$exo$::jsonb),
  ('7396e312-7adb-55b8-bacf-e4d5660ee603'::uuid, 3, 'redaction', $exo${"titre":"Coloniser, résister","consigne":"Rédige un paragraphe argumenté d'une quinzaine de lignes en t'appuyant sur des exemples précis.","enonce":"**Sujet.** Entre 1850 et 1914, l'Europe conquiert l'Afrique et une grande partie de l'Asie.\n\n1. Décris la société coloniale : le statut des colons et celui des colonisés.\n2. Cite quatre résistances à la colonisation (nom, lieu).\n3. Rédige un paragraphe : la conférence de Berlin explique-t-elle encore des conflits actuels ? Pourquoi ?","bareme":[{"critere":"Société coloniale : colons (pouvoir, terre) ; colonisés (indigénat, travail forcé, impôt)","points":6},{"critere":"Quatre résistances exactes avec lieu","points":5},{"critere":"Berlin : frontières à la règle, ignorance des peuples, conflits actuels","points":5},{"critere":"Paragraphe argumenté","points":4}],"dureeMin":15,"corrige":"1. Les **colons européens** détiennent le **pouvoir** et la **terre**. Les **colonisés** ont un statut d'**indigène** : sans droits politiques, soumis au **travail forcé**, à l'**impôt** et au **code de l'indigénat**.\n\n2. **Abd el-Kader** (Algérie), **Samory Touré** (Afrique de l'Ouest), les **Cipayes** (Inde, 1857), les **Herero** (Namibie).\n\n3. Paragraphe : à **Berlin** (1884-1885), aucun Africain n'est présent ; les **frontières** sont tracées à la **règle**, en ignorant peuples et royaumes existants. Cette carte, dessinée en Europe, organise encore la géographie politique du continent et beaucoup de conflits actuels : des peuples divisés ou des rivaux réunis dans un même État."}$exo$::jsonb),
  ('7f7c0bad-8a3e-50d1-a7f4-815e8facf8e1'::uuid, 1, 'redaction', $exo${"titre":"Les repères de l'urbanisation","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. À partir de quand plus de la moitié de l'humanité vit-elle en ville ?\n2. Où la croissance urbaine est-elle la plus rapide ?\n3. Distingue une mégapole et une mégalopole en donnant un exemple de chaque.","bareme":[{"critere":"2007","points":4},{"critere":"Asie et Afrique (pays en développement)","points":6},{"critere":"Mégapole (plus de 10 millions, une ville) et mégalopole (chapelet de villes) avec exemples","points":10}],"dureeMin":6,"corrige":"1. Depuis **2007**.\n\n2. Dans les pays **en développement**, surtout en **Asie** et en **Afrique**.\n\n3. Une **mégapole** est **une** ville de plus de **10 millions** d'habitants (Tokyo, Delhi, Shanghai, São Paulo, Lagos). Une **mégalopole** est un **chapelet continu de villes** reliées entre elles (BosWash, la mégalopole japonaise, la dorsale européenne)."}$exo$::jsonb),
  ('7f7c0bad-8a3e-50d1-a7f4-815e8facf8e1'::uuid, 2, 'redaction', $exo${"titre":"Deux quartiers d'une même ville","consigne":"Lis le document, puis réponds aux questions.","enonce":"> **Document — Description d'une ville (texte écrit pour l'exercice), ville imaginaire d'Asie de 12 millions d'habitants.**\n> « Au centre, des tours de verre abritent les banques et les sièges d'entreprises. À deux kilomètres, un bidonville s'étend le long de la rivière : des cabanes sans égouts. En périphérie, de nouveaux lotissements avalent chaque année des rizières. En été, la température y dépasse de plusieurs degrés celle des campagnes voisines. »\n\n1. Comment appelle-t-on chacun des espaces décrits : les tours, le bidonville, les lotissements sur les rizières ?\n2. Cette ville est-elle une mégapole ? Justifie.\n3. Explique le dernier phénomène décrit et propose deux réponses possibles.","bareme":[{"critere":"Trois espaces nommés : quartier d'affaires (CBD), bidonville, étalement urbain","points":6},{"critere":"Mégapole : plus de 10 millions d'habitants","points":4},{"critere":"Îlot de chaleur urbain expliqué","points":5},{"critere":"Deux réponses : densification, transports collectifs, végétalisation","points":5}],"dureeMin":10,"corrige":"1. Les tours : **quartier d'affaires** (CBD). Le bidonville : habitat précaire (favelas, slums). Les lotissements sur les rizières : **étalement urbain**, la ville grignote les campagnes.\n\n2. Oui : avec **12 millions** d'habitants, c'est une **mégapole** (plus de 10 millions).\n\n3. C'est l'**îlot de chaleur urbain** : la ville est plus chaude que la campagne voisine (béton, peu de végétation). Réponses : **densification**, **transports collectifs**, **végétalisation**."}$exo$::jsonb),
  ('7f7c0bad-8a3e-50d1-a7f4-815e8facf8e1'::uuid, 3, 'redaction', $exo${"titre":"Des villes qui grandissent vite","consigne":"Rédige un paragraphe argumenté d'une quinzaine de lignes en t'appuyant sur des exemples précis.","enonce":"**Sujet.** « Une ville qui grandit vite ne devient pas riche partout en même temps : elle fabrique du contraste avant de fabriquer du confort. »\n\n1. Compare la croissance urbaine des pays développés et des pays en développement.\n2. Donne un chiffre sur l'habitat précaire et cite deux noms qui le désignent.\n3. Rédige un paragraphe : quels défis la croissance urbaine pose-t-elle et comment y répondre ?","bareme":[{"critere":"Comparaison : lente et ancienne / rapide et moteur du mouvement","points":5},{"critere":"Environ un milliard en habitat précaire ; favelas, slums","points":4},{"critere":"Au moins trois défis cités (logement, transports, eau, déchets, pollution, îlot de chaleur)","points":6},{"critere":"Réponses et paragraphe structuré","points":5}],"dureeMin":15,"corrige":"1. Dans les pays **développés**, les villes sont anciennes et croissent lentement. Dans les pays **en développement**, surtout en **Asie** et en **Afrique**, la croissance est **rapide** et porte l'essentiel du mouvement.\n\n2. Environ **un milliard** de personnes vivent en habitat précaire : **bidonvilles**, **favelas**, **slums**.\n\n3. Paragraphe : défis de **logement**, de **transports**, d'**eau**, de **déchets**, de **pollution de l'air**, d'**îlot de chaleur urbain**, de préservation des terres agricoles face à l'**étalement urbain**. Réponses : **densification**, **transports collectifs**, **végétalisation**. Les tours de verre et les bidonvilles coexistent parfois à quelques centaines de mètres."}$exo$::jsonb),
  ('e1b2d4a2-9af3-545d-95cd-a8329995a0e7'::uuid, 1, 'redaction', $exo${"titre":"Les villes mondiales","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Qu'est-ce qu'une ville mondiale ? Cite trois exemples.\n2. Que transportent les ports à conteneurs ? les aéroports ? les câbles sous-marins ?\n3. Qu'est-ce que la métropolisation ?","bareme":[{"critere":"Ville mondiale définie, trois exemples exacts","points":7},{"critere":"Marchandises, personnes, données d'internet","points":6},{"critere":"Métropolisation définie","points":7}],"dureeMin":6,"corrige":"1. Une **ville mondiale** concentre la finance, les décisions et les flux. Exemples : **New York**, **Londres**, **Tokyo** (aussi Paris, Shanghai, Singapour, Hong Kong, Dubaï).\n\n2. Ports à conteneurs : les **marchandises**. Aéroports : les **personnes**. Câbles sous-marins : l'**essentiel d'internet**.\n\n3. La **métropolisation** est la concentration des activités, des emplois et des capitaux dans quelques grandes villes."}$exo$::jsonb),
  ('e1b2d4a2-9af3-545d-95cd-a8329995a0e7'::uuid, 2, 'redaction', $exo${"titre":"Deux villes, deux destins","consigne":"Lis le document, puis réponds aux questions.","enonce":"> **Document — Deux fiches de villes (texte écrit pour l'exercice).**\n> **Ville A.** 10 millions d'habitants ; un grand aéroport de correspondance ; le siège de nombreuses firmes ; une place boursière ; plusieurs universités réputées.\n> **Ville B.** 4 millions d'habitants ; croissance très rapide ; aucun aéroport international ; pas de câble sous-marin ; peu d'entreprises étrangères ; une grande partie des habitants travaille dans le commerce informel.\n\n1. Laquelle est une ville mondiale ? Justifie par deux éléments du document.\n2. Explique la situation de la ville B en utilisant l'expression « à l'écart ».\n3. Pourquoi une ville comme A attire-t-elle emplois et capitaux ?","bareme":[{"critere":"Ville A, avec deux éléments (aéroport, firmes, bourse, universités)","points":6},{"critere":"Ville B : grandit vite sans être reliée aux réseaux mondiaux","points":5},{"critere":"A concentre fonctions de commandement, attire emplois et capitaux","points":5},{"critere":"Réponses rédigées","points":4}],"dureeMin":10,"corrige":"1. La **ville A**, car elle a un **hub aéroportuaire**, des **sièges de firmes**, une **place boursière**, des **universités** : ce sont les fonctions qui fixent son rang.\n\n2. La ville B est **à l'écart** : elle grandit vite sans être reliée aux réseaux mondiaux (aéroports, câbles, sièges de firmes). Elle concentre la **population** sans concentrer la **richesse**.\n\n3. Une ville bien connectée attire **emplois**, **étudiants** et **capitaux**, souvent au détriment des villes moyennes de son propre pays : c'est la **métropolisation**."}$exo$::jsonb),
  ('e1b2d4a2-9af3-545d-95cd-a8329995a0e7'::uuid, 3, 'redaction', $exo${"titre":"La mondialisation relie des villes","consigne":"Rédige un paragraphe argumenté d'une quinzaine de lignes en t'appuyant sur des exemples précis.","enonce":"**Sujet.** « La mondialisation ne relie pas des pays : elle relie des villes, et elle en laisse beaucoup de côté. »\n\n1. Explique l'expression « hiérarchie urbaine » avec des fonctions précises.\n2. Montre par un exemple que les villes mondiales sont plus proches entre elles que de leur arrière-pays.\n3. Rédige un paragraphe : comment les villes se font-elles concurrence, et quels risques cette compétition comporte-t-elle ?","bareme":[{"critere":"Hiérarchie urbaine : rang selon les fonctions (bourses, sièges, universités, aéroports)","points":5},{"critere":"Exemple Londres-New York plus liés que Londres et une ville anglaise moyenne","points":5},{"critere":"Compétition pour entreprises, congrès, grands événements ; endettement, équipements inutiles","points":6},{"critere":"Paragraphe argumenté","points":4}],"dureeMin":15,"corrige":"1. Les villes ne se valent pas : leur **rang** dépend de leurs **fonctions** : **bourses**, **sièges sociaux**, **universités**, **aéroports**, institutions internationales.\n\n2. Une décision prise à **Londres** pèse davantage sur **New York** que sur une ville anglaise moyenne : les villes mondiales sont reliées **entre elles** bien plus étroitement qu'à leur arrière-pays.\n\n3. Paragraphe : les villes se disputent **entreprises**, **congrès** et **grands événements** (Jeux olympiques, expositions universelles) pour la visibilité et les capitaux, mais elles peuvent **s'endetter** pour des équipements dont l'usage après coup n'est pas garanti. Cela creuse l'écart avec les villes à l'écart."}$exo$::jsonb),
  ('2b7b7129-b680-5559-83f6-c675d1f5476b'::uuid, 1, 'redaction', $exo${"titre":"Le commerce triangulaire","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Quels ports européens s'enrichissent grâce au grand commerce ? Cite deux ports français et deux ports britanniques.\n2. Décris les trois étapes du commerce triangulaire.\n3. Combien d'Africains ont été déportés par la traite atlantique ?","bareme":[{"critere":"Bordeaux, Nantes ; Liverpool, Bristol","points":6},{"critere":"Trois étapes : Europe → Afrique → Amérique → Europe avec cargaison","points":8},{"critere":"Environ 12 millions","points":6}],"dureeMin":7,"corrige":"1. France : **Bordeaux**, **Nantes**. Royaume-Uni : **Liverpool**, **Bristol**.\n\n2. **Europe → Afrique** : armes, tissus, alcool, verroterie contre des **captifs**. **Afrique → Amérique** : la traversée des esclaves, le « **passage du milieu** ». **Amérique → Europe** : les produits des **plantations** (sucre, café, cacao, coton, tabac).\n\n3. Environ **12 millions** d'Africains entre le XVIe et le XIXe siècle."}$exo$::jsonb),
  ('2b7b7129-b680-5559-83f6-c675d1f5476b'::uuid, 2, 'redaction', $exo${"titre":"Un armateur de Nantes","consigne":"Lis le document, puis réponds aux questions.","enonce":"> **Document — Lettre d'un armateur (texte écrit pour l'exercice), Nantes, 1770.**\n> « Mon navire part en février avec des armes, des tissus et de l'alcool. Il les échangera sur la côte africaine contre des captifs qu'il vendra aux planteurs de Saint-Domingue. Il reviendra chargé de sucre et de café que je revendrai à Bordeaux. Chaque étape me rapporte, et j'espère que mes affaires me permettront d'acheter une terre et de siéger un jour aux affaires du royaume. »\n\n1. Quelle organisation commerciale ce document décrit-il ? Nomme-la et explique-la.\n2. Pourquoi ce commerce est-il si rentable et durable ?\n3. Quelle ambition l'armateur exprime-t-il ? Quel groupe social représente-t-il ?","bareme":[{"critere":"Commerce triangulaire nommé et expliqué avec étapes","points":6},{"critere":"Chaque étape rapporte, raison économique de la persistance","points":5},{"critere":"Ambition politique et sociale ; négociants et armateurs, nouvelle bourgeoisie","points":6},{"critere":"Réponses rédigées","points":3}],"dureeMin":10,"corrige":"1. Le **commerce triangulaire** : Europe → Afrique (marchandises contre captifs), Afrique → Amérique (traversée, « passage du milieu »), Amérique → Europe (produits des plantations).\n\n2. **Chaque étape rapporte** : c'est ce qui rend l'ensemble extraordinairement rentable et explique sa persistance.\n\n3. Il veut acquérir des **terres** et **peser politiquement**. Il représente la **bourgeoisie négociante**, des négociants et armateurs enrichis sans être nobles, qui bâtissent des hôtels particuliers et financent des théâtres. Cette frustration politique nourrira 1789."}$exo$::jsonb),
  ('2b7b7129-b680-5559-83f6-c675d1f5476b'::uuid, 3, 'redaction', $exo${"titre":"Fortunes et contestations","consigne":"Rédige un paragraphe argumenté d'une quinzaine de lignes en t'appuyant sur des exemples et des dates.","enonce":"**Sujet.** Les ports atlantiques s'enrichissent comme jamais au XVIIIe siècle, mais cette fortune repose sur la vente d'êtres humains.\n\n1. Explique ce qu'est le Code Noir de 1685 et ce qu'il dit de l'esclave.\n2. Cite les dates de la première abolition, du rétablissement et de l'abolition définitive de l'esclavage en France.\n3. Rédige un paragraphe : comment l'esclavage a-t-il été contesté ? Cite deux penseurs et une association.","bareme":[{"critere":"Code Noir : règle l'esclavage aux Antilles, esclave bien meuble","points":5},{"critere":"Dates exactes : 1794, 1802, 1848","points":5},{"critere":"Contestations : Montesquieu ironise, Condorcet condamne, Société des amis des Noirs (1788), révoltes d'esclaves","points":6},{"critere":"Paragraphe argumenté","points":4}],"dureeMin":15,"corrige":"1. Le **Code Noir** (1685) règle l'esclavage aux Antilles : il définit l'esclave comme un **bien meuble**, juridiquement une chose que l'on possède, vend et transmet.\n\n2. **1794** : première abolition. **1802** : Bonaparte rétablit l'esclavage. **1848** : abolition définitive.\n\n3. Paragraphe : **Montesquieu** ironise, **Condorcet** condamne. La **Société des amis des Noirs** est fondée en **1788**. Et des **révoltes d'esclaves** éclatent bien avant que l'Europe n'en débatte : les esclaves sont les premiers acteurs de leur libération. La contestation est lente car le système est très rentable pour les ports et les planteurs."}$exo$::jsonb),
  ('6255e663-4edf-5792-a61b-5d5e190bdddd'::uuid, 1, 'redaction', $exo${"titre":"Les grands noms des Lumières","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Quel principe est au cœur des Lumières ?\n2. Associe chaque penseur à son idée : Montesquieu, Voltaire, Rousseau.\n3. Qu'est-ce que l'Encyclopédie ? Qui la dirige et en quelles années paraît-elle ?","bareme":[{"critere":"La raison doit éclairer le monde, à la place de la tradition et de l'autorité","points":5},{"critere":"Montesquieu (séparation des pouvoirs), Voltaire (tolérance), Rousseau (souveraineté du peuple)","points":8},{"critere":"Encyclopédie : 28 volumes, Diderot et d'Alembert, 1751-1772","points":7}],"dureeMin":7,"corrige":"1. La **raison** doit éclairer le monde, à la place de la **tradition** et de l'**autorité**.\n\n2. **Montesquieu** : la **séparation des pouvoirs** (exécutif, législatif, judiciaire), dans *De l'esprit des lois* (1748). **Voltaire** : la **tolérance religieuse**, contre le fanatisme (affaire Calas). **Rousseau** : la **souveraineté du peuple**, dans *Du contrat social* (1762).\n\n3. L'**Encyclopédie** réunit et diffuse tout le savoir en **28 volumes**. Elle est dirigée par **Diderot** et **d'Alembert** et paraît de **1751 à 1772**."}$exo$::jsonb),
  ('6255e663-4edf-5792-a61b-5d5e190bdddd'::uuid, 2, 'redaction', $exo${"titre":"Un livre interdit","consigne":"Lis le document, puis réponds aux questions.","enonce":"> **Document — Lettre d'un libraire (texte écrit pour l'exercice), Paris, 1760.**\n> « Le livre que vous me demandez est interdit par la censure. Il a été imprimé à Amsterdam et je l'ai reçu caché parmi des sacs de farine. Je ne peux le vendre que sous le manteau, à des clients sûrs, et il coûte trois fois son prix. Hier soir, on en a lu des passages dans le salon de Mme de Verneuil. »\n\n1. Pourquoi le livre est-il imprimé à l'étranger ?\n2. Relève deux lieux ou moyens par lesquels les idées des Lumières circulent.\n3. Que dit le cours d'une idée interdite ? Comment ce document l'illustre-t-il ?","bareme":[{"critere":"Échapper à la censure","points":4},{"critere":"Deux moyens : livres sous le manteau, salons (et cafés, académies, loges)","points":6},{"critere":"Idée interdite circule plus cher et plus vite","points":5},{"critere":"Lien avec le document (prix triplé, lectures en salon)","points":5}],"dureeMin":10,"corrige":"1. Pour **échapper à la censure** française.\n\n2. Le **livre vendu sous le manteau**, le **salon** (souvent tenu par une femme, ici Mme de Verneuil). Le cours ajoute cafés, académies et loges maçonniques.\n\n3. « Une idée interdite ne cesse pas de circuler : elle circule **plus cher**, et **plus vite**. » Dans le document, le livre coûte **trois fois son prix**, mais des passages sont lus en salon dès le lendemain."}$exo$::jsonb),
  ('6255e663-4edf-5792-a61b-5d5e190bdddd'::uuid, 3, 'redaction', $exo${"titre":"Éclairer sans partager","consigne":"Rédige un paragraphe argumenté d'une quinzaine de lignes en t'appuyant sur des exemples précis.","enonce":"**Sujet.** Les Lumières critiquent la monarchie absolue, les privilèges et l'intolérance, mais certains souverains se disent inspirés par elles.\n\n1. Cite trois revendications des Lumières.\n2. Donne trois souverains éclairés avec leur pays.\n3. Rédige un paragraphe : le despotisme éclairé applique-t-il vraiment les idées des Lumières ? Termine par la portée de ces idées (deux dates).","bareme":[{"critere":"Trois revendications (liberté d'expression, conscience, égalité devant la loi, justice, fin de la torture)","points":4},{"critere":"Frédéric II (Prusse), Catherine II (Russie), Joseph II (Autriche)","points":4},{"critere":"Réformes mais tout le pouvoir gardé : au nom du peuple, jamais avec lui","points":7},{"critere":"Portée : 1776 et 1789, textes sur les droits de l'homme","points":5}],"dureeMin":15,"corrige":"1. Trois au choix : **liberté d'expression**, **liberté de conscience**, **égalité devant la loi**, **justice équitable**, **fin de la torture**.\n\n2. **Frédéric II** (Prusse), **Catherine II** (Russie), **Joseph II** (Autriche).\n\n3. Paragraphe : les souverains réforment (tolérance, codes de lois, écoles) mais **gardent tout le pouvoir** : le despotisme éclairé réforme **au nom du peuple, jamais avec lui**. Ils ne remettent pas en cause la monarchie absolue et les privilèges. Les vraies conséquences viennent ailleurs : **1776**, Déclaration d'indépendance américaine ; **1789**, Révolution française. Ces idées fondent encore nos textes sur les droits de l'homme."}$exo$::jsonb),
  ('49b51a1c-152a-5f93-9a94-69520a6b9e39'::uuid, 1, 'redaction', $exo${"titre":"Les trois ordres","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Nomme les trois ordres de l'Ancien Régime et indique lesquels sont privilégiés.\n2. Quelle part de la population représente le tiers état ?\n3. Donne la date de la prise de la Bastille et celle de la Déclaration des droits de l'homme et du citoyen.","bareme":[{"critere":"Clergé, noblesse, tiers état ; clergé et noblesse privilégiés","points":7},{"critere":"98 %","points":4},{"critere":"14 juillet 1789 et 26 août 1789","points":9}],"dureeMin":6,"corrige":"1. Le **clergé**, la **noblesse** et le **tiers état**. Le clergé et la noblesse sont **privilégiés**, exemptés de l'essentiel des impôts ; le tiers état paie.\n\n2. Le tiers état représente **98 %** de la population.\n\n3. Prise de la Bastille : **14 juillet 1789**. Déclaration des droits de l'homme et du citoyen : **26 août 1789**."}$exo$::jsonb),
  ('49b51a1c-152a-5f93-9a94-69520a6b9e39'::uuid, 2, 'redaction', $exo${"titre":"Le pain à Paris en 1789","consigne":"Lis le document, puis réponds aux questions.","enonce":"> **Document — Lettre d'un boulanger parisien (texte écrit pour l'exercice), juin 1789.**\n> « La récolte de l'an dernier fut mauvaise et le prix du pain n'a cessé de monter : une famille d'ouvriers dépense presque tout son salaire pour manger. On dit que le roi a besoin d'argent et que les impôts retombent toujours sur nous. Les députés du tiers état se sont proclamés Assemblée nationale et ont juré de ne pas se séparer avant d'avoir donné une constitution. »\n\n1. Quelles sont les deux causes de la crise que le document laisse voir ?\n2. De quel événement du 20 juin 1789 le texte parle-t-il en fin de document ? Explique.\n3. Quels événements suivent, en juillet et août ? Cite-en trois avec leur date.","bareme":[{"critere":"Crise financière (impôts, roi sans argent) et mauvaises récoltes (pain cher)","points":5},{"critere":"Serment du Jeu de paume expliqué","points":5},{"critere":"Trois événements datés : 14 juillet, Grande Peur, 4 août, 26 août","points":7},{"critere":"Réponses rédigées","points":3}],"dureeMin":10,"corrige":"1. Les finances royales ruinées (impôts qui retombent sur le tiers état) et les **mauvaises récoltes de 1788** : le **pain** devient hors de prix.\n\n2. Le **serment du Jeu de paume** (20 juin) : les députés du tiers état jurent de ne pas se séparer avant d'avoir donné une **constitution** à la France.\n\n3. **14 juillet** : prise de la Bastille ; été 1789 : **Grande Peur** dans les campagnes ; **4 août** : abolition des privilèges ; **26 août** : Déclaration des droits de l'homme et du citoyen."}$exo$::jsonb),
  ('49b51a1c-152a-5f93-9a94-69520a6b9e39'::uuid, 3, 'redaction', $exo${"titre":"Une révolution immense et incomplète","consigne":"Rédige un paragraphe argumenté d'une quinzaine de lignes en t'appuyant sur des exemples précis.","enonce":"**Sujet.** « Un texte peut être immense et incomplet en même temps. »\n\n1. Cite trois droits naturels proclamés par la Déclaration de 1789 et dis à qui appartient la souveraineté.\n2. Qui est exclu de la Déclaration ? Qui dénonce cette exclusion et quand ?\n3. Rédige un paragraphe : en quoi la Constitution de 1791 transforme-t-elle la monarchie tout en maintenant des inégalités ? (veto, suffrage censitaire)","bareme":[{"critere":"Trois droits naturels ; souveraineté à la Nation","points":5},{"critere":"Exclus : femmes et esclaves ; Olympe de Gouges, 1791","points":5},{"critere":"Constitution de 1791 : pouvoir du roi limité, veto ; suffrage censitaire expliqué","points":6},{"critere":"Paragraphe argumenté","points":4}],"dureeMin":15,"corrige":"1. **Liberté**, **propriété**, **sûreté**, **résistance à l'oppression**. La **souveraineté** appartient à la **Nation** ; la loi est l'expression de la volonté générale.\n\n2. La Déclaration ne concerne **ni les femmes, ni les esclaves** des colonies. **Olympe de Gouges** le dénonce dès **1791**.\n\n3. Paragraphe : la **Constitution de 1791** met fin à la monarchie absolue : le roi voit son pouvoir **limité**, mais garde un **droit de veto**. Le suffrage est **censitaire** : seuls votent les hommes payant un certain impôt. L'égalité proclamée en 1789 est donc limitée. Mais les limites du texte ont servi d'argument à ceux qui ont ensuite obtenu leur suppression."}$exo$::jsonb),
  ('22991364-07ac-5bf7-9059-313215b36cd6'::uuid, 1, 'redaction', $exo${"titre":"De la monarchie à la République","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Que se passe-t-il en juin 1791 ? Pourquoi le roi perd-il la confiance du pays ?\n2. Donne la date de la proclamation de la Première République et celle de l'exécution de Louis XVI.\n3. Quel organe gouverne pendant la Terreur et qui le domine ?","bareme":[{"critere":"Fuite à Varennes, roi arrêté","points":6},{"critere":"22 septembre 1792 et 21 janvier 1793","points":8},{"critere":"Comité de salut public dominé par Robespierre","points":6}],"dureeMin":7,"corrige":"1. C'est la **fuite à Varennes** : le roi tente de quitter le pays et est arrêté. Il perd la confiance du pays.\n\n2. République : **22 septembre 1792**. Exécution de Louis XVI : **21 janvier 1793**.\n\n3. Le **Comité de salut public**, dominé par **Robespierre**."}$exo$::jsonb),
  ('22991364-07ac-5bf7-9059-313215b36cd6'::uuid, 2, 'redaction', $exo${"titre":"Un suspect en 1793","consigne":"Lis le document, puis réponds aux questions.","enonce":"> **Document — Récit d'un habitant de Nantes (texte écrit pour l'exercice), automne 1793.**\n> « Mon voisin a été arrêté hier : on l'accuse de ne pas aimer la République, mais personne ne sait rien de précis. Il attendra le tribunal révolutionnaire, qui juge vite. Dans les campagnes de l'Ouest, l'insurrection se poursuit et l'armée y est envoyée. À Paris, on réquisitionne le blé et on fixe le prix maximum du pain. »\n\n1. Quelle mesure permet d'arrêter quelqu'un « sur simple soupçon » ? Quelle est cette loi ?\n2. Dans quel contexte de danger la République agit-elle ainsi ? Cite trois menaces.\n3. Nomme la région de l'insurrection et une mesure économique évoquée.","bareme":[{"critere":"Loi des suspects, arrestation sur simple soupçon","points":5},{"critere":"Trois menaces : guerre aux frontières, insurrection en Vendée, révoltes fédéralistes","points":6},{"critere":"Vendée ; maximum des prix / réquisitions (levée en masse)","points":5},{"critere":"Réponses rédigées","points":4}],"dureeMin":10,"corrige":"1. La **loi des suspects** permet d'être arrêté sur simple **soupçon**.\n\n2. La République est menacée de toutes parts : **guerre** aux frontières, **insurrection en Vendée**, **révoltes fédéralistes**. Le Comité de salut public gouverne par l'exception.\n\n3. La **Vendée** (l'Ouest). Le **maximum des prix** et les **réquisitions** relèvent de la levée en masse."}$exo$::jsonb),
  ('22991364-07ac-5bf7-9059-313215b36cd6'::uuid, 3, 'redaction', $exo${"titre":"Liberté et Terreur","consigne":"Rédige un paragraphe argumenté d'une quinzaine de lignes en t'appuyant sur des exemples précis.","enonce":"**Sujet.** « La Terreur est faite au nom de la liberté, contre des gens jugés sans preuve. »\n\n1. Donne un chiffre sur la répression du tribunal révolutionnaire et un sur la Vendée.\n2. Cite trois avancées de la Convention, dont une jamais appliquée.\n3. Rédige un paragraphe sur le paradoxe de la Révolution en terminant par la chute de Robespierre (date) et ce qui suit jusqu'en 1799.","bareme":[{"critere":"Environ 17 000 condamnations à mort ; des dizaines de milliers de morts en Vendée","points":4},{"critere":"Trois avancées : esclavage février 1794, suffrage universel masculin (1793, jamais appliqué), instruction publique, système métrique","points":5},{"critere":"Paradoxe liberté / terreur exposé sans excès de simplification","points":6},{"critere":"9 thermidor an II (27 juillet 1794), Directoire, 18 brumaire","points":5}],"dureeMin":15,"corrige":"1. Environ **17 000** condamnations à mort par le tribunal révolutionnaire ; des **dizaines de milliers de morts** en Vendée.\n\n2. Abolition de l'**esclavage** (février **1794**) ; **suffrage universel masculin** (Constitution de 1793, **jamais appliquée**) ; **instruction publique**, **système métrique**.\n\n3. Paragraphe : la Terreur défend la République menacée, mais elle arrête sur soupçon, juge vite et guillotine. Le paradoxe est celui d'une révolution qui proclame la liberté et suspend les libertés. Le **9 thermidor an II** (27 juillet 1794), **Robespierre** est renversé et exécuté. Suivent le **Directoire** (1795-1799), régime instable, puis le coup d'État du **18 brumaire** (9 novembre 1799) de Bonaparte."}$exo$::jsonb),
  ('b0461f1e-9622-5e6b-b130-43b5e4d03254'::uuid, 1, 'redaction', $exo${"titre":"Bonaparte prend le pouvoir","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Comment Bonaparte prend-il le pouvoir en 1799 ? Quel titre reçoit-il ?\n2. Quand est-il sacré empereur ?\n3. Cite deux institutions qu'il consolide.","bareme":[{"critere":"Coup d'État du 18 brumaire (9 novembre 1799), Premier consul","points":7},{"critere":"2 décembre 1804","points":5},{"critere":"Deux institutions : Code civil, Banque de France, préfets, lycées, Concordat…","points":8}],"dureeMin":6,"corrige":"1. Par le **coup d'État du 18 brumaire** (**9 novembre 1799**) : il devient **Premier consul**.\n\n2. Le **2 décembre 1804**.\n\n3. Deux au choix : **Code civil** (1804), **Banque de France** et franc germinal, **préfets** et cadastre, **lycées** et Légion d'honneur, **Concordat** (1801)."}$exo$::jsonb),
  ('b0461f1e-9622-5e6b-b130-43b5e4d03254'::uuid, 2, 'redaction', $exo${"titre":"Un bulletin de vote qui n'en est pas un","consigne":"Lis le document, puis réponds aux questions.","enonce":"> **Document — Article de journal (texte écrit pour l'exercice), 1804.**\n> « Les Français sont appelés à répondre par oui ou par non à la question suivante : le peuple veut-il que Napoléon Bonaparte soit empereur ? Aucun autre candidat n'est proposé. Les journaux publient les résultats sous le contrôle du gouvernement, et les articles critiques sont supprimés par la censure. »\n\n1. Comment appelle-t-on ce type de vote ? Pourquoi ne s'agit-il pas d'une vraie élection ?\n2. Quelle liberté le texte montre-t-il supprimée ?\n3. Cite deux libertés ou droits que Napoléon garde ou supprime, et un acquis conservé de la Révolution.","bareme":[{"critere":"Plébiscite, approuve mais ne choisit pas","points":6},{"critere":"Liberté de la presse, censure","points":4},{"critere":"Un droit supprimé (esclavage rétabli 1802, droits des femmes) ; un acquis (égalité devant la loi, Code civil)","points":6},{"critere":"Réponses rédigées","points":4}],"dureeMin":10,"corrige":"1. Un **plébiscite** : on approuve, on ne **choisit** pas. Il n'y a qu'un seul « candidat » : les élections réelles sont supprimées.\n\n2. La **liberté de la presse** : les journaux sont censurés, les opposants surveillés.\n\n3. Supprimé : l'abolition de l'**esclavage** (rétabli en **1802**) ; les droits des **femmes** (le Code civil place la femme mariée sous l'autorité de son mari). Gardé : l'**égalité devant la loi**, la propriété garantie (**Code civil**, 1804). Il garde l'égalité devant la loi et l'administration et supprime tout ce qui contrôle le pouvoir."}$exo$::jsonb),
  ('b0461f1e-9622-5e6b-b130-43b5e4d03254'::uuid, 3, 'redaction', $exo${"titre":"Napoléon, héritier ou fossoyeur de la Révolution ?","consigne":"Rédige un paragraphe argumenté d'une quinzaine de lignes en t'appuyant sur des exemples et des dates.","enonce":"**Sujet.** Napoléon garde de la Révolution ce qui rend l'État fort et supprime ce qui limite le pouvoir.\n\n1. Donne trois mesures qui consolident l'État.\n2. Retrace la chute de l'Empire en quatre dates (1812, 1813, 1815 et un événement d'Espagne).\n3. Rédige un paragraphe : que reste-t-il de l'œuvre de Napoléon après 1815, alors que les rois reviennent ?","bareme":[{"critere":"Trois mesures exactes","points":4},{"critere":"Chute : guerre d'Espagne, Russie 1812, Leipzig 1813, Waterloo 1815, Sainte-Hélène","points":6},{"critere":"Congrès de Vienne rétablit les rois ; Code civil, administration, idée de nation restent","points":6},{"critere":"Paragraphe argumenté","points":4}],"dureeMin":15,"corrige":"1. Trois au choix : **Code civil**, **Banque de France** et franc germinal, **préfets** et cadastre, **lycées**, **Légion d'honneur**, **Concordat**.\n\n2. La guerre d'**Espagne** s'enlise avant la Russie ; **1812** : la campagne de Russie tourne au désastre ; **1813** : défaite de **Leipzig** ; **1815** : **Waterloo**, exil à **Sainte-Hélène**.\n\n3. Paragraphe : le **congrès de Vienne** rétablit les rois en 1815, mais le **Code civil**, l'**administration** centralisée et l'**idée de nation** restent : ils traverseront tout le XIXe siècle. Le Code civil inspire encore le droit de dizaines de pays. L'héritage est donc double : État fort et égalité juridique, mais aussi mémoire d'un pouvoir sans contrôle."}$exo$::jsonb),
  ('1545e755-542d-5d56-b483-50163051d583'::uuid, 1, 'redaction', $exo${"titre":"Le vocabulaire des migrations","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Combien de personnes vivent hors de leur pays de naissance ? Quelle part de l'humanité cela représente-t-il ?\n2. Distingue émigrer et immigrer.\n3. Qu'est-ce qu'un réfugié ?","bareme":[{"critere":"Environ 280 millions, soit 3,5 %","points":7},{"critere":"Émigrer : partir de ; immigrer : arriver dans","points":6},{"critere":"Réfugié fuyant un danger, protégé par la convention de Genève","points":7}],"dureeMin":6,"corrige":"1. Environ **280 millions** de personnes, soit **3,5 %** de l'humanité.\n\n2. **Émigrer**, c'est partir **de** son pays ; **immigrer**, c'est arriver **dans** un pays.\n\n3. Un **réfugié** est une personne qui fuit un danger (guerre, persécution) et est protégée par la **convention de Genève** (1951)."}$exo$::jsonb),
  ('1545e755-542d-5d56-b483-50163051d583'::uuid, 2, 'redaction', $exo${"titre":"Idées reçues sur les migrations","consigne":"Lis le document, puis réponds aux questions.","enonce":"> **Document — Extrait d'un débat (texte écrit pour l'exercice).**\n> « Tous les migrants du monde veulent aller en Europe, et l'Europe accueille la plupart des réfugiés. » — « Non, répond une lycéenne. Chez nous, en classe, on a appris que la plupart des gens migrent vers un pays voisin. Et que des pays pauvres accueillent bien plus de réfugiés que l'Europe. »\n\n1. Que penser de la première affirmation ? Rectifie-la avec deux faits du cours.\n2. Cite deux causes de migration en précisant laquelle est majoritaire.\n3. Nomme un effet pour le pays de départ et un pour le pays d'arrivée.","bareme":[{"critere":"Rectification : majorité des migrations entre pays voisins ; réfugiés surtout dans des pays en développement","points":7},{"critere":"Deux causes ; économique majoritaire","points":5},{"critere":"Départ : fuite des cerveaux ou transferts d'argent ; arrivée : main-d'œuvre, jeunesse, compétences","points":6},{"critere":"Réponses rédigées","points":2}],"dureeMin":10,"corrige":"1. Elle est fausse : la majorité des migrations se font **entre pays voisins** et la majorité des **réfugiés** sont accueillis par des **pays en développement**, pas par l'Europe. Ce qu'on croit un mouvement Sud-Nord est d'abord Sud-Sud.\n\n2. Cause **économique** (chercher du travail : la cause **majoritaire**), politique, familiale, étudiante, environnementale.\n\n3. Départ : la **fuite des cerveaux** (perte de diplômés) ou les **transferts d'argent** (plusieurs fois l'aide au développement). Arrivée : apport de **main-d'œuvre**, de compétences, de jeunesse."}$exo$::jsonb),
  ('1545e755-542d-5d56-b483-50163051d583'::uuid, 3, 'redaction', $exo${"titre":"Les migrants : un phénomène nuancé","consigne":"Rédige un paragraphe argumenté d'une quinzaine de lignes en t'appuyant sur des exemples précis.","enonce":"**Sujet.** Les migrations internationales concernent une faible part de l'humanité, mais elles suscitent des débats vifs.\n\n1. Explique pourquoi 3,5 % est une part faible mais en hausse.\n2. Décris les dangers des routes migratoires (deux exemples de routes).\n3. Rédige un paragraphe : les migrations sont-elles un problème ou une ressource ? Discute les effets sur le pays de départ et sur le pays d'arrivée.","bareme":[{"critere":"Part faible, en hausse, très inégalement répartie","points":4},{"critere":"Routes : Méditerranée, Sahara, désert Mexique-États-Unis ; passeurs, milliers de morts","points":5},{"critere":"Effets nuancés départ/arrivée avec fuite des cerveaux, transferts, main-d'œuvre, débats politiques","points":7},{"critere":"Paragraphe argumenté avec conclusion","points":4}],"dureeMin":15,"corrige":"1. 3,5 % de l'humanité vit hors de son pays de naissance : c'est une part **faible**, mais **en hausse** et **très inégalement répartie**.\n\n2. La **Méditerranée**, le **Sahara**, le désert entre le **Mexique** et les **États-Unis** : ces routes tuent chaque année des milliers de personnes et alimentent des réseaux de **passeurs**.\n\n3. Paragraphe : pour le pays de départ, la **fuite des cerveaux** prive de diplômés, mais les **transferts d'argent** dépassent plusieurs fois l'aide au développement. Pour le pays d'arrivée : apport de **main-d'œuvre**, de compétences, de jeunesse, mais aussi débats politiques vifs. Conclusion nuancée : ni problème ni solution unique, un phénomène majoritairement régional."}$exo$::jsonb),
  ('887e3308-bd55-5205-8129-5653367a928d'::uuid, 1, 'redaction', $exo${"titre":"Le tourisme en chiffres","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Combien de touristes internationaux compte-t-on par an avant 2020 ?\n2. Qui voyage principalement ?\n3. Cite trois grands espaces touristiques.","bareme":[{"critere":"Plus d'un milliard","points":5},{"critere":"Habitants des pays développés et classes moyennes émergentes (Chine, Inde, Brésil)","points":7},{"critere":"Trois espaces : littoraux, montagne, villes d'art, espaces naturels protégés","points":8}],"dureeMin":6,"corrige":"1. **Plus d'un milliard** par an avant 2020.\n\n2. Surtout les habitants des pays **développés** et les **classes moyennes émergentes** (Chine, Inde, Brésil).\n\n3. Les **littoraux** chauds (Méditerranée, Caraïbes, Asie du Sud-Est), la **montagne**, les **villes d'art** (Paris, Rome, Venise, Kyoto), les espaces **naturels** protégés (parcs, safaris)."}$exo$::jsonb),
  ('887e3308-bd55-5205-8129-5653367a928d'::uuid, 2, 'redaction', $exo${"titre":"Venise ou l'île qui se vide","consigne":"Lis le document, puis réponds aux questions.","enonce":"> **Document — Interview d'une habitante d'une ville d'art (texte écrit pour l'exercice).**\n> « Chaque été, des milliers de visiteurs envahissent les ruelles. Les commerces de quartier ferment pour laisser place aux boutiques de souvenirs. Les loyers ont tellement monté que mes voisins sont partis. Mon travail de serveuse dépend de la saison : en hiver, je suis sans emploi. »\n\n1. Quel phénomène est décrit ? Définis-le.\n2. Relève deux effets négatifs du tourisme dans ce texte.\n3. Cite un effet positif du tourisme et une réponse possible au problème.","bareme":[{"critere":"Surtourisme défini","points":5},{"critere":"Deux effets : chasse les habitants par les prix, emplois saisonniers, perte des commerces","points":6},{"critere":"Un effet positif (emplois, devises, patrimoine, désenclavement)","points":4},{"critere":"Une réponse : régulation des flux, quotas, tourisme de proximité, écotourisme","points":5}],"dureeMin":10,"corrige":"1. Le **surtourisme** : une fréquentation si forte qu'elle dégrade le lieu et chasse les habitants. Le cours cite Venise, Barcelone, Machu Picchu.\n\n2. Le tourisme **chasse les habitants par les prix** (loyers) ; les emplois sont **saisonniers** et peu qualifiés (la serveuse est sans emploi l'hiver).\n\n3. Positif : **emplois**, **devises**, entretien du **patrimoine**, désenclavement de certaines régions. Réponse : **régulation des flux**, **quotas**, tourisme de proximité, **écotourisme**."}$exo$::jsonb),
  ('887e3308-bd55-5205-8129-5653367a928d'::uuid, 3, 'redaction', $exo${"titre":"Le tourisme, richesse et fragilité","consigne":"Rédige un paragraphe argumenté d'une quinzaine de lignes en t'appuyant sur des exemples précis.","enonce":"**Sujet.** « Une région qui vit du tourisme dépend d'une décision prise ailleurs. »\n\n1. Explique pourquoi le tourisme est un marqueur d'inégalité mondiale (trois conditions).\n2. Donne deux aménagements touristiques et un exemple de paysage fabriqué de toutes pièces.\n3. Rédige un paragraphe : le tourisme est-il une chance ou un risque pour un pays qui en dépend ? Cite deux avantages et deux inconvénients.","bareme":[{"critere":"Trois conditions : temps libre, revenu, passeport utile","points":4},{"critere":"Deux aménagements (hôtels, marinas…) et Dubaï ou Cancún","points":4},{"critere":"Avantages et inconvénients cités (emplois, devises ; bétonisation, saisonnier, dépendance)","points":7},{"critere":"Paragraphe argumenté, dépendance aux crises","points":5}],"dureeMin":15,"corrige":"1. Voyager suppose du **temps libre**, un **revenu** et un **passeport utile** : le tourisme n'est pas ouvert à tous.\n\n2. Aménagements : hôtels, resorts, marinas, remontées mécaniques, aéroports, parcs à thème. Paysages fabriqués : **Dubaï**, **Cancún**.\n\n3. Paragraphe : **avantages** : emplois, devises, entretien du patrimoine. **Inconvénients** : emplois **saisonniers** et peu qualifiés, **bétonisation** des littoraux, pression sur l'eau et les déchets, **surtourisme**. Surtout, la **dépendance** : un pays très tourné vers le tourisme s'effondre en cas de crise extérieure, car les voyageurs peuvent aller voir ailleurs du jour au lendemain. Des solutions : écotourisme, régulation des flux, quotas."}$exo$::jsonb),
  ('2c4af367-1f90-51b8-b1dd-f43ed6c28022'::uuid, 1, 'redaction', $exo${"titre":"Les régimes et le vote","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Qu'est-ce que le suffrage censitaire ?\n2. Quand le suffrage universel masculin est-il proclamé ? Quand les femmes votent-elles en France ?\n3. À quelle date l'isoloir apparaît-il ?","bareme":[{"critere":"Suffrage censitaire défini","points":7},{"critere":"1848 et 1944","points":8},{"critere":"1913","points":5}],"dureeMin":6,"corrige":"1. Le **suffrage censitaire** réserve le droit de vote à ceux qui paient un impôt élevé : voter est un privilège de fortune.\n\n2. Le suffrage universel masculin est proclamé en **1848** ; les femmes obtiennent le droit de vote en **1944**.\n\n3. L'**isoloir** est instauré en **1913**."}$exo$::jsonb),
  ('2c4af367-1f90-51b8-b1dd-f43ed6c28022'::uuid, 2, 'redaction', $exo${"titre":"Les électeurs sous la monarchie de Juillet","consigne":"Lis le document, puis réponds aux questions.","enonce":"> **Document — Tableau (texte écrit pour l'exercice à partir de chiffres du cours).**\n> | Régime | Nombre d'électeurs |\n> | Restauration | environ 100 000 |\n> | Monarchie de Juillet | environ 240 000 |\n> | Deuxième République | environ 9 millions |\n\n1. Quelle évolution ce tableau montre-t-il ? Calcule environ combien de fois plus d'électeurs il y a sous la Deuxième République que sous la monarchie de Juillet.\n2. Explique la différence entre suffrage censitaire et suffrage universel masculin.\n3. Quelle révolution précède la Deuxième République et quelle est celle de 1830 ?","bareme":[{"critere":"Évolution : forte hausse ; environ 37 fois (9 millions / 240 000)","points":6},{"critere":"Censitaire : privilège de fortune ; universel masculin : droit pour tous les hommes","points":6},{"critere":"Révolution de 1848 ; Trois Glorieuses (1830)","points":5},{"critere":"Réponses rédigées","points":3}],"dureeMin":10,"corrige":"1. Le nombre d'électeurs passe de **100 000** à **240 000**, puis à **9 millions** d'un coup. 9 000 000 / 240 000 = **37,5** : environ **37 fois** plus.\n\n2. **Censitaire** : ceux qui paient un impôt élevé votent (privilège de fortune). **Universel masculin** : tous les hommes votent, voter devient un **droit**. Les **femmes** en sont exclues jusqu'en **1944**.\n\n3. La **révolution de 1848** précède la Deuxième République ; celle de **1830** est celle des **Trois Glorieuses**, qui installe la monarchie de Juillet (Louis-Philippe)."}$exo$::jsonb),
  ('2c4af367-1f90-51b8-b1dd-f43ed6c28022'::uuid, 3, 'redaction', $exo${"titre":"Arracher le droit de vote","consigne":"Rédige un paragraphe argumenté d'une quinzaine de lignes en t'appuyant sur des exemples précis.","enonce":"**Sujet.** « Chaque avancée suit une crise. Aucune n'est offerte. »\n\n1. Présente les cinq régimes de 1815 à 1870 avec leurs dates.\n2. Explique comment Napoléon III encadre le suffrage universel.\n3. Rédige un paragraphe : comment le droit de vote a-t-il été conquis et pourquoi le vote reste-t-il limité jusqu'en 1913 et 1944 ?","bareme":[{"critere":"Restauration, monarchie de Juillet, IIe République, Second Empire, IIIe République (1870) avec dates","points":5},{"critere":"Candidature officielle et censure","points":4},{"critere":"Révolutions 1830 et 1848, banquets, presse ; vote public jusqu'en 1913 ; femmes 1944","points":7},{"critere":"Paragraphe argumenté","points":4}],"dureeMin":15,"corrige":"1. **1815-1830** Restauration ; **1830-1848** monarchie de Juillet ; **1848-1852** Deuxième République ; **1852-1870** Second Empire ; **1870** Troisième République.\n\n2. Napoléon III maintient le suffrage universel mais l'encadre par la **candidature officielle** (le pouvoir soutient ses candidats) et la **censure**.\n\n3. Paragraphe : le droit est arraché par les **révolutions de 1830 et 1848**, les barricades, la presse et les **banquets républicains** qui contournent l'interdiction de réunion. Le vote reste limité : longtemps **public**, donc **surveillé**, jusqu'à l'**isoloir** et l'enveloppe de **1913** ; et les **femmes** attendent **1944**. Cette lente conquête explique l'attachement des Français au vote."}$exo$::jsonb),
  ('9d5de0b0-162d-5646-8a5c-b20837b5bed7'::uuid, 1, 'redaction', $exo${"titre":"La naissance de la République","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Quand la Troisième République est-elle proclamée et après quelle défaite ?\n2. Que rendent les lois Jules Ferry de 1881-1882 ?\n3. Quelle loi de 1905 est votée ?","bareme":[{"critere":"4 septembre 1870, défaite de Sedan","points":7},{"critere":"École primaire gratuite, laïque et obligatoire","points":7},{"critere":"Séparation des Églises et de l'État","points":6}],"dureeMin":6,"corrige":"1. Le **4 septembre 1870**, après la défaite de **Sedan**.\n\n2. Les lois **Jules Ferry** (1881-1882) rendent l'école primaire **gratuite**, **laïque** et **obligatoire** (de 6 à 13 ans).\n\n3. La loi de **séparation des Églises et de l'État** (laïcité)."}$exo$::jsonb),
  ('9d5de0b0-162d-5646-8a5c-b20837b5bed7'::uuid, 2, 'redaction', $exo${"titre":"L'affaire Dreyfus","consigne":"Lis le document, puis réponds aux questions.","enonce":"> **Document — Journal d'un lycéen (texte écrit pour l'exercice), janvier 1898.**\n> « Papa et oncle Paul se sont disputés au dîner. Un officier, Dreyfus, a été condamné pour trahison, mais certains disent qu'on l'a condamné à tort parce qu'il est juif. Ce matin, un grand écrivain, Zola, a écrit une lettre ouverte dans un journal. Toute la France ne parle que de cela. »\n\n1. De quelle affaire s'agit-il ? Entre quelles dates a-t-elle divisé la France ?\n2. Quel texte de Zola le document évoque-t-il ? Comment s'appelle-t-il ?\n3. Comment la République ressort-elle de cette crise ?","bareme":[{"critere":"Affaire Dreyfus, 1894-1906","points":5},{"critere":"« J'accuse… ! » (1898)","points":5},{"critere":"République renforcée, attachement à la justice ; officier juif condamné à tort","points":6},{"critere":"Réponses rédigées","points":4}],"dureeMin":8,"corrige":"1. L'**affaire Dreyfus**, de **1894 à 1906**. Un officier juif est condamné à tort pour trahison.\n\n2. La lettre ouverte de **Zola**, « **J'accuse… !** », publiée en **1898**.\n\n3. La France se déchire, mais la République **tient** et en sort **renforcée** dans son attachement à la **justice**. Elle traverse aussi le boulangisme et le scandale de Panama."}$exo$::jsonb),
  ('9d5de0b0-162d-5646-8a5c-b20837b5bed7'::uuid, 3, 'redaction', $exo${"titre":"Enraciner la République","consigne":"Rédige un paragraphe argumenté d'une quinzaine de lignes en t'appuyant sur des exemples précis.","enonce":"**Sujet.** « Une république qui veut durer ne se contente pas de lois : elle forme ses citoyens. »\n\n1. Explique pourquoi la naissance de la République en 1875 fut difficile (vote, majorité à l'Assemblée).\n2. Donne quatre lois qui l'enracinent, avec leur date.\n3. Rédige un paragraphe : quel rôle l'école et les symboles jouent-ils, et qu'est-ce qui reste inachevé ?","bareme":[{"critere":"Amendement Wallon (1875) à une voix, monarchistes majoritaires, perte de l'Alsace-Moselle","points":5},{"critere":"Quatre lois datées : 1881 presse/réunion, 1881-1882 Ferry, 1884 syndicats, 1901 associations, 1905 séparation","points":5},{"critere":"École (français, histoire nationale, civisme, instituteur) et symboles (Marianne, 14 juillet 1880, Marseillaise 1879)","points":6},{"critere":"Inachevé : femmes, empire colonial, inégalités","points":4}],"dureeMin":15,"corrige":"1. Les **monarchistes** sont majoritaires ; en **1875**, l'**amendement Wallon** fait passer la République à **une seule voix**. Elle naît d'une défaite (Sedan), avec la perte de l'**Alsace-Moselle** et la Commune écrasée en 1871.\n\n2. Quatre au choix : **1881** liberté de la presse et de réunion ; **1881-1882** lois Ferry ; **1884** liberté syndicale ; **1901** liberté d'association ; **1905** séparation des Églises et de l'État.\n\n3. Paragraphe : l'**école** enseigne à lire, écrire, compter, le **français** (contre les langues régionales), l'**histoire nationale** et le **civisme** : l'**instituteur**, « hussard noir », fait face au curé. Symboles : **Marianne**, le **14 juillet** (1880), **La Marseillaise** (1879), la devise. Reste inachevé : les **femmes** ne votent pas, l'**empire colonial** contredit les principes, les **inégalités sociales** demeurent."}$exo$::jsonb),
  ('391db6c3-de5d-5a3a-a5f5-7a0cdc56013b'::uuid, 1, 'redaction', $exo${"titre":"Les femmes et le Code civil","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Quel statut le Code civil de 1804 donne-t-il à la femme mariée ?\n2. Cite deux choses qu'elle ne peut pas faire seule.\n3. Quand le divorce est-il autorisé, supprimé, puis rétabli ?","bareme":[{"critere":"Incapable majeure, sous l'autorité de son mari","points":7},{"critere":"Deux actes : travailler, ouvrir un compte, signer un contrat","points":5},{"critere":"1792, 1816, 1884","points":8}],"dureeMin":6,"corrige":"1. Elle est placée sous l'autorité de son mari : **incapable majeure**.\n\n2. Deux au choix : **travailler**, **ouvrir un compte**, **signer un contrat**.\n\n3. Autorisé en **1792**, supprimé en **1816**, rétabli en **1884**."}$exo$::jsonb),
  ('391db6c3-de5d-5a3a-a5f5-7a0cdc56013b'::uuid, 2, 'redaction', $exo${"titre":"Une ouvrière et une bourgeoise","consigne":"Lis le document, puis réponds aux questions.","enonce":"> **Document — Deux portraits (texte écrit pour l'exercice), France, vers 1890.**\n> **Jeanne, ouvrière du textile.** Elle travaille douze heures par jour, gagne moitié moins que ses collègues masculins et s'occupe seule de ses enfants le soir.\n> **Madame Roussel, épouse d'un notaire.** Elle ne travaille pas ; l'oisiveté affichée est un signe de richesse de son mari. Elle ne peut rien signer sans son accord.\n\n1. Compare la condition des deux femmes.\n2. Comment justifie-t-on le salaire moindre de Jeanne ?\n3. Cite deux avancées qui améliorent la situation des femmes entre 1861 et 1907, avec leur date.","bareme":[{"critere":"Comparaison : double journée sans protection / cantonnée au foyer, sous tutelle","points":6},{"critere":"Salaire vu comme un appoint","points":4},{"critere":"Deux avancées datées : 1861, 1880, 1881-1882, 1884, 1907","points":6},{"critere":"Réponses rédigées","points":4}],"dureeMin":10,"corrige":"1. **Jeanne** vit une **double journée** (travail et famille) sans aucune protection ; **Madame Roussel** est **cantonnée au foyer**, son oisiveté étant un signe de richesse **du mari**, et reste juridiquement sous son autorité. Les deux conditions sont très différentes selon les milieux.\n\n2. On considère son salaire comme un simple « **appoint** », d'où **moitié moins** qu'un homme pour le même travail.\n\n3. Deux au choix : **1861** Julie-Victoire Daubié, première bachelière ; **1880** loi Camille Sée, lycées de filles ; **1881-1882** école primaire obligatoire pour les deux sexes ; **1884** divorce rétabli ; **1907** femmes mariées disposent de leur salaire."}$exo$::jsonb),
  ('391db6c3-de5d-5a3a-a5f5-7a0cdc56013b'::uuid, 3, 'redaction', $exo${"titre":"Un siècle d'inégalités","consigne":"Rédige un paragraphe argumenté d'une quinzaine de lignes en t'appuyant sur des exemples précis.","enonce":"**Sujet.** Le XIXe siècle a inventé l'idée que la place des femmes serait « naturellement » au foyer, alors que des millions d'entre elles travaillaient en usine.\n\n1. Présente le travail des femmes au XIXe siècle (métiers, caractère « invisible »).\n2. Explique le combat pour le droit de vote : qui le mène, où, et quand il est obtenu en France.\n3. Rédige un paragraphe : pourquoi peut-on parler de décalage entre les faits et le discours sur les femmes ?","bareme":[{"critere":"Travail massif et invisible : ouvrières, domestiques, blanchisseuses, paysannes, travail à domicile","points":5},{"critere":"Suffragistes (Hubertine Auclert), suffragettes britanniques, 1944, refus du Sénat, retard","points":6},{"critere":"Décalage discours / réalité : au foyer contre travail réel, double journée, salaire moitié moindre","points":5},{"critere":"Paragraphe argumenté","points":4}],"dureeMin":15,"corrige":"1. Le travail des femmes est **massif et invisible** : ouvrières du textile, **domestiques**, **blanchisseuses**, paysannes, ouvrières à **domicile**.\n\n2. Les **suffragistes**, comme **Hubertine Auclert** en France, et les **suffragettes** au Royaume-Uni réclament le vote dès les **années 1870**. Refusé à plusieurs reprises par le **Sénat**, il n'est obtenu qu'en **1944**, très en retard sur les pays voisins.\n\n3. Paragraphe : le discours dit que la femme est « naturellement » au foyer ; en réalité, elle travaille massivement, souvent **payée moitié moins** et avec une **double journée**. Le Code civil la place sous l'autorité de son mari. Les avancées (Daubié 1861, lycées de filles 1880, divorce 1884, salaire 1907) sont **tardives** et arrachées. Le décalage est net : des millions de travailleuses sont dites « au foyer »."}$exo$::jsonb),
  ('a66ae76b-4466-413f-8dde-c05c0a645e9d'::uuid, 1, 'traduction', $exo${"titre":"Imparfait ou parfait ?","consigne":"Réponds en français, phrase par phrase.","enonce":"**A. Identifie le temps** de chaque verbe (imparfait ou parfait) et traduis-le.\n\n1. *amabat*\n2. *amavit*\n3. *portabant*\n4. *cecidit*\n\n**B. Complète** : quelle marque reconnaît-on dans un verbe à l'imparfait latin ?","bareme":[{"critere":"Quatre temps identifiés justement (imparfait, parfait, imparfait, parfait)","points":8},{"critere":"Quatre traductions justes (il aimait ; il aima / il a aimé ; ils portaient ; il tomba / il est tombé)","points":8},{"critere":"Marque -ba- de l'imparfait donnée","points":4}],"dureeMin":7,"corrige":"**A.**\n1. *amabat* : imparfait (marque -ba-), « il aimait ».\n2. *amavit* : parfait (radical en -v-), « il aima » ou « il a aimé ».\n3. *portabant* : imparfait (-ba- + terminaison -nt), « ils portaient ».\n4. *cecidit* : parfait (radical propre au parfait), « il tomba » ou « il est tombé ».\n\n**B.** L'imparfait se reconnaît à la marque **-ba-** insérée entre le radical et la terminaison."}$exo$::jsonb),
  ('a66ae76b-4466-413f-8dde-c05c0a645e9d'::uuid, 2, 'traduction', $exo${"titre":"Le décor et l'action","consigne":"Réponds en phrases complètes.","enonce":"Voici une phrase latine (extraite du cours) :\n\n> *Dum ambulabat, subito cecidit.*\n\n1. Traduis la phrase en français (*dum* = pendant que ; *subito* = soudain).\n2. Relève les deux verbes et donne le temps de chacun.\n3. Explique pourquoi le latin emploie l'imparfait pour le premier verbe et le parfait pour le second.\n4. Quels temps français choisirais-tu pour traduire un verbe à l'imparfait et un verbe au parfait dans un récit ?","bareme":[{"critere":"Traduction juste : pendant qu'il marchait, soudain il tomba","points":5},{"critere":"Deux verbes relevés avec leur temps : ambulabat (imparfait), cecidit (parfait)","points":4},{"critere":"Explication : l'imparfait pose le décor, ce qui dure ; le parfait rapporte l'action ponctuelle","points":7},{"critere":"Temps français : imparfait pour l'imparfait ; passé simple ou passé composé pour le parfait","points":4}],"dureeMin":10,"corrige":"1. *Pendant qu'il marchait, soudain il tomba* (ou *il est tombé*).\n2. *ambulabat* est à l'**imparfait** (marque -ba-) ; *cecidit* est au **parfait**.\n3. L'imparfait décrit une action qui **dure** : c'est le décor, le fond du tableau (il marchait). Le parfait exprime une action **achevée et ponctuelle** qui fait avancer l'histoire et fait basculer le récit (il tomba).\n4. L'imparfait latin se traduit par un imparfait français (« il marchait ») ; le parfait latin par un passé simple (« il tomba ») ou un passé composé (« il est tombé »)."}$exo$::jsonb),
  ('a66ae76b-4466-413f-8dde-c05c0a645e9d'::uuid, 3, 'traduction', $exo${"titre":"Traduire un petit récit","consigne":"Réponds en français, en justifiant chaque temps.","enonce":"Voici un petit récit **écrit pour l'exercice** :\n\n> *Puella in horto ambulabat. Subito puer rosam portavit.*\n\n*Vocabulaire* : *puella* = la jeune fille ; *in horto* = dans le jardin ; *puer* = le garçon ; *rosam* = la rose (complément d'objet) ; *subito* = soudain ; *ambulare* = marcher ; *portare* = porter.\n\n1. Traduis le récit en français, en choisissant les temps qui conviennent.\n2. Pour chaque verbe, indique son temps latin et l'indice qui te l'a fait reconnaître.\n3. Lequel des deux verbes plante le décor, lequel fait avancer l'histoire ? Justifie.\n4. Réécris la première phrase avec le verbe au parfait (*ambulavit*). Comment le sens change-t-il ?","bareme":[{"critere":"Traduction juste avec imparfait (marchait) puis passé simple ou composé (apporta / a apporté)","points":6},{"critere":"Deux verbes analysés : ambulabat imparfait (-ba-), portavit parfait (radical en -v-)","points":5},{"critere":"Décor et action distingués et justifiés","points":5},{"critere":"Effet du parfait ambulavit : action achevée, ponctuelle, et non plus une description qui dure","points":4}],"dureeMin":14,"corrige":"1. *La jeune fille marchait dans le jardin. Soudain le garçon apporta (ou a apporté) la rose.* (*portavit* : « il porta / il a porté » ; « apporta » est accepté.)\n2. *ambulabat* : imparfait, reconnaissable à la marque **-ba-**. *portavit* : parfait, reconnaissable à son radical en **-v-** et à la terminaison *-it*.\n3. *ambulabat* plante le **décor** : une action qui dure. *portavit* est l'**action ponctuelle** qui fait avancer l'histoire, accompagnée de *subito*.\n4. *Puella in horto ambulavit* : « la jeune fille marcha dans le jardin ». Le parfait présente la marche comme un fait achevé, un événement du récit, au lieu d'une description qui dure et sert de fond."}$exo$::jsonb),
  ('130356ab-7263-49f1-9a37-0410fe637b30'::uuid, 1, 'traduction', $exo${"titre":"Les groupes de la société","consigne":"Réponds en français.","enonce":"**A. Définis** chacun de ces mots en une phrase.\n\n1. un patricien (*patricius*)\n2. un plébéien\n3. un esclave (*servus*)\n4. un affranchi (*libertus*)\n\n**B.** Quelle magistrature défend le peuple, la plèbe ?","bareme":[{"critere":"Patricien : membre d'une grande famille noble et riche","points":4},{"critere":"Plébéien : citoyen libre du peuple (paysan, artisan, commerçant)","points":4},{"critere":"Esclave : non libre, propriété de son maître","points":4},{"critere":"Affranchi : ancien esclave libéré, resté lié à son patron","points":4},{"critere":"Tribun de la plèbe nommé","points":4}],"dureeMin":7,"corrige":"**A.**\n1. Un **patricien** appartient à l'une des grandes familles nobles et riches de Rome, qui détiennent longtemps le pouvoir et les prêtrises.\n2. Un **plébéien** est un citoyen libre du peuple : paysan, artisan ou commerçant.\n3. Un **esclave** n'est pas libre : c'est la propriété de son maître.\n4. Un **affranchi** est un esclave libéré par son maître ; il obtient la liberté et certains droits, mais reste lié à son ancien maître, devenu son patron.\n\n**B.** Le **tribun de la plèbe** (*tribunus plebis*) défend le peuple."}$exo$::jsonb),
  ('130356ab-7263-49f1-9a37-0410fe637b30'::uuid, 2, 'traduction', $exo${"titre":"La carrière d'un magistrat","consigne":"Réponds en phrases complètes.","enonce":"Marcus est un jeune Romain qui souhaite faire une carrière politique.\n\n1. Comment appelle-t-on l'ordre des magistratures que Marcus va gravir ? Traduis cette expression.\n2. Range dans l'ordre, du plus modeste au plus prestigieux : *consul, questeur, préteur, édile*.\n3. Donne le rôle de chacune de ces quatre magistratures.\n4. Après le consulat, que peut-il devenir ?","bareme":[{"critere":"Cursus honorum nommé et traduit (la carrière des honneurs)","points":4},{"critere":"Ordre juste : questeur, édile, préteur, consul","points":6},{"critere":"Rôles justes : finances, fêtes-marchés-voirie, justice, plus haut pouvoir (deux par an)","points":6},{"critere":"Suite de carrière : censeur ou entrée au Sénat","points":4}],"dureeMin":10,"corrige":"1. C'est le **cursus honorum**, « la carrière des honneurs ».\n2. **Questeur → édile → préteur → consul.**\n3. Le **questeur** s'occupe des finances ; l'**édile** des fêtes, des marchés et de la voirie ; le **préteur** de la justice ; le **consul** détient le plus haut pouvoir (il y en a deux par an).\n4. Après le consulat, Marcus peut devenir **censeur** ou entrer au **Sénat**, l'assemblée qui guidait la République."}$exo$::jsonb),
  ('130356ab-7263-49f1-9a37-0410fe637b30'::uuid, 3, 'traduction', $exo${"titre":"Tous égaux à Rome ?","consigne":"Rédige un paragraphe argumenté d'une dizaine de lignes, avec des exemples du cours.","enonce":"**Sujet.** Les habitants de Rome avaient-ils tous les mêmes droits ?\n\nDans ton paragraphe :\n- distingue au moins trois groupes de la société romaine et leur situation ;\n- explique ce que permettait la formule *civis Romanus sum* ;\n- montre comment un plébéien pouvait faire entendre sa voix, et comment un esclave pouvait changer de condition ;\n- conclus par une phrase.","bareme":[{"critere":"Au moins trois groupes distingués et caractérisés (patriciens, plébéiens, esclaves, affranchis)","points":6},{"critere":"Droits du citoyen et formule civis Romanus sum expliqués (voter, protection de la loi)","points":5},{"critere":"Tribun de la plèbe et affranchissement cités comme évolutions possibles","points":5},{"critere":"Paragraphe organisé, avec une conclusion claire","points":4}],"dureeMin":18,"corrige":"Éléments attendus : la société romaine est **hiérarchisée**, on n'a pas les mêmes droits selon sa naissance et son statut. Les **patriciens** sont les grandes familles nobles et riches, qui détiennent longtemps le pouvoir ; les **plébéiens** sont le reste du peuple libre ; les **esclaves** sont la propriété de leur maître. Le **citoyen** (*civis Romanus*) peut voter, faire du commerce, se marier légalement et est protégé par la loi : dire *civis Romanus sum* (« je suis citoyen romain ») était une protection. Les femmes ne votent pas et restent sous l'autorité du *pater familias*. La situation peut évoluer : après de longues luttes, les plébéiens obtiennent le **tribun de la plèbe**, qui les défend ; un maître peut libérer un esclave, qui devient **affranchi** (*libertus*), libre mais lié à son patron. Conclusion : les Romains n'étaient donc pas égaux, mais les statuts pouvaient changer."}$exo$::jsonb),
  ('5a3b55cb-a48c-4cfb-8ded-27ce52002b84'::uuid, 1, 'traduction', $exo${"titre":"Les dieux romains","consigne":"Réponds en français.","enonce":"**A. Donne l'équivalent grec** de chacun de ces dieux romains.\n\n1. Jupiter\n2. Junon\n3. Minerve\n4. Neptune\n\n**B.** Quel dieu ou déesse est associé à la guerre (un seul nom suffit) ? Quelle déesse est celle de l'amour ?","bareme":[{"critere":"Quatre équivalents grecs justes : Zeus, Héra, Athéna, Poséidon","points":12},{"critere":"Un dieu de la guerre juste (Mars, ou Minerve) et la déesse de l'amour (Vénus)","points":8}],"dureeMin":6,"corrige":"**A.** 1. Jupiter = **Zeus** (roi des dieux, le ciel). 2. Junon = **Héra** (reine, mariage). 3. Minerve = **Athéna** (sagesse, guerre). 4. Neptune = **Poséidon** (la mer).\n\n**B.** **Mars** est le dieu de la guerre (Minerve est aussi liée à la guerre). **Vénus** est la déesse de l'amour et de la beauté, équivalente d'Aphrodite."}$exo$::jsonb),
  ('5a3b55cb-a48c-4cfb-8ded-27ce52002b84'::uuid, 2, 'traduction', $exo${"titre":"La fuite d'Énée","consigne":"Réponds en phrases complètes.","enonce":"1. Qui est Énée ? Donne son origine et le nom de sa mère.\n2. Raconte en trois ou quatre phrases sa fuite de Troie : que fait-il de son père Anchise et de son fils Ascagne ?\n3. Comment s'appelle le poème qui raconte ses aventures, et qui en est l'auteur ?\n4. Que veut dire l'expression *pius Aeneas* ? Quelle valeur romaine illustre-t-elle ?","bareme":[{"critere":"Énée : prince troyen, fils de Vénus","points":4},{"critere":"Fuite de Troie racontée : père Anchise sur le dos, fils Ascagne par la main","points":6},{"critere":"Énéide (Aeneis) de Virgile","points":4},{"critere":"Pius Aeneas : le pieux Énée, respect des dieux et de sa famille ; pietas","points":6}],"dureeMin":10,"corrige":"1. **Énée** (*Aeneas*) est un prince troyen, fils de la déesse **Vénus**.\n2. Après la chute de Troie, il fuit la ville en flammes en portant son vieux père **Anchise** sur son dos et en tenant son fils **Ascagne** par la main. Guidé par le destin, il gagne l'Italie, où ses descendants fonderont Rome.\n3. Ses aventures sont racontées dans l'**Énéide** (*Aeneis*), grand poème épique de **Virgile**.\n4. *Pius Aeneas* signifie « le pieux Énée » : il respecte les dieux et sa famille. Il illustre la **pietas**, le sens du devoir, valeur admirée à Rome."}$exo$::jsonb),
  ('5a3b55cb-a48c-4cfb-8ded-27ce52002b84'::uuid, 3, 'traduction', $exo${"titre":"Pourquoi raconter des mythes ?","consigne":"Rédige un paragraphe argumenté d'une dizaine de lignes, en t'appuyant sur le cours.","enonce":"**Sujet.** Pourquoi les Romains se racontaient-ils des mythes comme ceux d'Énée et de Romulus et Remus ?\n\nDans ton paragraphe :\n- résume chacune des deux légendes en deux phrases ;\n- explique le lien entre elles (qui descend de qui) ;\n- dis quelles valeurs ces récits transmettaient, en citant la *pietas* ;\n- explique en quoi ce n'étaient pas de simples histoires ;\n- conclus par une phrase.","bareme":[{"critere":"Deux légendes résumées justement (Énée, Anchise, Ascagne, Énéide ; Romulus, Remus, louve, 753 av. J.-C.)","points":6},{"critere":"Lien établi : Romulus et Remus sont des descendants d'Énée","points":4},{"critere":"Valeurs citées : courage, pietas, amour de la patrie, fidélité","points":5},{"critere":"Fonction des mythes : enseigner ces vertus et donner à Rome un passé glorieux ; paragraphe organisé","points":5}],"dureeMin":18,"corrige":"Éléments attendus : **Énée**, prince troyen fils de Vénus, fuit Troie en flammes en portant son père Anchise et en tenant la main de son fils Ascagne ; ses voyages jusqu'en Italie sont chantés par **Virgile** dans l'*Énéide*. **Romulus et Remus**, descendants d'Énée, sont abandonnés puis allaités par une louve ; après une querelle, Romulus tue son frère et donne son nom à Rome (753 av. J.-C. selon la tradition). Les deux légendes se suivent : le premier apporte les ancêtres, les seconds fondent la ville. Ces récits **enseignent des valeurs** : courage, fidélité, sens du devoir (*pietas*), amour de la patrie. Ce ne sont pas de simples histoires : ils servent à transmettre ces vertus et à donner à Rome un **passé glorieux**. Conclusion : les mythes forment l'identité et les valeurs des Romains."}$exo$::jsonb),
  ('e0f02b95-7ff3-56bb-9b80-ef14ab4de755'::uuid, 1, 'probleme', $exo${"titre":"Des fractions de quantités","consigne":"Réponds à chaque question en écrivant le calcul effectué.","enonce":"**Questions de cours et d'application.**\n\n1. Calcule les **2/3 de 45** en commençant par la division, puis les **5/6 de 42**.\n2. En remplaçant chaque pourcentage par une fraction simple, calcule **20 % de 85** et **75 % de 48**.\n3. Calcule **le tiers des 3/4** et donne le résultat sous forme d'une fraction simplifiée.","bareme":[{"critere":"Les 2/3 de 45 = 30 et les 5/6 de 42 = 35, avec les calculs écrits","points":8},{"critere":"20 % de 85 = 17 et 75 % de 48 = 36, en passant par 1/5 et 3/4","points":7},{"critere":"Produit 1/3 × 3/4 posé et simplifié en 1/4","points":5}],"dureeMin":7,"corrige":"1. Le mot « de » se traduit par × :\n   - 2/3 de 45 = 45 × 2/3 : 45 ÷ 3 = 15, puis 15 × 2 = **30**.\n   - 5/6 de 42 = 42 × 5/6 : 42 ÷ 6 = 7, puis 7 × 5 = **35**.\n   On commence par la division, car elle tombe juste.\n\n2. 20 % = 20/100 = 1/5 : 20 % de 85 = 85 ÷ 5 = **17**.\n   75 % = 3/4 : 75 % de 48 = 48 ÷ 4 × 3 = 12 × 3 = **36**.\n\n3. Une fraction d'une fraction se calcule en multipliant les deux fractions : 1/3 × 3/4 = 3/12 = **1/4** (simplification par 3).\n\nContrôle de vraisemblance : toutes les fractions sont inférieures à 1, chaque résultat est plus petit que la quantité de départ."}$exo$::jsonb),
  ('e0f02b95-7ff3-56bb-9b80-ef14ab4de755'::uuid, 2, 'probleme', $exo${"titre":"La cagnotte de la 4e B","consigne":"Réponds à chaque question en détaillant tes calculs.","enonce":"**Situation.** La classe de 4e B a récolté **480 €** pour sa sortie de fin d'année.\n- Les **3/8** de la cagnotte paient le car.\n- **25 %** de la cagnotte paient l'entrée du parc.\n- Le reste sert à acheter le pique-nique.\n\n1. Combien coûte le car ?\n2. Combien coûte l'entrée du parc ? Écris d'abord 25 % sous forme de fraction.\n3. Quelle somme reste-t-il pour le pique-nique ?\n4. Quelle fraction de la cagnotte le pique-nique représente-t-il ? Donne-la sous forme simplifiée.","bareme":[{"critere":"Prix du car : 480 × 3/8 = 180 €, calcul détaillé","points":6},{"critere":"25 % écrit 1/4 et prix du parc : 120 €","points":5},{"critere":"Somme restante pour le pique-nique : 180 €","points":4},{"critere":"Fraction du pique-nique : 3/8, obtenue par simplification ou par 1 − 3/8 − 1/4","points":5}],"dureeMin":10,"corrige":"1. Car : 480 × 3/8. On divise d'abord, car la division tombe juste : 480 ÷ 8 = 60, puis 60 × 3 = **180 €**.\n\n2. 25 % = 25/100 = **1/4**. Parc : 480 × 1/4 = 480 ÷ 4 = **120 €**.\n\n3. Pique-nique : 480 − 180 − 120 = **180 €**.\n\n4. 180/480 : on simplifie par 60, ce qui donne **3/8**.\n   Autre méthode : 1 − 3/8 − 1/4 = 8/8 − 3/8 − 2/8 = **3/8**.\n   Vérification : 480 × 3/8 = 180 €."}$exo$::jsonb),
  ('e0f02b95-7ff3-56bb-9b80-ef14ab4de755'::uuid, 3, 'probleme', $exo${"titre":"Le club de handball","consigne":"Réponds à chaque question en justifiant tes calculs. Vérifie la vraisemblance de tes résultats.","enonce":"**Situation.** Au club de handball de Maëlle :\n- les **3/5** des licenciés sont des filles ;\n- les **2/3** de ces filles ont moins de 15 ans ;\n- il y a **72 filles** au club.\n\n1. Quelle fraction de l'ensemble des licenciés représentent les filles de moins de 15 ans ? Justifie.\n2. Combien le club compte-t-il de licenciés en tout ? Vérifie que ton résultat est vraisemblable.\n3. Combien le club compte-t-il de filles de moins de 15 ans ? Calcule-le de deux façons.\n4. Le président prévoit que l'an prochain, le nombre de licenciés sera égal aux **5/4** du nombre actuel. Combien le club aura-t-il de licenciés ? Explique pourquoi on pouvait prévoir une hausse avant de calculer.\n5. Arthur a écrit : « Nombre total de licenciés = 72 × 3/5 = 43,2. » Explique son erreur, et donne deux indices qui montrent que son résultat est impossible.","bareme":[{"critere":"Fraction des filles de moins de 15 ans : 2/3 × 3/5 = 2/5","points":4},{"critere":"Nombre total : 72 ÷ 3/5 = 120 licenciés, avec la vérification de vraisemblance","points":5},{"critere":"48 filles de moins de 15 ans, par au moins une méthode juste","points":3},{"critere":"150 licenciés et explication : 5/4 > 1 fait augmenter la quantité","points":4},{"critere":"Erreur d’Arthur : multiplication au lieu de division, 43,2 < 72 et non entier","points":4}],"dureeMin":16,"corrige":"1. C'est une fraction d'une fraction : on multiplie. 2/3 × 3/5 = 6/15 = **2/5** des licenciés.\n\n2. Les 72 filles représentent les 3/5 du total : pour retrouver le tout, on **divise** par la fraction.\n   72 ÷ 3/5 = 72 × 5/3 = 360 ÷ 3 = **120 licenciés**.\n   Vraisemblance : 3/5 < 1, donc le tout doit être plus grand que la partie ; 120 > 72, c'est cohérent. Vérification : 120 × 3/5 = 24 × 3 = 72.\n\n3. Première façon : 2/3 de 72 = 72 ÷ 3 × 2 = **48**.\n   Deuxième façon : 2/5 de 120 = 120 ÷ 5 × 2 = **48**. Les deux résultats concordent.\n\n4. 120 × 5/4 = 120 ÷ 4 × 5 = 30 × 5 = **150 licenciés**.\n   On pouvait prévoir la hausse : 5/4 est supérieur à 1, et prendre une fraction supérieure à 1 d'une quantité l'augmente.\n\n5. Arthur a **multiplié** par 3/5 au lieu de **diviser** : il a pris une fraction de 72 au lieu de retrouver le tout.\n   Deux indices : 43,2 est plus petit que 72, alors que le tout doit être plus grand que la partie ; et 43,2 n'est pas un nombre entier, ce qui est impossible pour un nombre de personnes."}$exo$::jsonb),
  ('9175214a-ff51-5d25-ac1d-180fe1a65c33'::uuid, 1, 'probleme', $exo${"titre":"Vérifier et compléter","consigne":"Justifie chaque réponse par les produits en croix.","enonce":"**Questions de cours et d'application.**\n\n1. Les fractions **12/18** et **10/15** sont-elles égales ? Même question pour **4/7** et **9/16**.\n2. Trouve la valeur de x dans chaque égalité, puis vérifie ton résultat :\n   - a) x/9 = 8/12\n   - b) 5/x = 15/21","bareme":[{"critere":"Les deux vérifications : 180 = 180 (égales) et 64 ≠ 63 (différentes)","points":8},{"critere":"a) 12x = 72, donc x = 6","points":6},{"critere":"b) 15x = 105, donc x = 7, avec une vérification","points":6}],"dureeMin":7,"corrige":"1. On multiplie « en croix » : le numérateur de l'une par le dénominateur de l'autre.\n   - 12 × 15 = 180 et 18 × 10 = 180 : les produits sont égaux, donc **12/18 = 10/15**.\n   - 4 × 16 = 64 et 7 × 9 = 63 : 64 ≠ 63, donc **4/7 et 9/16 ne sont pas égales**.\n\n2. a) 12 × x = 9 × 8, soit 12x = 72, donc x = 72 ÷ 12 = **6**. Vérification : 6/9 = 2/3 et 8/12 = 2/3.\n   b) 5 × 21 = 15 × x, soit 15x = 105, donc x = 105 ÷ 15 = **7**. Vérification : 15/21 = 5/7 (simplification par 3)."}$exo$::jsonb),
  ('9175214a-ff51-5d25-ac1d-180fe1a65c33'::uuid, 2, 'probleme', $exo${"titre":"Les crêpes de Nathan","consigne":"Réponds aux questions en écrivant l'égalité utilisée avant chaque calcul.","enonce":"**Situation.** Pour faire **12 crêpes**, Nathan utilise **250 g de farine** et **0,5 L de lait**. Les quantités sont proportionnelles au nombre de crêpes. Il veut en faire **30** pour la fête du club.\n\n| Nombre de crêpes | 12 | 30 |\n| --- | --- | --- |\n| Farine (g) | 250 | x |\n\n1. Calcule x par un produit en croix.\n2. Quelle quantité de lait lui faut-il pour 30 crêpes ?\n3. Finalement, il ne lui reste que **400 g** de farine. Combien de crêpes peut-il faire au maximum ?","bareme":[{"critere":"Farine pour 30 crêpes : 625 g, par un produit en croix","points":6},{"critere":"Lait pour 30 crêpes : 1,25 L","points":5},{"critere":"Avec 400 g : 19,2 trouvé puis arrondi à 19 crêpes, arrondi justifié","points":6},{"critere":"Méthode rédigée : égalité posée, produit en croix, division","points":3}],"dureeMin":10,"corrige":"1. 250/12 = x/30, donc 12 × x = 250 × 30 = 7 500, et x = 7 500 ÷ 12 = **625 g** de farine.\n\n2. On note y la quantité de lait : 0,5/12 = y/30, donc 12 × y = 0,5 × 30 = 15, et y = 15 ÷ 12 = **1,25 L** de lait.\n\n3. On note n le nombre de crêpes : 250/12 = 400/n, donc 250 × n = 12 × 400 = 4 800, et n = 4 800 ÷ 250 = 19,2.\n   On ne fait pas 0,2 crêpe : il peut en faire **19 au maximum**. (Pour 20 crêpes, il faudrait 20 × 250 ÷ 12 ≈ 417 g de farine : c'est trop.)"}$exo$::jsonb),
  ('9175214a-ff51-5d25-ac1d-180fe1a65c33'::uuid, 3, 'probleme', $exo${"titre":"Deux salles d'escalade","consigne":"Réponds en justifiant chaque calcul. Dis clairement si chaque situation est proportionnelle ou non.","enonce":"**Situation.** Deux salles d'escalade affichent leurs tarifs.\n- **Salle Verticale** : 8 € la séance, sans abonnement.\n- **Salle Prise** : abonnement annuel de 20 €, puis 5 € la séance.\n\n1. Salle Verticale : 4 séances coûtent 32 €. Le prix est-il proportionnel au nombre de séances ? Calcule le prix de 15 séances par un produit en croix.\n2. Salle Prise : 4 séances coûtent 20 + 4 × 5 = 40 €. Léna calcule le prix de 10 séances par un produit en croix : 10 × 40 ÷ 4 = 100 €. Calcule le vrai prix de 10 séances, puis explique pourquoi la méthode de Léna ne convenait pas.\n3. Montre, à l'aide des produits en croix, que les quotients 40/4 et 70/10 ne sont pas égaux. Que confirme ce résultat ?\n4. Avec un budget de 100 €, combien de séances au maximum peut-on faire dans chaque salle ?","bareme":[{"critere":"Salle Verticale : situation proportionnelle, 15 séances = 120 € par produit en croix","points":5},{"critere":"Salle Prise : vrai prix 70 € et abonnement fixe qui rend le produit en croix faux","points":5},{"critere":"Produits en croix 400 et 280, différents : le tarif n’est pas proportionnel","points":5},{"critere":"Avec 100 € : 12 séances à la salle Verticale, 16 à la salle Prise","points":5}],"dureeMin":16,"corrige":"1. Chaque séance coûte 8 € : le prix est toujours 8 fois le nombre de séances, c'est une **situation de proportionnalité**.\n   4/32 = 15/x, donc 4 × x = 32 × 15 = 480, et x = 480 ÷ 4 = **120 €** (vérification : 15 × 8 = 120).\n\n2. Vrai prix : 20 + 10 × 5 = 20 + 50 = **70 €**.\n   Léna a appliqué le produit en croix à une situation **qui n'est pas proportionnelle** : l'abonnement de 20 € se paie une seule fois, quel que soit le nombre de séances. Le produit en croix donne alors un résultat faux, et rien dans le calcul ne le signale.\n\n3. 40 × 10 = 400 et 4 × 70 = 280 : 400 ≠ 280, donc 40/4 ≠ 70/10 (10 € par séance dans un cas, 7 € dans l'autre).\n   Le prix d'une séance n'est pas constant : cela **confirme que le tarif de la salle Prise n'est pas proportionnel**.\n\n4. Salle Verticale : 100 = 8 × 12 + 4, donc **12 séances** (il reste 4 €).\n   Salle Prise : après l'abonnement, il reste 100 − 20 = 80 €, soit 80 ÷ 5 = **16 séances**."}$exo$::jsonb),
  ('e22f5910-eb9a-55d1-aec7-e85c209809a9'::uuid, 1, 'probleme', $exo${"titre":"Poser et interpréter","consigne":"Réponds à chaque question en écrivant les égalités utilisées.","enonce":"**Questions de cours et d'application.**\n\n1. Effectue la division euclidienne de **158 par 12**. Écris l'égalité a = b × q + r et vérifie la condition sur le reste.\n2. Dans cette égalité, nomme le dividende, le diviseur, le quotient et le reste.\n3. 158 est-il divisible par 12 ? Et 156 ? Justifie chaque réponse par une égalité.","bareme":[{"critere":"Égalité 158 = 12 × 13 + 2, avec la condition 2 < 12","points":8},{"critere":"Dividende, diviseur, quotient et reste correctement nommés","points":6},{"critere":"158 non divisible par 12, 156 divisible (reste nul), justifiés","points":6}],"dureeMin":6,"corrige":"1. 12 × 13 = 156 et 158 − 156 = 2, donc **158 = 12 × 13 + 2**, avec 0 ≤ 2 < 12 : la condition sur le reste est respectée.\n\n2. **Dividende** : 158 (ce qu'on partage) ; **diviseur** : 12 ; **quotient** : 13 ; **reste** : 2.\n\n3. Le reste de la division de 158 par 12 vaut 2 : il n'est pas nul, donc **158 n'est pas divisible par 12**.\n   En revanche, 156 = 12 × 13 + 0 : le reste est nul, donc **156 est divisible par 12** (12 est un diviseur de 156, et 156 est un multiple de 12)."}$exo$::jsonb),
  ('e22f5910-eb9a-55d1-aec7-e85c209809a9'::uuid, 2, 'probleme', $exo${"titre":"Les cookies de la kermesse","consigne":"Pose les divisions euclidiennes et dis, pour chaque question, si la réponse est le quotient, le reste, ou autre chose.","enonce":"**Situation.** Pour la kermesse du collège, Inès doit emballer **250 cookies** dans des sachets de **12**.\n\n1. Pose la division euclidienne de 250 par 12. Combien de sachets complets peut-elle remplir ? Combien de cookies restent ?\n2. Elle veut que tous les cookies soient emballés, quitte à avoir un sachet incomplet. Combien de sachets lui faut-il en tout ?\n3. La kermesse a lieu un **samedi**. La suivante aura lieu **45 jours** plus tard. Quel jour de la semaine sera-ce ? Justifie avec une division euclidienne.","bareme":[{"critere":"Division 250 = 12 × 20 + 10, avec 10 < 12","points":6},{"critere":"Interprétation : 20 sachets complets et 10 cookies restants","points":4},{"critere":"21 sachets en tout, avec la justification du sachet incomplet","points":5},{"critere":"Jour de la kermesse suivante : mardi, par 45 = 7 × 6 + 3","points":5}],"dureeMin":10,"corrige":"1. 12 × 20 = 240 et 250 − 240 = 10 : **250 = 12 × 20 + 10**, avec 10 < 12.\n   Le **quotient** donne le nombre de sachets complets : **20 sachets**. Le **reste** donne les cookies restants : **10 cookies**.\n\n2. Les 10 cookies restants demandent un sachet de plus : 20 + 1 = **21 sachets**. Ici, ni le quotient seul ni le reste seul ne répondent : il faut interpréter.\n\n3. Une semaine compte 7 jours : 45 = 7 × 6 + 3, avec 3 < 7.\n   Six semaines complètes ramènent au samedi, puis 3 jours de plus : dimanche, lundi, **mardi**. C'est le reste qui répond."}$exo$::jsonb),
  ('e22f5910-eb9a-55d1-aec7-e85c209809a9'::uuid, 3, 'probleme', $exo${"titre":"Restes, cycles et guirlande","consigne":"Réponds en justifiant chaque réponse par une égalité de division euclidienne.","enonce":"**Exercice.**\n\n1. Dans la division euclidienne d'un nombre a par 7, le quotient est 15 et le reste est 4. Trouve a.\n2. Léo écrit : « 100 = 7 × 13 + 9 ». Son égalité est-elle juste ? Est-ce l'égalité de la division euclidienne de 100 par 7 ? Corrige-la si besoin, en expliquant.\n3. Une guirlande répète toujours le même motif de 5 ampoules : **rouge, vert, bleu, jaune, blanc**, puis de nouveau rouge, vert… De quelle couleur est la **83e** ampoule ? Et la **100e** ?\n4. Trouve tous les nombres entiers compris entre 50 et 80 dont le reste dans la division euclidienne par 9 est égal à 2. Explique ta méthode.","bareme":[{"critere":"a = 7 × 15 + 4 = 109","points":3},{"critere":"Égalité de Léo juste mais reste 9 ≥ 7 ; correction 100 = 7 × 14 + 2","points":5},{"critere":"Guirlande : 83e ampoule bleue, 100e blanche, reste nul bien interprété","points":6},{"critere":"Les nombres 56, 65 et 74, trouvés sous la forme 9 × q + 2","points":6}],"dureeMin":16,"corrige":"1. a = b × q + r = 7 × 15 + 4 = 105 + 4 = **109** (et 4 < 7 : c'est bien un reste possible).\n\n2. 7 × 13 = 91 et 91 + 9 = 100 : l'égalité est **juste**. Mais ce n'est **pas** la division euclidienne de 100 par 7, car le reste 9 est supérieur au diviseur 7 : le quotient est trop petit d'un cran. On le relève : **100 = 7 × 14 + 2**, avec 2 < 7. C'est la condition 0 ≤ r < b qui rend le quotient et le reste uniques.\n\n3. Le motif revient toutes les 5 ampoules : on cherche le reste de la division par 5.\n   - 83 = 5 × 16 + 3 : 16 motifs complets, puis la 3e couleur du motif, **bleu**.\n   - 100 = 5 × 20 + 0 : le reste est nul, la 100e ampoule termine le 20e motif ; c'est la dernière couleur, **blanc**.\n\n4. Ces nombres s'écrivent 9 × q + 2. On teste les quotients :\n   - 9 × 5 + 2 = 47 : trop petit ;\n   - 9 × 6 + 2 = **56** ; 9 × 7 + 2 = **65** ; 9 × 8 + 2 = **74** ;\n   - 9 × 9 + 2 = 83 : trop grand.\n   Les nombres cherchés sont **56, 65 et 74**."}$exo$::jsonb),
  ('c060f999-ab79-5a71-835f-d87337f6a97d'::uuid, 1, 'probleme', $exo${"titre":"Multiples et diviseurs","consigne":"Réponds à chaque question en justifiant par des égalités.","enonce":"**Questions de cours et d'application.**\n\n1. Écris tous les multiples de 9 compris entre 40 et 80.\n2. Liste tous les diviseurs de 30 en utilisant la méthode des paires.\n3. 91 est-il un multiple de 7 ? Justifie par une égalité, puis complète la phrase : « … est un diviseur de … ».","bareme":[{"critere":"Multiples de 9 entre 40 et 80 : 45, 54, 63, 72","points":5},{"critere":"Les huit diviseurs de 30, trouvés par paires","points":9},{"critere":"91 = 7 × 13 et la phrase « 7 est un diviseur de 91 »","points":6}],"dureeMin":7,"corrige":"1. 9 × 5 = 45, 9 × 6 = 54, 9 × 7 = 63, 9 × 8 = 72 (9 × 4 = 36 et 9 × 9 = 81 sont en dehors de l'intervalle) : **45, 54, 63 et 72**.\n\n2. On forme les paires : 30 = 1 × 30 = 2 × 15 = 3 × 10 = 5 × 6. On teste 4 : 30 n'est pas divisible par 4. Après 5 × 6, les facteurs se croisent : on s'arrête.\n   Diviseurs de 30 : **1, 2, 3, 5, 6, 10, 15 et 30**.\n\n3. **91 = 7 × 13**, avec 13 entier : 91 est un multiple de 7. Donc **7 est un diviseur de 91** (13 aussi)."}$exo$::jsonb),
  ('c060f999-ab79-5a71-835f-d87337f6a97d'::uuid, 2, 'probleme', $exo${"titre":"Les sachets de bonbons","consigne":"Réponds en justifiant avec les listes de diviseurs.","enonce":"**Situation.** Pour la fête de son petit frère, Yasmine a **24 sucettes** et **36 caramels**. Elle veut préparer des sachets **identiques** (même nombre de sucettes et même nombre de caramels dans chaque sachet) en utilisant **tous** les bonbons.\n\n1. Liste les diviseurs de 24, puis ceux de 36.\n2. Quels nombres de sachets sont possibles ? Explique.\n3. Quel est le plus grand nombre de sachets qu'elle peut préparer ? Que contient alors chaque sachet ?","bareme":[{"critere":"Diviseurs de 24 et de 36 complets","points":6},{"critere":"Diviseurs communs 1, 2, 3, 4, 6, 12, avec l’explication du partage","points":5},{"critere":"Plus grand nombre de sachets : 12","points":4},{"critere":"Contenu d’un sachet : 2 sucettes et 3 caramels","points":5}],"dureeMin":10,"corrige":"1. 24 = 1 × 24 = 2 × 12 = 3 × 8 = 4 × 6 : diviseurs de 24 : **1, 2, 3, 4, 6, 8, 12, 24**.\n   36 = 1 × 36 = 2 × 18 = 3 × 12 = 4 × 9 = 6 × 6 : diviseurs de 36 : **1, 2, 3, 4, 6, 9, 12, 18, 36**.\n\n2. Le nombre de sachets doit diviser 24 (pour partager toutes les sucettes) **et** 36 (pour partager tous les caramels) : c'est un **diviseur commun**. Nombres possibles : **1, 2, 3, 4, 6 ou 12 sachets**.\n\n3. Le plus grand diviseur commun est **12** : elle peut préparer **12 sachets**.\n   Chaque sachet contient 24 ÷ 12 = **2 sucettes** et 36 ÷ 12 = **3 caramels**."}$exo$::jsonb),
  ('c060f999-ab79-5a71-835f-d87337f6a97d'::uuid, 3, 'probleme', $exo${"titre":"Fractions, nombres premiers et bus","consigne":"Réponds en justifiant avec des listes de diviseurs ou de multiples.","enonce":"**Exercice.**\n\n1. Liste les diviseurs de 45 et ceux de 56. Ces deux nombres sont-ils premiers entre eux ? Que peux-tu en déduire pour la fraction 45/56 ?\n2. Liste les diviseurs de 42 et ceux de 70. Rends la fraction **42/70** irréductible en une seule simplification.\n3. Parmi les nombres **37, 39, 49 et 53**, lesquels sont premiers ? Justifie pour chacun.\n4. Deux bus partent ensemble de la gare à **8 h**. Le bus A repart de la gare toutes les **12 min**, le bus B toutes les **18 min**. Écris les multiples de 12 et de 18 jusqu'à 72. À quelle heure les deux bus repartiront-ils ensemble pour la première fois ?","bareme":[{"critere":"45 et 56 premiers entre eux, donc 45/56 irréductible","points":5},{"critere":"42/70 simplifiée par 14 en 3/5, listes de diviseurs à l’appui","points":5},{"critere":"37 et 53 premiers ; 39 = 3 × 13 et 49 = 7 × 7 non premiers","points":4},{"critere":"Multiples de 12 et de 18 listés, départ commun à 8 h 36","points":6}],"dureeMin":18,"corrige":"1. Diviseurs de 45 : 1, 3, 5, 9, 15, 45. Diviseurs de 56 : 1, 2, 4, 7, 8, 14, 28, 56.\n   Leur seul diviseur commun est 1 : **45 et 56 sont premiers entre eux**, donc la fraction **45/56 est déjà irréductible**.\n\n2. Diviseurs de 42 : 1, 2, 3, 6, 7, 14, 21, 42. Diviseurs de 70 : 1, 2, 5, 7, 10, 14, 35, 70.\n   Diviseurs communs : 1, 2, 7, 14 ; le plus grand est 14. 42/70 = (42 ÷ 14)/(70 ÷ 14) = **3/5**.\n\n3. - **37** : non divisible par 2, 3, 5 ; et 7 × 7 = 49 > 37. Ses seuls diviseurs sont 1 et 37 : **premier**.\n   - **39** = 3 × 13 : **pas premier**.\n   - **49** = 7 × 7 : **pas premier**.\n   - **53** : non divisible par 2, 3, 5, 7 ; et 8 × 8 = 64 > 53 : **premier**.\n\n4. Multiples de 12 : 12, 24, **36**, 48, 60, 72. Multiples de 18 : 18, **36**, 54, 72.\n   Le premier multiple commun non nul est 36 : les bus repartent ensemble au bout de 36 min, soit à **8 h 36**."}$exo$::jsonb),
  ('c0bf100f-b4c4-5cdb-92dd-f004e501c944'::uuid, 1, 'probleme', $exo${"titre":"Le tableau des critères","consigne":"Pour chaque nombre, réponds par oui ou non et cite le critère qui justifie tes réponses.","enonce":"**Questions de cours et d'application.**\n\nRecopie et complète le tableau par « oui » ou « non ».\n\n| Divisible par… | 2 | 3 | 4 | 5 | 9 | 10 | 25 |\n| --- | --- | --- | --- | --- | --- | --- | --- |\n| 3 420 | | | | | | | |\n| 1 575 | | | | | | | |\n| 2 718 | | | | | | | |","bareme":[{"critere":"Ligne de 3 420 juste (oui pour 2, 3, 4, 5, 9, 10 ; non pour 25), critères cités","points":7},{"critere":"Ligne de 1 575 juste (oui pour 3, 5, 9, 25 ; non pour 2, 4, 10), critères cités","points":7},{"critere":"Ligne de 2 718 juste (oui pour 2, 3, 9 ; non pour 4, 5, 10, 25), critères cités","points":6}],"dureeMin":8,"corrige":"| Divisible par… | 2 | 3 | 4 | 5 | 9 | 10 | 25 |\n| --- | --- | --- | --- | --- | --- | --- | --- |\n| 3 420 | oui | oui | oui | oui | oui | oui | non |\n| 1 575 | non | oui | non | oui | oui | non | oui |\n| 2 718 | oui | oui | non | non | oui | non | non |\n\n- **3 420** se termine par 0 : divisible par 2, 5 et 10. Somme des chiffres : 3 + 4 + 2 + 0 = 9, divisible par 3 et par 9. Ses deux derniers chiffres forment 20, multiple de 4. Il se termine par 20, et non par 00, 25, 50 ou 75 : pas divisible par 25.\n- **1 575** est impair : ni par 2, ni par 4, ni par 10. Il se termine par 75 : divisible par 5 et par 25. Somme : 1 + 5 + 7 + 5 = 18, divisible par 3 et par 9.\n- **2 718** se termine par 8 : divisible par 2, mais pas par 5, 10 ni 25. 18 n'est pas un multiple de 4 : pas divisible par 4. Somme : 2 + 7 + 1 + 8 = 18, divisible par 3 et par 9."}$exo$::jsonb),
  ('c0bf100f-b4c4-5cdb-92dd-f004e501c944'::uuid, 2, 'probleme', $exo${"titre":"Simplifier sans tâtonner","consigne":"Justifie chaque réponse par un critère de divisibilité, sans poser de division.","enonce":"**Exercice.**\n\n1. Montre, sans poser de division, que **135** et **225** sont tous les deux divisibles par 5 et par 9.\n2. Déduis-en une simplification de la fraction **135/225**, puis donne-la sous forme irréductible.\n3. On considère le nombre **7■2**, où ■ est un chiffre.\n   - a) Quels chiffres peut-on écrire à la place de ■ pour que le nombre soit divisible par 3 ?\n   - b) Parmi ces nombres, lesquels sont aussi divisibles par 4 ? Par quel nombre sont-ils alors divisibles ? Justifie.","bareme":[{"critere":"135 et 225 divisibles par 5 (dernier chiffre) et par 9 (somme 9)","points":6},{"critere":"135/225 simplifiée jusqu’à 3/5, forme irréductible justifiée","points":5},{"critere":"Chiffres possibles pour ■ : 0, 3, 6 ou 9","points":4},{"critere":"732 et 792 divisibles par 4, donc par 12, car 3 et 4 sont premiers entre eux","points":5}],"dureeMin":11,"corrige":"1. 135 et 225 se terminent par 5 : ils sont divisibles par 5. Sommes des chiffres : 1 + 3 + 5 = 9 et 2 + 2 + 5 = 9 : ils sont divisibles par 9.\n\n2. On simplifie par 5 : 135/225 = 27/45 ; puis par 9 : 27/45 = **3/5**. (Comme 5 et 9 sont premiers entre eux, on pouvait aussi simplifier directement par 45.) La fraction 3/5 est irréductible : 3 et 5 n'ont que 1 comme diviseur commun.\n\n3. a) Somme des chiffres : 7 + ■ + 2 = 9 + ■, qui doit être divisible par 3. Donc ■ = **0, 3, 6 ou 9** (nombres 702, 732, 762, 792).\n   b) On regarde les deux derniers chiffres : 02 et 62 ne sont pas des multiples de 4 ; **32** (= 4 × 8) et **92** (= 4 × 23) en sont. Donc **732 et 792** sont divisibles par 3 et par 4. Comme 3 et 4 sont premiers entre eux, ils sont divisibles par **12** (732 = 12 × 61 et 792 = 12 × 66)."}$exo$::jsonb),
  ('c0bf100f-b4c4-5cdb-92dd-f004e501c944'::uuid, 3, 'probleme', $exo${"titre":"Le code du cadenas","consigne":"Réponds en citant à chaque fois le critère de divisibilité utilisé.","enonce":"**Situation.** Tom a oublié le code à quatre chiffres de son cadenas. Il sait qu'il s'écrit **3 ■ 6 ▲** (3 pour les milliers, 6 pour les dizaines) et se souvient de quatre indices :\n- le code est divisible par 5 ;\n- le code est divisible par 4 ;\n- le code est divisible par 9 ;\n- le chiffre des centaines n'est pas 0.\n\n1. Trouve le chiffre des unités ▲, en expliquant comment tu utilises les deux premiers indices.\n2. Trouve le chiffre des centaines ■, puis donne le code.\n3. Le code est-il divisible par 36 ? Justifie sans poser de division.\n4. Julie affirme : « Le code est divisible par 6 et par 9, donc il est divisible par 54. » Son raisonnement est-il valable ? Vérifie sa conclusion.","bareme":[{"critere":"Chiffre des unités 0, déduit des critères de 5 et de 4","points":4},{"critere":"Chiffre des centaines 9 par la somme des chiffres, code 3 960","points":5},{"critere":"Divisibilité par 36 justifiée par 36 = 4 × 9, avec 4 et 9 premiers entre eux","points":5},{"critere":"Julie : 6 et 9 non premiers entre eux, et 3 960 ÷ 54 ne tombe pas juste","points":6}],"dureeMin":16,"corrige":"1. Divisible par 5 : le code se termine par 0 ou 5. Divisible par 4 : il est pair. Donc **▲ = 0**. On vérifie : les deux derniers chiffres forment 60, et 60 = 4 × 15 est bien un multiple de 4.\n\n2. Divisible par 9 : 3 + ■ + 6 + 0 = 9 + ■ doit être divisible par 9, donc ■ = 0 ou ■ = 9. Le chiffre des centaines n'est pas 0 : **■ = 9**. Le code est **3 960**.\n\n3. 36 = 4 × 9, et 4 et 9 sont premiers entre eux. 3 960 est divisible par 4 et par 9, donc **il est divisible par 36** (3 960 = 36 × 110).\n\n4. Le raisonnement **n'est pas valable** : on ne peut combiner deux critères que si les deux diviseurs sont premiers entre eux, or 6 et 9 ont 3 comme diviseur commun.\n   D'ailleurs, 3 960 = 54 × 73 + 18 : le reste n'est pas nul, **3 960 n'est pas divisible par 54**."}$exo$::jsonb),
  ('0d56d33e-0375-5914-8834-470c354ed4f9'::uuid, 1, 'probleme', $exo${"titre":"Les trois questions des pourcentages","consigne":"Pour chaque question, dis si l'on cherche une partie, un pourcentage ou le tout, puis calcule.","enonce":"**Questions.**\n\n1. Calcule **35 % de 60**.\n2. Dans un collège de **400 élèves**, **92** viennent à vélo. Quel pourcentage des élèves cela représente-t-il ?\n3. **27 élèves** représentent **36 %** des élèves de 4e d'un collège. Combien y a-t-il d'élèves de 4e dans ce collège ?","bareme":[{"critere":"35 % de 60 = 60 × 0,35 = 21","points":6},{"critere":"Pourcentage des cyclistes : (92 ÷ 400) × 100 = 23 %","points":7},{"critere":"Nombre d’élèves de 4e : 27 ÷ 0,36 = 75, avec une vérification","points":7}],"dureeMin":7,"corrige":"1. On cherche une **partie** : on multiplie. 60 × 0,35 = **21**.\n\n2. On cherche un **pourcentage** : on divise, puis on multiplie par 100. (92 ÷ 400) × 100 = 0,23 × 100 = **23 %**.\n\n3. On cherche le **tout** : on divise par le coefficient. 27 ÷ 0,36 = **75 élèves**.\n   Vérification : 75 × 0,36 = 27, et le tout (75) est bien plus grand que la partie (27)."}$exo$::jsonb),
  ('0d56d33e-0375-5914-8834-470c354ed4f9'::uuid, 2, 'probleme', $exo${"titre":"Les soldes de Chloé","consigne":"Utilise les coefficients multiplicateurs et détaille tes calculs.","enonce":"**Situation.** Pendant les soldes, Chloé achète deux articles :\n- un jean affiché **60 €**, avec une remise de **20 %** ;\n- un sweat qu'elle paie **34 €** après une remise de **15 %**.\n\n1. Combien paie-t-elle le jean ?\n2. Quel était le prix du sweat avant la remise ?\n3. Son frère propose de retrouver le prix du sweat avant remise en ajoutant 15 % à 34 €. Quel résultat obtiendrait-il ? Pourquoi est-ce faux ?\n4. Quel est le taux d'évolution entre le prix total des deux articles avant remises et le prix total payé ?","bareme":[{"critere":"Prix du jean : 60 × 0,8 = 48 €","points":5},{"critere":"Prix du sweat avant remise : 34 ÷ 0,85 = 40 €","points":6},{"critere":"Erreur du frère : 39,10 € trouvé et expliqué (les 15 % portent sur le prix initial)","points":4},{"critere":"Taux d’évolution global : de 100 € à 82 €, soit −18 %","points":5}],"dureeMin":12,"corrige":"1. Une baisse de 20 % laisse 80 % du prix : coefficient 0,8. 60 × 0,8 = **48 €**.\n\n2. Le prix payé vaut 0,85 fois le prix initial. Pour retrouver le prix initial, on divise : 34 ÷ 0,85 = **40 €**. Vérification : 40 × 0,85 = 34.\n\n3. Il obtiendrait 34 × 1,15 = **39,10 €**, ce qui est faux : les 15 % portaient sur le prix **initial** (40 €), pas sur le prix soldé. 15 % de 34 € est plus petit que 15 % de 40 €.\n\n4. Avant remises : 60 + 40 = 100 €. Prix payé : 48 + 34 = 82 €.\n   Taux d'évolution : (82 − 100) ÷ 100 × 100 = **−18 %**."}$exo$::jsonb),
  ('0d56d33e-0375-5914-8834-470c354ed4f9'::uuid, 3, 'probleme', $exo${"titre":"L'abonnement de la salle de sport","consigne":"Réponds en justifiant chaque calcul à l'aide des coefficients multiplicateurs.","enonce":"**Situation.** L'abonnement mensuel d'une salle de sport évolue au cours de l'année.\n- En janvier, il coûte **30 €**.\n- En juin, il augmente de **20 %**.\n- En septembre, une promotion le fait baisser de **20 %**.\n\n1. Calcule le prix en juin, puis en septembre.\n2. Hugo pense qu'en septembre le prix est revenu à 30 €. Montre qu'il a tort à l'aide des coefficients multiplicateurs, et donne le taux d'évolution global entre janvier et septembre.\n3. En décembre, l'abonnement coûte **31,68 €**. Calcule le taux d'évolution entre septembre et décembre.\n4. Une autre salle affiche **27 €** après une baisse de **10 %**. Quel était son prix avant la baisse ? Explique pourquoi on ne calcule pas 27 × 1,1.","bareme":[{"critere":"Prix de juin 36 € et de septembre 28,80 €","points":4},{"critere":"Coefficient global 1,2 × 0,8 = 0,96, soit −4 % : Hugo a tort","points":5},{"critere":"Taux de septembre à décembre : +10 %","points":5},{"critere":"Prix avant la baisse : 27 ÷ 0,9 = 30 €, et rejet de 27 × 1,1 expliqué","points":6}],"dureeMin":17,"corrige":"1. Juin : 30 × 1,2 = **36 €**. Septembre : 36 × 0,8 = **28,80 €**.\n\n2. Les évolutions successives se multiplient : 1,2 × 0,8 = **0,96**. Le prix de janvier est multiplié par 0,96, il ne revient donc pas à 30 € (30 × 0,96 = 28,80 €).\n   Le coefficient 0,96 correspond à une baisse de **4 %**. Vérification : (28,80 − 30) ÷ 30 × 100 = −4 %.\n   La baisse de 20 % porte sur 36 €, un prix plus élevé que les 30 € sur lesquels portait la hausse : elle enlève plus que la hausse n'avait ajouté.\n\n3. (31,68 − 28,80) ÷ 28,80 × 100 = 2,88 ÷ 28,80 × 100 = **+10 %**.\n\n4. Le prix affiché vaut 0,9 fois le prix initial : 27 ÷ 0,9 = **30 €**.\n   Calculer 27 × 1,1 = 29,70 € serait faux : les 10 % portaient sur le prix initial, pas sur le prix réduit."}$exo$::jsonb),
  ('9146ff73-d337-5ad9-ba54-f90e3a56e64d'::uuid, 1, 'probleme', $exo${"titre":"Carte et plan","consigne":"Réponds en convertissant les distances dans la même unité avant de calculer.","enonce":"**Questions.**\n\n1. Sur une carte au **1/25 000**, un chemin mesure **6 cm**. Quelle est sa longueur réelle, en mètres ?\n2. Sur la même carte, quelle longueur représente une distance réelle de **3,5 km** ?\n3. Sur le plan d'un appartement, une pièce de **5 m** de long mesure **10 cm**. Quelle est l'échelle du plan ?","bareme":[{"critere":"Longueur réelle du chemin : 150 000 cm = 1 500 m","points":7},{"critere":"3,5 km = 350 000 cm, soit 14 cm sur la carte","points":7},{"critere":"Échelle du plan : 10 ÷ 500 = 1/50","points":6}],"dureeMin":8,"corrige":"1. Du plan vers le réel : 6 × 25 000 = 150 000 cm. Or 1 m = 100 cm, donc 150 000 cm = **1 500 m**.\n\n2. On convertit d'abord : 3,5 km = 350 000 cm. Du réel vers le plan : 350 000 × 1/25 000 = 350 000 ÷ 25 000 = **14 cm**.\n\n3. Même unité : 5 m = 500 cm. Échelle = distance sur le plan ÷ distance réelle = 10 ÷ 500 = **1/50**."}$exo$::jsonb),
  ('9146ff73-d337-5ad9-ba54-f90e3a56e64d'::uuid, 2, 'probleme', $exo${"titre":"Le plan de la maison de Noah","consigne":"Réponds en détaillant les conversions.","enonce":"**Situation.** Le plan de la maison de Noah est au **1/100**.\n\n1. Sur le plan, le salon est un rectangle de **6 cm sur 4,5 cm**. Quelles sont ses dimensions réelles, en mètres ?\n2. Calcule l'aire réelle du salon en m², puis l'aire du rectangle dessiné sur le plan en cm². Par combien l'aire a-t-elle été divisée ?\n3. Le garage mesure en réalité **5,2 m** de long. Quelle longueur aura-t-il sur le plan ?","bareme":[{"critere":"Dimensions réelles du salon : 6 m et 4,5 m","points":5},{"critere":"Aire réelle du salon : 27 m²","points":4},{"critere":"Aire sur le plan 27 cm², et aire divisée par 10 000 = 100²","points":6},{"critere":"Longueur du garage sur le plan : 5,2 cm","points":5}],"dureeMin":12,"corrige":"1. 6 × 100 = 600 cm = **6 m** et 4,5 × 100 = 450 cm = **4,5 m**.\n\n2. Aire réelle : 6 × 4,5 = **27 m²**. Aire sur le plan : 6 × 4,5 = **27 cm²**.\n   Or 27 m² = 270 000 cm², et 270 000 ÷ 27 = 10 000. L'aire a été divisée par **10 000 = 100²** : l'échelle porte sur les longueurs, et les aires sont divisées par le carré de 100.\n\n3. 5,2 m = 520 cm, et 520 ÷ 100 = **5,2 cm**."}$exo$::jsonb),
  ('9146ff73-d337-5ad9-ba54-f90e3a56e64d'::uuid, 3, 'probleme', $exo${"titre":"La carte de randonnée","consigne":"Réponds en justifiant chaque calcul. Attention aux conversions.","enonce":"**Situation.** Sur une carte de randonnée, le refuge et le lac sont séparés de **8,4 cm**. En réalité, ils sont à **2,1 km** l'un de l'autre.\n\n1. Calcule l'échelle de la carte.\n2. Sur la carte, le sentier qui mène au sommet mesure **18 cm**. Quelle est sa longueur réelle, en km ?\n3. Sur la carte, le lac occupe environ **8 cm²**. Par combien faut-il multiplier une aire lue sur la carte pour obtenir l'aire réelle ? Déduis-en l'aire réelle du lac, en m² (1 m² = 10 000 cm²).\n4. Mila agrandit la carte à la photocopieuse : sur la copie, le refuge et le lac sont à **16,8 cm** l'un de l'autre. Quelle est l'échelle de la photocopie ?","bareme":[{"critere":"Échelle de la carte : 8,4 ÷ 210 000 = 1/25 000","points":5},{"critere":"Longueur réelle du sentier : 4,5 km","points":4},{"critere":"Aires multipliées par 25 000², aire réelle du lac : 500 000 m²","points":6},{"critere":"Échelle de la photocopie : 1/12 500","points":5}],"dureeMin":18,"corrige":"1. Même unité : 2,1 km = 210 000 cm. Échelle = 8,4 ÷ 210 000 = **1/25 000** (car 210 000 ÷ 8,4 = 25 000).\n\n2. 18 × 25 000 = 450 000 cm = 4 500 m = **4,5 km**.\n\n3. Les longueurs réelles sont 25 000 fois plus grandes : les aires le sont 25 000² = **625 000 000** fois.\n   Aire réelle : 8 × 625 000 000 = 5 000 000 000 cm². Avec 1 m² = 10 000 cm² : 5 000 000 000 ÷ 10 000 = **500 000 m²**.\n\n4. 16,8 ÷ 210 000 = **1/12 500** (car 210 000 ÷ 16,8 = 12 500).\n   La distance sur la carte a doublé (8,4 → 16,8 cm), l'échelle aussi : 1/12 500 = 2 × 1/25 000."}$exo$::jsonb),
  ('2cf74dd8-58a4-595f-86a4-b239271d4633'::uuid, 1, 'probleme', $exo${"titre":"Simples ou composées ?","consigne":"Réponds en donnant, pour chaque grandeur, son unité.","enonce":"**Questions de cours.**\n\n1. Classe les six grandeurs suivantes en deux groupes, **grandeurs simples** et **grandeurs composées**, et donne une unité pour chacune : une masse, une vitesse, une durée, une aire, un débit, une longueur.\n2. Pour chaque grandeur composée, écris sa formule et précise si elle s'obtient par une multiplication ou par une division.","bareme":[{"critere":"Classement : masse, durée, longueur simples ; vitesse, aire, débit composées","points":8},{"critere":"Une unité correcte pour chacune des six grandeurs","points":6},{"critere":"Formules de l’aire (produit), de la vitesse et du débit (quotients)","points":6}],"dureeMin":7,"corrige":"1. **Grandeurs simples** (lues directement sur un instrument) : la masse (kilogramme, à la balance), la durée (seconde, au chronomètre), la longueur (mètre, à la règle).\n   **Grandeurs composées** (obtenues par un calcul) : la vitesse (m/s ou km/h), l'aire (m²), le débit (L/min).\n\n2. - Aire = longueur × longueur : **multiplication** (unité m²).\n   - Vitesse = distance ÷ durée : **division** (unité m/s ou km/h).\n   - Débit = volume ÷ durée : **division** (unité L/min).\n   L'unité révèle la construction : le « ² » signale un produit, la barre « / » un quotient."}$exo$::jsonb),
  ('2cf74dd8-58a4-595f-86a4-b239271d4633'::uuid, 2, 'probleme', $exo${"titre":"Les calculs de la maison de Lina","consigne":"Réponds en écrivant la formule utilisée et l'unité de chaque résultat.","enonce":"**Situation.** Chez Lina, on fait quelques calculs du quotidien.\n\n1. Le four, d'une puissance de **2,5 kW**, fonctionne pendant **1 h 30 min**. Quelle énergie consomme-t-il, en kWh ? Le kWh coûte **0,20 €** : combien coûte cette cuisson ?\n2. Un tuyau remplit une piscine gonflable de **6 000 L** en **50 min**. Quel est son débit, en L/min ?\n3. Un morceau de fromage de **400 g** coûte **7,20 €**. Quel est son prix au kilo ?","bareme":[{"critere":"Énergie du four : 2,5 × 1,5 = 3,75 kWh","points":6},{"critere":"Coût de la cuisson : 0,75 €","points":3},{"critere":"Débit du tuyau : 6 000 ÷ 50 = 120 L/min","points":5},{"critere":"Prix au kilo : 7,20 ÷ 0,4 = 18 €/kg","points":6}],"dureeMin":11,"corrige":"1. 1 h 30 min = 1,5 h. Énergie = puissance × durée = 2,5 kW × 1,5 h = **3,75 kWh**.\n   Coût : 3,75 × 0,20 = **0,75 €**.\n\n2. Débit = volume ÷ durée = 6 000 L ÷ 50 min = **120 L/min**.\n\n3. 400 g = 0,4 kg. Prix au kilo = prix ÷ masse = 7,20 € ÷ 0,4 kg = **18 €/kg**.\n   L'unité €/kg dit bien qu'on divise un prix par une masse."}$exo$::jsonb),
  ('2cf74dd8-58a4-595f-86a4-b239271d4633'::uuid, 3, 'probleme', $exo${"titre":"Le pavé d'aluminium","consigne":"Réponds en justifiant chaque calcul et en donnant toujours l'unité.","enonce":"**Situation.** Sacha dispose d'un petit pavé en aluminium de **5 cm × 4 cm × 2 cm**. Sur la balance, il pèse **108 g**.\n\n1. Calcule le volume du pavé.\n2. Calcule la masse volumique de l'aluminium. Donne son unité et explique ce que cette unité dit du calcul.\n3. Une pièce du même métal a un volume de **250 cm³**. Quelle est sa masse ?\n4. Jade écrit : « masse volumique = 40 ÷ 108 ≈ 0,37 ». Explique, à l'aide des unités, pourquoi son résultat est faux et incomplet.\n5. Parmi les grandeurs utilisées dans cet exercice (longueur, masse, volume, masse volumique), lesquelles sont simples ? Lesquelles sont composées, et par quelle opération ?","bareme":[{"critere":"Volume du pavé : 40 cm³","points":3},{"critere":"Masse volumique : 108 ÷ 40 = 2,7 g/cm³, sens de l’unité expliqué","points":5},{"critere":"Masse de la pièce de 250 cm³ : 675 g","points":4},{"critere":"Erreur de Jade : quotient inversé (cm³/g) et unité absente","points":4},{"critere":"Longueur et masse simples ; volume (produit) et masse volumique (quotient) composés","points":4}],"dureeMin":16,"corrige":"1. Volume = L × l × h = 5 × 4 × 2 = **40 cm³**.\n\n2. Masse volumique = masse ÷ volume = 108 g ÷ 40 cm³ = **2,7 g/cm³**.\n   L'unité g/cm³ se lit « des grammes divisés par des centimètres cubes » : c'est la masse d'un seul cm³ d'aluminium.\n\n3. Chaque cm³ pèse 2,7 g : 2,7 × 250 = **675 g**.\n\n4. Jade a divisé le volume par la masse : elle obtient des cm³/g, et non des g/cm³ ; le bon quotient est masse ÷ volume. De plus, elle n'a écrit aucune unité : un résultat sans unité n'a pas de sens.\n\n5. **Simples** : la longueur (à la règle) et la masse (à la balance).\n   **Composées** : le volume, obtenu par **multiplication** de trois longueurs (cm³), et la masse volumique, obtenue par **division** d'une masse par un volume (g/cm³)."}$exo$::jsonb),
  ('96308e0d-b349-5937-9ca8-fa0fceb05c61'::uuid, 1, 'probleme', $exo${"titre":"Série de conversions","consigne":"Recopie et complète chaque égalité. Écris le calcul pour les durées.","enonce":"**Conversions.** Recopie et complète.\n\n- a) 4,2 km = … m\n- b) 350 mm = … cm\n- c) 2,5 kg = … g\n- d) 750 mg = … g\n- e) 1,2 L = … cL\n- f) 3 h 45 min = … h (en heures décimales)\n- g) 0,4 h = … min","bareme":[{"critere":"Longueurs et masses justes : 4 200 m, 35 cm, 2 500 g, 0,75 g","points":9},{"critere":"Contenance : 1,2 L = 120 cL","points":3},{"critere":"Durées : 3 h 45 min = 3,75 h et 0,4 h = 24 min, en passant par 60","points":8}],"dureeMin":7,"corrige":"- a) 1 km = 1 000 m : 4,2 km = **4 200 m**.\n- b) 1 cm = 10 mm : 350 mm = **35 cm**.\n- c) 1 kg = 1 000 g : 2,5 kg = **2 500 g**.\n- d) 1 g = 1 000 mg : 750 mg = **0,75 g**.\n- e) 1 L = 100 cL : 1,2 L = **120 cL**.\n- f) 45 min = 45 ÷ 60 h = 0,75 h, donc 3 h 45 min = **3,75 h** (et non 3,45 h).\n- g) 0,4 × 60 = **24 min**.\n\nContrôle de vraisemblance : vers une unité plus petite, le nombre grandit (a, c, e) ; vers une unité plus grande, il diminue (b, d)."}$exo$::jsonb),
  ('96308e0d-b349-5937-9ca8-fa0fceb05c61'::uuid, 2, 'probleme', $exo${"titre":"L'entraînement de Karim","consigne":"Réponds en mettant les grandeurs dans la même unité avant de calculer.","enonce":"**Situation.** Karim s'entraîne pour le cross du collège.\n\n1. Lundi, il fait **3 tours** d'une piste de **400 m**, puis **2,3 km** sur la route. Quelle distance totale a-t-il parcourue, en km ?\n2. Son entraînement dure **45 min**. Écris cette durée en heures décimales.\n3. Sa gourde contient **75 cL**. Il boit **450 mL**. Quel volume reste-t-il dans la gourde, en cL ?","bareme":[{"critere":"Distance totale : 1,2 km + 2,3 km = 3,5 km","points":7},{"critere":"45 min = 0,75 h, en divisant par 60","points":6},{"critere":"Volume restant : 750 mL − 450 mL = 300 mL = 30 cL","points":7}],"dureeMin":10,"corrige":"1. Piste : 3 × 400 = 1 200 m = 1,2 km. Total : 1,2 + 2,3 = **3,5 km**. On met les deux distances dans la même unité avant d'additionner.\n\n2. 45 min = 45 ÷ 60 h = **0,75 h** (et non 0,45 h : une heure compte 60 minutes, pas 100).\n\n3. 75 cL = 750 mL. Il reste 750 − 450 = 300 mL = **30 cL**."}$exo$::jsonb),
  ('96308e0d-b349-5937-9ca8-fa0fceb05c61'::uuid, 3, 'probleme', $exo${"titre":"La citerne du jardin partagé","consigne":"Réponds en détaillant chaque conversion.","enonce":"**Situation.** Au jardin partagé, une citerne récupère l'eau de pluie. Pleine, elle contient **1 250 L**.\n\n1. Exprime ce volume en dm³, puis en cm³.\n2. Julien remplit des arrosoirs de **12,5 L**. Combien d'arrosoirs pleins peut-il remplir avec la citerne pleine ?\n3. Remplir un arrosoir prend **1 min 12 s**. Combien de temps faut-il pour remplir tous ces arrosoirs ? Donne le résultat en secondes, puis en heures.\n4. Un litre d'eau a une masse de **1 kg**. Quelle est la masse de l'eau de la citerne pleine, en tonnes ?\n5. Emma écrit : « 1 min 12 s = 1,12 min ». Corrige son erreur.","bareme":[{"critere":"1 250 L = 1 250 dm³ = 1 250 000 cm³","points":4},{"critere":"Nombre d’arrosoirs : 1 250 ÷ 12,5 = 100","points":3},{"critere":"Durée totale : 100 × 72 s = 7 200 s = 2 h","points":5},{"critere":"Masse de l’eau : 1 250 kg = 1,25 t","points":4},{"critere":"Correction d’Emma : 1 min 12 s = 1,2 min, en divisant par 60","points":4}],"dureeMin":16,"corrige":"1. 1 L = 1 dm³, donc 1 250 L = **1 250 dm³**.\n   1 L = 1 000 mL et 1 mL = 1 cm³, donc 1 250 L = 1 250 000 mL = **1 250 000 cm³**.\n\n2. 1 250 ÷ 12,5 = **100 arrosoirs**.\n\n3. 1 min 12 s = 60 s + 12 s = 72 s. Pour 100 arrosoirs : 100 × 72 = **7 200 s**.\n   7 200 ÷ 60 = 120 min, et 120 ÷ 60 = **2 h**.\n\n4. 1 250 L d'eau ont une masse de 1 250 kg. Comme 1 t = 1 000 kg : 1 250 kg = **1,25 t**.\n\n5. 12 s = 12 ÷ 60 min = 0,2 min, donc **1 min 12 s = 1,2 min**. Les durées ne se comptent pas de 10 en 10 : pour passer des secondes aux minutes, on divise par 60."}$exo$::jsonb),
  ('ea10d373-53b1-5f93-85bf-37fa6a6eeeae'::uuid, 1, 'probleme', $exo${"titre":"Aires et volumes : les bonnes colonnes","consigne":"Écris chaque conversion en expliquant le nombre de colonnes utilisées.","enonce":"**Questions de cours et d’application.**\n\n1. Convertis **3,5 m²** en cm².\n2. Convertis **4 500 dm²** en m².\n3. Convertis **0,75 m³** en litres, puis **2 500 cm³** en litres.","bareme":[{"critere":"3,5 m² = 35 000 cm², avec le facteur 10 000 (et non 100) justifié","points":7},{"critere":"4 500 dm² = 45 m², avec le facteur 100 entre dm² et m²","points":6},{"critere":"0,75 m³ = 750 L et 2 500 cm³ = 2,5 L, via 1 dm³ = 1 L","points":7}],"dureeMin":6,"corrige":"1. Une aire se convertit **de 100 en 100** : de m² à cm², on passe deux unités, donc on multiplie par 100 × 100 = 10 000. Ainsi 3,5 m² = 3,5 × 10 000 = **35 000 cm²**.\n\n2. De dm² à m², on remonte d’une unité : on divise par 100. Ainsi 4 500 dm² = 4 500 ÷ 100 = **45 m²**.\n\n3. On utilise 1 m³ = 1 000 L. Donc 0,75 m³ = 0,75 × 1 000 = **750 L**.\n   Pour 2 500 cm³ : 1 000 cm³ = 1 dm³ = 1 L, donc 2 500 cm³ = 2 500 ÷ 1 000 = **2,5 L**.\n\nErreur à éviter : convertir une aire comme une longueur (facteur 100 au lieu de 10 000 pour m² → cm²)."}$exo$::jsonb),
  ('ea10d373-53b1-5f93-85bf-37fa6a6eeeae'::uuid, 2, 'probleme', $exo${"titre":"Scooter contre cycliste","consigne":"Réponds à chaque question en détaillant tes conversions.","enonce":"**Situation.** Sur une piste, Malik roule en scooter à **45 km/h** et Inès pédale à **12 m/s**.\n\n1. Convertis la vitesse de Malik en m/s.\n2. Convertis la vitesse d’Inès en km/h.\n3. Qui roule le plus vite ? Justifie.\n4. Quelle distance Malik parcourt-il en 2 minutes, en mètres ? (Pense à utiliser sa vitesse en m/s.)","bareme":[{"critere":"Vitesse de Malik : 45 ÷ 3,6 = 12,5 m/s","points":5},{"critere":"Vitesse d’Inès : 12 × 3,6 = 43,2 km/h","points":5},{"critere":"Comparaison dans la même unité : Malik est plus rapide","points":4},{"critere":"Distance en 2 min : 12,5 × 120 = 1 500 m, avec conversion des minutes en secondes","points":6}],"dureeMin":10,"corrige":"1. km/h → m/s : on divise par 3,6. 45 ÷ 3,6 = **12,5 m/s**.\n\n2. m/s → km/h : on multiplie par 3,6. 12 × 3,6 = **43,2 km/h**.\n\n3. Dans la même unité, on compare : 12,5 m/s > 12 m/s (ou 45 km/h > 43,2 km/h). **Malik est plus rapide**, de peu.\n\n4. 2 minutes = 120 secondes. Distance = vitesse × durée = 12,5 × 120 = **1 500 m** (soit 1,5 km).\n\nVérification : 45 km/h pendant 2 min = 45 × (2/60) = 1,5 km. Les deux méthodes concordent."}$exo$::jsonb),
  ('ea10d373-53b1-5f93-85bf-37fa6a6eeeae'::uuid, 3, 'probleme', $exo${"titre":"Remplir le bassin","consigne":"Rédige chaque étape avec ses conversions et ses calculs.","enonce":"**Situation.** Un robinet remplit un bassin avec un débit de **12 L/min**. Le bassin est un pavé droit de **3 m de long, 2 m de large et 1,2 m de profondeur**.\n\n1. Exprime le débit en L/h.\n2. Exprime ce débit en m³/h.\n3. Calcule le volume du bassin en m³, puis en litres.\n4. Combien de temps faut-il pour le remplir complètement ? Donne le résultat en minutes, puis en heures.\n5. L’eau a une masse volumique de **1 g/cm³**. Convertis-la en kg/m³ puis calcule la masse d’eau contenue dans le bassin plein.","bareme":[{"critere":"Débit en L/h : 12 × 60 = 720 L/h","points":3},{"critere":"Débit en m³/h : 720 L/h = 0,72 m³/h (1 m³ = 1 000 L)","points":3},{"critere":"Volume du bassin : 3 × 2 × 1,2 = 7,2 m³ = 7 200 L","points":4},{"critere":"Durée de remplissage : 7 200 ÷ 12 = 600 min = 10 h","points":5},{"critere":"1 g/cm³ = 1 000 kg/m³, donc masse d’eau 7,2 × 1 000 = 7 200 kg","points":5}],"dureeMin":15,"corrige":"1. Une heure vaut 60 minutes : 12 L/min = 12 × 60 = **720 L/h**.\n\n2. 1 m³ = 1 000 L, donc 720 L/h = 720 ÷ 1 000 = **0,72 m³/h**.\n\n3. Volume du pavé droit : 3 × 2 × 1,2 = **7,2 m³**. Comme 1 m³ = 1 000 L : 7,2 × 1 000 = **7 200 L**.\n\n4. Durée = volume ÷ débit = 7 200 ÷ 12 = **600 minutes**, soit 600 ÷ 60 = **10 heures**. Vérification : 7,2 m³ ÷ 0,72 m³/h = 10 h.\n\n5. On convertit le numérateur et le dénominateur séparément : 1 g/cm³ = 1 000 kg/m³. La masse d’eau vaut 7,2 × 1 000 = **7 200 kg** (soit 7,2 tonnes). Elle est égale au nombre de litres, car 1 L d’eau pèse 1 kg."}$exo$::jsonb),
  ('787349c7-b624-5bb9-a75e-0e76edf04e0f'::uuid, 1, 'probleme', $exo${"titre":"Angles et inégalité triangulaire","consigne":"Justifie chaque réponse avec la propriété du cours.","enonce":"**Questions de cours et d’application.**\n\n1. Dans un triangle ABC, l’angle A mesure **48°** et l’angle B mesure **67°**. Calcule l’angle C.\n2. Un triangle SAB est isocèle en S et son angle au sommet S mesure **40°**. Calcule ses angles à la base.\n3. Peut-on construire un triangle dont les côtés mesurent **5 cm, 6 cm et 12 cm** ? Justifie.","bareme":[{"critere":"Angle C = 180 − 48 − 67 = 65°, avec la somme des angles","points":6},{"critere":"Angles à la base : (180 − 40) ÷ 2 = 70° chacun, car ils sont égaux","points":7},{"critere":"Triangle impossible : 5 + 6 = 11 est inférieur à 12","points":7}],"dureeMin":7,"corrige":"1. La somme des angles d’un triangle vaut 180° : C = 180 − (48 + 67) = 180 − 115 = **65°**.\n\n2. Dans un triangle isocèle, les deux angles à la base sont égaux. Leur somme vaut 180 − 40 = 140°, donc chacun mesure 140 ÷ 2 = **70°**.\n\n3. On applique l’inégalité triangulaire : le plus grand côté doit être plus petit que la somme des deux autres. Ici 5 + 6 = 11 et 11 < 12 : **la construction est impossible**, les deux petits côtés ne peuvent pas se rejoindre."}$exo$::jsonb),
  ('787349c7-b624-5bb9-a75e-0e76edf04e0f'::uuid, 2, 'probleme', $exo${"titre":"Le jardin triangulaire","consigne":"Réponds à chaque question en détaillant tes calculs.","enonce":"**Situation.** Le jardin de Sofia est un triangle ABC **rectangle en B**, avec **AB = 12 m** et **BC = 9 m**.\n\n1. Calcule l’aire du jardin en choisissant BC comme base. Quelle est alors la hauteur correspondante ?\n2. Un sachet de graines de gazon couvre **6 m²**. Combien de sachets faut-il pour tout le jardin ?\n3. L’angle en A mesure **50°**. Calcule l’angle en C et explique pourquoi les angles A et C sont complémentaires.\n4. Sofia change de base et prend AB. Quelle est la hauteur relative à AB ? Retrouve l’aire.","bareme":[{"critere":"Aire = 9 × 12 ÷ 2 = 54 m², hauteur relative à BC : AB = 12 m","points":5},{"critere":"54 ÷ 6 = 9 sachets","points":4},{"critere":"Angle C = 90 − 50 = 40°, angles complémentaires dans un triangle rectangle","points":5},{"critere":"Base AB, hauteur BC = 9 m, aire 12 × 9 ÷ 2 = 54 m²","points":6}],"dureeMin":10,"corrige":"1. Le triangle est rectangle en B : les côtés (AB) et (BC) sont perpendiculaires. Avec la base BC = 9 m, la hauteur relative est **AB = 12 m**. Aire = (base × hauteur) ÷ 2 = 9 × 12 ÷ 2 = 108 ÷ 2 = **54 m²**.\n\n2. 54 ÷ 6 = **9 sachets**.\n\n3. Dans un triangle rectangle, les deux autres angles sont complémentaires : leur somme vaut 90°. Donc C = 90 − 50 = **40°**. Vérification avec la somme des angles : 90 + 50 + 40 = 180°.\n\n4. Si la base est AB, la hauteur relative est **BC = 9 m**. Aire = 12 × 9 ÷ 2 = **54 m²** : on retrouve le même résultat, quelle que soit la base choisie."}$exo$::jsonb),
  ('787349c7-b624-5bb9-a75e-0e76edf04e0f'::uuid, 3, 'probleme', $exo${"titre":"Vrai ou faux ? Quatre affirmations","consigne":"Pour chaque affirmation, réponds par « vrai » ou « faux » et justifie avec une propriété du cours.","enonce":"**Quatre affirmations sur les triangles.** Pour chacune, dis si elle est vraie ou fausse et justifie ta réponse par un calcul ou une propriété.\n\n**A.** « On peut construire un triangle dont les côtés mesurent 7 cm, 10 cm et 17 cm. »\n\n**B.** « Un triangle isocèle dont un angle à la base mesure 55° a un angle au sommet de 70°. »\n\n**C.** « Dans un triangle ABC, la médiane issue de A mesure 9 cm ; le centre de gravité G est à 6 cm de A. »\n\n**D.** « Un triangle qui a deux angles de 60° et de 65° est équilatéral. »","bareme":[{"critere":"A fausse : 7 + 10 = 17, donc points alignés, pas de triangle","points":5},{"critere":"B vraie : 180 − 55 − 55 = 70°","points":5},{"critere":"C vraie : G est aux deux tiers depuis le sommet, soit 6 cm","points":5},{"critere":"D fausse : troisième angle 55°, pas trois angles de 60°","points":5}],"dureeMin":14,"corrige":"**A. Fausse.** L’inégalité triangulaire demande que le plus grand côté soit strictement plus petit que la somme des deux autres. Ici 7 + 10 = 17 : il y a égalité, donc les trois points sont **alignés** et il n’y a pas de vrai triangle.\n\n**B. Vraie.** Les deux angles à la base sont égaux : 55° + 55° = 110°. L’angle au sommet vaut 180 − 110 = **70°**.\n\n**C. Vraie.** Le centre de gravité se trouve sur chaque médiane, aux **deux tiers depuis le sommet**. Donc AG = 2/3 × 9 = **6 cm** (et GM = 3 cm).\n\n**D. Fausse.** Le troisième angle vaut 180 − 60 − 65 = **55°**. Un triangle équilatéral aurait trois angles de 60° : ce triangle n’est même pas isocèle, ses trois angles sont différents."}$exo$::jsonb),
  ('f91e9054-fdd3-5d3e-8910-de90cc5862b9'::uuid, 1, 'probleme', $exo${"titre":"Un pavé droit de 6 cm sur 4 cm sur 3 cm","consigne":"Réponds à chaque question en écrivant la formule utilisée.","enonce":"**Questions de cours et d’application.** Un pavé droit mesure **6 cm de longueur, 4 cm de largeur et 3 cm de hauteur**.\n\n1. Combien a-t-il de faces, d’arêtes et de sommets ?\n2. Calcule son volume.\n3. Calcule son aire totale (somme des aires de toutes ses faces).","bareme":[{"critere":"6 faces, 12 arêtes et 8 sommets","points":5},{"critere":"Volume = 6 × 4 × 3 = 72 cm³","points":7},{"critere":"Aire totale = 2 × (24 + 18 + 12) = 108 cm²","points":8}],"dureeMin":8,"corrige":"1. Un pavé droit a **6 faces** (des rectangles), **12 arêtes** et **8 sommets**.\n\n2. Volume = L × l × h = 6 × 4 × 3 = **72 cm³**.\n\n3. Aire totale = 2 × (L × l + L × h + l × h) = 2 × (6 × 4 + 6 × 3 + 4 × 3) = 2 × (24 + 18 + 12) = 2 × 54 = **108 cm²**.\n   Vérification face par face : 2 faces de 24 cm², 2 de 18 cm² et 2 de 12 cm² donnent 48 + 36 + 24 = 108 cm²."}$exo$::jsonb),
  ('f91e9054-fdd3-5d3e-8910-de90cc5862b9'::uuid, 2, 'probleme', $exo${"titre":"L’aquarium de Tom","consigne":"Réponds à chaque question en détaillant tes calculs et tes conversions.","enonce":"**Situation.** L’aquarium de Tom est un pavé droit de **60 cm de long, 30 cm de large et 40 cm de haut**.\n\n1. Calcule son volume en cm³ puis en litres.\n2. Tom verse **45 L** d’eau. Quelle est la hauteur d’eau dans l’aquarium ? (Pense que 1 L = 1 000 cm³.)\n3. Il colle des vitres sur les quatre faces latérales et sur le fond (pas de dessus). Quelle est l’aire totale du verre nécessaire ?","bareme":[{"critere":"Volume : 60 × 30 × 40 = 72 000 cm³ = 72 L","points":5},{"critere":"Hauteur d’eau : 45 000 ÷ (60 × 30) = 25 cm","points":7},{"critere":"Aire de verre : 2 × 2 400 + 2 × 1 200 + 1 800 = 9 000 cm²","points":8}],"dureeMin":10,"corrige":"1. Volume = L × l × h = 60 × 30 × 40 = **72 000 cm³**. Comme 1 L = 1 000 cm³, cela fait **72 L**.\n\n2. 45 L = 45 000 cm³. Le volume d’eau est celui d’un pavé droit de même base (60 × 30 = 1 800 cm²) et de hauteur h : 1 800 × h = 45 000, donc h = 45 000 ÷ 1 800 = **25 cm**. Cette hauteur est bien inférieure à 40 cm.\n\n3. Faces latérales : 2 faces de 60 × 40 = 2 400 cm² et 2 faces de 30 × 40 = 1 200 cm², soit 4 800 + 2 400 = 7 200 cm². Fond : 60 × 30 = 1 800 cm². Total : 7 200 + 1 800 = **9 000 cm²**."}$exo$::jsonb),
  ('f91e9054-fdd3-5d3e-8910-de90cc5862b9'::uuid, 3, 'probleme', $exo${"titre":"Se repérer dans la boîte ABCDEFGH","consigne":"Justifie tes réponses avec le vocabulaire et les formules du cours.","enonce":"**Situation.** ABCDEFGH est un pavé droit : ABCD est la face du dessous, EFGH celle du dessus, et E est au-dessus de A, F au-dessus de B, G au-dessus de C, H au-dessus de D. On prend **A comme origine** et les arêtes [AB], [AD] et [AE] comme axes, avec **AB = 8 cm, AD = 6 cm et AE = 5 cm**.\n\n1. Donne les coordonnées des points B, D, E et G dans ce repère (en écrivant (x ; y ; z), avec x sur (AB), y sur (AD), z sur (AE)).\n2. Calcule la longueur de la diagonale [AC] de la face ABCD.\n3. Les droites (AB) et (DH) sont-elles parallèles, sécantes ou non coplanaires ? Justifie. Que dire des plans (ABCD) et (EFGH) ?\n4. Calcule le volume du pavé.","bareme":[{"critere":"Coordonnées : B (8 ; 0 ; 0), D (0 ; 6 ; 0), E (0 ; 0 ; 5), G (8 ; 6 ; 5)","points":5},{"critere":"Diagonale [AC] par Pythagore : √(64 + 36) = 10 cm","points":6},{"critere":"(AB) et (DH) non coplanaires, justifiées ; plans (ABCD) et (EFGH) parallèles","points":5},{"critere":"Volume = 8 × 6 × 5 = 240 cm³","points":4}],"dureeMin":15,"corrige":"1. B est sur l’axe des x : **B (8 ; 0 ; 0)**. D est sur l’axe des y : **D (0 ; 6 ; 0)**. E est sur l’axe des z : **E (0 ; 0 ; 5)**. G est le sommet opposé à A : **G (8 ; 6 ; 5)**.\n\n2. La diagonale [AC] est celle du rectangle ABCD, dont les côtés mesurent 8 et 6. Par Pythagore : AC² = 8² + 6² = 64 + 36 = 100, donc AC = **10 cm**.\n\n3. La droite (AB) est dans le plan du dessous, la droite (DH) est verticale. Elles ne sont pas parallèles (l’une est horizontale, l’autre verticale) et ne se coupent jamais : elles ne sont pas dans un même plan. Elles sont donc **non coplanaires**. Les plans (ABCD) et (EFGH) sont les faces opposées du pavé : ils sont **parallèles**.\n\n4. Volume = L × l × h = 8 × 6 × 5 = **240 cm³**."}$exo$::jsonb),
  ('58cfa258-69f9-5109-927a-c51fd8fae8c7'::uuid, 1, 'probleme', $exo${"titre":"Volumes d’une pyramide et d’un cône","consigne":"Écris la formule, puis le calcul avec les unités.","enonce":"**Questions de cours et d’application.**\n\n1. Une pyramide a pour base un carré de **6 cm de côté** et pour hauteur **10 cm**. Calcule son volume.\n2. Un cône de révolution a pour rayon de base **3 cm** et pour hauteur **7 cm**. Donne son volume exact en fonction de π, puis arrondi à l’unité.\n3. Combien de faces a un tétraèdre ? Quelle est la nature de ces faces ?","bareme":[{"critere":"Pyramide : (1/3) × 36 × 10 = 120 cm³","points":8},{"critere":"Cône : (1/3) × π × 9 × 7 = 21π ≈ 66 cm³","points":8},{"critere":"Tétraèdre : 4 faces, toutes des triangles","points":4}],"dureeMin":8,"corrige":"1. Aire de la base = 6 × 6 = 36 cm². Volume = (1/3) × aire de la base × hauteur = (1/3) × 36 × 10 = **120 cm³**.\n\n2. Volume = (1/3) × π × R² × h = (1/3) × π × 3² × 7 = (1/3) × π × 63 = **21π cm³**, soit environ **66 cm³** (21 × 3,14159… ≈ 65,97).\n\n3. Un tétraèdre est une pyramide à base triangulaire : il a **4 faces**, qui sont toutes des **triangles**."}$exo$::jsonb),
  ('58cfa258-69f9-5109-927a-c51fd8fae8c7'::uuid, 2, 'probleme', $exo${"titre":"Le cornet de glace","consigne":"Réponds à chaque question en détaillant tes calculs.","enonce":"**Situation.** Un cornet de glace a la forme d’un cône de révolution de **rayon 3 cm** et de **hauteur 12 cm**. On suppose qu’il est rempli à ras bord.\n\n1. Calcule le volume du cornet : d’abord la valeur exacte en fonction de π, puis la valeur arrondie au dixième de cm³.\n2. Convertis ce volume en millilitres (arrondi à l’unité).\n3. Combien de cornets peut-on remplir entièrement avec une bouteille de crème glacée liquide de **1 L** ?","bareme":[{"critere":"Volume exact (1/3) × π × 9 × 12 = 36π ≈ 113,1 cm³","points":8},{"critere":"113,1 cm³ = 113,1 mL, soit environ 113 mL (1 cm³ = 1 mL)","points":4},{"critere":"1 000 ÷ 113,1 ≈ 8,84 : 8 cornets entiers","points":8}],"dureeMin":10,"corrige":"1. Volume = (1/3) × π × R² × h = (1/3) × π × 3² × 12 = (1/3) × π × 108 = **36π cm³**, soit environ **113,1 cm³** (36 × 3,14159 ≈ 113,10).\n\n2. 1 cm³ = 1 mL, donc le cornet contient environ **113 mL**.\n\n3. 1 L = 1 000 mL. On calcule 1 000 ÷ 113,1 ≈ 8,84. On ne peut remplir que des cornets entiers : **8 cornets** (le neuvième ne serait rempli qu’aux 84 %)."}$exo$::jsonb),
  ('58cfa258-69f9-5109-927a-c51fd8fae8c7'::uuid, 3, 'probleme', $exo${"titre":"Une pyramide coupée près du sommet","consigne":"Justifie tes calculs avec les rapports de réduction du cours.","enonce":"**Situation.** La pyramide SABCD a pour base un carré ABCD de **9 cm de côté** et pour hauteur **12 cm**. On la coupe par un plan **parallèle à la base**, situé à **4 cm du sommet S** (mesurés sur la hauteur). La section est un carré, et la petite pyramide au-dessus de la section est une réduction de la grande.\n\n1. Calcule le volume de la grande pyramide.\n2. Quel est le coefficient de réduction k ? Quel est le côté de la section ?\n3. Calcule l’aire de la section de deux façons : avec son côté, puis avec k².\n4. Calcule le volume de la petite pyramide de deux façons : avec la formule (1/3) × aire × hauteur, puis avec k³.","bareme":[{"critere":"Grande pyramide : (1/3) × 81 × 12 = 324 cm³","points":4},{"critere":"k = 4/12 = 1/3 et côté de la section : 9 × 1/3 = 3 cm","points":5},{"critere":"Aire de la section : 3² = 9 cm² et 81 × (1/3)² = 9 cm²","points":4},{"critere":"Petite pyramide : (1/3) × 9 × 4 = 12 cm³ et 324 × (1/3)³ = 12 cm³","points":7}],"dureeMin":15,"corrige":"1. Aire de la base = 9 × 9 = 81 cm². Volume = (1/3) × 81 × 12 = 27 × 12 = **324 cm³**.\n\n2. La petite pyramide a pour hauteur 4 cm au lieu de 12 cm : k = 4 ÷ 12 = **1/3**. Les longueurs sont multipliées par 1/3 : le côté de la section vaut 9 × 1/3 = **3 cm**.\n\n3. Avec le côté : 3 × 3 = **9 cm²**. Avec k² : 81 × (1/3)² = 81 × 1/9 = **9 cm²**. Les deux résultats concordent : les aires sont multipliées par k².\n\n4. Avec la formule : (1/3) × 9 × 4 = **12 cm³**. Avec k³ : 324 × (1/3)³ = 324 × 1/27 = **12 cm³**. Les volumes sont multipliés par k³. Le volume du morceau restant vaut 324 − 12 = 312 cm³."}$exo$::jsonb),
  ('990b3f90-a500-56fe-8672-24b970637547'::uuid, 1, 'probleme', $exo${"titre":"Agrandir un rectangle","consigne":"Réponds à chaque question en écrivant le calcul effectué.","enonce":"**Questions de cours et d’application.** Un rectangle mesure **4 cm sur 6 cm**. On l’agrandit avec un rapport **k = 2,5**.\n\n1. Calcule les dimensions du rectangle agrandi.\n2. Calcule l’aire de chaque rectangle et vérifie que le rapport des aires est égal à k².\n3. Les angles du rectangle sont-ils modifiés par l’agrandissement ? Justifie.","bareme":[{"critere":"Dimensions agrandies : 4 × 2,5 = 10 cm et 6 × 2,5 = 15 cm","points":6},{"critere":"Aires 24 cm² et 150 cm², rapport 150 ÷ 24 = 6,25 = 2,5²","points":8},{"critere":"Angles conservés : ils restent droits (90°)","points":6}],"dureeMin":7,"corrige":"1. Toutes les longueurs sont multipliées par k = 2,5 : 4 × 2,5 = **10 cm** et 6 × 2,5 = **15 cm**.\n\n2. Aire initiale : 4 × 6 = **24 cm²**. Aire agrandie : 10 × 15 = **150 cm²**. Le rapport des aires vaut 150 ÷ 24 = **6,25**, et k² = 2,5 × 2,5 = 6,25 : les aires sont bien multipliées par k², pas par k.\n\n3. Les angles ne sont **pas modifiés** : un agrandissement conserve la forme, donc les angles gardent la même mesure. Le rectangle agrandi a toujours quatre angles droits."}$exo$::jsonb),
  ('990b3f90-a500-56fe-8672-24b970637547'::uuid, 2, 'probleme', $exo${"titre":"La maquette du phare","consigne":"Réponds à chaque question en détaillant tes calculs et tes conversions.","enonce":"**Situation.** Une maquette d’un phare est construite à l’échelle **1/40**. Le vrai phare mesure **30 m** de haut.\n\n1. Quelle est la hauteur de la maquette, en cm ?\n2. Une vitre de la lanterne mesure **12 cm²** sur la maquette. Quelle est l’aire réelle de cette vitre, en cm² puis en m² ?\n3. Le volume de la lanterne sur la maquette est de **90 cm³**. Quel est son volume réel, en m³ ?","bareme":[{"critere":"Hauteur de la maquette : 3 000 ÷ 40 = 75 cm","points":5},{"critere":"Aire réelle : 12 × 40² = 19 200 cm² = 1,92 m²","points":7},{"critere":"Volume réel : 90 × 40³ = 5 760 000 cm³ = 5,76 m³","points":8}],"dureeMin":10,"corrige":"1. Sur la maquette, les longueurs sont divisées par 40. 30 m = 3 000 cm, et 3 000 ÷ 40 = **75 cm**.\n\n2. La réalité est un agrandissement de rapport k = 40 de la maquette : les aires sont multipliées par k² = 40² = 1 600. Aire réelle = 12 × 1 600 = **19 200 cm²**. Comme 1 m² = 10 000 cm², cela fait **1,92 m²**.\n\n3. Les volumes sont multipliés par k³ = 40³ = 64 000. Volume réel = 90 × 64 000 = 5 760 000 cm³. Comme 1 m³ = 1 000 000 cm³, cela fait **5,76 m³**."}$exo$::jsonb),
  ('990b3f90-a500-56fe-8672-24b970637547'::uuid, 3, 'probleme', $exo${"titre":"La statue et sa figurine","consigne":"Justifie chaque calcul avec le rapport d’agrandissement ou de réduction.","enonce":"**Situation.** Une figurine est une réduction à l’échelle **1/30** d’une statue de **4,5 m** de haut. La figurine est faite de la même matière que la statue et pèse **120 g** ; la statue est pleine. Pour la peindre, il faut couvrir **27 m²** de surface sur la statue.\n\n1. Calcule la hauteur de la figurine, en cm.\n2. Quelle est la surface à peindre sur la figurine, en cm² ?\n3. Quelle est la masse de la statue, en kg ? (La masse est proportionnelle au volume, car la matière est la même.)\n4. Karim affirme : « La statue est 30 fois plus lourde que la figurine, puisque l’échelle est 1/30. » Explique son erreur.","bareme":[{"critere":"Hauteur de la figurine : 450 ÷ 30 = 15 cm","points":4},{"critere":"Surface : 270 000 ÷ 30² = 300 cm²","points":6},{"critere":"Masse : 120 × 30³ = 3 240 000 g = 3 240 kg","points":6},{"critere":"Erreur de Karim : les volumes sont multipliés par 30³ = 27 000, pas par 30","points":4}],"dureeMin":15,"corrige":"1. 4,5 m = 450 cm ; la réduction divise les longueurs par 30 : 450 ÷ 30 = **15 cm**.\n\n2. 27 m² = 270 000 cm². Les aires sont multipliées par k² = 30² = 900 de la figurine à la statue, donc l’aire de la figurine vaut 270 000 ÷ 900 = **300 cm²**.\n\n3. Les volumes sont multipliés par k³ = 30³ = 27 000. La matière étant la même, la masse suit le volume : 120 × 27 000 = 3 240 000 g = **3 240 kg** (3,24 tonnes).\n\n4. Karim confond le rapport des **longueurs** avec celui des **masses**. La masse suit le volume, qui est multiplié par k³ = 27 000, et non par 30. La statue est donc **27 000 fois** plus lourde que la figurine."}$exo$::jsonb),
  ('05b94edf-f4f0-5eb9-8d79-ae92e41e213f'::uuid, 1, 'probleme', $exo${"titre":"Égaux ou semblables ?","consigne":"Justifie chaque réponse avec un cas du cours.","enonce":"**Questions de cours et d’application.**\n\n1. Les triangles ABC et DEF vérifient **AB = DE = 5 cm**, **AC = DF = 6 cm** et **l’angle A = l’angle D = 40°**. Sont-ils égaux ? Quel cas d’égalité utilises-tu ? Que peux-tu dire de BC et EF ?\n2. Cite les trois cas d’égalité des triangles.\n3. Deux triangles ont chacun deux angles de **50°** et de **60°**. Sont-ils semblables ? Quel est leur troisième angle ?","bareme":[{"critere":"Triangles égaux par le cas deux côtés et l’angle compris ; BC = EF","points":7},{"critere":"Trois cas : trois côtés ; deux côtés et l’angle compris ; un côté et deux angles adjacents","points":6},{"critere":"Semblables (deux angles égaux) ; troisième angle 70°","points":7}],"dureeMin":8,"corrige":"1. Les deux triangles ont deux côtés égaux deux à deux et **l’angle compris entre ces côtés** égal : c’est le cas « deux côtés et l’angle compris ». Les triangles ABC et DEF sont donc **égaux**. Leurs côtés restants sont égaux : **BC = EF**.\n\n2. Trois cas d’égalité : **trois côtés** égaux deux à deux ; **deux côtés et l’angle compris** entre eux ; **un côté et les deux angles adjacents**.\n\n3. Deux angles égaux (50° et 60°) suffisent à démontrer que deux triangles sont **semblables**. Le troisième angle vaut 180 − 50 − 60 = **70°** dans chacun des deux triangles."}$exo$::jsonb),
  ('05b94edf-f4f0-5eb9-8d79-ae92e41e213f'::uuid, 2, 'probleme', $exo${"titre":"Deux triangles semblables","consigne":"Réponds à chaque question en justifiant avec le rapport de similitude.","enonce":"**Situation.** Le triangle ABC est rectangle en A, avec **AB = 3 cm, AC = 4 cm et BC = 5 cm**. Le triangle DEF est semblable à ABC, avec les correspondances A↔D, B↔E, C↔F, et **DE = 7,5 cm**.\n\n1. Calcule le rapport de similitude k de ABC à DEF.\n2. Calcule DF et EF.\n3. Calcule l’aire de ABC. En déduire l’aire de DEF avec k², puis vérifie-la avec les longueurs de DEF (rappel : DEF est rectangle en D).","bareme":[{"critere":"Rapport k = DE ÷ AB = 7,5 ÷ 3 = 2,5","points":5},{"critere":"DF = 4 × 2,5 = 10 cm et EF = 5 × 2,5 = 12,5 cm","points":7},{"critere":"Aire ABC = 6 cm², aire DEF = 6 × 6,25 = 37,5 cm², vérifiée par 7,5 × 10 ÷ 2","points":8}],"dureeMin":10,"corrige":"1. Les côtés homologues sont AB et DE : k = DE ÷ AB = 7,5 ÷ 3 = **2,5**.\n\n2. Les longueurs de DEF sont celles de ABC multipliées par 2,5 : DF = 4 × 2,5 = **10 cm** (homologue de AC) et EF = 5 × 2,5 = **12,5 cm** (homologue de BC).\n\n3. ABC est rectangle en A : aire = 3 × 4 ÷ 2 = **6 cm²**. Les aires sont multipliées par k² = 2,5² = 6,25 : aire de DEF = 6 × 6,25 = **37,5 cm²**.\n   Vérification : DEF est rectangle en D, donc son aire est 7,5 × 10 ÷ 2 = 75 ÷ 2 = 37,5 cm². Les deux calculs concordent."}$exo$::jsonb),
  ('05b94edf-f4f0-5eb9-8d79-ae92e41e213f'::uuid, 3, 'probleme', $exo${"titre":"La hauteur de l’arbre","consigne":"Rédige comme dans le cours : hypothèses, conclusion, puis calculs.","enonce":"**Situation.** À midi, un piquet vertical de **1,5 m** projette une ombre de **2 m** sur un sol horizontal. Au même moment, l’ombre d’un arbre mesure **12 m**. Les rayons du soleil sont parallèles. On appelle ABC le triangle formé par le piquet, son ombre et le rayon (rectangle au pied du piquet), et DEF celui formé par l’arbre, son ombre et le rayon (rectangle au pied de l’arbre).\n\n1. Explique pourquoi les triangles ABC et DEF sont semblables (rédige en utilisant le critère des deux angles).\n2. Calcule le rapport de similitude, puis la hauteur de l’arbre.\n3. Calcule l’aire du triangle ABC, puis celle du triangle DEF avec k². Vérifie avec les dimensions de DEF.","bareme":[{"critere":"Justification rédigée : angle droit et angle du rayon du soleil égaux, donc semblables","points":7},{"critere":"Rapport 12 ÷ 2 = 6, hauteur de l’arbre 1,5 × 6 = 9 m","points":6},{"critere":"Aires 1,5 m² et 1,5 × 36 = 54 m², vérifiée par 9 × 12 ÷ 2","points":7}],"dureeMin":15,"corrige":"1. Dans les triangles ABC et DEF : les deux triangles ont un **angle droit** (le piquet et l’arbre sont verticaux, le sol est horizontal), et l’angle formé par le rayon du soleil et le sol est **le même**, car les rayons sont parallèles. Deux angles sont égaux deux à deux, **donc ABC et DEF sont semblables**. Par conséquent leurs côtés homologues sont proportionnels.\n\n2. Rapport de similitude : k = ombre de l’arbre ÷ ombre du piquet = 12 ÷ 2 = **6**. Hauteur de l’arbre = 1,5 × 6 = **9 m**.\n\n3. Aire de ABC : 1,5 × 2 ÷ 2 = **1,5 m²**. Les aires sont multipliées par k² = 36 : aire de DEF = 1,5 × 36 = **54 m²**. Vérification : 9 × 12 ÷ 2 = 108 ÷ 2 = 54 m²."}$exo$::jsonb),
  ('b448aeea-8ff7-59c3-925f-8ed2edb8fa33'::uuid, 1, 'probleme', $exo${"titre":"Calculer une longueur avec Thalès","consigne":"Écris les quotients dans le bon ordre, puis résous par le produit en croix.","enonce":"**Situation.** Dans le triangle ABC, le point M est sur [AB] et le point N est sur [AC], avec **(MN) // (BC)**. On donne **AM = 3 cm, AB = 5 cm, AN = 4,5 cm et MN = 6 cm**.\n\n1. Écris les égalités de quotients données par le théorème de Thalès.\n2. Calcule AC.\n3. Calcule BC.","bareme":[{"critere":"Égalités AM/AB = AN/AC = MN/BC, avec les hypothèses citées","points":6},{"critere":"AC = 4,5 × 5 ÷ 3 = 7,5 cm","points":7},{"critere":"BC = 6 × 5 ÷ 3 = 10 cm","points":7}],"dureeMin":8,"corrige":"1. Les points A, M, B sont alignés, les points A, N, C sont alignés et (MN) // (BC). D’après le théorème de Thalès :\n   **AM/AB = AN/AC = MN/BC**, soit 3/5 = 4,5/AC = 6/BC.\n\n2. 3/5 = 4,5/AC. Produit en croix : AC = 4,5 × 5 ÷ 3 = 22,5 ÷ 3 = **7,5 cm**.\n\n3. 3/5 = 6/BC. Produit en croix : BC = 6 × 5 ÷ 3 = 30 ÷ 3 = **10 cm**.\n\nVérification : 3/5 = 0,6 ; 4,5/7,5 = 0,6 ; 6/10 = 0,6. Les trois quotients sont égaux."}$exo$::jsonb),
  ('b448aeea-8ff7-59c3-925f-8ed2edb8fa33'::uuid, 2, 'probleme', $exo${"titre":"La largeur de la mare","consigne":"Réponds à chaque question en rédigeant avec le théorème de Thalès.","enonce":"**Situation.** Pour mesurer la largeur d’une mare, des élèves plantent un piquet en A. Les points B et C sont sur les deux rives (on ne peut pas mesurer BC). Ils placent M sur la droite (AB) et N sur la droite (AC), de l’autre côté de A (A est entre B et M, et entre C et N), de sorte que **(MN) // (BC)**. Ils mesurent : **AB = 15 m, AM = 6 m, AN = 8 m et MN = 9 m**.\n\n1. Comment appelle-t-on cette configuration ? Quelles hypothèses permettent d’appliquer Thalès ?\n2. Écris les égalités de quotients.\n3. Calcule AC.\n4. Calcule la largeur BC de la mare.","bareme":[{"critere":"Configuration papillon, hypothèses : alignements et (MN) // (BC)","points":5},{"critere":"Égalités AM/AB = AN/AC = MN/BC, sommet A en tête de chaque quotient","points":5},{"critere":"AC = 8 × 15 ÷ 6 = 20 m","points":4},{"critere":"BC = 9 × 15 ÷ 6 = 22,5 m","points":6}],"dureeMin":10,"corrige":"1. Les points M et N sont de part et d’autre du sommet A : c’est la configuration **papillon**. Hypothèses : A, B, M sont alignés, A, C, N sont alignés et (MN) // (BC).\n\n2. D’après le théorème de Thalès : **AM/AB = AN/AC = MN/BC**, soit 6/15 = 8/AC = 9/BC.\n\n3. 6/15 = 8/AC, donc AC = 8 × 15 ÷ 6 = 120 ÷ 6 = **20 m**.\n\n4. 6/15 = 9/BC, donc BC = 9 × 15 ÷ 6 = 135 ÷ 6 = **22,5 m**.\n\nLa mare mesure donc 22,5 m de large. Vérification : 6/15 = 0,4 ; 8/20 = 0,4 ; 9/22,5 = 0,4."}$exo$::jsonb),
  ('b448aeea-8ff7-59c3-925f-8ed2edb8fa33'::uuid, 3, 'probleme', $exo${"titre":"Parallèles ou non ? La réciproque en action","consigne":"Rédige chaque démonstration : quotients calculés, comparés, puis conclusion.","enonce":"**Situation.** Dans un triangle ABC, M est sur [AB] et N est sur [AC].\n\n**Cas 1.** AM = 3 cm, AB = 5 cm, AN = 4,5 cm, AC = 7,5 cm.\n**Cas 2.** AM = 4 cm, AB = 6 cm, AN = 5 cm, AC = 8 cm.\n\n1. Dans le cas 1, les droites (MN) et (BC) sont-elles parallèles ? Justifie.\n2. Dans le cas 2, les droites (MN) et (BC) sont-elles parallèles ? Justifie.\n3. Dans le cas 1, on sait que BC = 9 cm. Calcule MN.\n4. Dans le cas 1, l’aire du triangle ABC est de 40 cm². Calcule l’aire du triangle AMN.","bareme":[{"critere":"Cas 1 : 3/5 = 0,6 = 4,5/7,5, alignements dans le même ordre, donc parallèles","points":6},{"critere":"Cas 2 : 4/6 ≈ 0,667 et 5/8 = 0,625, différents, donc non parallèles","points":6},{"critere":"MN = 0,6 × 9 = 5,4 cm","points":4},{"critere":"Aire AMN = 40 × 0,6² = 14,4 cm²","points":4}],"dureeMin":15,"corrige":"1. Les points A, M, B d’une part, A, N, C d’autre part sont alignés dans le même ordre. On compare AM/AB = 3/5 = 0,6 et AN/AC = 4,5/7,5 = 0,6. Les deux quotients sont égaux : d’après la **réciproque du théorème de Thalès**, **(MN) // (BC)**.\n\n2. On compare AM/AB = 4/6 = 2/3 ≈ 0,667 et AN/AC = 5/8 = 0,625. Les deux quotients sont **différents** : si (MN) était parallèle à (BC), Thalès donnerait l’égalité. Donc **(MN) n’est pas parallèle à (BC)**.\n\n3. Dans le cas 1, (MN) // (BC), donc MN/BC = 3/5 = 0,6. Alors MN = 0,6 × 9 = **5,4 cm**.\n\n4. Le triangle AMN est une réduction du triangle ABC de rapport k = 3/5 = 0,6. Les aires sont multipliées par k² = 0,36 : aire de AMN = 40 × 0,36 = **14,4 cm²**."}$exo$::jsonb),
  ('5fb4a98f-4599-5332-9d79-41375f4de191'::uuid, 1, 'probleme', $exo${"titre":"Pythagore et un cosinus","consigne":"Écris la formule ou la propriété utilisée avant chaque calcul.","enonce":"**Questions de cours et d’application.**\n\n1. Le triangle ABC est rectangle en A, avec **AB = 6 cm** et **AC = 8 cm**. Calcule BC.\n2. Le triangle DEF est rectangle en D, avec **EF = 13 cm** et **DE = 5 cm**. Calcule DF.\n3. Dans le triangle ABC de la question 1, calcule le cosinus de l’angle ABC, puis donne l’angle arrondi au degré.","bareme":[{"critere":"BC² = 36 + 64 = 100, donc BC = 10 cm","points":7},{"critere":"DF² = 169 − 25 = 144, donc DF = 12 cm (on soustrait)","points":7},{"critere":"cos(ABC) = 6/10 = 0,6, angle ≈ 53°","points":6}],"dureeMin":8,"corrige":"1. ABC est rectangle en A : BC est l’hypoténuse. BC² = AB² + AC² = 36 + 64 = 100, donc BC = **10 cm**.\n\n2. DEF est rectangle en D : EF est l’hypoténuse. On cherche un côté de l’angle droit, donc on soustrait : DF² = EF² − DE² = 169 − 25 = 144, donc DF = **12 cm**.\n\n3. cos(ABC) = côté adjacent ÷ hypoténuse = AB ÷ BC = 6 ÷ 10 = **0,6**. Avec la calculatrice en degrés : cos⁻¹(0,6) ≈ 53,13°, soit environ **53°**."}$exo$::jsonb),
  ('5fb4a98f-4599-5332-9d79-41375f4de191'::uuid, 2, 'probleme', $exo${"titre":"L’échelle contre le mur","consigne":"Réponds à chaque question en détaillant tes calculs (calculatrice en degrés).","enonce":"**Situation.** Une échelle de **5 m** est posée contre un mur vertical, sur un sol horizontal. Son pied est à **1,4 m** du mur.\n\n1. À quelle hauteur du mur l’échelle arrive-t-elle ?\n2. Calcule l’angle que fait l’échelle avec le sol, arrondi au degré.\n3. Pour être stable, l’échelle doit faire avec le sol un angle compris entre 65° et 75°. L’échelle est-elle bien posée ?","bareme":[{"critere":"Hauteur : √(25 − 1,96) = √23,04 = 4,8 m, en soustrayant les carrés","points":7},{"critere":"cos(angle) = 1,4 ÷ 5 = 0,28, angle ≈ 74°","points":8},{"critere":"Conclusion : 74° est compris entre 65° et 75°, l’échelle est bien posée","points":5}],"dureeMin":10,"corrige":"1. Le mur, le sol et l’échelle forment un triangle rectangle où l’échelle est l’**hypoténuse** (5 m). Hauteur² = 5² − 1,4² = 25 − 1,96 = 23,04, donc hauteur = √23,04 = **4,8 m**.\n\n2. Dans ce triangle, le côté adjacent à l’angle au sol est la distance au mur (1,4 m) : cos(angle) = 1,4 ÷ 5 = 0,28. Avec la calculatrice : cos⁻¹(0,28) ≈ 73,7°, soit environ **74°**.\n\n3. 65° < 74° < 75° : l’échelle est **bien posée**."}$exo$::jsonb),
  ('5fb4a98f-4599-5332-9d79-41375f4de191'::uuid, 3, 'probleme', $exo${"titre":"Un terrain rectangle ?","consigne":"Rédige chaque démonstration avec la réciproque ou la contraposée, puis calcule les angles.","enonce":"**Situation.** Deux terrains triangulaires sont dessinés sur un plan.\n\n**Terrain 1 :** ABC avec AB = 9 m, AC = 12 m et BC = 15 m.\n**Terrain 2 :** DEF avec DE = 5 m, DF = 7 m et EF = 9 m.\n\n1. Le terrain 1 est-il rectangle ? Si oui, en quel sommet ?\n2. Le terrain 2 est-il rectangle ? Justifie.\n3. Pour le terrain 1, calcule le cosinus de l’angle B, puis les angles B et C arrondis au degré.\n4. Un élève écrit : « cos C = 15 ÷ 12 = 1,25 ». Explique son erreur et donne la bonne valeur de cos C.","bareme":[{"critere":"Terrain 1 rectangle en A : 81 + 144 = 225 = 15², par la réciproque","points":6},{"critere":"Terrain 2 non rectangle : 25 + 49 = 74 différent de 81, contraposée","points":5},{"critere":"cos B = 9/15 = 0,6, B ≈ 53° et C ≈ 37°","points":5},{"critere":"Erreur : l’hypoténuse doit être au dénominateur ; cos C = 12/15 = 0,8","points":4}],"dureeMin":15,"corrige":"1. Le plus grand côté est BC = 15 m. BC² = 225 et AB² + AC² = 81 + 144 = 225. Les deux sont égaux : d’après la **réciproque du théorème de Pythagore**, ABC est **rectangle en A** (angle droit opposé au plus grand côté).\n\n2. Le plus grand côté est EF = 9 m. EF² = 81 et DE² + DF² = 25 + 49 = 74. Comme 81 ≠ 74, d’après la **contraposée** du théorème de Pythagore, DEF **n’est pas rectangle**.\n\n3. cos B = côté adjacent ÷ hypoténuse = AB ÷ BC = 9 ÷ 15 = **0,6**, donc B ≈ 53° (cos⁻¹(0,6) ≈ 53,13°). Comme le triangle est rectangle en A, C = 90 − 53 = **37°**.\n\n4. L’élève a inversé le quotient : le cosinus est le côté adjacent **divisé par l’hypoténuse**, et l’hypoténuse (15) va au dénominateur. Un cosinus d’angle aigu est toujours compris entre 0 et 1 : 1,25 est un signal d’erreur. Pour l’angle C, le côté adjacent est AC : cos C = 12 ÷ 15 = **0,8**, donc C ≈ 37°, ce qui confirme la question 3."}$exo$::jsonb),
  ('85198058-0dfe-5d69-9c6b-468913a7d6a0'::uuid, 1, 'probleme', $exo${"titre":"Propriétés d’un parallélogramme","consigne":"Réponds à chaque question en citant la propriété utilisée.","enonce":"**Questions de cours et d’application.** ABCD est un parallélogramme de centre O (O est le point d’intersection de ses diagonales). On donne **AB = 7 cm, AD = 4 cm, l’angle A = 70°, AC = 10 cm et BD = 8 cm**.\n\n1. Donne les longueurs CD et BC, et la mesure de l’angle C.\n2. Donne les longueurs OA et OB.\n3. Quel est le centre de symétrie de ABCD ? Combien a-t-il d’axes de symétrie ?","bareme":[{"critere":"CD = 7 cm, BC = 4 cm, angle C = 70° (côtés et angles opposés égaux)","points":7},{"critere":"OA = 5 cm et OB = 4 cm (les diagonales se coupent en leur milieu)","points":7},{"critere":"Centre de symétrie : O ; aucun axe de symétrie","points":6}],"dureeMin":7,"corrige":"1. Dans un parallélogramme, les côtés opposés ont la même longueur : **CD = AB = 7 cm** et **BC = AD = 4 cm**. Les angles opposés sont égaux : **angle C = angle A = 70°**.\n\n2. Les diagonales d’un parallélogramme se coupent en leur milieu : OA = AC ÷ 2 = 10 ÷ 2 = **5 cm** et OB = BD ÷ 2 = 8 ÷ 2 = **4 cm**.\n\n3. Le centre de symétrie est le point d’intersection des diagonales : **O**. Un parallélogramme quelconque n’a **aucun axe de symétrie**."}$exo$::jsonb),
  ('85198058-0dfe-5d69-9c6b-468913a7d6a0'::uuid, 2, 'probleme', $exo${"titre":"Rectangle, losange ou carré ?","consigne":"Pour chaque quadrilatère, écris une phrase de démonstration comme dans le cours.","enonce":"**Situation.** Trois quadrilatères sont tracés sur un plan. Dans chacun, les diagonales se coupent **en leur milieu**.\n\n- **EFGH** : ses diagonales mesurent toutes les deux 12 cm.\n- **IJKL** : ses diagonales sont perpendiculaires.\n- **MNPQ** : ses diagonales mesurent toutes les deux 10 cm et sont perpendiculaires.\n\n1. Quelle est la nature de EFGH ? Rédige la démonstration.\n2. Quelle est la nature de IJKL ? Rédige la démonstration.\n3. Quelle est la nature de MNPQ ? Rédige la démonstration.\n4. Donne le nombre d’axes de symétrie de chacun de ces trois quadrilatères.","bareme":[{"critere":"EFGH est un rectangle : diagonales de même milieu et de même longueur","points":5},{"critere":"IJKL est un losange : diagonales de même milieu et perpendiculaires","points":5},{"critere":"MNPQ est un carré : diagonales de même milieu, égales et perpendiculaires","points":5},{"critere":"Axes de symétrie : rectangle 2, losange 2, carré 4","points":5}],"dureeMin":10,"corrige":"1. « Les diagonales de EFGH se coupent en leur milieu, donc EFGH est un parallélogramme. Ses diagonales ont la même longueur, **donc EFGH est un rectangle**. »\n\n2. « Les diagonales de IJKL se coupent en leur milieu, donc IJKL est un parallélogramme. Ses diagonales sont perpendiculaires, **donc IJKL est un losange**. »\n\n3. « Les diagonales de MNPQ se coupent en leur milieu, sont de même longueur et sont perpendiculaires : MNPQ est à la fois un rectangle et un losange, **donc MNPQ est un carré**. »\n\n4. Un rectangle a **2 axes** de symétrie, un losange **2 axes**, un carré **4 axes** (rappel : un parallélogramme quelconque n’en a aucun)."}$exo$::jsonb),
  ('85198058-0dfe-5d69-9c6b-468913a7d6a0'::uuid, 3, 'probleme', $exo${"titre":"Le losange ABCD","consigne":"Rédige chaque réponse avec la propriété du cours, puis calcule.","enonce":"**Situation.** ABCD est un parallélogramme dont deux côtés consécutifs sont égaux : **AB = BC = 5 cm**. Ses diagonales se coupent en O, avec **AC = 6 cm** et **BD = 8 cm**. Les diagonales sont perpendiculaires.\n\n1. Quelle est la nature de ABCD ? Justifie. Que valent alors AD et CD ?\n2. Donne les longueurs OA et OB. ABCD est-il un carré ? Justifie.\n3. Combien ABCD a-t-il d’axes de symétrie ? Quel est son centre de symétrie ?\n4. Le losange est découpé par ses diagonales en quatre triangles rectangles superposables. Calcule l’aire d’un de ces triangles (rectangle en O), puis l’aire de ABCD.","bareme":[{"critere":"Losange : parallélogramme avec deux côtés consécutifs égaux ; AD = CD = 5 cm","points":5},{"critere":"OA = 3 cm, OB = 4 cm ; pas un carré car les diagonales 6 et 8 sont différentes","points":5},{"critere":"Deux axes de symétrie, centre de symétrie O","points":4},{"critere":"Triangle AOB : 3 × 4 ÷ 2 = 6 cm² ; aire du losange 4 × 6 = 24 cm²","points":6}],"dureeMin":15,"corrige":"1. ABCD est un parallélogramme qui a deux côtés consécutifs de même longueur (AB = BC) : **c’est un losange**. Ses quatre côtés sont égaux, donc **AD = CD = 5 cm**.\n\n2. Les diagonales se coupent en leur milieu : OA = 6 ÷ 2 = **3 cm** et OB = 8 ÷ 2 = **4 cm**. ABCD n’est **pas un carré** : un carré a des diagonales de même longueur, or AC = 6 cm et BD = 8 cm sont différentes (le losange n’est pas un rectangle).\n\n3. Un losange a **2 axes de symétrie** (ses diagonales) ; son centre de symétrie est **O**, intersection des diagonales.\n\n4. Le triangle AOB est rectangle en O, avec OA = 3 cm et OB = 4 cm : aire = 3 × 4 ÷ 2 = **6 cm²**. Les quatre triangles étant superposables, l’aire de ABCD = 4 × 6 = **24 cm²**."}$exo$::jsonb),
  ('bbbcbbfa-efdd-5760-97fa-fd6d4c720ac2'::uuid, 1, 'probleme', $exo${"titre":"Le triangle qui glisse","consigne":"Réponds à chaque question en justifiant avec le cours.","enonce":"**Situation.** Le triangle ABC a pour dimensions AB = 6 cm, BC = 4 cm, un angle ABC de 35° et une aire de 9 cm². On le fait glisser par la translation qui transforme A en D. Le triangle obtenu est DEF (B devient E et C devient F).\n\n1. Quelles informations définissent une translation ?\n2. Donne, sans les mesurer, les longueurs DE et EF, l'angle DEF et l'aire du triangle DEF. Justifie.\n3. Quelle est la nature du quadrilatère ABED ? Le triangle DEF est-il « retourné » par rapport à ABC ?","bareme":[{"critere":"Une direction, un sens et une longueur (une flèche) citées","points":6},{"critere":"DE = 6 cm, EF = 4 cm, angle 35° et aire 9 cm², avec la conservation justifiée","points":8},{"critere":"ABED est un parallélogramme ; pas de retournement, l’orientation est conservée","points":6}],"dureeMin":7,"corrige":"1. Une translation est définie par **une direction, un sens et une longueur**, c’est-à-dire par une flèche (par exemple de A vers D).\n\n2. Une translation conserve les longueurs, les angles et les aires :\n   - DE = AB = **6 cm** et EF = BC = **4 cm** ;\n   - l’angle DEF = l’angle ABC = **35°** ;\n   - l’aire de DEF = l’aire de ABC = **9 cm²**.\n\n3. Comme E est l’image de B et D l’image de A, les segments [AD] et [BE] sont parallèles, de même sens et de même longueur : **ABED est un parallélogramme**.\n   Le triangle DEF n’est pas retourné : la translation conserve l’orientation (contrairement à une symétrie axiale). On peut superposer les deux triangles en les faisant seulement glisser."}$exo$::jsonb),
  ('bbbcbbfa-efdd-5760-97fa-fd6d4c720ac2'::uuid, 2, 'probleme', $exo${"titre":"Un déplacement sur le quadrillage","consigne":"Rédige tes réponses en indiquant les coordonnées obtenues.","enonce":"**Situation.** Dans un repère, on place les points A(1 ; 1) et B(4 ; 5). On considère la translation qui transforme A en B. On donne aussi M(2 ; 3) et N(−1 ; 0).\n\n1. De combien de carreaux se déplace-t-on vers la droite et vers le haut pour aller de A à B ?\n2. Donne les coordonnées de M′ et N′, images de M et N par cette translation.\n3. Quelle est la nature de ABM′M ? Calcule la longueur MM′ sachant que AB = 5 unités.\n4. Le point I est le milieu de [MN]. Donne ses coordonnées, puis celles de son image I′. Que constates-tu pour le milieu de [M′N′] ?","bareme":[{"critere":"Déplacement de 3 vers la droite et 4 vers le haut lu correctement","points":4},{"critere":"M′(5 ; 7) et N′(2 ; 4) obtenus en appliquant le même déplacement","points":6},{"critere":"ABM′M parallélogramme et MM′ = AB = 5 unités","points":5},{"critere":"I(0,5 ; 1,5), I′(3,5 ; 5,5) et lien avec le milieu de [M′N′]","points":5}],"dureeMin":10,"corrige":"1. De A(1 ; 1) à B(4 ; 5) : 4 − 1 = 3 vers la droite et 5 − 1 = 4 vers le haut.\n\n2. On applique ce déplacement (+3 ; +4) :\n   - M′ : (2 + 3 ; 3 + 4) = **(5 ; 7)** ;\n   - N′ : (−1 + 3 ; 0 + 4) = **(2 ; 4)**.\n\n3. M′ est l’image de M par la translation qui transforme A en B : **ABM′M est un parallélogramme**. Ses côtés opposés [AB] et [MM′] ont la même longueur : **MM′ = AB = 5 unités**.\n\n4. I est le milieu de [MN] : I((2 + (−1))/2 ; (3 + 0)/2) = **(0,5 ; 1,5)**. Son image : I′ = (0,5 + 3 ; 1,5 + 4) = **(3,5 ; 5,5)**.\n   Le milieu de [M′N′] est ((5 + 2)/2 ; (7 + 4)/2) = (3,5 ; 5,5) : c’est I′. La translation **conserve les milieux**."}$exo$::jsonb),
  ('bbbcbbfa-efdd-5760-97fa-fd6d4c720ac2'::uuid, 3, 'probleme', $exo${"titre":"Deux glissements à la suite","consigne":"Justifie chaque résultat par un calcul ou par une propriété du cours.","enonce":"**Situation.** Dans un repère, la translation t₁ déplace chaque point de 3 vers la droite et de 1 vers le haut. La translation t₂ déplace chaque point de 1 vers la gauche et de 2 vers le haut. On applique d’abord t₁, puis t₂. On donne M(1 ; 2) et le triangle ABC avec A(0 ; 0), B(2 ; 0) et C(0 ; 3).\n\n1. Donne l’image M₁ de M par t₁, puis l’image M₂ de M₁ par t₂.\n2. Par quelle translation unique peut-on remplacer t₁ suivie de t₂ ? Vérifie avec M.\n3. Donne les coordonnées de A″, B″, C″, images de A, B, C par t₁ puis t₂, et l’aire du triangle A″B″C″.\n4. Explique pourquoi A″B″C″ se superpose à ABC sans retourner la figure.","bareme":[{"critere":"M₁(4 ; 3) et M₂(3 ; 5) obtenus étape par étape","points":5},{"critere":"Translation unique de 2 vers la droite et 3 vers le haut, vérifiée avec M","points":5},{"critere":"A″(2 ; 3), B″(4 ; 3), C″(2 ; 6) et aire 3 (base 2, hauteur 3)","points":6},{"critere":"Justification : conservation des longueurs, des angles et de l’orientation","points":4}],"dureeMin":14,"corrige":"1. M₁ = (1 + 3 ; 2 + 1) = **(4 ; 3)**. M₂ = (4 − 1 ; 3 + 2) = **(3 ; 5)**.\n\n2. Deux translations successives équivalent à une seule dont les déplacements s’ajoutent : (+3 − 1 ; +1 + 2) = **(+2 ; +3)**, soit 2 vers la droite et 3 vers le haut.\n   Vérification : M(1 ; 2) devient (1 + 2 ; 2 + 3) = (3 ; 5) = M₂. ✓\n\n3. On ajoute (+2 ; +3) à chaque point :\n   - A″(2 ; 3), B″(4 ; 3), C″(2 ; 6).\n   Le triangle ABC a une base AB = 2 et une hauteur AC = 3 (angle droit en A) : aire = 2 × 3 ÷ 2 = 3. Une translation conserve les aires : l’aire de A″B″C″ vaut **3**. (Base A″B″ = 2, hauteur A″C″ = 3, on retrouve 3.)\n\n4. Le résultat est une translation : elle conserve les longueurs et les angles, et elle **conserve l’orientation**. La figure est seulement déplacée, jamais retournée, donc on peut la superposer à ABC en la faisant glisser."}$exo$::jsonb),
  ('805434a4-e66b-59e7-9f49-6ca5ab6b24ac'::uuid, 1, 'probleme', $exo${"titre":"Produit ou quotient ?","consigne":"Pour chaque grandeur, écris le calcul, le résultat et son unité.","enonce":"**Questions de cours et d’application.**\n\n1. Pour chacune de ces situations, dis si la grandeur est un **produit** ou un **quotient**, écris le calcul et le résultat avec son unité :\n   a. l’aire d’un rectangle de 8 m sur 5 m ;\n   b. la vitesse d’une voiture qui parcourt 150 km en 2 h ;\n   c. la masse volumique d’un objet de 240 g qui occupe 30 cm³.\n2. Une plaque chauffante de 2 kW fonctionne pendant 3 h. Quelle énergie consomme-t-elle ? Est-ce un produit ou un quotient ?","bareme":[{"critere":"Les trois grandeurs identifiées et calculées : 40 m², 75 km/h, 8 g/cm³, unités justes","points":12},{"critere":"Énergie = 2 × 3 = 6 kWh, reconnue comme un produit","points":8}],"dureeMin":6,"corrige":"1. a. Aire : **produit** (longueur × largeur) = 8 × 5 = **40 m²**.\n   b. Vitesse : **quotient** (distance ÷ durée) = 150 ÷ 2 = **75 km/h**.\n   c. Masse volumique : **quotient** (masse ÷ volume) = 240 ÷ 30 = **8 g/cm³**.\n\n2. L’énergie est un **produit** : puissance × durée = 2 kW × 3 h = **6 kWh**.\n\nAstuce : l’unité donne l’opération. « m² » et « kWh » viennent d’une multiplication ; « km/h » et « g/cm³ » viennent d’une division."}$exo$::jsonb),
  ('805434a4-e66b-59e7-9f49-6ca5ab6b24ac'::uuid, 2, 'probleme', $exo${"titre":"Au marché et dans les communes","consigne":"Écris chaque calcul, puis une phrase-réponse avec l’unité.","enonce":"**Situation.**\n- Un maraîcher vend 3,6 kg de pommes pour 9 €.\n- Une piscine gonflable de 900 L se remplit avec un robinet dont le débit est de 15 L/min.\n- La commune A compte 12 000 habitants sur 40 km². La commune B compte 9 000 habitants sur 25 km².\n\n1. Calcule le prix au kilo des pommes.\n2. Calcule la durée nécessaire pour remplir la piscine, en minutes puis en heures.\n3. Calcule la densité de population de chaque commune. Laquelle est la plus dense ?","bareme":[{"critere":"Prix au kilo : 9 ÷ 3,6 = 2,50 €/kg avec la bonne unité","points":5},{"critere":"Durée : 900 ÷ 15 = 60 min, soit 1 h","points":5},{"critere":"Densités : 300 hab/km² pour A et 360 hab/km² pour B","points":6},{"critere":"Conclusion : B est plus dense, et phrases-réponses avec unités","points":4}],"dureeMin":9,"corrige":"1. Prix au kilo = prix ÷ masse = 9 ÷ 3,6 = **2,50 €/kg**.\n\n2. Durée = volume ÷ débit = 900 ÷ 15 = **60 min**, soit **1 h**.\n\n3. Densité = habitants ÷ superficie :\n   - commune A : 12 000 ÷ 40 = **300 hab/km²** ;\n   - commune B : 9 000 ÷ 25 = **360 hab/km²**.\n   La commune B est **plus dense**, bien qu’elle ait moins d’habitants : elle est plus petite.\n\nChaque résultat est un quotient : son unité (€/kg, min, hab/km²) montre qu’on a bien divisé."}$exo$::jsonb),
  ('805434a4-e66b-59e7-9f49-6ca5ab6b24ac'::uuid, 3, 'probleme', $exo${"titre":"Ampoule classique ou LED","consigne":"Justifie les conversions d’unités et rédige une conclusion.","enonce":"**Situation.** Une ampoule classique de 60 W reste allumée 5 h par jour pendant 30 jours. Une ampoule LED de 10 W éclaire autant et reste allumée le même temps. Le prix de l’électricité est de 0,20 € le kWh. Rappel : 1 kW = 1 000 W.\n\n1. Convertis 60 W et 10 W en kW.\n2. Calcule l’énergie consommée en 30 jours par chaque ampoule, en kWh. Précise si c’est un produit ou un quotient.\n3. Calcule le coût de chaque ampoule pour ces 30 jours.\n4. Un cube d’aluminium a une arête de 5 cm et une masse de 337,5 g. Calcule son volume, puis sa masse volumique.","bareme":[{"critere":"Conversions 0,06 kW et 0,01 kW justifiées (÷ 1 000)","points":4},{"critere":"Énergies 9 kWh et 1,5 kWh, avec durée totale 150 h et mention d’un produit","points":6},{"critere":"Coûts 1,80 € et 0,30 €, économie de 1,50 €","points":4},{"critere":"Volume 125 cm³ et masse volumique 2,7 g/cm³ (quotient)","points":6}],"dureeMin":14,"corrige":"1. 60 W = 60 ÷ 1 000 = **0,06 kW** ; 10 W = **0,01 kW**.\n\n2. Durée totale : 5 h × 30 = 150 h. L’énergie est un **produit** (puissance × durée) :\n   - ampoule classique : 0,06 × 150 = **9 kWh** ;\n   - LED : 0,01 × 150 = **1,5 kWh**.\n\n3. Coût = énergie × prix du kWh :\n   - classique : 9 × 0,20 = **1,80 €** ;\n   - LED : 1,5 × 0,20 = **0,30 €**.\n   La LED fait économiser 1,80 − 0,30 = **1,50 €** en 30 jours.\n\n4. Volume du cube = 5 × 5 × 5 = **125 cm³** (produit de trois longueurs).\n   Masse volumique = masse ÷ volume = 337,5 ÷ 125 = **2,7 g/cm³** (quotient)."}$exo$::jsonb),
  ('141cd0b9-b54b-52da-8d7f-450f4cefa8cf'::uuid, 1, 'probleme', $exo${"titre":"La sortie à vélo de Malik","consigne":"Écris la formule utilisée et le calcul.","enonce":"**Questions.**\n\n1. Malik parcourt 45 km en 1 h 30 min. Calcule sa vitesse moyenne en km/h.\n2. Convertis 54 km/h en m/s.\n3. Écris 2 h 15 min en heures sous forme décimale.","bareme":[{"critere":"Vitesse moyenne : 1 h 30 = 1,5 h puis 45 ÷ 1,5 = 30 km/h","points":8},{"critere":"54 ÷ 3,6 = 15 m/s","points":6},{"critere":"2 h 15 min = 2,25 h (15 min = 0,25 h)","points":6}],"dureeMin":6,"corrige":"1. 1 h 30 min = 1,5 h (et non 1,30 h). v = d ÷ t = 45 ÷ 1,5 = **30 km/h**.\n\n2. Pour passer de km/h à m/s, on divise par 3,6 : 54 ÷ 3,6 = **15 m/s**.\n\n3. 15 min = 15/60 h = 0,25 h, donc 2 h 15 min = **2,25 h**.\n   Les durées ne sont pas décimales : on ne peut pas écrire 2,15 h."}$exo$::jsonb),
  ('141cd0b9-b54b-52da-8d7f-450f4cefa8cf'::uuid, 2, 'probleme', $exo${"titre":"Train, robinet et voiture","consigne":"Convertis les données si nécessaire et écris chaque calcul.","enonce":"**Situation.**\n- Un train roule à 84 km/h sur 210 km.\n- Un robinet de 9 L/min remplit un bac de 135 L.\n- Une voiture consomme 6 L/100 km. Elle fait un trajet de 250 km. L’essence coûte 1,80 € le litre.\n\n1. Quelle est la durée du trajet du train, en heures puis en heures et minutes ?\n2. Combien de temps faut-il pour remplir le bac ?\n3. Quelle quantité d’essence la voiture consomme-t-elle ? Quel est le coût du carburant ?","bareme":[{"critere":"Durée du train : 210 ÷ 84 = 2,5 h","points":5},{"critere":"Conversion 2,5 h = 2 h 30 min","points":3},{"critere":"Remplissage : 135 ÷ 9 = 15 min","points":5},{"critere":"Consommation 6 × 2,5 = 15 L et coût 15 × 1,80 = 27 €","points":7}],"dureeMin":10,"corrige":"1. t = d ÷ v = 210 ÷ 84 = **2,5 h**. Comme 0,5 h = 30 min, la durée est **2 h 30 min**.\n\n2. Durée = volume ÷ débit = 135 ÷ 9 = **15 min**.\n\n3. 250 km = 2,5 fois 100 km. Consommation : 6 × 2,5 = **15 L**.\n   Coût : 15 × 1,80 = **27 €**.\n\nVérification de l’ordre de grandeur : un train à 84 km/h met un peu plus de 2 h pour 210 km, un débit de 9 L/min remplit un bac de 135 L en un quart d’heure : les résultats sont vraisemblables."}$exo$::jsonb),
  ('141cd0b9-b54b-52da-8d7f-450f4cefa8cf'::uuid, 3, 'probleme', $exo${"titre":"L’aller-retour du cycliste","consigne":"Détaille chaque étape, sans oublier les unités.","enonce":"**Situation.** Un cycliste va de la ville A à la ville B, distantes de 30 km, à la vitesse moyenne de 15 km/h. Il revient de B à A par le même chemin, à la vitesse moyenne de 10 km/h.\n\n1. Calcule la durée de l’aller et la durée du retour.\n2. Calcule la vitesse moyenne du cycliste sur l’ensemble de l’aller-retour.\n3. Louis affirme : « la vitesse moyenne est (15 + 10) ÷ 2 = 12,5 km/h ». Explique pourquoi c’est faux.\n4. Convertis la vitesse moyenne de l’aller-retour en m/s (arrondie au dixième).","bareme":[{"critere":"Durées : aller 30 ÷ 15 = 2 h, retour 30 ÷ 10 = 3 h","points":4},{"critere":"Distance totale 60 km, durée totale 5 h, vitesse moyenne 12 km/h","points":6},{"critere":"Explication : il faut repasser par distance totale et durée totale ; les durées ne sont pas égales","points":6},{"critere":"12 ÷ 3,6 ≈ 3,3 m/s","points":4}],"dureeMin":14,"corrige":"1. Aller : 30 ÷ 15 = **2 h**. Retour : 30 ÷ 10 = **3 h**.\n\n2. Distance totale : 30 + 30 = 60 km. Durée totale : 2 + 3 = 5 h.\n   Vitesse moyenne = 60 ÷ 5 = **12 km/h**.\n\n3. La vitesse moyenne d’un aller-retour n’est pas la moyenne des deux vitesses : le cycliste passe **plus de temps** à rouler à 10 km/h (3 h) qu’à 15 km/h (2 h). Il faut toujours calculer distance totale ÷ durée totale. Louis trouve 12,5 km/h, ce qui est trop grand.\n\n4. 12 km/h ÷ 3,6 = 3,33… soit environ **3,3 m/s**."}$exo$::jsonb),
  ('bbc8df26-d175-58d1-affb-8efd8a429819'::uuid, 1, 'probleme', $exo${"titre":"Signes et produits","consigne":"Indique le signe, puis le résultat.","enonce":"**Questions.**\n\n1. Calcule : (−6) × (+7) et (−8) × (−9).\n2. Calcule : (+56) ÷ (−8) et (−48) ÷ (−6).\n3. Calcule (−1) × (−5) × (−2) et explique le signe du résultat.","bareme":[{"critere":"(−6) × (+7) = −42 et (−8) × (−9) = +72","points":6},{"critere":"(+56) ÷ (−8) = −7 et (−48) ÷ (−6) = +8","points":6},{"critere":"Produit = −10, avec trois facteurs négatifs (nombre impair) donc résultat négatif","points":8}],"dureeMin":6,"corrige":"1. (−6) × (+7) : signes contraires, résultat négatif, 6 × 7 = 42, donc **−42**.\n   (−8) × (−9) : signes identiques, résultat positif, donc **+72**.\n\n2. (+56) ÷ (−8) : signes contraires, donc **−7**.\n   (−48) ÷ (−6) : signes identiques, donc **+8**.\n\n3. (−1) × (−5) × (−2) : il y a **trois** facteurs négatifs, un nombre impair, donc le produit est négatif. 1 × 5 × 2 = 10, donc **−10**."}$exo$::jsonb),
  ('bbc8df26-d175-58d1-affb-8efd8a429819'::uuid, 2, 'probleme', $exo${"titre":"Le congélateur qui refroidit","consigne":"Écris chaque calcul avec ses signes.","enonce":"**Situation.** La température T (en °C) d’un congélateur qui refroidit est donnée par la formule T = 5 + (−3) × t, où t est le temps en heures. Le temps t = 0 correspond à l’instant présent ; t = 4 signifie « dans 4 heures » et t = −2 signifie « il y a 2 heures ».\n\n1. Calcule la température dans 4 heures.\n2. Calcule la température il y a 2 heures, puis il y a 1 heure.\n3. Un élève écrit (−3) × (−2) = −6. Corrige son erreur et explique la règle des signes utilisée.\n4. Le congélateur refroidit de 3 °C par heure. De combien de degrés a-t-il refroidi en 4 h ? Écris ce calcul avec des nombres relatifs.","bareme":[{"critere":"T(4) = 5 + (−3) × 4 = 5 − 12 = −7 °C","points":5},{"critere":"T(−2) = 5 + 6 = 11 °C et T(−1) = 5 + 3 = 8 °C","points":5},{"critere":"(−3) × (−2) = +6, avec la règle « deux signes identiques donnent un produit positif »","points":5},{"critere":"Variation (−3) × 4 = −12 °C, refroidissement de 12 °C","points":5}],"dureeMin":10,"corrige":"1. Pour t = 4 : T = 5 + (−3) × 4 = 5 + (−12) = **−7 °C**.\n\n2. Pour t = −2 : T = 5 + (−3) × (−2) = 5 + 6 = **11 °C** (produit de deux nombres négatifs : positif).\n   Pour t = −1 : T = 5 + (−3) × (−1) = 5 + 3 = **8 °C**.\n   Vérification : la température baisse au fil du temps, donc elle était plus élevée avant (11 puis 8, puis 5 maintenant).\n\n3. L’élève s’est trompé : (−3) × (−2) = **+6**. Deux signes identiques donnent un résultat positif. On calcule d’abord le signe, puis 3 × 2 = 6.\n\n4. En 4 h, la variation est (−3) × 4 = **−12 °C** : le congélateur a refroidi de 12 °C."}$exo$::jsonb),
  ('bbc8df26-d175-58d1-affb-8efd8a429819'::uuid, 3, 'probleme', $exo${"titre":"Calculs et raisonnements sur les relatifs","consigne":"Justifie les signes et ne saute aucune étape.","enonce":"**Questions.**\n\n1. Calcule A = (−2) × (−3) × (−4) × (+5).\n2. Calcule B = (−3)² − 3² et C = −3² + (−3)². Explique la différence entre (−3)² et −3².\n3. Calcule D = (−18) ÷ (+3) × (−2), en effectuant les opérations de gauche à droite, puis E = (−18) ÷ [(+3) × (−2)]. Pourquoi D et E sont-ils différents ?\n4. Sans calculer, donne le signe du produit (−2) × (−7) × (−1) × (−3) × (+4) × (−5). Justifie.","bareme":[{"critere":"A = −120 avec le signe justifié (trois facteurs négatifs)","points":4},{"critere":"B = 0, C = 0 et explication : (−3)² = +9, tandis que −3² = −9 (le carré ne porte que sur 3)","points":4},{"critere":"D = (−6) × (−2) = 12, E = (−18) ÷ (−6) = 3 et explication par les parenthèses","points":7},{"critere":"Signe négatif : cinq facteurs négatifs (impair)","points":5}],"dureeMin":16,"corrige":"1. Trois facteurs négatifs (nombre impair) : le produit est négatif. 2 × 3 × 4 × 5 = 120, donc A = **−120**.\n\n2. (−3)² = (−3) × (−3) = +9, et 3² = 9 : B = 9 − 9 = **0**.\n   Dans −3², le carré ne porte que sur le 3 : −3² = −9. Donc C = −9 + 9 = **0**.\n   La différence : avec des parenthèses, le carré s’applique au signe aussi (+9) ; sans parenthèses, non (−9).\n\n3. D : (−18) ÷ (+3) = −6, puis (−6) × (−2) = **+12**.\n   E : (+3) × (−2) = −6 d’abord (parenthèses), puis (−18) ÷ (−6) = **+3**.\n   Ils diffèrent car les parenthèses changent l’ordre des calculs : diviser par 3 puis multiplier par −2 n’est pas diviser par le produit.\n\n4. Les facteurs négatifs sont −2, −7, −1, −3 et −5 : il y en a **cinq**, un nombre impair. Le produit est donc **négatif**. (Le facteur +4 ne change pas le signe.)"}$exo$::jsonb),
  ('5e75256d-577d-5004-ac78-1c34f23fc75f'::uuid, 1, 'probleme', $exo${"titre":"Ranger et encadrer","consigne":"Écris les comparaisons avec les symboles < et >.","enonce":"**Questions.**\n\n1. Range du plus petit au plus grand : −4 ; 2,5 ; −0,5 ; 0 ; −4,5.\n2. Compare 3/7 et 5/7, puis 3/8 et 3/5.\n3. Encadre le nombre 7,382 à l’unité, puis au dixième.","bareme":[{"critere":"Rangement −4,5 < −4 < −0,5 < 0 < 2,5","points":7},{"critere":"3/7 < 5/7 et 3/8 < 3/5 avec justification (même dénominateur / même numérateur)","points":6},{"critere":"7 < 7,382 < 8 et 7,3 < 7,382 < 7,4","points":7}],"dureeMin":6,"corrige":"1. Entre deux négatifs, le plus petit est celui qui est le plus éloigné de zéro : **−4,5 < −4 < −0,5 < 0 < 2,5**.\n\n2. Même dénominateur : on compare les numérateurs, donc **3/7 < 5/7**.\n   Même numérateur : plus le dénominateur est grand, plus la fraction est petite. 8 > 5, donc **3/8 < 3/5**.\n\n3. À l’unité : **7 < 7,382 < 8**. Au dixième : **7,3 < 7,382 < 7,4**."}$exo$::jsonb),
  ('5e75256d-577d-5004-ac78-1c34f23fc75f'::uuid, 2, 'probleme', $exo${"titre":"Fractions et racine de 3","consigne":"Justifie chaque comparaison et chaque encadrement.","enonce":"**Situation.** Trois amis ont mangé une part de gâteau : Inès 3/4, Paul 5/8, Sara 7/12. On donne aussi √3 ≈ 1,7320.\n\n1. Range les trois fractions de la plus petite à la plus grande, en les réduisant au même dénominateur.\n2. Encadre √3 à l’unité, au dixième, puis au centième.\n3. Donne l’amplitude de chacun de ces trois encadrements.\n4. Donne les valeurs approchées de √3 par défaut, par excès et l’arrondi, au centième.","bareme":[{"critere":"Réduction au dénominateur 24 : 18/24 ; 15/24 ; 14/24, puis rangement 7/12 < 5/8 < 3/4","points":5},{"critere":"Encadrements 1 < √3 < 2 ; 1,7 < √3 < 1,8 ; 1,73 < √3 < 1,74","points":6},{"critere":"Amplitudes 1 ; 0,1 ; 0,01","points":4},{"critere":"Valeur par défaut 1,73, par excès 1,74, arrondi 1,73","points":5}],"dureeMin":10,"corrige":"1. Le dénominateur commun est 24 : 3/4 = 18/24 ; 5/8 = 15/24 ; 7/12 = 14/24.\n   Comme 14 < 15 < 18 : **7/12 < 5/8 < 3/4**. Sara a mangé la plus petite part.\n\n2. Avec √3 ≈ 1,7320 :\n   - à l’unité : **1 < √3 < 2** ;\n   - au dixième : **1,7 < √3 < 1,8** ;\n   - au centième : **1,73 < √3 < 1,74**.\n\n3. L’amplitude est l’écart entre les bornes : 2 − 1 = **1** ; 1,8 − 1,7 = **0,1** ; 1,74 − 1,73 = **0,01**. Plus l’amplitude est petite, plus l’encadrement est précis.\n\n4. Au centième : valeur approchée **par défaut = 1,73** (borne inférieure), **par excès = 1,74** (borne supérieure). L’arrondi est la borne la plus proche de 1,7320 : **1,73**."}$exo$::jsonb),
  ('5e75256d-577d-5004-ac78-1c34f23fc75f'::uuid, 3, 'probleme', $exo${"titre":"Comparer, encadrer, corriger","consigne":"Rédige avec des phrases courtes et justifie tes choix.","enonce":"**Questions.**\n\n1. Compare −2/3 et −3/4 en justifiant soigneusement.\n2. On donne 22/7 ≈ 3,142857 et π ≈ 3,14159. Encadre 22/7 au centième. Pourquoi 22/7 est-il une valeur approchée de π par excès ?\n3. Un élève écrit « −0,2 > −0,15 car 0,2 > 0,15 ». Explique son erreur et donne la bonne comparaison.\n4. Le premier encadrement d’un nombre est 1 < x < 2 et le second 1,41 < x < 1,42. Lequel est le plus précis ? Justifie avec l’amplitude.","bareme":[{"critere":"−2/3 > −3/4 : comparaison de 2/3 = 8/12 et 3/4 = 9/12, puis inversion pour les négatifs","points":5},{"critere":"3,14 < 22/7 < 3,15, et 22/7 > π donc valeur par excès","points":5},{"critere":"Erreur : pour deux négatifs, le plus grand est le plus proche de zéro ; −0,15 > −0,2","points":5},{"critere":"Second encadrement plus précis : amplitude 0,01 contre 1","points":5}],"dureeMin":14,"corrige":"1. On compare d’abord 2/3 et 3/4 : 2/3 = 8/12 et 3/4 = 9/12, donc 2/3 < 3/4. Pour des négatifs, l’ordre s’inverse (la plus grande distance à zéro donne le plus petit nombre) : **−2/3 > −3/4**.\n\n2. 22/7 ≈ 3,142857 : **3,14 < 22/7 < 3,15**. Comme π ≈ 3,14159 est plus petit que 22/7, le nombre 22/7 est plus grand que π : c’est une valeur approchée **par excès**.\n\n3. L’élève a comparé les distances à zéro sans tenir compte du signe. Entre deux négatifs, le plus grand est celui qui est le plus proche de zéro : 0,15 < 0,2, donc **−0,15 > −0,2**, c’est-à-dire −0,2 < −0,15.\n\n4. L’amplitude du premier est 2 − 1 = 1, celle du second 1,42 − 1,41 = 0,01. Le **second** encadrement est le plus précis, car son amplitude est 100 fois plus petite."}$exo$::jsonb),
  ('6d35af41-354f-52e9-b68a-ffc87011d036'::uuid, 1, 'probleme', $exo${"titre":"Des fractions qui valent pareil","consigne":"Écris les calculs utilisés.","enonce":"**Questions.**\n\n1. Complète : 2/5 = ?/20 et 18/27 = 2/?.\n2. Simplifie 30/45 et 24/40 au maximum.\n3. Les fractions 3/4 et 9/12 sont-elles égales ? Justifie avec le produit en croix.","bareme":[{"critere":"Compléments 8 (×4) et 3 (÷9)","points":6},{"critere":"30/45 = 2/3 et 24/40 = 3/5","points":7},{"critere":"Produit en croix 3 × 12 = 36 = 4 × 9, donc égales","points":7}],"dureeMin":6,"corrige":"1. 2/5 = (2 × 4)/(5 × 4) = **8**/20. 18/27 = (18 ÷ 9)/(27 ÷ 9) = 2/**3**.\n\n2. 30/45 : on divise par 15, donc **2/3**. 24/40 : on divise par 8, donc **3/5**.\n\n3. Produit en croix : 3 × 12 = 36 et 4 × 9 = 36. Les produits sont égaux, donc **3/4 = 9/12**."}$exo$::jsonb),
  ('6d35af41-354f-52e9-b68a-ffc87011d036'::uuid, 2, 'probleme', $exo${"titre":"Les parts de pizza","consigne":"Justifie chaque réponse par un calcul.","enonce":"**Situation.** Trois amis mangent une pizza : Lina en mange 6/8, Yanis 9/12 et Sam 4/6.\n\n1. Simplifie les fractions 6/8, 9/12 et 4/6.\n2. Lina et Yanis ont-ils mangé la même quantité ? Vérifie avec le produit en croix.\n3. Réduis 9/12 et 4/6 au même dénominateur. Qui a mangé le plus, Yanis ou Sam ?\n4. Simplifie 15/21.","bareme":[{"critere":"Simplifications 3/4, 3/4 et 2/3","points":5},{"critere":"Produit en croix 6 × 12 = 72 = 8 × 9, donc parts égales","points":5},{"critere":"Dénominateur 12 : 9/12 et 8/12, donc Yanis a mangé plus","points":5},{"critere":"15/21 = 5/7","points":5}],"dureeMin":10,"corrige":"1. 6/8 = **3/4** (÷ 2) ; 9/12 = **3/4** (÷ 3) ; 4/6 = **2/3** (÷ 2).\n\n2. Produit en croix : 6 × 12 = 72 et 8 × 9 = 72. Ils sont égaux : **6/8 = 9/12**. Lina et Yanis ont mangé la même quantité.\n\n3. Dénominateur commun 12 : 4/6 = 8/12. Comme 9/12 > 8/12, **Yanis a mangé plus que Sam**.\n\n4. 15/21 : on divise par 3 : **5/7**, fraction irréductible."}$exo$::jsonb),
  ('6d35af41-354f-52e9-b68a-ffc87011d036'::uuid, 3, 'probleme', $exo${"titre":"Fractions, facteurs premiers et erreur de Karim","consigne":"Justifie soigneusement, avec calculs.","enonce":"**Questions.**\n\n1. Décompose 168 et 210 en produits de facteurs premiers, puis simplifie la fraction 168/210 au maximum.\n2. Trouve le nombre x tel que 168/210 = x/35.\n3. Karim affirme : « 7/10 = 12/15, car j’ai ajouté 5 en haut et en bas ». Montre qu’il a tort avec le produit en croix et explique l’erreur.\n4. Réduis 5/12 et 7/18 au plus petit dénominateur commun possible.","bareme":[{"critere":"168 = 2³ × 3 × 7, 210 = 2 × 3 × 5 × 7 et 168/210 = 4/5","points":6},{"critere":"x = 28 en divisant par 6 (ou 4/5 × 35)","points":4},{"critere":"Produit en croix : 7 × 15 = 105 ≠ 10 × 12 = 120 ; on ne peut pas ajouter, seulement multiplier ou diviser","points":5},{"critere":"Plus petit dénominateur commun 36 : 15/36 et 14/36","points":5}],"dureeMin":15,"corrige":"1. 168 = 2 × 84 = 2² × 42 = 2³ × 21 = 2³ × 3 × 7 ; 210 = 2 × 3 × 5 × 7.\n   On barre les facteurs communs 2, 3 et 7 : il reste 2² au numérateur et 5 au dénominateur : 168/210 = **4/5**.\n\n2. 210 ÷ 6 = 35, donc 168 ÷ 6 = 28 : **x = 28**. (Contrôle : 4/5 × 35 = 28.)\n\n3. Produit en croix : 7 × 15 = 105 et 10 × 12 = 120. Ils sont différents : **7/10 ≠ 12/15**. Karim s’est trompé : une fraction ne garde sa valeur que si on **multiplie ou divise** le numérateur et le dénominateur par un même nombre, jamais si on leur ajoute un même nombre.\n\n4. Multiples de 12 : 12, 24, 36 ; multiples de 18 : 18, 36. Le plus petit dénominateur commun est **36** : 5/12 = **15/36** et 7/18 = **14/36**."}$exo$::jsonb),
  ('105df279-2f8a-5b37-a20c-e5cd54cd33ab'::uuid, 1, 'probleme', $exo${"titre":"Calculer avec des fractions","consigne":"Écris chaque calcul et simplifie le résultat.","enonce":"**Questions.** Calcule et donne le résultat sous forme de fraction simplifiée.\n\nA = 1/3 + 2/5\n\nB = 7/8 − 1/4\n\nC = 2/3 × 9/10","bareme":[{"critere":"A = 5/15 + 6/15 = 11/15","points":6},{"critere":"B = 7/8 − 2/8 = 5/8","points":7},{"critere":"C = 18/30 = 3/5, avec simplification","points":7}],"dureeMin":6,"corrige":"A = 1/3 + 2/5 : dénominateur commun 15, donc 5/15 + 6/15 = **11/15**.\n\nB = 7/8 − 1/4 : dénominateur commun 8, donc 7/8 − 2/8 = **5/8**.\n\nC = 2/3 × 9/10 : on multiplie numérateurs et dénominateurs : 18/30 = **3/5** (ou on simplifie avant : 2/10 = 1/5 et 9/3 = 3, donc 3/5).\n\nPour l’addition et la soustraction, il faut un dénominateur commun ; pour la multiplication, aucun."}$exo$::jsonb),
  ('105df279-2f8a-5b37-a20c-e5cd54cd33ab'::uuid, 2, 'probleme', $exo${"titre":"Le gâteau d’anniversaire","consigne":"Écris chaque calcul et une phrase de conclusion.","enonce":"**Situation.** Un gâteau pèse 1,2 kg. Léa en mange 1/4 et Tom en mange 2/5.\n\n1. Quelle fraction du gâteau a été mangée en tout ?\n2. Quelle fraction reste-t-il ?\n3. Quelle est la masse du gâteau restant ?\n4. On partage le reste en 3 parts égales. Quelle fraction du gâteau entier représente une part ?","bareme":[{"critere":"Fraction mangée : 1/4 + 2/5 = 5/20 + 8/20 = 13/20","points":5},{"critere":"Reste : 1 − 13/20 = 7/20","points":5},{"critere":"Masse restante : 7/20 × 1,2 = 0,42 kg","points":5},{"critere":"Une part : 7/20 ÷ 3 = 7/60","points":5}],"dureeMin":10,"corrige":"1. 1/4 + 2/5 = 5/20 + 8/20 = **13/20**.\n\n2. Reste = 1 − 13/20 = 20/20 − 13/20 = **7/20**.\n\n3. Masse restante = 7/20 × 1,2 = 8,4 ÷ 20 = **0,42 kg** (soit 420 g). Vérification : 1/20 de 1,2 kg = 0,06 kg et 0,06 × 7 = 0,42.\n\n4. Une part = 7/20 ÷ 3 = 7/20 × 1/3 = **7/60** du gâteau entier."}$exo$::jsonb),
  ('105df279-2f8a-5b37-a20c-e5cd54cd33ab'::uuid, 3, 'probleme', $exo${"titre":"Expressions avec des fractions","consigne":"Respecte les priorités de calcul et détaille chaque étape.","enonce":"**Questions.**\n\n1. Calcule A = 5/6 − 2/3 ÷ 4/9 et donne le résultat simplifié.\n2. Calcule B = (1/2 − 3/4) ÷ 1/8.\n3. Un élève écrit 1/2 + 1/3 = 2/5. Explique pourquoi c’est faux (avec un argument de bon sens), puis donne le bon résultat.\n4. Donne l’opposé et l’inverse de −3/4.","bareme":[{"critere":"A : division en premier 2/3 ÷ 4/9 = 3/2, puis A = 5/6 − 9/6 = −2/3","points":6},{"critere":"B : parenthèse −1/4, puis × 8 = −2","points":6},{"critere":"Erreur : 2/5 est plus petit que 1/2 ; bon résultat 5/6","points":4},{"critere":"Opposé 3/4 et inverse −4/3","points":4}],"dureeMin":15,"corrige":"1. La division est prioritaire sur la soustraction : 2/3 ÷ 4/9 = 2/3 × 9/4 = 18/12 = 3/2.\n   A = 5/6 − 3/2 = 5/6 − 9/6 = −4/6 = **−2/3**.\n\n2. Parenthèse d’abord : 1/2 − 3/4 = 2/4 − 3/4 = −1/4.\n   B = −1/4 ÷ 1/8 = −1/4 × 8 = **−2**.\n\n3. On n’additionne jamais les dénominateurs. Le bon sens le montre : 1/2 + 1/3 doit être plus grand que 1/2, or 2/5 est plus petit que 1/2. Correct : 1/2 + 1/3 = 3/6 + 2/6 = **5/6**.\n\n4. L’**opposé** de −3/4 est **3/4**. L’**inverse** de −3/4 est **−4/3** (on retourne la fraction et le signe est conservé). Opposé et inverse ne sont pas la même chose."}$exo$::jsonb),
  ('b3560004-1ea7-5651-ba9d-dbb240eeb02f'::uuid, 1, 'probleme', $exo${"titre":"Puissances et écriture scientifique","consigne":"Écris les calculs.","enonce":"**Questions.**\n\n1. Calcule 2⁵, 10³ et 7⁰.\n2. Écris sous la forme d’une seule puissance : 3⁴ × 3² et 5⁷ ÷ 5⁵.\n3. Donne l’écriture scientifique de 4 500 000 et de 0,00032.","bareme":[{"critere":"2⁵ = 32, 10³ = 1 000 et 7⁰ = 1","points":6},{"critere":"3⁴ × 3² = 3⁶ et 5⁷ ÷ 5⁵ = 5²","points":7},{"critere":"4,5 × 10⁶ et 3,2 × 10⁻⁴","points":7}],"dureeMin":6,"corrige":"1. 2⁵ = 2 × 2 × 2 × 2 × 2 = **32** ; 10³ = **1 000** ; 7⁰ = **1** (toute puissance zéro d’un nombre non nul vaut 1).\n\n2. Même base : on additionne les exposants pour un produit, on les soustrait pour un quotient.\n   3⁴ × 3² = 3⁴⁺² = **3⁶** ; 5⁷ ÷ 5⁵ = 5⁷⁻⁵ = **5²**.\n\n3. 4 500 000 = **4,5 × 10⁶** (la virgule recule de 6 rangs). 0,00032 = **3,2 × 10⁻⁴** (la virgule avance de 4 rangs)."}$exo$::jsonb),
  ('b3560004-1ea7-5651-ba9d-dbb240eeb02f'::uuid, 2, 'probleme', $exo${"titre":"La lumière du Soleil","consigne":"Utilise les puissances de 10 et écris les étapes.","enonce":"**Situation.** La distance de la Terre au Soleil est d’environ 150 000 000 km. La lumière se déplace à environ 3 × 10⁵ km/s.\n\n1. Écris 150 000 000 en notation scientifique.\n2. Calcule le temps mis par la lumière du Soleil pour atteindre la Terre : donne le résultat en secondes, sous la forme d’une puissance de 10 multipliée par un nombre.\n3. Convertis ce temps en minutes et secondes.\n4. Une bactérie mesure 2 × 10⁻⁶ m. Exprime cette longueur en micromètres (1 µm = 10⁻⁶ m).","bareme":[{"critere":"150 000 000 = 1,5 × 10⁸","points":4},{"critere":"Temps = (1,5 × 10⁸) ÷ (3 × 10⁵) = 0,5 × 10³ = 500 s","points":8},{"critere":"500 s = 8 min 20 s","points":4},{"critere":"2 × 10⁻⁶ m = 2 µm","points":4}],"dureeMin":10,"corrige":"1. 150 000 000 = **1,5 × 10⁸** km.\n\n2. Temps = distance ÷ vitesse = (1,5 × 10⁸) ÷ (3 × 10⁵) = (1,5 ÷ 3) × 10⁸⁻⁵ = 0,5 × 10³ = **500 s** (soit 5 × 10² s).\n\n3. 500 s = 480 s + 20 s = 8 min + 20 s, soit **8 min 20 s**.\n\n4. 1 µm = 10⁻⁶ m, donc 2 × 10⁻⁶ m = **2 µm**."}$exo$::jsonb),
  ('b3560004-1ea7-5651-ba9d-dbb240eeb02f'::uuid, 3, 'probleme', $exo${"titre":"Calculs avec les puissances","consigne":"Justifie chaque simplification par une règle de calcul.","enonce":"**Questions.**\n\n1. Écris A = (2³ × 2⁻⁵) ÷ 2⁴ sous la forme d’une puissance de 2, puis sous forme d’une fraction.\n2. Donne l’écriture scientifique de B = (3 × 10⁴) × (4 × 10⁻⁷).\n3. Donne l’écriture scientifique de C = (6 × 10⁵) ÷ (2 × 10⁻³).\n4. Compare 4,2 × 10⁻³ et 3,9 × 10⁻².\n5. Un élève écrit 2³ × 5³ = 10⁶. Montre que c’est faux et donne la bonne écriture.","bareme":[{"critere":"A = 2⁻² ÷ 2⁴ = 2⁻⁶ = 1/64","points":4},{"critere":"B = 12 × 10⁻³ = 1,2 × 10⁻²","points":5},{"critere":"C = 3 × 10⁸","points":4},{"critere":"3,9 × 10⁻² > 4,2 × 10⁻³ en comparant d’abord les exposants","points":3},{"critere":"2³ × 5³ = 8 × 125 = 1 000 = 10³ ; les exposants ne s’additionnent que pour une même base","points":4}],"dureeMin":16,"corrige":"1. 2³ × 2⁻⁵ = 2³⁺⁽⁻⁵⁾ = 2⁻² ; puis 2⁻² ÷ 2⁴ = 2⁻²⁻⁴ = **2⁻⁶** = 1/2⁶ = **1/64**.\n\n2. B = (3 × 4) × (10⁴ × 10⁻⁷) = 12 × 10⁻³. Or 12 n’est pas compris entre 1 et 10 : 12 × 10⁻³ = 1,2 × 10 × 10⁻³ = **1,2 × 10⁻²**.\n\n3. C = (6 ÷ 2) × (10⁵ ÷ 10⁻³) = 3 × 10⁵⁻⁽⁻³⁾ = **3 × 10⁸**.\n\n4. On compare d’abord les exposants : −2 > −3. Donc **3,9 × 10⁻² > 4,2 × 10⁻³** (0,039 contre 0,0042).\n\n5. 2³ × 5³ = 8 × 125 = 1 000 = **10³**, et non 10⁶. Les exposants ne s’additionnent que pour des puissances de **même base** ; ici on utilise (a × b)ⁿ = aⁿ × bⁿ : 2³ × 5³ = (2 × 5)³ = 10³."}$exo$::jsonb),
  ('e1a17713-b4c0-5c80-bb0d-afaabdf4aef4'::uuid, 1, 'probleme', $exo${"titre":"Racines carrées de base","consigne":"Écris les calculs.","enonce":"**Questions de cours et d’application sur les racines carrées.** Écris chaque calcul et donne le résultat exact.\n\n1. Calcule √81, √144 et (√11)².\n2. Calcule √3 × √12 et √50 ÷ √2.\n3. Simplifie √20.","bareme":[{"critere":"√81 = 9, √144 = 12, (√11)² = 11","points":6},{"critere":"√3 × √12 = √36 = 6 et √50 ÷ √2 = √25 = 5","points":7},{"critere":"√20 = √(4 × 5) = 2√5","points":7}],"dureeMin":6,"corrige":"1. √81 = **9** (car 9² = 81) ; √144 = **12** ; (√11)² = **11**.\n\n2. √3 × √12 = √(3 × 12) = √36 = **6**. √50 ÷ √2 = √(50 ÷ 2) = √25 = **5**.\n\n3. On cherche le plus grand carré parfait qui divise 20 : c’est 4. √20 = √(4 × 5) = √4 × √5 = **2√5**."}$exo$::jsonb),
  ('e1a17713-b4c0-5c80-bb0d-afaabdf4aef4'::uuid, 2, 'probleme', $exo${"titre":"Deux jardins carrés","consigne":"Écris les calculs et des phrases-réponses.","enonce":"**Situation.** Le carré A est un jardin d’aire 169 m². Le carré B est un jardin d’aire 50 m².\n\n1. Calcule le côté du jardin A.\n2. Donne la valeur exacte du côté du jardin B, puis simplifie-la.\n3. Encadre ce côté entre deux entiers consécutifs, en le justifiant avec des carrés parfaits.\n4. Donne la valeur exacte du périmètre du jardin B.","bareme":[{"critere":"Côté de A : √169 = 13 m","points":4},{"critere":"Côté de B : √50 = √(25 × 2) = 5√2","points":6},{"critere":"Encadrement 7 < √50 < 8 car 49 < 50 < 64","points":5},{"critere":"Périmètre : 4 × 5√2 = 20√2 m","points":5}],"dureeMin":10,"corrige":"1. Le côté est √169 = **13 m** (car 13² = 169).\n\n2. Le côté de B est √50 m. Comme 50 = 25 × 2 : √50 = √25 × √2 = **5√2 m**.\n\n3. 7² = 49 et 8² = 64 ; comme 49 < 50 < 64, on a 7 < √50 < 8. Le côté de B est **entre 7 m et 8 m**.\n\n4. Périmètre = 4 × côté = 4 × 5√2 = **20√2 m** (environ 28,3 m)."}$exo$::jsonb),
  ('e1a17713-b4c0-5c80-bb0d-afaabdf4aef4'::uuid, 3, 'probleme', $exo${"titre":"Vrai ou faux avec racines","consigne":"Réponds par « vrai » ou « faux » et justifie par un calcul.","enonce":"**Questions.**\n\n1. Dis si chaque égalité est vraie ou fausse, en justifiant par un calcul :\n   a. √(16 + 9) = √16 + √9 ;\n   b. √(4 × 9) = √4 × √9 ;\n   c. (√5)² = 5 ;\n   d. √(−4) = −2.\n2. Simplifie √75.\n3. Calcule √72 ÷ √2.\n4. Compare 3√2 et 4 sans calculatrice, en écrivant 3√2 sous la forme √N.","bareme":[{"critere":"Les quatre affirmations jugées avec justification : faux, vrai, vrai, faux","points":8},{"critere":"√75 = √(25 × 3) = 5√3","points":4},{"critere":"√72 ÷ √2 = √36 = 6","points":3},{"critere":"3√2 = √18 > √16 = 4, donc 3√2 > 4","points":5}],"dureeMin":16,"corrige":"1. a. **Faux** : √(16 + 9) = √25 = 5, alors que √16 + √9 = 4 + 3 = 7.\n   b. **Vrai** : √36 = 6 et √4 × √9 = 2 × 3 = 6.\n   c. **Vrai** : (√a)² = a, donc (√5)² = 5.\n   d. **Faux** : la racine carrée d’un nombre négatif n’existe pas (aucun carré n’est négatif), et une racine carrée n’est jamais négative.\n\n2. √75 = √(25 × 3) = √25 × √3 = **5√3**.\n\n3. √72 ÷ √2 = √(72 ÷ 2) = √36 = **6**.\n\n4. 3√2 = √9 × √2 = √18. Comme 18 > 16, √18 > √16 = 4. Donc **3√2 > 4**. (Contrôle : 3 × 1,414 ≈ 4,24.)"}$exo$::jsonb),
  ('bb7d2fb5-5930-51ad-a2a2-5e4c0cec344d'::uuid, 1, 'probleme', $exo${"titre":"Reconnaître les nombres premiers","consigne":"Justifie tes réponses.","enonce":"**Questions.**\n\n1. Parmi 21, 23, 27, 29 et 33, quels sont les nombres premiers ? Justifie pour ceux qui ne le sont pas.\n2. Pourquoi 1 n’est-il pas un nombre premier ? Quel est le seul nombre premier pair ?\n3. Décompose 60 en produit de facteurs premiers.","bareme":[{"critere":"23 et 29 premiers ; 21 = 3 × 7, 27 = 3 × 9 et 33 = 3 × 11 justifiés","points":7},{"critere":"1 n’a qu’un seul diviseur ; 2 est le seul premier pair","points":5},{"critere":"60 = 2² × 3 × 5 obtenu par divisions successives","points":8}],"dureeMin":7,"corrige":"1. **23 et 29** sont premiers : ils n’ont que deux diviseurs, 1 et eux-mêmes. Les autres ne le sont pas : 21 = 3 × 7 ; 27 = 3 × 9 ; 33 = 3 × 11.\n\n2. Le nombre 1 n’a **qu’un seul** diviseur (lui-même), or un nombre premier en a exactement deux. Le seul nombre premier pair est **2**.\n\n3. 60 = 2 × 30 = 2 × 2 × 15 = 2 × 2 × 3 × 5, soit **60 = 2² × 3 × 5**."}$exo$::jsonb),
  ('bb7d2fb5-5930-51ad-a2a2-5e4c0cec344d'::uuid, 2, 'probleme', $exo${"titre":"Simplifier avec les facteurs premiers","consigne":"Écris les décompositions, puis les conclusions.","enonce":"**Questions.**\n\n1. Décompose 126 et 210 en produits de facteurs premiers.\n2. Simplifie la fraction 126/210 jusqu’à la rendre irréductible.\n3. Les nombres 25 et 36 sont-ils premiers entre eux ? Justifie avec leurs décompositions.\n4. Le nombre 91 est-il premier ? Justifie.","bareme":[{"critere":"126 = 2 × 3² × 7 et 210 = 2 × 3 × 5 × 7","points":5},{"critere":"126/210 = 3/5 en barrant les facteurs communs 2, 3 et 7","points":5},{"critere":"25 = 5² et 36 = 2² × 3² : aucun facteur commun, donc premiers entre eux","points":5},{"critere":"91 = 7 × 13, donc non premier","points":5}],"dureeMin":10,"corrige":"1. 126 = 2 × 63 = 2 × 3 × 21 = 2 × 3 × 3 × 7 = **2 × 3² × 7**. 210 = **2 × 3 × 5 × 7**.\n\n2. On barre les facteurs communs (2, 3 et 7) : il reste 3 au numérateur et 5 au dénominateur. Donc 126/210 = **3/5**, fraction irréductible.\n\n3. 25 = 5² et 36 = 2² × 3². Ils n’ont **aucun facteur premier commun** : 25 et 36 sont premiers entre eux (même si aucun des deux n’est premier).\n\n4. 91 = 7 × 13 (7 × 13 = 91). Il a d’autres diviseurs que 1 et lui-même : **91 n’est pas premier**."}$exo$::jsonb),
  ('bb7d2fb5-5930-51ad-a2a2-5e4c0cec344d'::uuid, 3, 'probleme', $exo${"titre":"Tester, décomposer, raisonner","consigne":"Explique quels diviseurs tu testes et pourquoi tu t’arrêtes.","enonce":"**Questions.**\n\n1. Le nombre 137 est-il premier ? Explique jusqu’à quel diviseur il faut tester.\n2. Le nombre 143 est-il premier ? Justifie.\n3. Décompose 1 260 en produit de facteurs premiers.\n4. Par quel plus petit entier faut-il multiplier 90 pour obtenir un carré parfait ? Donne alors ce carré et sa racine carrée.","bareme":[{"critere":"137 : on teste 2, 3, 5, 7, 11 et on s’arrête car 13² = 169 > 137 ; aucun ne divise, donc premier","points":5},{"critere":"143 = 11 × 13 donc non premier","points":4},{"critere":"1 260 = 2² × 3² × 5 × 7","points":5},{"critere":"90 = 2 × 3² × 5 ; multiplier par 10 ; 900 = 30²","points":6}],"dureeMin":15,"corrige":"1. On teste les nombres premiers 2, 3, 5, 7, 11, puis on s’arrête car 13² = 169 dépasse 137. 137 est impair (pas 2), 1 + 3 + 7 = 11 n’est pas un multiple de 3, il ne finit ni par 0 ni par 5, 137 ÷ 7 ≈ 19,57 et 137 ÷ 11 ≈ 12,45 ne sont pas entiers. **137 est premier.**\n\n2. 143 n’est divisible ni par 2, 3, 5 ni 7, mais 11 × 13 = 143. **143 n’est pas premier.**\n\n3. 1 260 = 2 × 630 = 2² × 315 = 2² × 3 × 105 = 2² × 3² × 35 = **2² × 3² × 5 × 7**.\n\n4. 90 = 2 × 3² × 5. Dans un carré parfait, chaque facteur premier a un exposant pair. Il manque un 2 et un 5 : on multiplie par 2 × 5 = **10**. On obtient 900 = 2² × 3² × 5² = (2 × 3 × 5)² = **30²**, donc √900 = 30."}$exo$::jsonb),
  ('2d76d260-0009-5038-9ee1-223f12d3a274'::uuid, 1, 'probleme', $exo${"titre":"Développer, factoriser, réduire","consigne":"Écris chaque étape.","enonce":"**Questions de cours et d’application sur le calcul littéral.** Écris chaque étape de ton calcul.\n\n1. Développe 4(x + 6) et −3(2x − 5).\n2. Factorise 6x + 18 et x² + 5x.\n3. Réduis 4x + 3 − x + 8.","bareme":[{"critere":"4x + 24 et −6x + 15 (signes justes)","points":7},{"critere":"6(x + 3) et x(x + 5)","points":7},{"critere":"3x + 11","points":6}],"dureeMin":6,"corrige":"1. 4(x + 6) = 4 × x + 4 × 6 = **4x + 24**.\n   −3(2x − 5) = −3 × 2x + (−3) × (−5) = **−6x + 15**.\n\n2. 6x + 18 = 6 × x + 6 × 3 = **6(x + 3)**. x² + 5x = x × x + x × 5 = **x(x + 5)**.\n\n3. 4x − x = 3x et 3 + 8 = 11, donc **3x + 11**."}$exo$::jsonb),
  ('2d76d260-0009-5038-9ee1-223f12d3a274'::uuid, 2, 'probleme', $exo${"titre":"L’aire d’un rectangle","consigne":"Développe et réduis avec soin.","enonce":"**Situation.** Un rectangle a pour longueur x + 5 et pour largeur x + 2 (en cm).\n\n1. Développe et réduis l’expression de l’aire A = (x + 5)(x + 2).\n2. Pour x = 3, calcule l’aire de deux façons (directement, puis avec l’expression développée).\n3. Développe (x − 3)(2x + 1).\n4. Factorise (x + 4)(x − 1) + (x + 4) × 3.","bareme":[{"critere":"A = x² + 2x + 5x + 10 = x² + 7x + 10","points":5},{"critere":"Pour x = 3 : 8 × 5 = 40 et 9 + 21 + 10 = 40","points":4},{"critere":"(x − 3)(2x + 1) = 2x² − 5x − 3","points":5},{"critere":"(x + 4)(x − 1 + 3) = (x + 4)(x + 2)","points":6}],"dureeMin":10,"corrige":"1. (x + 5)(x + 2) = x × x + x × 2 + 5 × x + 5 × 2 = x² + 2x + 5x + 10 = **x² + 7x + 10**.\n\n2. Pour x = 3 : longueur 3 + 5 = 8, largeur 3 + 2 = 5, aire 8 × 5 = **40**. Avec l’expression : 3² + 7 × 3 + 10 = 9 + 21 + 10 = **40**. Les deux résultats coïncident.\n\n3. (x − 3)(2x + 1) = 2x² + x − 6x − 3 = **2x² − 5x − 3**.\n\n4. Le facteur commun est (x + 4) : (x + 4)(x − 1) + (x + 4) × 3 = (x + 4)[(x − 1) + 3] = **(x + 4)(x + 2)**."}$exo$::jsonb),
  ('2d76d260-0009-5038-9ee1-223f12d3a274'::uuid, 3, 'probleme', $exo${"titre":"Prouver ou réfuter une égalité","consigne":"Justifie par un calcul complet ou par un contre-exemple.","enonce":"**Questions.**\n\n1. Développe et réduis (2x − 3)(x + 4).\n2. Un élève affirme que (x + 1)² = x² + 1. Prouve qu’il a tort avec un contre-exemple, puis donne la bonne égalité en développant.\n3. Montre que, quel que soit le nombre n, (n + 1)(n + 5) − (n + 2)(n + 4) est toujours égal à −3.\n4. Factorise (3x + 1)(x − 2) − (3x + 1) × 4.","bareme":[{"critere":"2x² + 5x − 12 avec les quatre produits","points":4},{"critere":"Contre-exemple x = 2 : 9 ≠ 5, puis (x + 1)² = x² + 2x + 1","points":5},{"critere":"Développement des deux produits et différence égale à −3","points":6},{"critere":"(3x + 1)(x − 6)","points":5}],"dureeMin":16,"corrige":"1. (2x − 3)(x + 4) = 2x² + 8x − 3x − 12 = **2x² + 5x − 12**.\n\n2. Pour x = 2 : (2 + 1)² = 9 alors que 2² + 1 = 5. Un seul contre-exemple suffit : l’égalité est **fausse**.\n   Bonne égalité : (x + 1)² = (x + 1)(x + 1) = x² + x + x + 1 = **x² + 2x + 1**.\n\n3. (n + 1)(n + 5) = n² + 5n + n + 5 = n² + 6n + 5.\n   (n + 2)(n + 4) = n² + 4n + 2n + 8 = n² + 6n + 8.\n   Différence : (n² + 6n + 5) − (n² + 6n + 8) = n² + 6n + 5 − n² − 6n − 8 = **−3**, quel que soit n. (Le signe moins change tous les signes de la seconde parenthèse.)\n\n4. Facteur commun (3x + 1) : (3x + 1)[(x − 2) − 4] = **(3x + 1)(x − 6)**."}$exo$::jsonb),
  ('33562b41-7711-5225-8fc3-9d1e10b7713a'::uuid, 1, 'probleme', $exo${"titre":"Résoudre des équations simples","consigne":"Écris les étapes de la résolution.","enonce":"**Questions de cours et d’application sur les équations.** Résous chaque équation en écrivant les étapes et en justifiant chaque transformation.\n\n1. x + 9 = 14\n2. 4x = 28\n3. 5x − 3 = 17, puis vérifie ta solution.","bareme":[{"critere":"x = 5 en soustrayant 9 aux deux membres","points":6},{"critere":"x = 7 en divisant par 4","points":6},{"critere":"x = 4 avec vérification 5 × 4 − 3 = 17","points":8}],"dureeMin":6,"corrige":"1. x + 9 = 14 : on soustrait 9 aux deux membres, donc x = 14 − 9 = **5**.\n\n2. 4x = 28 : on divise les deux membres par 4, donc x = 28 ÷ 4 = **7**.\n\n3. 5x − 3 = 17 : on ajoute 3 aux deux membres, 5x = 20, puis x = 20 ÷ 5 = **4**.\n   Vérification : 5 × 4 − 3 = 20 − 3 = 17. ✓"}$exo$::jsonb),
  ('33562b41-7711-5225-8fc3-9d1e10b7713a'::uuid, 2, 'probleme', $exo${"titre":"Le cinéma et les équations","consigne":"Rédige les étapes, puis une phrase de conclusion pour le problème.","enonce":"**Questions.**\n\n1. Résous 6x − 5 = 3x + 10.\n2. Résous (x − 3)(x + 2) = 0.\n3. Au cinéma, un billet enfant coûte 4 € de moins qu’un billet adulte. Pour 2 adultes et 3 enfants, on paie 38 €. Soit x le prix d’un billet adulte, en euros. Mets le problème en équation et résous-le.\n4. Écris une phrase de conclusion et vérifie le résultat.","bareme":[{"critere":"Équation 1 : 3x = 15 puis x = 5","points":5},{"critere":"Produit nul : x = 3 ou x = −2","points":5},{"critere":"Mise en équation 2x + 3(x − 4) = 38 et résolution x = 10","points":6},{"critere":"Conclusion : billet adulte 10 €, billet enfant 6 € ; vérification 20 + 18 = 38","points":4}],"dureeMin":11,"corrige":"1. 6x − 5 = 3x + 10 → 6x − 3x = 10 + 5 → 3x = 15 → **x = 5**.\n\n2. Un produit est nul si l’un de ses facteurs est nul : x − 3 = 0 ou x + 2 = 0. Les solutions sont **3** et **−2**.\n\n3. Le billet enfant coûte x − 4. L’équation est 2x + 3(x − 4) = 38.\n   On développe : 2x + 3x − 12 = 38, donc 5x = 50 et **x = 10**.\n\n4. Un billet adulte coûte **10 €** et un billet enfant 10 − 4 = **6 €**.\n   Vérification : 2 × 10 + 3 × 6 = 20 + 18 = 38 €. ✓"}$exo$::jsonb),
  ('33562b41-7711-5225-8fc3-9d1e10b7713a'::uuid, 3, 'probleme', $exo${"titre":"Trois problèmes, une méthode","consigne":"Définis l’inconnue, écris l’équation, résous puis conclus.","enonce":"**Questions.**\n\n1. Trois amis ont ensemble 40 billes. Ali en a x, Bob en a 4 de plus qu’Ali et Chloé en a le double d’Ali. Mets le problème en équation, résous-le et conclus par une phrase.\n2. Résous 5(x − 2) = 3x + 8.\n3. Résous 3(x + 2) = 3x + 6, puis 3(x + 2) = 3x + 7. Que remarques-tu ?\n4. Un élève résout x(x − 4) = 0 et écrit « x − 4 = 0 donc x = 4 ». Corrige-le.","bareme":[{"critere":"Équation x + (x + 4) + 2x = 40, résolution x = 9 et phrase avec 9, 13 et 18 billes","points":7},{"critere":"5x − 10 = 3x + 8, puis x = 9","points":4},{"critere":"Première équation : toutes les valeurs ; seconde : aucune solution","points":5},{"critere":"Solutions 0 et 4 : produit nul, l’autre facteur x peut aussi être nul","points":4}],"dureeMin":16,"corrige":"1. Soit x le nombre de billes d’Ali. Bob en a x + 4 et Chloé 2x. Équation : x + (x + 4) + 2x = 40, donc 4x + 4 = 40, 4x = 36 et **x = 9**.\n   Ali a **9 billes**, Bob **13** et Chloé **18**. Vérification : 9 + 13 + 18 = 40. ✓\n\n2. 5(x − 2) = 3x + 8 → 5x − 10 = 3x + 8 → 2x = 18 → **x = 9**.\n\n3. 3(x + 2) = 3x + 6 devient 3x + 6 = 3x + 6, soit 0x = 0 : **tous les nombres** sont solutions.\n   3(x + 2) = 3x + 7 devient 3x + 6 = 3x + 7, soit 0x = 1 : **aucune solution**.\n\n4. Un produit est nul si l’un des facteurs est nul : x = 0 **ou** x − 4 = 0. Les solutions sont **0 et 4**. L’élève a oublié la solution x = 0."}$exo$::jsonb),
  ('efd99958-83d9-5671-9d06-d227670481cb'::uuid, 1, 'probleme', $exo${"titre":"Traduire des phrases","consigne":"Écris chaque expression sous forme littérale.","enonce":"**Questions.**\n\n1. Traduis par une expression littérale : le double de x augmenté de 5 ; le carré de x diminué de 1 ; trois entiers consécutifs dont le plus petit est n ; un prix p après une hausse de 10 %.\n2. Calcule les deux premières expressions pour x = 4.\n3. Pierre a n billes. Ses deux frères en ont 2 et 5 de plus que lui. Écris le nombre de billes de chaque frère, puis le nombre total de billes des trois garçons, réduit.","bareme":[{"critere":"2x + 5 ; x² − 1 ; n, n + 1, n + 2 ; 1,1 × p","points":8},{"critere":"Pour x = 4 : 13 et 15","points":6},{"critere":"n + 2 ; n + 5 ; total n + (n + 2) + (n + 5) = 3n + 7","points":6}],"dureeMin":8,"corrige":"1. Le double de x augmenté de 5 : **2x + 5**. Le carré de x diminué de 1 : **x² − 1**. Trois entiers consécutifs : **n, n + 1, n + 2**. Une hausse de 10 % : **1,1 × p**.\n\n2. Pour x = 4 : 2 × 4 + 5 = **13** ; 4² − 1 = 16 − 1 = **15**.\n\n3. Les frères ont **n + 2** et **n + 5** billes. Total : n + (n + 2) + (n + 5) = **3n + 7**."}$exo$::jsonb),
  ('efd99958-83d9-5671-9d06-d227670481cb'::uuid, 2, 'probleme', $exo${"titre":"Un programme de calcul","consigne":"Traduis le programme par une expression, puis développe et réduis.","enonce":"**Situation.** Voici un programme de calcul :\n- Choisis un nombre x.\n- Multiplie-le par 4.\n- Ajoute 6.\n- Divise le résultat par 2.\n- Retire 3.\n\n1. Écris une expression littérale qui traduit ce programme.\n2. Développe et réduis cette expression.\n3. Teste le programme avec x = 5, puis avec x = −3.\n4. Que fait ce programme ? Formule une conclusion valable pour tous les nombres.","bareme":[{"critere":"Expression (4x + 6) ÷ 2 − 3","points":6},{"critere":"Réduction 2x + 3 − 3 = 2x","points":5},{"critere":"Tests x = 5 donne 10 et x = −3 donne −6","points":4},{"critere":"Conclusion : le programme donne toujours le double du nombre de départ","points":5}],"dureeMin":10,"corrige":"1. Multiplier par 4 : 4x ; ajouter 6 : 4x + 6 ; diviser par 2 : (4x + 6)/2 ; retirer 3. Expression : **(4x + 6) ÷ 2 − 3**.\n\n2. (4x + 6) ÷ 2 = 2x + 3, puis 2x + 3 − 3 = **2x**.\n\n3. Pour x = 5 : 5 × 4 = 20, 20 + 6 = 26, 26 ÷ 2 = 13, 13 − 3 = **10** = 2 × 5. ✓\n   Pour x = −3 : −12 + 6 = −6, −6 ÷ 2 = −3, −3 − 3 = **−6** = 2 × (−3). ✓\n\n4. Le programme donne **toujours le double du nombre choisi**. La preuve est le calcul littéral : un ou deux tests ne suffisent pas, l’expression réduite 2x le démontre pour tous les nombres."}$exo$::jsonb),
  ('efd99958-83d9-5671-9d06-d227670481cb'::uuid, 3, 'probleme', $exo${"titre":"Deux clubs de sport","consigne":"Écris les expressions, l’équation, puis discute selon le nombre de séances.","enonce":"**Situation.** Deux clubs proposent des tarifs :\n- le club A fait payer 12 € par séance ;\n- le club B demande un abonnement de 60 € plus 6 € par séance.\n\nSoit n le nombre de séances.\n\n1. Écris le prix payé au club A puis au club B en fonction de n.\n2. Pour quel nombre de séances les deux clubs coûtent-ils autant ?\n3. Quel club est le moins cher pour 8 séances ? pour 15 séances ? Justifie par les prix.\n4. Le prix payé au club A est-il proportionnel au nombre de séances ? Et celui du club B ? Justifie.","bareme":[{"critere":"Prix A = 12n et prix B = 60 + 6n","points":4},{"critere":"Équation 12n = 60 + 6n, donc n = 10 séances","points":5},{"critere":"8 séances : A 96 € contre B 108 € ; 15 séances : A 180 € contre B 150 €","points":6},{"critere":"A proportionnel (coefficient 12) ; B non à cause de l’abonnement fixe","points":5}],"dureeMin":15,"corrige":"1. Club A : **12 × n**. Club B : **60 + 6 × n**.\n\n2. On cherche n tel que 12n = 60 + 6n. Alors 12n − 6n = 60, 6n = 60 et **n = 10**. Pour 10 séances, les deux clubs coûtent 120 €.\n\n3. Pour 8 séances : A = 12 × 8 = 96 €, B = 60 + 6 × 8 = 108 € : le club **A** est moins cher.\n   Pour 15 séances : A = 12 × 15 = 180 €, B = 60 + 6 × 15 = 150 € : le club **B** est moins cher.\n   Conclusion : A est plus avantageux en dessous de 10 séances, B au-dessus.\n\n4. Le prix de A est proportionnel à n (coefficient 12 € par séance, et 0 séance coûte 0 €). Le prix de B n’est **pas** proportionnel : même sans séance, on paie 60 € (part fixe)."}$exo$::jsonb),
  ('f6b44486-50b1-5c22-a554-1db8059cc8b7'::uuid, 1, 'probleme', $exo${"titre":"Étendue, moyenne, médiane","consigne":"Écris les calculs et range la série avant la médiane.","enonce":"**Situation.** Les notes de cinq élèves sont : 12 ; 5 ; 16 ; 9 ; 8.\n\n1. Calcule l’étendue de la série.\n2. Calcule la moyenne de la série.\n3. Calcule la médiane de la série.","bareme":[{"critere":"Étendue 16 − 5 = 11","points":6},{"critere":"Moyenne 50 ÷ 5 = 10","points":6},{"critere":"Série ordonnée 5 ; 8 ; 9 ; 12 ; 16 et médiane 9","points":8}],"dureeMin":6,"corrige":"1. Étendue = plus grande valeur − plus petite valeur = 16 − 5 = **11**.\n\n2. Somme : 12 + 5 + 16 + 9 + 8 = 50. Moyenne = 50 ÷ 5 = **10**.\n\n3. On ordonne d’abord : 5 ; 8 ; 9 ; 12 ; 16. Il y a 5 valeurs, la médiane est la 3e : **9**."}$exo$::jsonb),
  ('f6b44486-50b1-5c22-a554-1db8059cc8b7'::uuid, 2, 'probleme', $exo${"titre":"Les sports de la classe","consigne":"Écris les calculs et justifie le choix du graphique.","enonce":"**Situation.** On a interrogé 40 élèves sur leur sport préféré : foot 16 élèves, basket 10, natation 8, tennis 6.\n\n1. Quel est l’effectif total ? Le caractère étudié est-il qualitatif ou quantitatif ?\n2. Calcule la fréquence de chaque sport, en pourcentage.\n3. On veut un diagramme circulaire. Calcule l’angle de chaque secteur et vérifie que la somme est 360°.\n4. Pourquoi ce diagramme est-il mieux adapté qu’une courbe ?","bareme":[{"critere":"Effectif total 40 et caractère qualitatif","points":4},{"critere":"Fréquences 40 %, 25 %, 20 % et 15 %","points":6},{"critere":"Angles 144°, 90°, 72° et 54°, somme 360°","points":6},{"critere":"Diagramme circulaire adapté à une répartition, la courbe étant réservée à une évolution dans le temps","points":4}],"dureeMin":10,"corrige":"1. Effectif total : 16 + 10 + 8 + 6 = **40**. Le sport pratiqué ne se mesure pas : le caractère est **qualitatif**.\n\n2. Fréquence = effectif ÷ effectif total : foot 16 ÷ 40 = **40 %** ; basket 10 ÷ 40 = **25 %** ; natation 8 ÷ 40 = **20 %** ; tennis 6 ÷ 40 = **15 %**. La somme fait bien 100 %.\n\n3. Angle = fréquence × 360° : foot 0,40 × 360 = **144°** ; basket 0,25 × 360 = **90°** ; natation 0,20 × 360 = **72°** ; tennis 0,15 × 360 = **54°**. Somme : 144 + 90 + 72 + 54 = 360°. ✓\n\n4. Le diagramme circulaire montre la **répartition d’un tout** en parts. Une courbe sert à montrer une évolution dans le temps, ce qui n’est pas le cas ici."}$exo$::jsonb),
  ('f6b44486-50b1-5c22-a554-1db8059cc8b7'::uuid, 3, 'probleme', $exo${"titre":"Deux classes, même moyenne","consigne":"Calcule les indicateurs puis interprète-les.","enonce":"**Situation.** Voici les notes de deux petites classes.\n- Classe A : 6 ; 8 ; 10 ; 12 ; 14.\n- Classe B : 2 ; 10 ; 10 ; 10 ; 18.\n\n1. Calcule la moyenne, la médiane et l’étendue de la classe A.\n2. Calcule la moyenne, la médiane et l’étendue de la classe B.\n3. Que peut-on dire de ces deux classes ? Quel indicateur les distingue et que signifie-t-il ?\n4. Calcule la médiane de la série 3 ; 5 ; 7 ; 9 ; 10 ; 12 (six valeurs).","bareme":[{"critere":"Classe A : moyenne 10, médiane 10, étendue 8","points":5},{"critere":"Classe B : moyenne 10, médiane 10, étendue 16","points":5},{"critere":"Même centre mais l’étendue distingue les classes : notes plus dispersées en B","points":5},{"critere":"Médiane de six valeurs : (7 + 9) ÷ 2 = 8","points":5}],"dureeMin":15,"corrige":"1. Classe A : somme 6 + 8 + 10 + 12 + 14 = 50, moyenne 50 ÷ 5 = **10**. La série est ordonnée, la médiane (3e valeur) est **10**. Étendue : 14 − 6 = **8**.\n\n2. Classe B : somme 2 + 10 + 10 + 10 + 18 = 50, moyenne **10**. La médiane (3e valeur) est **10**. Étendue : 18 − 2 = **16**.\n\n3. Les deux classes ont la **même moyenne et la même médiane** (10), mais l’**étendue** est deux fois plus grande en B : les notes y sont plus dispersées (2 et 18 contre 6 et 14). La moyenne seule ne suffit donc pas à décrire une série.\n\n4. Il y a 6 valeurs (nombre pair) : la médiane est le milieu entre la 3e et la 4e valeur, soit (7 + 9) ÷ 2 = **8**."}$exo$::jsonb),
  ('7c7c4288-96dd-5768-b875-58bce65ca9aa'::uuid, 1, 'probleme', $exo${"titre":"Un dé à six faces","consigne":"Donne chaque probabilité sous forme de fraction simplifiée.","enonce":"**Situation.** On lance un dé équilibré à six faces numérotées de 1 à 6 et on note le numéro obtenu.\n\n1. Quelle est la probabilité d’obtenir 6 ?\n2. Quelle est la probabilité d’obtenir un nombre pair ?\n3. Quelle est la probabilité d’obtenir un nombre supérieur à 4 ?\n4. Quelle est la probabilité de l’événement contraire de « obtenir 6 » ?","bareme":[{"critere":"P(6) = 1/6","points":5},{"critere":"P(pair) = 3/6 = 1/2","points":5},{"critere":"P(supérieur à 4) = 2/6 = 1/3","points":5},{"critere":"Événement contraire : 1 − 1/6 = 5/6","points":5}],"dureeMin":6,"corrige":"Le dé est équilibré : il y a 6 issues possibles, toutes équiprobables. P = issues favorables ÷ issues possibles.\n\n1. P(6) = **1/6**.\n2. Les nombres pairs sont 2, 4 et 6 : P = 3/6 = **1/2**.\n3. Les nombres supérieurs à 4 sont 5 et 6 : P = 2/6 = **1/3**.\n4. P(non 6) = 1 − P(6) = 1 − 1/6 = **5/6**."}$exo$::jsonb),
  ('7c7c4288-96dd-5768-b875-58bce65ca9aa'::uuid, 2, 'probleme', $exo${"titre":"L’urne colorée","consigne":"Justifie chaque probabilité par un calcul.","enonce":"**Situation.** Une urne contient 10 boules indiscernables au toucher : 5 rouges, 3 bleues et 2 vertes. On tire une boule au hasard.\n\n1. Quelle est la probabilité de tirer une boule rouge ?\n2. Quelle est la probabilité de tirer une boule bleue ?\n3. Quelle est la probabilité de ne pas tirer une boule verte ? Utilise l’événement contraire.\n4. Les événements « rouge » et « bleue » sont-ils incompatibles ? Calcule la probabilité de « rouge ou bleue ».","bareme":[{"critere":"P(rouge) = 5/10 = 1/2","points":5},{"critere":"P(bleue) = 3/10","points":5},{"critere":"P(non verte) = 1 − 2/10 = 8/10 = 4/5","points":5},{"critere":"Événements incompatibles, donc P(rouge ou bleue) = 5/10 + 3/10 = 8/10 = 4/5","points":5}],"dureeMin":10,"corrige":"1. P(rouge) = 5/10 = **1/2**.\n\n2. P(bleue) = **3/10**.\n\n3. Événement contraire : P(non verte) = 1 − P(verte) = 1 − 2/10 = 8/10 = **4/5**.\n\n4. Une boule ne peut pas être à la fois rouge et bleue : les événements sont **incompatibles**. P(rouge ou bleue) = P(rouge) + P(bleue) = 5/10 + 3/10 = 8/10 = **4/5**. On retrouve le résultat de la question 3 : « rouge ou bleue » est le contraire de « verte »."}$exo$::jsonb),
  ('7c7c4288-96dd-5768-b875-58bce65ca9aa'::uuid, 3, 'probleme', $exo${"titre":"Deux tirages avec remise","consigne":"Construis l’arbre, puis calcule en multipliant le long des branches.","enonce":"**Situation.** Une urne contient 3 boules rouges (R) et 2 boules bleues (B). On tire une boule, on note sa couleur, on la remet, puis on tire une seconde boule.\n\n1. Construis l’arbre de probabilités de cette expérience (décris-le avec les probabilités sur chaque branche).\n2. Calcule P(RR) et P(BB).\n3. Calcule la probabilité d’obtenir deux boules de couleurs différentes.\n4. Calcule la probabilité d’obtenir au moins une boule rouge, en utilisant l’événement contraire.","bareme":[{"critere":"Arbre : P(R) = 3/5 et P(B) = 2/5 sur chaque tirage","points":4},{"critere":"P(RR) = 9/25 et P(BB) = 4/25","points":5},{"critere":"Différentes : RB + BR = 6/25 + 6/25 = 12/25","points":5},{"critere":"Au moins une rouge : 1 − P(BB) = 21/25","points":6}],"dureeMin":14,"corrige":"1. À chaque tirage, comme la boule est remise : P(R) = **3/5** et P(B) = **2/5**. L’arbre a deux étages, avec ces probabilités sur chaque branche, et quatre issues : RR, RB, BR, BB.\n\n2. Le long d’une branche, on multiplie : P(RR) = 3/5 × 3/5 = **9/25** ; P(BB) = 2/5 × 2/5 = **4/25**.\n\n3. Deux couleurs différentes : RB ou BR. P(RB) = 3/5 × 2/5 = 6/25 et P(BR) = 2/5 × 3/5 = 6/25. Entre branches qui conviennent, on additionne : 6/25 + 6/25 = **12/25**.\n   Contrôle : 9/25 + 4/25 + 12/25 = 25/25 = 1. ✓\n\n4. Le contraire de « au moins une rouge » est « aucune rouge », donc BB. P = 1 − 4/25 = 25/25 − 4/25 = **21/25**."}$exo$::jsonb),
  ('b8a83eb5-6775-52b3-871c-7b460356ac11'::uuid, 1, 'probleme', $exo${"titre":"Compléter un tableau","consigne":"Écris la méthode utilisée.","enonce":"**Questions.**\n\n1. Le prix des baguettes est proportionnel à leur nombre. Deux baguettes coûtent 3 €, cinq baguettes 7,50 €. Combien coûtent huit baguettes ?\n2. 5 kg de pommes coûtent 12,50 €. Quel est le prix de 1 kg, puis de 8 kg ?\n3. Léo a 12 ans et sa sœur 9 ans. Dans trois ans, ils auront 15 ans et 12 ans. L’âge de Léo est-il proportionnel à celui de sa sœur ? Justifie.","bareme":[{"critere":"Coefficient 1,5 et prix de huit baguettes : 12 €","points":6},{"critere":"1 kg à 2,50 € et 8 kg à 20 €","points":7},{"critere":"Quotients 12/9 ≈ 1,33 et 15/12 = 1,25 différents, donc non proportionnel","points":7}],"dureeMin":7,"corrige":"1. Coefficient : 3 ÷ 2 = 1,5 €/baguette (contrôle : 5 × 1,5 = 7,50 ✓). Huit baguettes : 8 × 1,5 = **12 €**.\n\n2. Passage à l’unité : 12,50 ÷ 5 = **2,50 €** le kg. Puis 8 × 2,50 = **20 €**.\n\n3. Les quotients ne sont pas constants : 12 ÷ 9 ≈ 1,33 et 15 ÷ 12 = 1,25. L’écart d’âge reste 3 ans, mais le rapport change : ce **n’est pas** une situation de proportionnalité."}$exo$::jsonb),
  ('b8a83eb5-6775-52b3-871c-7b460356ac11'::uuid, 2, 'probleme', $exo${"titre":"La recette de crêpes","consigne":"Utilise la méthode de ton choix et écris tes calculs.","enonce":"**Situation.** Pour 4 personnes, une recette de crêpes demande 200 g de farine, 40 cl de lait et 4 œufs.\n\n1. Quelles quantités faut-il pour 10 personnes ?\n2. Quelle quantité de farine faut-il pour 6 personnes ?\n3. Un magasin vend des paquets de crêpes : 3 paquets coûtent 4,50 €, 5 paquets 7,50 € et 8 paquets 12 €. Ce tarif est-il proportionnel au nombre de paquets ? Justifie.\n4. Nomme la méthode que tu as utilisée à la question 1.","bareme":[{"critere":"10 personnes : 500 g de farine, 100 cl de lait et 10 œufs (coefficient 2,5)","points":7},{"critere":"6 personnes : 300 g de farine","points":4},{"critere":"Quotients 1,5 pour chaque colonne, donc proportionnel","points":5},{"critere":"Méthode citée : coefficient ou passage à l’unité","points":4}],"dureeMin":10,"corrige":"1. Coefficient : 10 ÷ 4 = 2,5. Farine : 200 × 2,5 = **500 g** ; lait : 40 × 2,5 = **100 cl** ; œufs : 4 × 2,5 = **10 œufs**.\n\n2. Pour 1 personne : 200 ÷ 4 = 50 g. Pour 6 personnes : 50 × 6 = **300 g**.\n\n3. Quotients : 4,50 ÷ 3 = 1,5 ; 7,50 ÷ 5 = 1,5 ; 12 ÷ 8 = 1,5. Ils sont constants : le tarif est **proportionnel**, le prix d’un paquet est 1,50 €.\n\n4. À la question 1, on a utilisé le **coefficient de proportionnalité** (× 2,5). On pouvait aussi passer par l’unité (50 g de farine par personne)."}$exo$::jsonb),
  ('b8a83eb5-6775-52b3-871c-7b460356ac11'::uuid, 3, 'probleme', $exo${"titre":"Deux salles de sport","consigne":"Complète, justifie avec le cours et interprète.","enonce":"**Situation.** La salle A fait payer 5 € par séance. La salle B fait payer un abonnement de 20 € plus 3 € par séance.\n\n1. Recopie et complète le tableau des prix pour 0, 2, 4 et 6 séances, pour la salle A puis pour la salle B.\n2. Laquelle de ces deux situations est une situation de proportionnalité ? Justifie avec des quotients.\n3. Décris l’allure du graphique de chaque salle (prix en fonction du nombre de séances). Laquelle passe par l’origine ?\n4. Pour combien de séances les deux salles coûtent-elles le même prix ?","bareme":[{"critere":"Tableau A : 0 ; 10 ; 20 ; 30 et tableau B : 20 ; 26 ; 32 ; 38","points":4},{"critere":"A proportionnelle (quotient 5) ; B non (26/2 = 13 et 32/4 = 8)","points":6},{"critere":"Deux droites : celle de A passe par l’origine, celle de B coupe l’axe des prix en 20","points":5},{"critere":"10 séances : 5n = 20 + 3n donne n = 10, soit 50 € dans les deux cas","points":5}],"dureeMin":15,"corrige":"1. Salle A : 0 → 0 € ; 2 → 10 € ; 4 → 20 € ; 6 → 30 €. Salle B : 0 → 20 € ; 2 → 26 € ; 4 → 32 € ; 6 → 38 €.\n\n2. Salle A : 10 ÷ 2 = 5 ; 20 ÷ 4 = 5 ; 30 ÷ 6 = 5 : quotient constant, **proportionnalité**. Salle B : 26 ÷ 2 = 13 et 32 ÷ 4 = 8 : quotients différents, **pas de proportionnalité** (à cause de l’abonnement fixe de 20 €).\n\n3. Les points de chaque salle sont alignés (deux droites). La droite de **A passe par l’origine** ; celle de B part de 20 € pour 0 séance et ne passe pas par l’origine.\n\n4. On cherche n tel que 5n = 20 + 3n. Alors 2n = 20 et **n = 10** : pour 10 séances, les deux salles coûtent 50 €. Avant, A est moins chère ; après, B est moins chère."}$exo$::jsonb),
  ('a4a9b404-01b5-555c-aab1-8228a323ce3f'::uuid, 1, 'probleme', $exo${"titre":"Calculer avec des pourcentages","consigne":"Écris les calculs.","enonce":"**Questions.**\n\n1. Calcule 20 % de 150 et 35 % de 80.\n2. Un prix de 60 € augmente de 10 % ; un autre de 80 € baisse de 25 %. Calcule les nouveaux prix.\n3. Dans une classe de 24 élèves, il y a 18 filles. Quel pourcentage de la classe représentent-elles ?","bareme":[{"critere":"20 % de 150 = 30 et 35 % de 80 = 28","points":6},{"critere":"60 × 1,10 = 66 € et 80 × 0,75 = 60 €","points":7},{"critere":"18 ÷ 24 × 100 = 75 %","points":7}],"dureeMin":6,"corrige":"1. 20 % de 150 = 150 × 0,20 = **30**. 35 % de 80 = 80 × 0,35 = **28**.\n\n2. Hausse de 10 % : coefficient 1,10, donc 60 × 1,10 = **66 €**. Baisse de 25 % : coefficient 0,75, donc 80 × 0,75 = **60 €**.\n\n3. Pourcentage = (partie ÷ tout) × 100 = 18 ÷ 24 × 100 = 0,75 × 100 = **75 %**."}$exo$::jsonb),
  ('a4a9b404-01b5-555c-aab1-8228a323ce3f'::uuid, 2, 'probleme', $exo${"titre":"Les soldes en deux temps","consigne":"Utilise les coefficients multiplicateurs et écris tes calculs.","enonce":"**Situation.** Une veste coûte 80 €. Elle est soldée à −30 %. À la caisse, on applique une réduction supplémentaire de 10 % sur le prix soldé.\n\n1. Calcule le prix soldé.\n2. Calcule le prix payé à la caisse.\n3. Quel pourcentage de réduction totale cela représente-t-il par rapport aux 80 € ?\n4. Un vendeur affirme que la réduction totale est de 30 % + 10 % = 40 %. Explique pourquoi c’est faux.","bareme":[{"critere":"Prix soldé 80 × 0,7 = 56 €","points":5},{"critere":"Prix payé 56 × 0,9 = 50,40 €","points":5},{"critere":"Réduction totale (80 − 50,40) ÷ 80 = 0,37, soit 37 %","points":7},{"critere":"Les pourcentages ne s’additionnent pas : la seconde remise porte sur le prix déjà réduit","points":3}],"dureeMin":10,"corrige":"1. Baisse de 30 % : coefficient 0,7, donc 80 × 0,7 = **56 €**.\n\n2. Baisse de 10 % sur 56 € : 56 × 0,9 = **50,40 €**.\n\n3. Réduction totale = 80 − 50,40 = 29,60 €. En pourcentage : 29,60 ÷ 80 = 0,37, soit **37 %**. (Avec les coefficients : 0,7 × 0,9 = 0,63, donc une baisse de 37 %.)\n\n4. Deux pourcentages successifs ne s’additionnent pas : la seconde remise de 10 % s’applique au prix **déjà réduit** (56 €), pas au prix de départ (80 €). La réduction totale est 37 %, pas 40 %."}$exo$::jsonb),
  ('a4a9b404-01b5-555c-aab1-8228a323ce3f'::uuid, 3, 'probleme', $exo${"titre":"Évolutions et taux","consigne":"Justifie les calculs avec des coefficients multiplicateurs.","enonce":"**Questions.**\n\n1. Le prix d’un article passe de 40 € à 46 €. Calcule le taux d’évolution en pourcentage.\n2. Un abonnement augmente de 8 % pour atteindre 27 €. Quel était son prix avant l’augmentation ?\n3. Le mois suivant, cet abonnement baisse de 8 %. Calcule son nouveau prix et explique pourquoi on ne retrouve pas le prix d’origine.\n4. Un stock augmente de 20 %, puis diminue de 20 %. Calcule le taux d’évolution global.","bareme":[{"critere":"Taux (46 − 40) ÷ 40 × 100 = +15 %","points":4},{"critere":"Prix initial 27 ÷ 1,08 = 25 €","points":6},{"critere":"27 × 0,92 = 24,84 € ; la baisse porte sur un prix plus grand, donc ≠ 25 €","points":6},{"critere":"1,2 × 0,8 = 0,96, soit −4 %","points":4}],"dureeMin":15,"corrige":"1. Taux = (valeur finale − valeur initiale) ÷ valeur initiale × 100 = (46 − 40) ÷ 40 × 100 = 6 ÷ 40 × 100 = **+15 %**.\n\n2. Une hausse de 8 % correspond au coefficient 1,08. On cherche le tout : prix initial = 27 ÷ 1,08 = **25 €**. (Vérification : 25 × 1,08 = 27.)\n\n3. Baisse de 8 % : coefficient 0,92, donc 27 × 0,92 = **24,84 €**. On ne retrouve pas 25 € car la baisse de 8 % s’applique à 27 €, un prix plus élevé que 25 € : les deux pourcentages ne portent pas sur la même quantité.\n\n4. Coefficient global : 1,2 × 0,8 = 0,96, donc une **baisse de 4 %**. Une hausse suivie d’une baisse du même taux ne ramène jamais à la valeur de départ."}$exo$::jsonb),
  ('4290e251-d2de-5cdc-8b95-ab632ef98d7a'::uuid, 1, 'probleme', $exo${"titre":"Une photocopieuse","consigne":"Écris les calculs et justifie.","enonce":"**Situation.** Une copie coûte 0,15 €. Le prix P à payer pour n copies est donné par P = 0,15 × n.\n\n1. Quelle est la variable ? Quelle est la grandeur dépendante ?\n2. Complète le tableau : n = 10, n = 20, n = 50.\n3. Cette situation est-elle une situation de proportionnalité ? Justifie.","bareme":[{"critere":"Variable n (nombre de copies) et grandeur dépendante P (prix)","points":6},{"critere":"P = 1,5 € ; 3 € ; 7,50 €","points":7},{"critere":"Proportionnalité : P = 0,15 × n, quotient constant 0,15 et 0 copie coûte 0 €","points":7}],"dureeMin":6,"corrige":"1. La **variable** est le nombre de copies n (celui qu’on choisit). La grandeur **dépendante** est le prix P, qui en découle.\n\n2. P = 0,15 × 10 = **1,50 €** ; 0,15 × 20 = **3 €** ; 0,15 × 50 = **7,50 €**.\n\n3. Oui : P est obtenu en multipliant n par le même nombre 0,15 (le quotient P ÷ n vaut toujours 0,15), et 0 copie coûte 0 €. Le graphique serait une droite passant par l’origine : c’est de la **proportionnalité**."}$exo$::jsonb),
  ('4290e251-d2de-5cdc-8b95-ab632ef98d7a'::uuid, 2, 'probleme', $exo${"titre":"La location de vélo","consigne":"Écris la formule, le tableau et tes conclusions.","enonce":"**Situation.** Un loueur demande 5 € de dépôt, puis 4 € par heure de location. Soit h le nombre d’heures et P le prix en euros.\n\n1. Écris la formule qui donne P en fonction de h.\n2. Complète un tableau de valeurs pour h = 0, 1, 2 et 3.\n3. Calcule le prix pour 6 heures, puis le nombre d’heures pour un prix de 37 €.\n4. Le prix est-il proportionnel au nombre d’heures ? Justifie avec le graphique.","bareme":[{"critere":"Formule P = 4 × h + 5","points":4},{"critere":"Tableau : 5 ; 9 ; 13 ; 17","points":5},{"critere":"6 heures coûtent 29 € et 37 € correspondent à 8 heures","points":6},{"critere":"Non proportionnel : la droite ne passe pas par l’origine, 0 h coûte 5 €","points":5}],"dureeMin":10,"corrige":"1. Le prix est la part fixe plus 4 € par heure : **P = 4 × h + 5**.\n\n2. h = 0 → P = **5** ; h = 1 → P = **9** ; h = 2 → P = **13** ; h = 3 → P = **17**.\n\n3. Pour h = 6 : P = 4 × 6 + 5 = **29 €**. Pour P = 37 : 4h + 5 = 37, donc 4h = 32 et h = **8 heures**.\n\n4. Le prix **n’est pas proportionnel** au nombre d’heures : pour 0 heure, on paie déjà 5 €, donc le graphique est une droite qui **ne passe pas par l’origine**. C’est une dépendance, mais pas une proportionnalité."}$exo$::jsonb),
  ('4290e251-d2de-5cdc-8b95-ab632ef98d7a'::uuid, 3, 'probleme', $exo${"titre":"Lire, comparer, distinguer","consigne":"Justifie chaque réponse à partir des données ou du cours.","enonce":"**Situation.** On a relevé la température T (en °C) à l’intérieur d’une serre, chaque heure, depuis 8 h.\n\n| Temps t (heures après 8 h) | 0 | 1 | 2 | 3 | 4 | 5 | 6 |\n| Température T (°C) | 12 | 15 | 18 | 18 | 18 | 16 | 13 |\n\n1. Quelle est la variable ? Quelle température lit-on à t = 2 ? Pour quelles valeurs de t la température vaut-elle 18 °C ?\n2. Décris l’évolution de T : quand augmente-t-elle, quand est-elle constante, quand diminue-t-elle ? De combien a-t-elle augmenté entre t = 0 et t = 2 ?\n3. La température est-elle proportionnelle au temps ? Justifie.\n4. L’aire d’un carré de côté c est A = c². Donne A pour c = 1, 2, 3. Est-ce une dépendance ? Est-ce une proportionnalité ?","bareme":[{"critere":"Variable t ; T(2) = 18 °C ; T = 18 °C pour t = 2, 3 et 4","points":5},{"critere":"Croissance jusqu’à t = 2 (+6 °C), palier de 2 à 4, puis diminution","points":5},{"critere":"Non proportionnelle : T(0) = 12 ≠ 0 et les quotients T ÷ t ne sont pas constants","points":5},{"critere":"A = 1 ; 4 ; 9 : dépendance oui, proportionnalité non (rapport 1 puis 2 puis 3)","points":5}],"dureeMin":16,"corrige":"1. La variable est le temps t. À t = 2, on lit **T = 18 °C**. La température vaut 18 °C pour **t = 2, 3 et 4**.\n\n2. De t = 0 à t = 2, T **augmente** (12 → 15 → 18), soit une hausse de 18 − 12 = **6 °C**. De t = 2 à t = 4, il y a un **palier** : T reste à 18 °C. De t = 4 à t = 6, T **diminue** (18 → 16 → 13).\n\n3. La température **n’est pas proportionnelle** au temps : à t = 0 elle vaut 12 °C et non 0 ; de plus 15 ÷ 1 = 15 et 18 ÷ 2 = 9, les quotients ne sont pas constants.\n\n4. A = 1² = **1** ; 2² = **4** ; 3² = **9**. L’aire dépend bien du côté : c’est une **dépendance**. Mais ce n’est **pas** une proportionnalité : quand le côté double (1 → 2), l’aire est multipliée par 4 (1 → 4) et non par 2. Les quotients A ÷ c valent 1, 2 et 3."}$exo$::jsonb)
) AS v (chapter_id, difficulte, style, contenu)
JOIN public.chapters c ON c.id = v.chapter_id
ON CONFLICT (id) DO UPDATE
  SET style      = EXCLUDED.style,
      contenu    = EXCLUDED.contenu,
      difficulte = EXCLUDED.difficulte,
      origine    = 'catalogue';

DO $$
DECLARE
  n INT;
BEGIN
  SELECT count(*) INTO n
    FROM public.chapter_exercices e
   WHERE e.origine = 'catalogue'
     AND e.chapter_id IN ('c7aa5303-cee8-5f65-982a-d7988ca78342', 'e104a714-229a-5083-b718-e27552811460', 'b270ad70-ec61-5760-b00d-1f57aa02685f', 'b0642ad8-fd82-5098-a691-f2de6b6d856e', '5b9ab20a-14af-58fa-a25c-bd2a53961130', '575652f4-6c8a-521c-942e-a10d9c4f3fb9', '25408f17-a202-5e42-9aaa-740ad9343e15', '47687896-757b-5f82-9a14-52626788c308', '5f0dd17a-731e-58c2-b628-990bc5b014c7', 'b02b1c1e-c59d-57e1-89d8-f06af97b87f2', 'a5ca98d8-8b8f-5cfa-b1e9-d855937fa78f', 'e44539ef-c1f1-509f-bb81-3f1246281327', '77d56b69-676a-5c71-93dc-e13260eee0ca', '35a5afc0-a4ac-5dd2-b136-d64c98aaaf75', 'dcbb94fb-6cd1-5461-b9ca-a4fb206add7d', '46988e38-b7a3-509b-a4b7-9df5e4264aa3', '92914028-1f3d-5b10-9383-a7c16ea1d813', 'a5c44eab-38c6-5217-9e7b-4a722e681f01', '5322f300-a345-53c3-9f13-beb4155b92fb', '7bed8703-f5f0-509a-b427-ced6a778ac29', '10fda032-3e4a-5bc1-a568-17428f3c8b29', '5a4d61d5-80eb-52e7-89a2-096322650cb1', '27d22a9c-3d7e-5d27-a482-53ddcf2e1397', '7396e312-7adb-55b8-bacf-e4d5660ee603', '7f7c0bad-8a3e-50d1-a7f4-815e8facf8e1', 'e1b2d4a2-9af3-545d-95cd-a8329995a0e7', '2b7b7129-b680-5559-83f6-c675d1f5476b', '6255e663-4edf-5792-a61b-5d5e190bdddd', '49b51a1c-152a-5f93-9a94-69520a6b9e39', '22991364-07ac-5bf7-9059-313215b36cd6', 'b0461f1e-9622-5e6b-b130-43b5e4d03254', '1545e755-542d-5d56-b483-50163051d583', '887e3308-bd55-5205-8129-5653367a928d', '2c4af367-1f90-51b8-b1dd-f43ed6c28022', '9d5de0b0-162d-5646-8a5c-b20837b5bed7', '391db6c3-de5d-5a3a-a5f5-7a0cdc56013b', 'a66ae76b-4466-413f-8dde-c05c0a645e9d', '130356ab-7263-49f1-9a37-0410fe637b30', '5a3b55cb-a48c-4cfb-8ded-27ce52002b84', 'e0f02b95-7ff3-56bb-9b80-ef14ab4de755', '9175214a-ff51-5d25-ac1d-180fe1a65c33', 'e22f5910-eb9a-55d1-aec7-e85c209809a9', 'c060f999-ab79-5a71-835f-d87337f6a97d', 'c0bf100f-b4c4-5cdb-92dd-f004e501c944', '0d56d33e-0375-5914-8834-470c354ed4f9', '9146ff73-d337-5ad9-ba54-f90e3a56e64d', '2cf74dd8-58a4-595f-86a4-b239271d4633', '96308e0d-b349-5937-9ca8-fa0fceb05c61', 'ea10d373-53b1-5f93-85bf-37fa6a6eeeae', '787349c7-b624-5bb9-a75e-0e76edf04e0f', 'f91e9054-fdd3-5d3e-8910-de90cc5862b9', '58cfa258-69f9-5109-927a-c51fd8fae8c7', '990b3f90-a500-56fe-8672-24b970637547', '05b94edf-f4f0-5eb9-8d79-ae92e41e213f', 'b448aeea-8ff7-59c3-925f-8ed2edb8fa33', '5fb4a98f-4599-5332-9d79-41375f4de191', '85198058-0dfe-5d69-9c6b-468913a7d6a0', 'bbbcbbfa-efdd-5760-97fa-fd6d4c720ac2', '805434a4-e66b-59e7-9f49-6ca5ab6b24ac', '141cd0b9-b54b-52da-8d7f-450f4cefa8cf', 'bbc8df26-d175-58d1-affb-8efd8a429819', '5e75256d-577d-5004-ac78-1c34f23fc75f', '6d35af41-354f-52e9-b68a-ffc87011d036', '105df279-2f8a-5b37-a20c-e5cd54cd33ab', 'b3560004-1ea7-5651-ba9d-dbb240eeb02f', 'e1a17713-b4c0-5c80-bb0d-afaabdf4aef4', 'bb7d2fb5-5930-51ad-a2a2-5e4c0cec344d', '2d76d260-0009-5038-9ee1-223f12d3a274', '33562b41-7711-5225-8fc3-9d1e10b7713a', 'efd99958-83d9-5671-9d06-d227670481cb', 'f6b44486-50b1-5c22-a554-1db8059cc8b7', '7c7c4288-96dd-5768-b875-58bce65ca9aa', 'b8a83eb5-6775-52b3-871c-7b460356ac11', 'a4a9b404-01b5-555c-aab1-8228a323ce3f', '4290e251-d2de-5cdc-8b95-ab632ef98d7a');
  RAISE NOTICE '429 : % sujets au catalogue (attendu : 225)', n;
  IF n < 225 THEN
    RAISE WARNING '429 : il manque des sujets — des fiches ont-elles changé d''identifiant ?';
  END IF;
END $$;
